function codexImageProviderMcpOverride({ socketPath, scriptPath }) {
  const command = JSON.stringify(process.execPath);
  const args = [scriptPath, "--socket", socketPath].map((value) => JSON.stringify(String(value))).join(", ");
  return [
    "mcp_servers.wfl_image_provider={",
    `command = ${command},`,
    `args = [${args}],`,
    "enabled = true,",
    "required = false,",
    "startup_timeout_sec = 10,",
    "tool_timeout_sec = 600,",
    'default_tools_approval_mode = "auto"',
    "}",
  ].join(" ");
}

