async function runtimeForUser(userId) {
  const existing = runtimeByUserId.get(userId);
  if (existing) return existing.initialize();
  const pending = runtimeInitializationByUserId.get(userId);
  if (pending) return pending;
  const initialization = withPersistentStateOperation(async () => {
    const initialized = runtimeByUserId.get(userId);
    if (initialized) return initialized.initialize();
    const user = multiUserStore.getUser(userId);
    if (!user) throw httpError(403, "用户运行上下文不存在");
    const runtime = await new UserRuntime(user).initialize();
    runtimeByUserId.set(user.id, runtime);
    return runtime;
  }).finally(() => runtimeInitializationByUserId.delete(userId));
  runtimeInitializationByUserId.set(userId, initialization);
  return initialization;
}

async function runtimeForRequest(request) {
  return runtimeForUser(request.user?.id || legacyUser.id);
}

async function restorePersistedUserGoalRuntimes() {
  if (RESCUE_MODE || !BACKEND_PRIMARY_AT_START || !multiUserStore.modeSnapshot().configured) return;
  const users = multiUserStore
    .listUsers(legacyUser.id)
    .filter((user) => user.id !== legacyUser.id && user.status === "active");
  for (const userSummary of users) {
    try {
      const user = multiUserStore.getUser(userSummary.id);
      if (!user?.stateDirectory || !user.codexHome) continue;
      const store = await new CodexGoalRecoveryStore(user.stateDirectory).initialize();
      if (store.needsBootstrap()) {
        const discovered = await scanCodexGoalRollouts(user.codexHome);
        await store.bootstrap(discovered.records);
      }
      if (!store.snapshot().some((goal) => (
        goal.status === "active"
        || goal.status === "usageLimited"
        || goal.resumeWhenAvailable
      ))) continue;
      await runtimeForUser(user.id);
    } catch (error) {
      console.error(`[${userSummary.id}] Unable to restore the user Goal runtime: ${error.message}`);
    }
  }
}

function allRuntimesIdle() {
  return [...runtimeByUserId.values()].every((runtime) => runtime.taskIsIdle());
}

function allRuntimes() {
  return [...runtimeByUserId.values()];
}

function codexRecoverySnapshotForUser(userId = null) {
  const pending = [...backendCodexRecoveryPending.values()]
    .filter((record) => userId == null || record.userId === userId)
    .map((record) => record.threadId);
  return {
    state: backendCodexRecoveryState,
    ready: pending.length === 0 && backendCodexRecoveryState === "ready",
    pendingThreadIds: [...new Set(pending)],
    error: backendCodexRecoveryError,
    observedAt: Date.now(),
  };
}

function codexRecoveryBlocksThread(userId, threadId) {
  if (typeof userId !== "string" || !userId || typeof threadId !== "string" || !threadId) return false;
  return backendCodexRecoveryPending.has(handoffRecordKey({ userId, threadId }));
}

function syncBackendCodexRecoveryPending(records = codexHandoffRecoveryStore?.snapshot()?.records) {
  backendCodexRecoveryPending.clear();
  for (const record of Array.isArray(records) ? records : []) {
    backendCodexRecoveryPending.set(handoffRecordKey(record), record);
  }
  return backendCodexRecoveryPending.size;
}

function broadcastCodexRecoveryStatus() {
  for (const runtime of allRuntimes()) {
    runtime.broadcast({
      type: "codex/recovery-status",
      payload: codexRecoverySnapshotForUser(runtime.user.id),
    });
    runtime.broadcastCodexStatus({
      status: runtime.bridge?.ready ? "ready" : "starting",
    });
  }
}

async function recoverBackendCodexHandoff() {
  if (RESCUE_MODE) return { ready: true, records: 0 };
  if (backendCodexRecoveryPromise) return backendCodexRecoveryPromise;
  const operation = (async () => {
    const journal = codexHandoffRecoveryStore?.snapshot();
    const records = Array.isArray(journal?.records) ? journal.records : [];
    backendCodexRecoveryState = "recovering";
    backendCodexRecoveryError = null;
    // Terminal records from the old process still need the new writer's
    // resume confirmation, so every journal record remains a send fence until
    // recoverHandoffRecord has completed.
    syncBackendCodexRecoveryPending(records);
    broadcastCodexRecoveryStatus();
    await codexHandoffRecoveryStore?.setState("recovering");

    const userIds = [...new Set(records.map((record) => record.userId))];
    await Promise.all(userIds.map((userId) => runtimeForUser(userId)));

    // A promoted candidate was intentionally initialized with the global
    // writer fence held. Release it only after every recorded runtime exists,
    // then let each bridge start through its normal lifecycle queue.
    if (backendAuthHandoffFenced) backendAuthHandoffFenced = false;
    await Promise.all(allRuntimes().map(async (runtime) => {
      if (!CODEX_ENABLED) return;
      if (!runtime.bridge?.ready) await runtime.resumeCodexAuthHandoff();
    }));

    for (const record of records) {
      const key = handoffRecordKey(record);
      const runtime = runtimeByUserId.get(record.userId);
      if (!runtime) throw new Error(`恢复运行上下文不存在：${record.userId}`);
      await codexHandoffRecoveryStore?.updateRecord(record, { state: "recovering" });
      try {
        const recovered = await runtime.recoverHandoffRecord(record);
        backendCodexRecoveryPending.delete(key);
        await codexHandoffRecoveryStore?.updateRecord(record, recovered);
        broadcastCodexRecoveryStatus();
      } catch (error) {
        await codexHandoffRecoveryStore?.updateRecord(record, {
          state: "failed",
          nativeStatus: null,
        });
        throw error;
      }
    }

    await codexHandoffRecoveryStore?.clear(journal?.handoffId || null);
    backendCodexRecoveryState = "ready";
    backendCodexRecoveryError = null;
    broadcastCodexRecoveryStatus();
    return { ready: true, records: records.length };
  })().catch((error) => {
    backendCodexRecoveryState = "failed";
    backendCodexRecoveryError = String(error?.message || "Codex handoff recovery failed").slice(0, 2_048);
    void codexHandoffRecoveryStore?.setState("failed").catch(() => {});
    broadcastCodexRecoveryStatus();
    const retryTimer = setTimeout(() => {
      if (!backendCodexRecoveryPromise && backendCodexRecoveryState === "failed") {
        void recoverBackendCodexHandoff().catch(() => {});
      }
    }, CODEX_HANDOFF_RETRY_DELAY_MS);
    retryTimer.unref?.();
    throw error;
  }).finally(() => {
    if (backendCodexRecoveryPromise === operation) backendCodexRecoveryPromise = null;
  });
  backendCodexRecoveryPromise = operation;
  return operation;
}

function maintenanceBackgroundIsIdle() {
  const backup = backupCenter.snapshot();
  const workspace = workspaceMigrationCenter.snapshot();
  const mapRender = mapRenderJobs?.status();
  const mapImage = mapImageJobs?.status();
  const imageExecution = imageExecutionQueue?.status();
  return !backupCreationTask
    && !backup.busy
    && !workspaceExportTask
    && !workspaceImportTask
    && workspaceInspectionInProgress === 0
    && !workspace.busy
    && workspace.activeUploadWrites === 0
    && pendingProviderAssignments.size === 0
    && (!imageExecution || (imageExecution.running === 0 && imageExecution.queueLength === 0))
    && (!mapImage || (mapImage.running === 0 && mapImage.queueLength === 0))
    && providerModelQueriesInFlight.size === 0
    && !officialAccountActions.hasPendingLogins()
    && !officialLoginBrowser?.hasActiveSession()
    && !claudeOfficialLoginBrowser?.hasActiveSession()
    && (!mapRender || (
      mapRender.running === 0
      && (!mapRender.enabled || mapRender.queueLength === 0)
    ))
    && temporarySshAccess.pendingOperations === 0
    && allRuntimes().every((runtime) => !runtime.providerSwitchInProgress)
    && !androidApkBuilder?.isBusy()
    && !opsSupervisor.pending;
}

function maintenanceStateIsIdle() {
  return persistentStateAdmission.idle && maintenanceBackgroundIsIdle();
}

async function beginPersistentStateOperation({ allowDuringDrain = false } = {}) {
  if (backendAuthorityStore && BACKEND_INSTANCE_ID) {
    await backendAuthorityStore.assertCurrent({
      backendInstanceId: BACKEND_INSTANCE_ID,
      writerEpoch: BACKEND_WRITER_EPOCH,
      port: PORT,
    });
  }
  return persistentStateAdmission.begin({ allowDuringDrain });
}

async function withPersistentStateOperation(operation, options) {
  const admission = await beginPersistentStateOperation(options);
  try {
    return await operation();
  } finally {
    admission.release();
  }
}

async function tryPersistentStateOperation(operation) {
  try {
    return await withPersistentStateOperation(operation);
  } catch (error) {
    if (error?.code === "ERR_MAINTENANCE_DRAIN_ACTIVE") return null;
    throw error;
  }
}

const app = express();
app.disable("x-powered-by");
app.use((request, _response, next) => {
  request.url = localRescuePath(request.url);
  next();
});
app.use(compression({ threshold: 1024 }));
app.use(express.json({
  // The AI provider test plugin can round-trip a Responses compaction item,
  // whose encrypted_content is documented at roughly 20 MB. Apply the larger
  // parser only to this plugin; ordinary JSON routes retain their smaller
  // request boundary.
  limit: "40mb",
  type: (request) => (
    !isWebdavPath(request.path)
    && request.path.startsWith("/api/plugins/ai-provider-real-test/")
    && Boolean(request.is("application/json", "application/*+json"))
  ),
}));
app.use(express.json({
  limit: "256kb",
  // WebDAV PUT carries the file bytes in the request stream. Do not let the
  // JSON parser consume a client that happens to label a file as JSON.
  // Keep the normal Content-Type check as well: a custom type callback that
  // only excludes WebDAV would make every binary upload look like JSON and
  // apply the JSON limit before the raw upload route can handle it.
  type: (request) => (
    !isWebdavPath(request.path)
    && !request.path.startsWith("/api/plugins/ai-provider-real-test/")
    && Boolean(request.is("application/json", "application/*+json"))
  ),
}));
app.use((request, response, next) => {
  const forwardedProtocol = trustedForwardedHeader(request, "x-forwarded-proto");
  if (forwardedProtocol === "http" && request.headers.host) {
    const publicHost = trustedForwardedHeader(request, "x-forwarded-host") || request.headers.host;
    if (!/^[a-z0-9.-]+(?::\d+)?$/i.test(publicHost)) {
      response.status(400).type("text/plain").send("Invalid host header");
      return;
    }
    response.redirect(308, `https://${publicHost}${request.originalUrl}`);
    return;
  }
  const embeddedUserManagement = ["/users", "/users/", "/users.html"].includes(request.path)
    && request.query.embed === "ops";
  const projectPreview = request.path.startsWith("/preview/");
  const mobilePreview = request.path.startsWith("/tools/mobile-preview/");
  const trustedProjectPreview = projectPreview && Boolean(trustedPreviewOriginRequest(request));
  response.setHeader("X-Content-Type-Options", "nosniff");
  if (!trustedProjectPreview) {
    response.setHeader("X-Frame-Options", embeddedUserManagement || projectPreview || mobilePreview ? "SAMEORIGIN" : "DENY");
  }
  response.setHeader("Referrer-Policy", "no-referrer");
  response.setHeader("Cross-Origin-Opener-Policy", "same-origin");
  response.setHeader("Cross-Origin-Resource-Policy", projectPreview || mobilePreview ? "cross-origin" : "same-origin");
  if (projectPreview) {
    response.setHeader("Access-Control-Allow-Origin", "*");
    response.setHeader("Content-Security-Policy", trustedProjectPreview
      ? trustedPreviewOriginCsp()
      : "sandbox allow-scripts allow-pointer-lock allow-downloads; default-src 'self' data: blob:; script-src 'self' 'unsafe-inline' 'unsafe-eval' data: blob:; style-src 'self' 'unsafe-inline' data: blob:; font-src 'self' data:; img-src 'self' data: blob:; media-src 'self' data: blob:; connect-src 'self'; worker-src 'self' blob:; child-src blob:; frame-src 'none'; object-src 'none'; base-uri 'none'; frame-ancestors 'self'; form-action 'none'");
  } else if (mobilePreview) {
    response.setHeader("Access-Control-Allow-Origin", "*");
    response.setHeader("Content-Security-Policy", MOBILE_PREVIEW_CSP);
  } else {
    response.setHeader(
      "Content-Security-Policy",
      `default-src 'self'; script-src 'self'; style-src 'self' 'unsafe-inline'; font-src 'self'; img-src 'self' data: blob:; connect-src 'self'; frame-src ${projectPreviewFrameSources()}; object-src 'none'; base-uri 'none'; frame-ancestors ${embeddedUserManagement || mobilePreview ? "'self'" : "'none'"}; form-action 'self'`,
    );
  }
  response.setHeader(
    "Permissions-Policy",
    "camera=(), microphone=(), geolocation=(), payment=(), usb=()",
  );
  if (forwardedProtocol === "https" || request.secure) {
    response.setHeader("Strict-Transport-Security", "max-age=31536000");
  }
  if (request.path.startsWith("/api/")) response.setHeader("Cache-Control", "no-store");
  next();
});
app.get("/internal/ready", (request, response, next) => {
  if (!isDirectLoopbackRequest(request)) {
    next();
    return;
  }
  response.setHeader("Cache-Control", "no-store");
  const recovery = codexRecoverySnapshotForUser();
  response.json({
    ok: true,
    version: APP_VERSION,
    codexReady: defaultRuntime.bridge.ready && recovery.ready,
    codexRecovery: recovery,
    rescueMode: RESCUE_MODE,
    backendInstanceId: BACKEND_INSTANCE_ID,
    writerEpoch: BACKEND_WRITER_EPOCH,
  });
});
app.post("/internal/auth-handoff/prepare", async (request, response, next) => {
  if (!isDirectLoopbackRequest(request)) {
    next();
    return;
  }
  response.setHeader("Cache-Control", "no-store");
  try {
    if (RESCUE_MODE || !BACKEND_INSTANCE_ID) throw new Error("Auth handoff is unavailable in rescue mode");
    await backendAuthorityStore.assertCurrent({
      backendInstanceId: BACKEND_INSTANCE_ID,
      writerEpoch: BACKEND_WRITER_EPOCH,
      port: PORT,
    });
    if (backendAuthHandoffPreparationPromise) {
      await backendAuthHandoffPreparationPromise;
    } else {
      if (backendCodexRecoveryState !== "ready") {
        throw new Error("已有 Codex 后端切换恢复正在进行，暂不能再次准备 handoff");
      }
      if (backendAuthHandoffFenced) {
        throw new Error("Codex 后端当前已被切换恢复流程占用");
      }
      const preparation = (async () => {
        const existing = codexHandoffRecoveryStore?.snapshot();
        if (existing?.records?.length) {
          throw new Error("已有未完成的 Codex handoff journal，必须先完成恢复");
        }
        const handoffId = crypto.randomUUID();
        // Persist the handoff boundary before asking any runtime to stop. If
        // this process is killed after the first runtime is fenced, the next
        // backend still has the identity and idempotency data it needs.
        await codexHandoffRecoveryStore?.begin({
          handoffId,
          sourceBackendInstanceId: BACKEND_INSTANCE_ID,
          sourceWriterEpoch: BACKEND_WRITER_EPOCH,
        });
        backendAuthHandoffFenced = true;
        backendCodexRecoveryState = "recovering";
        backendCodexRecoveryError = null;
        syncBackendCodexRecoveryPending([]);
        broadcastCodexRecoveryStatus();
        try {
          await Promise.all(allRuntimes().map((runtime) => runtime.prepareCodexAuthHandoff()));
          const prepared = codexHandoffRecoveryStore?.snapshot();
          syncBackendCodexRecoveryPending(prepared?.records);
          broadcastCodexRecoveryStatus();
        } catch (error) {
          const resumed = await Promise.allSettled(
            allRuntimes().map((runtime) => runtime.resumeCodexAuthHandoff()),
          );
          const resumeFailed = resumed.find((result) => result.status === "rejected");
          if (!resumeFailed) {
            await codexHandoffRecoveryStore?.clear(handoffId);
            syncBackendCodexRecoveryPending([]);
            backendCodexRecoveryState = "ready";
            backendCodexRecoveryError = null;
          } else {
            backendCodexRecoveryState = "failed";
            backendCodexRecoveryError = String(
              resumeFailed.reason?.message || error.message || "Codex handoff rollback failed",
            ).slice(0, 2_048);
          }
          backendAuthHandoffFenced = Boolean(resumeFailed);
          broadcastCodexRecoveryStatus();
          throw error;
        }
      })();
      backendAuthHandoffPreparationPromise = preparation;
      try {
        await preparation;
      } finally {
        if (backendAuthHandoffPreparationPromise === preparation) {
          backendAuthHandoffPreparationPromise = null;
        }
      }
    }
    response.json({ ok: true, fenced: true, runtimes: allRuntimes().length });
  } catch (error) {
    response.status(503).json({ ok: false, error: error.message });
  }
});
app.get("/internal/backend-identity", async (request, response, next) => {
  if (RESCUE_MODE || !isDirectLoopbackRequest(request)) {
    next();
    return;
  }
  response.setHeader("Cache-Control", "no-store");
  let selected = false;
  let authoritative = false;
  try {
    selected = await backendPortIsSelected(RELEASE_RUNTIME_DIR, PORT);
    if (BACKEND_INSTANCE_ID) {
      await backendAuthorityStore.assertCurrent({
        backendInstanceId: BACKEND_INSTANCE_ID,
        writerEpoch: BACKEND_WRITER_EPOCH,
        port: PORT,
      });
      authoritative = true;
    }
  } catch {
    // Identity remains observable after fencing so deployment recovery can
    // make an explicit decision without granting this process write access.
  }
  response.json({
    ok: true,
    version: APP_VERSION,
    port: PORT,
    backendInstanceId: BACKEND_INSTANCE_ID,
    writerEpoch: BACKEND_WRITER_EPOCH,
    primary: selected && authoritative,
    selected,
    authoritative,
    standby: false,
  });
});
app.get("/internal/codex-ready", async (request, response, next) => {
  if (!isDirectLoopbackRequest(request)) {
    next();
    return;
  }
  response.setHeader("Cache-Control", "no-store");
  const recovery = codexRecoverySnapshotForUser();
  if (
    !recovery.ready
    && !backendCodexRecoveryPromise
    && !backendAuthHandoffPreparationPromise
  ) {
    void recoverBackendCodexHandoff().catch(() => {});
  }
  if (!defaultRuntime.bridge.ready) {
    response.status(503).json({
      ok: false,
      version: APP_VERSION,
      codexReady: false,
      threadListReady: false,
      codexRecovery: recovery,
      runtimeBundleReady: CODEX_RUNTIME_BUNDLE.runtimeBundleReady,
      codeModeHostReady: CODEX_RUNTIME_BUNDLE.codeModeHostReady,
    });
    return;
  }
  if (!recovery.ready) {
    response.status(503).json({
      ok: false,
      version: APP_VERSION,
      codexReady: true,
      threadListReady: false,
      codexRecovery: recovery,
      runtimeBundleReady: CODEX_RUNTIME_BUNDLE.runtimeBundleReady,
      codeModeHostReady: CODEX_RUNTIME_BUNDLE.codeModeHostReady,
    });
    return;
  }
  try {
    const result = await probeDefaultRuntimeThreadList();
    response.json({
      ok: true,
      version: APP_VERSION,
      codexReady: true,
      threadListReady: true,
      codexRecovery: recovery,
      threadsObserved: result.data.length,
      runtimeBundleReady: CODEX_RUNTIME_BUNDLE.runtimeBundleReady,
      codeModeHostReady: CODEX_RUNTIME_BUNDLE.codeModeHostReady,
      codexVersion: CODEX_RUNTIME_BUNDLE.version,
      codexTarget: CODEX_RUNTIME_BUNDLE.target,
      codexRuntimeSha256: CODEX_RUNTIME_BUNDLE.treeSha256,
      codexCodeModeHostSha256: CODEX_RUNTIME_BUNDLE.codeModeHostSha256,
    });
  } catch (error) {
    console.error(`Candidate Codex probe failed: ${error.message}`);
    response.status(503).json({
      ok: false,
      version: APP_VERSION,
      codexReady: true,
      threadListReady: false,
      codexRecovery: codexRecoverySnapshotForUser(),
      runtimeBundleReady: CODEX_RUNTIME_BUNDLE.runtimeBundleReady,
      codeModeHostReady: CODEX_RUNTIME_BUNDLE.codeModeHostReady,
    });
  }
});
