// Recovery may need to re-arm a fenced backend before the selector is moved
// back to it.  Keeping this as a separate loopback-only endpoint preserves the
// normal promotion invariant (a standby cannot self-promote merely because it
// owns an old epoch) while allowing the verified deployment controller to
// restore the writer and deep readiness without first routing traffic to an
// unready process.
app.post("/internal/recover-primary", async (request, response, next) => {
  if (!isDirectLoopbackRequest(request)) {
    next();
    return;
  }
  response.setHeader("Cache-Control", "no-store");
  const recoveryOperation = request.get("x-wfl-deployment-recovery") || "";
  if (!/^[A-Za-z0-9](?:[A-Za-z0-9._-]{0,126}[A-Za-z0-9])?$/.test(recoveryOperation)) {
    response.status(400).json({ ok: false, error: "A verified deployment recovery identity is required" });
    return;
  }
  try {
    response.json(await activatePrimaryBackend());
  } catch (error) {
    response.status(503).json({ ok: false, error: error.message });
  }
});

async function activatePrimaryBackend() {
  if (RESCUE_MODE || !BACKEND_INSTANCE_ID) {
    throw new Error("Backend recovery promotion is unavailable in rescue mode");
  }
  if (backendAuthHandoffPreparationPromise) {
    await backendAuthHandoffPreparationPromise;
  }
  const authority = await backendAuthorityStore.read({ allowMissing: false });
  if (authority.backendInstanceId !== BACKEND_INSTANCE_ID || authority.port !== PORT) {
    const error = new Error("Backend does not own the selected writer authority");
    error.code = "ERR_BACKEND_WRITER_FENCED";
    throw error;
  }
  BACKEND_WRITER_EPOCH = authority.writerEpoch;
  await temporarySshAccess.activatePrimary();
  // A blue-green candidate starts fenced/standby and must not mutate any
  // project while it is serving no traffic. Once it owns the writer
  // authority, complete the same crash-recovery gate before promotion.
  await recoverMapResourceTransactionsAtStartup({ force: true });
  // The native Codex recovery handshake is part of promotion itself.  Do not
  // report primary until every journaled Thread has been interrupted,
  // resumed, and observed in an explicit idle/active state.
  await recoverBackendCodexHandoff();
  return {
    ok: true,
    version: APP_VERSION,
    backendInstanceId: BACKEND_INSTANCE_ID,
    writerEpoch: BACKEND_WRITER_EPOCH,
    primary: true,
  };
}

async function probeDefaultRuntimeThreadList() {
  const child = defaultRuntime.bridge.child;
  if (
    codexReadinessCache?.child === child
    && Date.now() - codexReadinessCache.checkedAt < CODEX_READINESS_CACHE_MS
  ) return codexReadinessCache.result;
  if (codexReadinessProbe?.child === child) return codexReadinessProbe.promise;

  const probe = {
    child,
    promise: requestThreadListAcrossProviders(
      defaultRuntime.bridge,
      { limit: 1, sortKey: "updated_at", sortDirection: "desc", archived: false },
      { timeoutMs: CODEX_READINESS_PROBE_TIMEOUT_MS },
    ).then((result) => {
      if (!Array.isArray(result?.data)) throw new Error("Unexpected thread/list response");
      codexReadinessCache = { child, checkedAt: Date.now(), result };
      return result;
    }).finally(() => {
      if (codexReadinessProbe === probe) codexReadinessProbe = null;
    }),
  };
  codexReadinessProbe = probe;
  return probe.promise;
}
