app.use((request, response, next) => {
  if (!isPersistentHttpMutation(request)) {
    next();
    return;
  }

  let admission = null;
  let responseFinished = false;
  let responseClosed = false;
  let downstreamStarted = false;
  const finish = () => {
    responseFinished = true;
    admission?.release();
  };
  const close = () => {
    responseClosed = true;
    if (responseFinished || response.writableFinished) {
      admission?.release();
      return;
    }
    if (!downstreamStarted) {
      admission?.release();
      return;
    }
    admission?.orphan();
    console.error(`Persistent request disconnected before completion; admission entered bounded recovery: ${request.method} ${request.path}`);
  };
  response.once("finish", finish);
  response.once("close", close);

  beginPersistentStateOperation({ allowDuringDrain: isEmergencyDeploymentControlPath(request) })
    .then((admittedOperation) => {
      admission = admittedOperation;
      if (responseFinished || (responseClosed && !downstreamStarted)) {
        admission.release();
        return;
      }
      request.completePersistentStateOperation = () => admission.release();
      downstreamStarted = true;
      next();
    })
    .catch((error) => {
      if (responseClosed || responseFinished) return;
      if (error?.code === "ERR_MAINTENANCE_DRAIN_ACTIVE") {
        response.setHeader("Retry-After", "2");
        response.status(503).json({ error: error.message, code: error.code });
        return;
      }
      next(httpError(503, `无法确认安全写入窗口：${error.message}`));
    });
});
