app.post("/api/auth/login", async (request, response, next) => {
  const clientKey = authClientKey(request);
  try {
    assertOperationRequest(request, "login");
    const retryAfter = authRetryAfter(clientKey);
    if (retryAfter > 0) {
      response.setHeader("Retry-After", String(retryAfter));
      throw httpError(429, "登录尝试过多，请稍后再试");
    }
    if (RESCUE_MODE) await refreshRescueAuthentication();
    const result = await multiUserStore.login(request.body?.username, request.body?.password);
    if (RESCUE_MODE && result.user.role !== "owner") {
      await multiUserStore.logout(result.token).catch(() => {});
      throw httpError(403, "独立救援服务仅允许所有者登录");
    }
    if (!RESCUE_MODE) {
      void schedulePendingProviderAssignment(result.user.id).catch((error) => {
        console.error(`[${result.user.id}] Unable to retry the default provider: ${error.message}`);
      });
    }
    clearAuthFailures(clientKey);
    setUserSessionCookie(response, request, result.token);
    response.json({ user: result.user });
  } catch (error) {
    if (error.statusCode === 401) recordAuthFailure(clientKey);
    next(error);
  } finally {
    if (request.body && typeof request.body === "object") request.body.password = "";
  }
});

app.post("/api/auth/register", async (request, response, next) => {
  const clientKey = authClientKey(request);
  try {
    if (RESCUE_MODE) throw httpError(403, "独立救援服务不接受新账号注册");
    assertOperationRequest(request, "register");
    const retryAfter = authRetryAfter(clientKey);
    if (retryAfter > 0) {
      response.setHeader("Retry-After", String(retryAfter));
      throw httpError(429, "注册尝试过多，请稍后再试");
    }
    const result = await multiUserStore.register(
      request.body?.invite,
      request.body || {},
      (user) => provisionManagedUser(user, {
        usersRoot: MULTI_USER_ROOT,
        controlStateRoot: path.join(STATE_DIR, "user-state"),
      }),
    );
    const providerSetup = await schedulePendingProviderAssignment(result.user.id).catch((error) => {
      console.error(`[${result.user.id}] Unable to apply the default provider: ${error.message}`);
      return { configured: false, pending: true };
    });
    clearAuthFailures(clientKey);
    setUserSessionCookie(response, request, result.token);
    response.status(201).json({ user: result.user, providerSetup });
  } catch (error) {
    if (error.statusCode >= 400 && error.statusCode < 500 && error.statusCode !== 429) recordAuthFailure(clientKey);
    next(error);
  } finally {
    if (request.body && typeof request.body === "object") request.body.password = "";
  }
});

app.post("/api/windows-host/pair", async (request, response, next) => {
  const clientKey = authClientKey(request);
  try {
    if (RESCUE_MODE || !windowsDeviceStore) throw httpError(404, "Windows Host 配对不可用");
    const retryAfter = devicePairingRetryAfter(clientKey);
    if (retryAfter > 0) {
      response.setHeader("Retry-After", String(retryAfter));
      throw httpError(429, "Windows Host 配对尝试过多，请稍后再试");
    }
    const result = await windowsDeviceStore.consumePairing(request.body || {});
    const pairedUser = multiUserStore.getUser(result.device.userId)
      || (result.device.userId === legacyUser.id ? legacyUser : null);
    if (!pairedUser || result.device.pluginIds.some((pluginId) => !pluginStore.isAuthorized(pluginId, pairedUser))) {
      await windowsDeviceStore.revoke(result.device.userId, result.device.id);
      throw httpError(403, "配对授权已变化，请从网页重新生成配对码");
    }
    clearDevicePairingFailures(clientKey);
    response.setHeader("Cache-Control", "no-store");
    response.status(201).json(result);
  } catch (error) {
    if (error.statusCode === 401) recordDevicePairingFailure(clientKey);
    next(error);
  } finally {
    if (request.body && typeof request.body === "object") request.body.code = "";
  }
});

