app.use(async (request, response, next) => {
  if (isWebdavPath(request.path)) {
    if (RESCUE_MODE) {
      response.status(404).type("text/plain").send("WebDAV is unavailable in the rescue window");
      return;
    }
    next();
    return;
  }
  if (RESCUE_MODE) {
    try {
      await refreshRescueAuthentication();
    } catch (error) {
      response.status(503).json({ error: `备用站管理员凭据暂不可用：${error.message}` });
      return;
    }
  }
  const multiUserEnabled = multiUserStore.modeSnapshot().enabled;
  // The Android builder MCP is a loopback-only, token-authenticated service.
  // It must be reachable by the local Codex stdio adapter without requiring
  // that adapter to possess a browser login cookie or password.
  if (
    request.path === "/api/plugins/android-drive-builder/mcp/call"
    && isDirectLoopbackAddress(request.socket.remoteAddress)
  ) {
    next();
    return;
  }
  if (isPublicAuthPath(request.path)) {
    next();
    return;
  }
  if (multiUserEnabled) {
    try {
      const authenticated = await multiUserStore.authenticateSession(
        sessionCookieToken(request.headers.cookie),
      );
      if (authenticated?.user && (!RESCUE_MODE || authenticated.user.role === "owner")) {
        request.user = authenticated.user;
        request.authSession = authenticated.session;
        next();
        return;
      }
    } catch (error) {
      next(error);
      return;
    }
  }

  request.user = legacyUser;
  if (!multiUserEnabled && legacySessionCanAuthenticate(request)) {
    next();
    return;
  }
  const clientKey = authClientKey(request);
  const retryAfter = authRetryAfter(clientKey);
  if (retryAfter > 0) {
    response.setHeader("Retry-After", String(retryAfter));
    response.status(429).type("text/plain").send("Too many authentication attempts");
    return;
  }
  if (AUTH && verifyBasicAuth(request.headers.authorization, AUTH) && rescueOwnerCanAuthenticate()) {
    clearAuthFailures(clientKey);
    if (multiUserEnabled) request.user = multiUserStore.getOwner() || legacyUser;
    if (!multiUserEnabled) setLegacySessionCookie(response, request);
    next();
    return;
  }
  if (multiUserEnabled) {
    if (RESCUE_MODE) {
      response.setHeader("WWW-Authenticate", 'Basic realm="WFL Codex Rescue", charset="UTF-8"');
      response.setHeader("Cache-Control", "no-store");
      response.status(401).type("text/plain").send("Owner authentication required");
      return;
    }
    if (request.path.startsWith("/api/")) {
      response.status(401).json({ error: "请先登录" });
    } else {
      response.redirect(302, `/login.html?next=${encodeURIComponent(request.originalUrl)}`);
    }
    return;
  }
  if (request.headers.authorization) {
    recordAuthFailure(clientKey);
    const blockedFor = authRetryAfter(clientKey);
    if (blockedFor > 0) {
      response.setHeader("Retry-After", String(blockedFor));
      response.status(429).type("text/plain").send("Too many authentication attempts");
      return;
    }
  }
  response.setHeader("WWW-Authenticate", 'Basic realm="WFL Codex Web Workspace", charset="UTF-8"');
  response.setHeader("Cache-Control", "no-store");
  response.status(401).type("text/plain").send("Authentication required");
});

