app.use((request, response, next) => {
  if (RESCUE_MODE && request.user?.role !== "owner") {
    response.status(403).json({ error: "独立救援服务仅允许所有者访问" });
    return;
  }
  if (!shouldRecordHttpRequest(request)) {
    next();
    return;
  }
  const startedAt = performance.now();
  httpRequestsInFlight += 1;
  let settled = false;
  const finish = () => {
    if (settled) return;
    settled = true;
    httpRequestsInFlight = Math.max(0, httpRequestsInFlight - 1);
    const operation = safeRouteTemplate(request);
    if (!operation) return;
    const statusCode = response.statusCode;
    void recordOpsTraffic({
      kind: "http",
      operation,
      method: request.method,
      statusCode,
      status: statusCode >= 400 ? "error" : "success",
      success: statusCode < 400,
      durationMs: performance.now() - startedAt,
      responseBytes: safeResponseBytes(response),
      userId: request.user?.id,
      username: request.user?.username,
    }).catch(() => {});
  };
  response.once("finish", finish);
  response.once("close", finish);
  next();
});

