app.post("/api/auth/logout", async (request, response, next) => {
  try {
    const currentBrowserSessionId = browserSessionIdentity(request);
    await scheduleMapBrowserSessionResourceRelease({
      userId: request.user.id,
      browserSessionId: currentBrowserSessionId,
    });
    await mapAiAccess?.revokeForBrowserSession({
      userId: request.user.id,
      browserSessionId: currentBrowserSessionId,
    });
    if (request.authSession) {
      disconnectAuthenticatedSessionSockets(
        request.authSession.id,
        "Session logged out",
        request.user.id,
      );
    }
    const revoked = await multiUserStore.revokeSession(
      sessionCookieToken(request.headers.cookie),
    );
    if (revoked && revoked.id !== currentBrowserSessionId) {
      await mapAiAccess?.revokeForBrowserSession({
        userId: revoked.userId || request.user.id,
        browserSessionId: revoked.id,
      });
    }
    if (revoked) disconnectAuthenticatedSessionSockets(revoked.id, "Session logged out", revoked.userId);
    clearUserSessionCookie(response, request);
    response.status(204).end();
  } catch (error) {
    next(error);
  }
});

