app.get("/api/account/official-quota", async (request, response, next) => {
  try {
    if (!canUseOfficialAccounts(request)) {
      response.setHeader("Cache-Control", "no-store");
      response.json({
        authorized: false,
        account: null,
        requiresOpenaiAuth: false,
        usage: null,
        rateLimits: null,
        queryErrors: [],
        updatedAt: null,
        stale: false,
        taskActive: false,
        refreshDeferred: false,
      });
      return;
    }
    const runtime = await runtimeForRequest(request);
    const taskActive = !runtime.taskIsIdle();
    const refreshRequested = request.query.refresh === "1";
    const cacheExpired = !runtime.officialQuotaCache
      || Date.now() - runtime.officialQuotaCache.updatedAt >= OFFICIAL_QUOTA_CACHE_TTL_MS;
    let refreshDeferred = false;

    if (runtime.bridge.ready && (refreshRequested || cacheExpired)) {
      if (taskActive) {
        refreshDeferred = true;
      } else if (!runtime.officialQuotaCache || refreshRequested) {
        await refreshOfficialQuotaCache(runtime, { timeoutMs: 8_000, force: refreshRequested }).catch(() => {});
      } else {
        void refreshOfficialQuotaCache(runtime, { timeoutMs: 8_000 }).catch(() => {});
      }
    }

    if (!runtime.officialQuotaCache && taskActive) {
      const localAccount = await readCodexChatGptAccount(runtime.user.codexHome, {
        uid: runtime.user.uid,
        gid: runtime.user.gid,
      }).catch(() => null);
      if (localAccount) {
        runtime.officialQuotaCache = {
          account: localAccount,
          requiresOpenaiAuth: false,
          usage: null,
          rateLimits: null,
          queryErrors: ["usage", "rateLimits"],
          updatedAt: Date.now(),
          stale: true,
        };
      }
    }

    response.setHeader("Cache-Control", "no-store");
    response.json({
      authorized: true,
      ...publicOfficialQuotaSnapshot(runtime),
      taskActive,
      refreshDeferred,
    });
  } catch (error) {
    next(officialAccountError(error, "无法查询官方账户额度"));
  }
});

app.patch("/api/account", async (request, response, next) => {
  try {
    assertOperationRequest(request, "account-profile-update");
    const body = request.body && typeof request.body === "object" && !Array.isArray(request.body)
      ? request.body
      : {};
    const keys = Object.keys(body);
    if (keys.length === 1 && keys[0] === "codexThreadLimit") {
      const storedUser = multiUserStore.getUser(request.user.id);
      if (storedUser) {
        await multiUserStore.updateUser(request.user.id, request.user.id, {
          codexThreadLimit: body.codexThreadLimit,
        });
      } else {
        await multiUserStore.updateSingleUserCodexThreadLimit(
          request.user.id,
          body.codexThreadLimit,
        );
      }
      const liveRuntime = runtimeByUserId.get(request.user.id);
      const refreshedUser = multiUserStore.getUser(request.user.id);
      if (liveRuntime && refreshedUser) liveRuntime.user = refreshedUser;
      liveRuntime?.codexTaskAdmissions.capacityChanged();
      response.json({
        user: publicAccountUser(refreshedUser || request.user),
        sessionRenewed: false,
      });
      return;
    }
    if (!multiUserStore.modeSnapshot().configured || !multiUserStore.getUser(request.user.id)) {
      throw httpError(409, "请先启用多用户工作区后再修改个人资料");
    }
    const result = await multiUserStore.updateOwnProfile(request.user.id, body);
    const liveRuntime = runtimeByUserId.get(request.user.id);
    if (liveRuntime) liveRuntime.user = multiUserStore.getUser(request.user.id);
    if (result.token) {
      const ownerPasswordChanged = request.user.role === "owner";
      if (ownerPasswordChanged) {
        const refreshedOwner = multiUserStore.getUser(request.user.id);
        if (refreshedOwner?.legacy && refreshedOwner.password) AUTH = { ...refreshedOwner.password };
        await requestRescueCredentialSync("owner-password-change");
      } else {
        await mapAiAccess?.revokeForUser({ userId: request.user.id });
      }
      setUserSessionCookie(response, request, result.token);
      if (!ownerPasswordChanged) {
        disconnectAuthenticatedUserSockets(request.user.id, "Password changed");
        liveRuntime?.disconnectClients("Password changed");
      }
    }
    response.json({ user: result.user, sessionRenewed: Boolean(result.token) });
  } catch (error) {
    next(error);
  } finally {
    if (request.body && typeof request.body === "object") {
      request.body.currentPassword = "";
      request.body.newPassword = "";
    }
  }
});

app.get("/api/multi-user/settings", async (request, response, next) => {
  try {
    requireAdmin(request);
    const mode = multiUserStore.modeSnapshot();
    const users = mode.configured ? multiUserStore.listUsers(request.user.id) : [];
    await opsTrafficStore.flush();
    const usernames = new Map(users.map((user) => [user.id, user.displayName || user.username]));
    const usersWithUsage = await Promise.all(users.map(async (user) => {
      const stored = multiUserStore.getUser(user.id);
      const usageRoot = stored?.legacy ? stored.projectRoot : stored?.home;
      const usedBytes = usageRoot && !stored.legacy
        ? await cachedDirectorySize(usageRoot, (stored.quotaBytes || Number.MAX_SAFE_INTEGER) + 1)
        : null;
      const tokenUsage = tokenUsageSnapshotForUser(user.id);
      const provider = await providerStatusForUser(stored || user);
      const liveRuntime = runtimeByUserId.get(user.id);
      const threadAdmission = liveRuntime?.codexTaskAdmissions.snapshot() || {
        active: 0,
        reserved: 0,
        queued: 0,
        maxActive: user.effectiveCodexThreadLimit,
      };
      const activeThreads = liveRuntime
        ? liveRuntime.taskStatus.list({ limit: 200 }).tasks.filter((task) => (
          ["queued", "running", "waiting", "stopping", "uncertain"].includes(task.status)
        ))
        : [];
      return {
        ...user,
        codexThreadUsage: threadAdmission.active,
        codexThreadAdmission: threadAdmission,
        activeCodexThreads: activeThreads,
        codexThreadLimitUpdatedByName: usernames.get(user.codexThreadLimitUpdatedBy) || null,
        usedBytes,
        tokenUsage,
        monthlyTokenUsage: tokenUsage.monthly,
        provider,
      };
    }));
    const policy = mode.configured ? await decoratedUserPolicy(request.user.id) : null;
    response.json({
      mode,
      policy: policy ? {
        ...policy,
        codexThreadLimitUpdatedByName: usernames.get(policy.codexThreadLimitUpdatedBy) || null,
      } : null,
      users: usersWithUsage,
      shares: mode.configured ? await decoratedProjectShares(request.user.id) : [],
    });
  } catch (error) {
    next(error);
  }
});

