    const owner = multiUserStore.getOwner();
    if (owner) {
      Object.assign(legacyUser, owner);
      defaultRuntime.user = owner;
      runtimeByUserId.delete("u-0000000000000000");
      runtimeByUserId.set(owner.id, defaultRuntime);
    }
    setUserSessionCookie(response, request, result.token);
    response.once("finish", () => defaultRuntime.disconnectClients("Authentication mode changed"));
    response.status(202).json({ mode: multiUserStore.modeSnapshot(), user: result.user });
