app.post("/api/multi-user/disable", async (request, response, next) => {
  try {
    assertOperationRequest(request, "multi-user-disable");
    const mapUserIds = multiUserStore.listUsers(request.user.id).map((user) => user.id);
    await multiUserStore.disable(request.user.id, request.body?.password);
    const mapAiSnapshot = mapAiAccess?.snapshot();
    for (const userId of mapAiSnapshot?.enabledUsers || []) {
      await mapAiAccess.revokeForUser({ userId });
    }
    disconnectAllAuthenticatedSessionSockets("Multi-user mode disabled");
    await Promise.allSettled(mapUserIds.map((userId) => scheduleMapUserResourceRelease({ userId })));
    for (const [userId, runtime] of runtimeByUserId) {
      if (userId !== legacyUser.id) {
        runtime.destroy("Multi-user mode disabled");
        runtimeByUserId.delete(userId);
      }
    }
    clearUserSessionCookie(response, request, { restoreLegacy: true });
    response.status(202).json({ mode: multiUserStore.modeSnapshot() });
  } catch (error) {
    next(error);
  } finally {
    if (request.body && typeof request.body === "object") request.body.password = "";
  }
});

