app.post("/api/multi-user/users/:id/provider", async (request, response, next) => {
  try {
    assertOperationRequest(request, "multi-user-provider-assign");
    requireAdmin(request);
    const target = multiUserStore.getUser(request.params.id);
    if (!target || target.status !== "active" || target.role === "owner") throw httpError(409, "目标用户不可分配供应商");
    if (request.user.role !== "owner" && target.role !== "member") throw httpError(403, "管理员只能给普通用户分配供应商");
    const actorRuntime = await runtimeForRequest(request);
    const source = actorRuntime.providerStore.getProfile(request.body?.providerId);
    if (!source) throw httpError(404, "管理员供应商不存在");
    const submittedLimits = tokenLimitPatch(request.body, target);
    const { runtime, assigned, activated } = await assignManagedProviderToUser({
      actor: request.user,
      target,
      source,
    });
    if (Object.keys(submittedLimits.patch).length) {
      await multiUserStore.updateUser(request.user.id, target.id, submittedLimits.patch);
      runtime.user = multiUserStore.getUser(target.id);
    }
    const updatedUser = multiUserStore.listUsers(request.user.id).find((user) => user.id === target.id);
    const tokenUsage = await tokenUsageForUser(target.id);
    await multiUserStore.audit("provider.assigned", request.user.id, {
      userId: target.id,
      providerId: source.id,
      assignedProfileId: assigned.id,
      ...submittedLimits.values,
    });
    response.status(201).json({
      profile: assigned,
      activeId: activated.activeId,
      user: updatedUser,
      tokenUsage,
      monthlyTokenUsage: tokenUsage.monthly,
    });
  } catch (error) {
    next(error);
  }
});

