app.post("/api/multi-user/users/:id/tier", async (request, response, next) => {
  try {
    assertOperationRequest(request, "multi-user-tier-apply");
    requireAdmin(request);
    const target = managedProviderTarget(request, request.params.id);
    const { tier, tierExpiresAt } = multiUserStore.getTierAssignment(
      request.user.id,
      request.body?.tierId,
      request.body?.tierExpiresAt,
    );
    const quotaMode = target.legacy
      ? target.quotaMode
      : await configureManagedUserQuota(target, tier.quotaBytes);
    if (target.permissions?.projectSharing && !tier.permissions.projectSharing) {
      for (const share of multiUserStore.projectSharesForUser(target.id)) {
        await revokeProjectShareAccess({
          projectPath: share.projectPath,
          sourceUser: multiUserStore.getUser(share.sourceUserId),
          targetUser: target,
          access: share.access,
        });
        await multiUserStore.removeProjectShare(request.user.id, share.id);
      }
    }
    if (tier.providerId) {
      const source = await ownerProviderProfile(tier.providerId);
      await assignManagedProviderToUser({ actor: request.user, target, source });
    } else {
      await removeManagedProviderFromUser({ actor: request.user, target });
    }
    const user = await multiUserStore.updateUser(request.user.id, target.id, {
      tierId: tier.id,
      quotaBytes: tier.quotaBytes,
      quotaMode,
      fiveHourTokenLimit: tier.fiveHourTokenLimit,
      weeklyTokenLimit: tier.weeklyTokenLimit,
      monthlyTokenLimit: tier.monthlyTokenLimit,
      permissions: tier.permissions,
      tierExpiresAt,
    });
    await enforceWindowsPluginAuthorization(user);
    const runtime = runtimeByUserId.get(user.id);
    if (runtime) {
      runtime.user = multiUserStore.getUser(user.id);
      await runtime.syncBackgroundTaskPermission();
      await runtime.wakeBackgroundTaskRetries();
    }
    await recordOpsEvent({
      type: "user.tier_applied",
      severity: "info",
      source: "user",
      title: "用户套餐已应用",
      detail: `${user.username} · ${tier.name}`,
    });
    response.json({ user, tier });
  } catch (error) {
    next(error);
  }
});

