app.post("/api/multi-user/shares", async (request, response, next) => {
  try {
    assertOperationRequest(request, "multi-user-project-share");
    requireAdmin(request);
    const runtime = await runtimeForRequest(request);
    const projectPath = path.resolve(String(request.body?.projectPath || ""));
    await assertOwnedProjectDirectory(projectPath, runtime);
    const target = multiUserStore.getUser(request.body?.targetUserId);
    if (!target || target.status !== "active") throw httpError(404, "目标用户不存在或已停用");
    const share = await multiUserStore.createProjectShare(request.user.id, {
      projectPath,
      targetUserId: target.id,
      access: request.body?.access,
    });
    try {
      await applyProjectShareAccess({
        projectPath,
        sourceUser: multiUserStore.getUser(request.user.id),
        targetUser: target,
        access: share.access,
      });
    } catch (error) {
      await multiUserStore.removeProjectShare(request.user.id, share.id).catch(() => {});
      throw error;
    }
    response.status(201).json({ share: await decorateProjectShare(share) });
  } catch (error) {
    next(error);
  }
});

app.delete("/api/multi-user/shares/:id", async (request, response, next) => {
  try {
    assertOperationRequest(request, "multi-user-project-unshare");
    requireAdmin(request);
    const existing = multiUserStore.getProjectShare(request.params.id);
    if (!existing) throw httpError(404, "共享工程授权不存在");
    const existingTarget = multiUserStore.getUser(existing.targetUserId);
    if (
      request.user.role !== "owner"
      && existing.sourceUserId !== request.user.id
      && !(request.user.role === "admin" && existingTarget?.role === "member")
    ) {
      throw httpError(403, "当前账号不能撤销这个共享工程");
    }
    await revokeProjectShareAccess({
      projectPath: existing.projectPath,
      sourceUser: multiUserStore.getUser(existing.sourceUserId),
      targetUser: existingTarget,
      access: existing.access,
    });
    await multiUserStore.removeProjectShare(request.user.id, existing.id);
    response.status(204).end();
  } catch (error) {
    next(error);
  }
});

