app.post("/api/release/candidates/:id/promote", async (request, response, next) => {
  const clientKey = `owner-confirmation:${authClientKey(request)}`;
  try {
    assertOperationRequest(request, "release-candidate-promote");
    requireOwner(request);
    if (!CANDIDATE_RELEASES_ENABLED) throw httpError(503, "此服务器未启用候选发布中心");
    if (candidatePromotionInProgress) throw httpError(409, "另一项正式提升正在执行");
    let candidate = await releaseCandidateStore.current();
    if (candidate?.phase === "promoting") {
      candidate = await reconcilePromotingCandidate(candidate);
    }
    if (!candidate || candidate.id !== request.params.id || candidate.phase !== "awaiting-approval") {
      throw httpError(409, "候选状态已经变化，请刷新后重试");
    }
    if (request.body?.actualValidationConfirmed !== true) {
      throw httpError(400, "必须确认已完成主服务器实际验证");
    }
    if (request.body?.confirmation !== candidate.id) {
      throw httpError(400, "请手动输入上方完整候选编号");
    }
    const retryAfter = authRetryAfter(clientKey);
    if (retryAfter > 0) {
      response.setHeader("Retry-After", String(retryAfter));
      throw httpError(429, "密码复验尝试过多，请稍后再试");
    }
    if (!verifyCurrentAdminPassword(request.user, request.body?.password)) {
      recordAuthFailure(clientKey);
      throw httpError(403, "当前所有者密码不正确");
    }
    clearAuthFailures(clientKey);
    candidatePromotionInProgress = true;
    try {
      await assertNoConflictingDeployment();
      await releaseCandidateStore.update(candidate.id, {
        phase: "promoting",
        detail: "正在复核源码并原子更新正式稳定通道",
        actualValidationConfirmed: true,
        actualValidationConfirmedAt: Date.now(),
        actualValidationConfirmedBy: request.user.username,
        error: null,
      }, { expectedPhases: ["awaiting-approval"] });
      const result = await promoteReleaseCandidate(candidate.id, request.user.username);
      void recordOpsEvent({
        type: "release.candidate_promoted", severity: "warning", source: "release",
        title: `v${candidate.version} 已提升为正式版本`,
        detail: `提交：${candidate.commitSha.slice(0, 12)}；操作账号：${request.user.username}`,
      }).catch(() => {});
      response.json({ ok: true, result, candidates: await releaseCandidateSnapshot() });
    } finally {
      candidatePromotionInProgress = false;
    }
  } catch (error) {
    next(error);
  } finally {
    if (request.body && typeof request.body === "object") request.body.password = "";
  }
});

app.post("/api/release/candidates/:id/discard", async (request, response, next) => {
  const clientKey = `owner-confirmation:${authClientKey(request)}`;
  try {
    assertOperationRequest(request, "release-candidate-discard");
    requireOwner(request);
    if (!CANDIDATE_RELEASES_ENABLED) throw httpError(503, "此服务器未启用候选发布中心");
    let candidate = await releaseCandidateStore.current();
    if (candidate?.phase === "promoting") {
      candidate = await reconcilePromotingCandidate(candidate);
    }
    if (!candidate || candidate.id !== request.params.id || !["awaiting-approval", "discarding", "failed"].includes(candidate.phase)) {
      throw httpError(409, "候选状态已经变化，请刷新后重试");
    }
    if (request.body?.confirmation !== candidate.id) {
      throw httpError(400, "请手动输入上方完整候选编号");
    }
    const retryAfter = authRetryAfter(clientKey);
    if (retryAfter > 0) {
      response.setHeader("Retry-After", String(retryAfter));
      throw httpError(429, "密码复验尝试过多，请稍后再试");
    }
    if (!verifyCurrentAdminPassword(request.user, request.body?.password)) {
      recordAuthFailure(clientKey);
      throw httpError(403, "当前所有者密码不正确");
    }
    clearAuthFailures(clientKey);

    if (candidateDiscardLaunchInProgress) {
      throw httpError(409, "另一项候选废弃操作正在启动，请稍后刷新状态");
    }
    candidateDiscardLaunchInProgress = candidate.id;
    try {
    if (candidate.phase === "discarding") {
      const reconciled = await reconcileDiscardingCandidate(candidate);
      if (reconciled.phase === "discarded" || reconciled.phase === "failed") {
        response.json({ ok: true, candidate: reconciled, candidates: await releaseCandidateSnapshot() });
        return;
      }
      if (reconciled.rollbackUnit) throw httpError(409, "候选回滚仍在执行，请稍后刷新状态");

      // The server may have restarted after marking the candidate as
      // discarding but before it persisted the launcher's unit. If no
      // rollback worker can be reconciled, safely resume the launch instead
      // of leaving the candidate permanently stuck in an intermediate phase.
      const rollbackVersion = reconciled.rollbackTargetVersion;
      if (!rollbackVersion) throw httpError(409, "候选回滚目标丢失，请先执行手动回滚");
      await assertNoConflictingDeployment();
      try {
        const rollback = await launchRollbackWorker(rollbackVersion, { candidateId: candidate.id });
        let launchedCandidate = await releaseCandidateStore.current();
        if (launchedCandidate?.phase === "discarding") {
          launchedCandidate = await releaseCandidateStore.update(candidate.id, {
            rollbackUnit: rollback.unit,
          }, { expectedPhases: ["discarding"] });
        }
        if (launchedCandidate?.phase === "discarded" || launchedCandidate?.phase === "failed") {
          response.json({ ok: true, candidate: launchedCandidate, candidates: await releaseCandidateSnapshot() });
          return;
        }
        response.status(202).json({
          ok: true,
          rollback,
          candidate: await releaseCandidateStore.current(),
          candidates: await releaseCandidateSnapshot(),
        });
        return;
      } catch (error) {
        const latest = await releaseCandidateStore.current().catch(() => null);
        const reconciledLatest = latest?.phase === "discarding"
          ? await reconcileDiscardingCandidate(latest).catch(() => latest)
          : latest;
        if (reconciledLatest?.phase === "discarded" || reconciledLatest?.phase === "failed") {
          response.json({ ok: true, candidate: reconciledLatest, candidates: await releaseCandidateSnapshot() });
          return;
        }
        if (reconciledLatest?.phase === "discarding" && reconciledLatest.rollbackUnit) {
          throw error;
        }
        if (reconciledLatest?.phase === "discarding") {
          await releaseCandidateStore.update(candidate.id, {
            detail: "候选废弃回滚尚未启动，可重试恢复目标版本",
            error: error.message,
          }, { expectedPhases: ["discarding"] }).catch(() => {});
        }
        throw error;
      }
    }

    const reason = request.body?.reason || "候选版本已由所有者废弃";
    const rollbackVersion = candidate.phase === "awaiting-approval"
      ? await candidateRollbackVersion(candidate)
      : null;
    if (candidate.phase === "awaiting-approval" && rollbackVersion) {
      await assertNoConflictingDeployment();
      await releaseCandidateStore.update(candidate.id, {
        phase: "discarding",
        detail: `候选已标记废弃，正在恢复 v${rollbackVersion}`,
        discardedBy: request.user.username,
        rollbackUnit: null,
        rollbackTargetVersion: rollbackVersion,
        error: null,
      }, { expectedPhases: ["awaiting-approval"] });
      try {
        const rollback = await launchRollbackWorker(rollbackVersion, { candidateId: candidate.id });
        let launchedCandidate = await releaseCandidateStore.current();
        if (launchedCandidate?.phase === "discarding") {
          launchedCandidate = await releaseCandidateStore.update(candidate.id, {
            rollbackUnit: rollback.unit,
          }, { expectedPhases: ["discarding"] });
        }
        if (launchedCandidate?.phase === "discarded" || launchedCandidate?.phase === "failed") {
          response.json({ ok: true, candidate: launchedCandidate, candidates: await releaseCandidateSnapshot() });
          return;
        }
        void recordOpsEvent({
          type: "release.candidate_discard_started", severity: "warning", source: "release",
          title: `正在恢复候选 v${candidate.version} 之前的版本`,
          detail: `目标 v${rollbackVersion}；操作账号：${request.user.username}`,
        }).catch(() => {});
        response.status(202).json({
          ok: true,
          rollback,
          candidate: await releaseCandidateStore.current(),
          candidates: await releaseCandidateSnapshot(),
        });
        return;
      } catch (error) {
        const latest = await releaseCandidateStore.current().catch(() => null);
        const reconciledLatest = latest?.phase === "discarding"
          ? await reconcileDiscardingCandidate(latest).catch(() => latest)
          : latest;
        if (reconciledLatest?.phase === "discarded" || reconciledLatest?.phase === "failed") {
          response.json({ ok: true, candidate: reconciledLatest, candidates: await releaseCandidateSnapshot() });
          return;
        }
        if (reconciledLatest?.phase === "discarding" && reconciledLatest.rollbackUnit) {
          throw error;
        }
        if (reconciledLatest?.phase === "discarding") {
          await releaseCandidateStore.update(candidate.id, {
            detail: "候选废弃回滚尚未启动，可重试恢复目标版本",
            error: error.message,
          }, { expectedPhases: ["discarding"] }).catch(() => {});
        }
        throw error;
      }
    }
    if (candidate.phase === "awaiting-approval" && await activeBackendSelectorExists()) {
      throw httpError(409, "候选正在承载流量，但没有可验证的候选前版本；为避免误停机，请先执行手动回滚");
    }
    const discarded = await releaseCandidateStore.discard(candidate.id, {
      reason,
      discardedBy: request.user.username,
    });
    void recordOpsEvent({
      type: "release.candidate_discarded", severity: "warning", source: "release",
      title: `v${candidate.version} 候选已废弃`, detail: `操作账号：${request.user.username}`,
    }).catch(() => {});
    response.json({ ok: true, candidate: discarded, candidates: await releaseCandidateSnapshot() });
    } finally {
      if (candidateDiscardLaunchInProgress === candidate.id) candidateDiscardLaunchInProgress = null;
    }
  } catch (error) {
    next(error);
  } finally {
    if (request.body && typeof request.body === "object") request.body.password = "";
  }
});

