app.post("/api/rescue/references", async (request, response, next) => {
  try {
    assertOperationRequest(request, "rescue-reference-create");
    requireOwner(request);
    if (!RESCUE_MODE) throw httpError(404, "Not found");
    const sourceThreadId = normalizeRescueReferenceSourceId(request.body?.sourceThreadId);
    const source = await requestActiveMainControl(`/references/${encodeURIComponent(sourceThreadId)}`);
    const selectedTurnIds = normalizeRescueReferenceTurnIds(request.body?.turnIds);
    const sourceTurns = Array.isArray(source?.thread?.turns) ? source.thread.turns : [];
    const selected = selectedTurnIds.length
      ? sourceTurns.filter((turn) => selectedTurnIds.includes(String(turn.id || "")))
      : sourceTurns;
    if (!selected.length) throw httpError(400, "请选择至少一条主站消息");
    const referenceTurns = selected.map((turn, index) => ({
      turnId: String(turn.id || `turn-${index + 1}`),
      ordinal: sourceTurns.indexOf(turn),
      text: referenceTurnText(turn),
    })).filter((turn) => turn.text);
    if (!referenceTurns.length) throw httpError(400, "所选主站消息没有可引用的文本");
    const reference = await defaultRuntime.rescueReferences.create({
      sourceThreadId: source.thread.id,
      sourceTitle: source.thread.name,
      sourceCwd: source.thread.cwd,
      sourceVersion: source.sourceVersion,
      sourceUpdatedAt: source.thread.updatedAt,
      turns: referenceTurns,
    });
    response.status(201).json({ reference });
  } catch (error) {
    next(error);
  }
});

