app.post("/api/rescue/component/update", async (request, response, next) => {
  const clientKey = `owner-confirmation:${authClientKey(request)}`;
  try {
    assertOperationRequest(request, "rescue-component-update");
    requireOwner(request);
    if (!RESCUE_MODE) throw httpError(404, "Not found");
    if (rescueUpdateLaunchInProgress) throw httpError(409, "独立救援组件升级正在启动");
    if (request.body?.confirmation !== "升级备用服务") {
      throw httpError(400, "请输入“升级备用服务”完成双重确认");
    }
    const retryAfter = authRetryAfter(clientKey);
    if (retryAfter > 0) {
      response.setHeader("Retry-After", String(retryAfter));
      throw httpError(429, "密码复验尝试过多，请稍后再试");
    }
    if (!verifyCurrentAdminPassword(request.user, request.body?.password)) {
      recordAuthFailure(clientKey);
      throw httpError(403, "当前所有者密码不正确");
    }
    clearAuthFailures(clientKey);
    rescueUpdateLaunchInProgress = true;
    const launch = await launchRescueComponentUpdate();
    void recordOpsEvent({
      type: "rescue.update_started",
      severity: "warning",
      source: "deployment",
      title: "所有者已启动独立救援组件升级",
      detail: `操作账号：${request.user.username}`,
    }).catch(() => {});
    response.status(202).json({ ok: true, launch });
  } catch (error) {
    next(error);
  } finally {
    rescueUpdateLaunchInProgress = false;
    if (request.body && typeof request.body === "object") request.body.password = "";
  }
});

app.post("/api/app/update/start", async (request, response, next) => {
  try {
    assertOperationRequest(request, "app-update");
    if (APP_UPDATE_DISABLED) throw httpError(503, "此环境未启用远程安全更新");
    if (appUpdateLaunchInProgress || codexUpdateLaunchInProgress || rollbackLaunchInProgress) {
      throw httpError(409, "另一项部署操作正在启动");
    }
    appUpdateLaunchInProgress = true;

    try {
      await assertNoConflictingDeployment();
      const remote = await remoteReleaseSnapshot(true);
      const snapshot = await releaseSnapshot();
      const sourcePending = snapshot.sourceVersion && snapshot.sourceVersion !== APP_VERSION;
      if (!remote.updateAvailable && !sourcePending) {
        throw httpError(409, remote.error || "当前源码和运行服务已经是最新稳定版");
      }
      await assertNoConflictingDeployment();
      const launch = await launchAppUpdateWorker({
        retryPreparedSource: sourcePending && !remote.updateAvailable,
      });
      response.status(202).json({
        ok: true,
        version: remote.version || snapshot.sourceVersion,
        ...launch,
      });
    } finally {
      appUpdateLaunchInProgress = false;
    }
  } catch (error) {
    next(error);
  }
});

