app.get("/api/ops/events", (request, response, next) => {
  try {
    const severity = request.query.severity ? String(request.query.severity) : null;
    if (severity && !["info", "warning", "critical"].includes(severity)) throw httpError(400, "事件级别筛选不正确");
    const type = request.query.type ? String(request.query.type) : null;
    if (type && !/^[a-z][a-z0-9_.-]{0,63}$/.test(type)) throw httpError(400, "事件类型筛选不正确");
    response.json({
      events: opsEventStore.query({
        limit: request.query.limit,
        before: request.query.before,
        severity,
        type,
      }),
    });
  } catch (error) {
    next(error);
  }
});

app.get("/api/ops/logs", (request, response, next) => {
  try {
    const category = String(request.query.category || "api");
    if (!["api", "rpc", "errors", "system", "warnings"].includes(category)) {
      throw httpError(400, "日志分类不正确");
    }
    if (category === "system" || category === "warnings") {
      const limit = Math.max(1, Math.min(200, Number(request.query.limit) || 100));
      const rows = category === "warnings"
        ? [
          ...opsEventStore.query({ limit, before: request.query.before, severity: "critical" }),
          ...opsEventStore.query({ limit, before: request.query.before, severity: "warning" }),
        ].sort((left, right) => right.at - left.at).slice(0, limit)
        : opsEventStore.query({ limit, before: request.query.before });
      response.json({
        category,
        rows,
      });
      return;
    }
    response.json({
      category,
      rows: opsTrafficStore.logs({ category, limit: request.query.limit, before: request.query.before }),
    });
  } catch (error) {
    next(error);
  }
});

