app.post("/api/ops/backups/:id/restore/prepare", async (request, response, next) => {
  try {
    assertOperationRequest(request, "ops-backup-restore-prepare");
    requireOwner(request);
    const backupId = String(request.params.id || "");
    if (request.body?.typedBackupId !== backupId) throw httpError(400, "输入的备份编号不一致");
    if (!verifyCurrentAdminPassword(request.user, request.body?.password)) throw httpError(403, "所有者密码不正确");
    const verified = await backupCenter.verify(backupId);
    if (verified.manifest.hostId !== await machineIdHash()) throw httpError(409, "此备份不属于当前服务器");
    if (verified.manifest.appVersion !== APP_VERSION) throw httpError(409, "备份版本与当前应用版本不一致");
    const nonce = crypto.randomBytes(24).toString("base64url");
    backupRestoreChallenges.set(nonce, { userId: request.user.id, backupId, expiresAt: Date.now() + 5 * 60 * 1000 });
    response.json({ confirmation: { nonce, backupId, expiresAt: Date.now() + 5 * 60 * 1000, manifest: verified.manifest } });
  } catch (error) {
    next(error);
  } finally {
    if (request.body && typeof request.body === "object") request.body.password = "";
  }
});

app.post("/api/ops/backups/:id/restore/execute", async (request, response, next) => {
  try {
    assertOperationRequest(request, "ops-backup-restore-execute");
    requireOwner(request);
    if (backupRestoreLaunchInProgress) throw httpError(409, "恢复任务正在启动");
    backupRestoreLaunchInProgress = true;
    await assertNoConflictingDeployment();
    const backupId = String(request.params.id || "");
    consumeBackupRestoreChallenge(request.user.id, backupId, request.body?.nonce);
    const launch = await launchBackupRestoreWorker(backupId);
    await recordOpsEvent({
      type: "backup.restore_started", severity: "warning", source: "deployment",
      title: "开始恢复数据备份", detail: `备份：${backupId} · 操作账号：${request.user.username}`,
    });
    response.status(202).json({ ok: true, backupId, ...launch });
  } catch (error) {
    next(error);
  } finally {
    backupRestoreLaunchInProgress = false;
    if (request.body && typeof request.body === "object") request.body.nonce = "";
  }
});

