app.post("/api/ops/rollback/execute", async (request, response, next) => {
  try {
    assertOperationRequest(request, "ops-rollback-execute");
    requireOwner(request);
    if (RELEASE_DISABLED) throw httpError(503, "此环境未启用手动回滚");
    if (appUpdateLaunchInProgress || codexUpdateLaunchInProgress || rollbackLaunchInProgress) {
      throw httpError(409, "另一项部署操作正在启动");
    }
    rollbackLaunchInProgress = true;
    await assertNoConflictingDeployment();
    const targetVersion = String(request.body?.targetVersion || "");
    await rollbackGuardStore.consume(request.user.id, targetVersion, request.body?.nonce);
    if (!verifyCurrentAdminPassword(request.user, request.body?.password)) {
      await recordOpsEvent({
        type: "rollback.password_rejected", severity: "warning", source: "deployment",
        title: "手动回滚密码复验失败", detail: `操作账号：${request.user.username}`,
      });
      throw httpError(403, "当前管理员密码不正确，回滚开关已自动关闭");
    }
    await verifyRollbackRelease(targetVersion, {
      runtimeDirectory: RELEASE_RUNTIME_DIR,
      sourceDirectory: SOURCE_DIR,
      backupDirectory: process.env.CODEX_DESKTOP_BACKUP_DIR,
      stateSchema: 1,
    });
    const launch = await launchRollbackWorker(targetVersion);
    await recordOpsEvent({
      type: "rollback.started", severity: "warning", source: "deployment",
      title: `开始手动回滚到 v${targetVersion}`, detail: `操作账号：${request.user.username}`,
    });
    response.status(202).json({ ok: true, targetVersion, ...launch });
  } catch (error) {
    next(error);
  } finally {
    rollbackLaunchInProgress = false;
    if (request.body && typeof request.body === "object") {
      request.body.password = "";
      request.body.nonce = "";
    }
  }
});

