app.get("/api/task/status", async (request, response, next) => {
  try {
    const runtime = await runtimeForRequest(request);
    const threadId = request.query.threadId;
    if (threadId !== undefined && (typeof threadId !== "string" || !threadId || threadId.length > 256 || /[\r\n\0]/.test(threadId))) {
      throw httpError(400, "Invalid thread ID");
    }
    const clientActiveTurnId = request.query.activeTurnId;
    if (
      clientActiveTurnId !== undefined
      && (
        typeof clientActiveTurnId !== "string"
        || !clientActiveTurnId
        || clientActiveTurnId.length > 256
        || /[\r\n\0]/.test(clientActiveTurnId)
      )
    ) {
      throw httpError(400, "Invalid active Turn ID");
    }
    const scope = request.query.scope;
    if (scope !== undefined && scope !== "threads") throw httpError(400, "Invalid task status scope");
    const includeThreads = request.query.includeThreads === "1" || scope === "threads";
    if (scope === "threads") {
      const overview = runtime.taskStatus.list({ limit: 200 });
      response.json({
        ...overview,
        admission: runtime.codexTaskAdmissions.snapshot(),
      });
      return;
    }
    let snapshot;
    if (threadId) {
      const local = runtime.taskStatus.snapshot(threadId);
      const localActive = CODEX_ACTIVE_TASK_STATUSES.has(local.status);
      const localTurnId = typeof local.turnId === "string" && local.turnId
        ? local.turnId
        : null;
      const hasExplicitClientTurnId = typeof clientActiveTurnId === "string"
        && Boolean(clientActiveTurnId);
      const clientTurnMismatch = hasExplicitClientTurnId
        && (!localActive || !localTurnId || localTurnId !== clientActiveTurnId);
      // An ordinary status poll is informational. Only a request that carries
      // the client's concrete Turn identity may trigger the expensive native
      // turns/list -> thread/read reconciliation fallback.
      if (clientTurnMismatch) {
        await runtime.reconcileNativeTaskStatus(threadId, {
          requestedTurnId: clientActiveTurnId || localTurnId,
          cwd: local.cwd,
        });
      }
      snapshot = await runtime.authoritativeTaskSnapshot(threadId, { clientActiveTurnId });
    } else {
      snapshot = runtime.taskStatus.snapshot(null);
    }
    const overview = includeThreads ? runtime.taskStatus.list({ limit: 200 }) : null;
    response.json({
      ...snapshot,
      ...(overview ? { tasks: overview.tasks } : {}),
      admission: runtime.codexTaskAdmissions.snapshot(),
    });
  } catch (error) {
    next(error);
  }
});

