app.put("/api/codex/goal/retry-settings", async (request, response, next) => {
  try {
    assertOperationRequest(request, "goal-retry-settings");
    if (typeof request.body?.unlimitedRetry !== "boolean") {
      throw httpError(400, "必须指定是否开启持续重试");
    }
    if (
      request.body?.retryFrequency !== undefined
      && !GOAL_RETRY_FREQUENCIES.includes(request.body.retryFrequency)
    ) {
      throw httpError(400, "必须选择有效的 Goal 重试频率");
    }
    const runtime = await runtimeForRequest(request);
    if (!runtime.goalRecoveryStore) throw httpError(404, "备用窗口不提供 Goal 后台重试设置");
    const previous = runtime.goalRecoveryStore.settingsSnapshot();
    const settings = await runtime.goalRecoveryStore.updateSettings({
      unlimitedRetry: request.body.unlimitedRetry,
      retryFrequency: request.body.retryFrequency ?? previous.retryFrequency,
    });
    await runtime.applyGoalRetrySettings(settings, {
      rebase: settings.unlimitedRetry && (
        !previous.unlimitedRetry
        || previous.retryFrequency !== settings.retryFrequency
      ),
    });
    response.json(goalRetrySettingsSnapshot(runtime));
  } catch (error) {
    next(error);
  }
});

app.post("/api/codex/goal/retry-now", async (request, response, next) => {
  try {
    assertOperationRequest(request, "goal-retry-now");
    const runtime = await runtimeForRequest(request);
    if (!runtime.goalRecoveryStore) throw httpError(404, "备用窗口不提供 Goal 后台恢复");
    const threadId = normalizeGoalControlThreadId(request.body?.threadId);
    const current = runtime.goalRecoveryStore.get(threadId);
    if (!current?.resumeWhenAvailable || current.suspendedReason !== "provider-unavailable") {
      throw httpError(409, "当前 Goal 不在连接恢复等待状态");
    }
    if (current.manualPauseState) throw httpError(409, "手动暂停的 Goal 需要使用继续按钮");
    const record = await runtime.goalRecoveryStore.rescheduleConnectivitySuspension(
      threadId,
      { retryDelayMs: 0 },
    );
    runtime.clearConnectivityGoalRetry(threadId);
    runtime.scheduleGoalRecovery(0, { force: true, threadId });
    runtime.scheduleConnectivityGoalRetry(record);
    response.json({
      ok: true,
      threadId,
      retry: goalRetrySettingsSnapshot(runtime).waiting.find((entry) => entry.threadId === threadId) || null,
    });
  } catch (error) {
    next(error);
  }
});

