app.post("/api/codex/worktrees", async (request, response, next) => {
  try {
    assertOperationRequest(request, "codex-worktree-create");
    const runtime = await runtimeForRequest(request);
    const store = requireCodexWorktreeStore(runtime);
    const projectPath = path.resolve(String(request.body?.projectPath || ""));
    await assertOwnedProjectDirectory(projectPath, runtime);
    await assertQuotaAvailable(runtime);
    const includeUncommitted = request.body?.includeUncommitted === true;
    // Creating a clean Worktree only reads the source repository's committed
    // HEAD and creates a separate checkout. It must be allowed while another
    // Worktree (or the source checkout) is running. Copying uncommitted source
    // files is the one case that genuinely needs the source-directory fence.
    const releaseScope = includeUncommitted
      ? runtime.acquireTaskScopeFence({
        projectPaths: [projectPath],
        message: "来源工程正在复制未提交修改，不能创建带修改的 Worktree",
      })
      : () => {};
    let worktree;
    try {
      worktree = await store.create({
        projectPath,
        baseRef: request.body?.baseRef,
        includeUncommitted,
        permanent: request.body?.permanent === true,
        label: request.body?.label,
        attachments: request.body?.attachments,
      });
    } finally {
      releaseScope();
    }
    await recordOpsEvent({
      type: "codex.worktree_created",
      severity: "info",
      source: "task",
      title: "Codex Worktree 已创建",
      detail: `用户：${runtime.user.username} · 基础：${worktree.baseRef}`,
    });
    broadcastWorktreeUpdated(runtime, worktree);
    response.status(201).json({ worktree });
  } catch (error) {
    next(error);
  }
});

