app.post("/api/codex/worktrees/:id/sync", async (request, response, next) => {
  try {
    assertOperationRequest(request, "codex-worktree-sync");
    const runtime = await runtimeForRequest(request);
    const store = requireCodexWorktreeStore(runtime);
    const current = store.get(request.params.id);
    const releaseScope = runtime.acquireTaskScopeFence({
      threadIds: [current?.threadId],
      // Sync mutates only this Worktree. Sibling Worktrees and the source
      // checkout must remain usable for parallel conversations; the source
      // commit is read as part of the sync operation itself.
      projectPaths: [current?.worktreeProjectPath],
      worktreeIds: [current?.id],
      message: "目标 Worktree 正在运行任务，不能同步",
    });
    try {
      const worktree = await store.sync(request.params.id);
      await recordOpsEvent({
        type: "codex.worktree_synced",
        severity: "info",
        source: "task",
        title: "Codex Worktree 已同步来源分支",
        detail: `用户：${runtime.user.username} · Worktree：${worktree.id} · 基准：${worktree.baseRef}`,
      });
      broadcastWorktreeUpdated(runtime, worktree);
      response.json({ worktree });
    } finally {
      releaseScope();
    }
  } catch (error) {
    next(error);
  }
});

