app.post("/api/codex/worktrees/:id/rebind", async (request, response, next) => {
  try {
    assertOperationRequest(request, "codex-worktree-rebind");
    const runtime = await runtimeForRequest(request);
    const store = requireCodexWorktreeStore(runtime);
    const threadId = request.body?.threadId;
    if (typeof threadId !== "string" || !threadId.trim()) {
      throw httpError(400, "重新绑定对话需要有效的对话 ID");
    }
    const targetId = request.params.id;
    if (request.body?.confirmation !== targetId) {
      throw httpError(400, "Worktree 重新绑定确认不匹配");
    }
    const target = store.get(targetId);
    const source = request.body?.sourceWorktreeId
      ? store.get(request.body.sourceWorktreeId)
      : store.forThread(threadId);
    const releaseScope = runtime.acquireTaskScopeFence({
      threadIds: [threadId, target?.threadId, source?.threadId],
      projectPaths: [
        target?.worktreeProjectPath,
        target?.location === "local" ? target.projectPath : null,
        source?.location === "local" ? source.projectPath : source?.worktreeProjectPath,
      ],
      worktreeIds: [target?.id, source?.id],
      message: "目标 Worktree 或对话正在运行任务，不能重新绑定",
    });
    try {
      const result = await store.rebindThread(
        targetId,
        threadId,
        request.body?.sourceWorktreeId,
      );
      await recordOpsEvent({
        type: "codex.worktree_rebind",
        severity: "info",
        source: "task",
        title: "Codex 对话已重新绑定 Worktree",
        detail: `用户：${runtime.user.username} · Worktree：${result.worktree.id}`,
      });
      broadcastWorktreeUpdated(runtime, result.worktree, result.previousWorktree);
      response.json(result);
    } finally {
      releaseScope();
    }
  } catch (error) {
    next(error);
  }
});

app.post("/api/codex/worktrees/:id/handoff", async (request, response, next) => {
  try {
    assertOperationRequest(request, "codex-worktree-handoff");
    const runtime = await runtimeForRequest(request);
    const store = requireCodexWorktreeStore(runtime);
    const target = request.body?.target;
    if (!["local", "worktree"].includes(target)) throw httpError(400, "Worktree 交接目标无效");
    const current = store.get(request.params.id);
    if (!current?.threadId) throw httpError(409, "只有绑定原生对话的 Worktree 才能交接");
    const releaseScope = runtime.acquireTaskScopeFence({
      threadIds: [current.threadId],
      // Handoff to Local writes the source checkout; handoff to another
      // location only writes the target Worktree. Do not fence the source
      // checkout for the independent Worktree-to-Worktree path.
      projectPaths: target === "local"
        ? [current.projectPath, current.worktreeProjectPath]
        : [current.worktreeProjectPath],
      worktreeIds: [current.id],
      message: "目标 Worktree 或对话正在运行任务，不能交接",
    });
    try {
      const worktree = await store.handoff(request.params.id, target);
      await recordOpsEvent({
        type: "codex.worktree_handoff",
        severity: "info",
        source: "task",
        title: `Codex 对话已交接到 ${target === "local" ? "Local" : "Worktree"}`,
        detail: `用户：${runtime.user.username} · Worktree：${worktree.id}`,
      });
      broadcastWorktreeUpdated(runtime, worktree);
      response.json({
        worktree,
        cwd: worktree.location === "local" ? worktree.projectPath : worktree.worktreeProjectPath,
      });
    } finally {
      releaseScope();
    }
  } catch (error) {
    next(error);
  }
});

app.post("/api/codex/worktrees/:id/snapshot", async (request, response, next) => {
  try {
    assertOperationRequest(request, "codex-worktree-snapshot");
    const runtime = await runtimeForRequest(request);
    const store = requireCodexWorktreeStore(runtime);
    const current = store.get(request.params.id);
    const releaseScope = runtime.acquireTaskScopeFence({
      threadIds: [current?.threadId],
      projectPaths: [current?.worktreeProjectPath],
      worktreeIds: [current?.id],
      message: "目标 Worktree 或对话正在运行任务，不能生成快照",
    });
    try {
      const worktree = await store.snapshot(request.params.id);
      broadcastWorktreeUpdated(runtime, worktree);
      response.json({ worktree });
    } finally {
      releaseScope();
    }
  } catch (error) {
    next(error);
  }
});

