app.delete("/api/codex/worktrees/:id", async (request, response, next) => {
  try {
    const purge = request.body?.purge === true;
    assertOperationRequest(request, purge ? "codex-worktree-purge" : "codex-worktree-remove");
    const runtime = await runtimeForRequest(request);
    if (request.body?.confirmation !== request.params.id) {
      throw httpError(400, "Worktree 清理确认不匹配");
    }
    const store = requireCodexWorktreeStore(runtime);
    const current = store.get(request.params.id);
    const releaseScope = runtime.acquireTaskScopeFence({
      threadIds: [current?.threadId],
      projectPaths: [current?.worktreeProjectPath],
      worktreeIds: [current?.id],
      message: "目标 Worktree 或对话正在运行任务，不能清理",
    });
    try {
      let deletedThreadId = null;
      if (purge && current?.threadId) {
        deletedThreadId = current.threadId;
        try {
          await executeBrowserRpc(runtime, "thread/delete", { threadId: deletedThreadId });
        } catch (error) {
          if (!codexRolloutMissing(error)) throw error;
        }
        const stillBound = store.forThread(deletedThreadId);
        if (stillBound?.threadId === deletedThreadId) {
          await store.unbindThread(stillBound.id, deletedThreadId);
        }
      }
      const worktree = purge
        ? await store.purge(request.params.id, { deleteBranch: request.body?.deleteBranch === true })
        : await store.remove(request.params.id, {
            snapshot: request.body?.discardSnapshot !== true,
            deleteBranch: request.body?.deleteBranch === true,
          });
      if (purge) {
        runtime.broadcast({
          type: "worktree/purged",
          payload: {
            worktreeId: request.params.id,
            threadId: deletedThreadId || worktree.unboundThreadId || null,
            projectPath: worktree.projectPath || current?.projectPath || null,
            label: worktree.label || current?.label || "Worktree 对话",
          },
        });
      } else {
        broadcastWorktreeUpdated(runtime, worktree);
      }
      response.json({ worktree });
    } finally {
      releaseScope();
    }
  } catch (error) {
    next(error);
  }
});

