app.post("/api/codex/background-tasks", async (request, response, next) => {
  try {
    assertOperationRequest(request, "codex-background-create");
    requireCodexBackgroundAccess(request);
    const runtime = await runtimeForRequest(request);
    const projectPath = path.resolve(String(request.body?.projectPath || ""));
    await assertOwnedProjectDirectory(projectPath, runtime);
    if (request.body?.destination === "existingThread") {
      const threadId = String(request.body?.threadId || "");
      if (!threadId) throw httpError(400, "回到原对话的后台任务缺少对话 ID");
    }
    const task = await requireCodexBackgroundTaskStore(runtime).create({
      ...request.body,
      projectPath,
    });
    runtime.scheduleBackgroundTaskPump(0);
    await recordOpsEvent({
      type: "codex.background_created",
      severity: "info",
      source: "task",
      title: "Codex 后台任务已创建",
      detail: `用户：${runtime.user.username} · 调度：${task.schedule.kind}`,
    });
    response.status(201).json({ task });
  } catch (error) {
    next(error);
  }
});

app.post("/api/codex/background-tasks/:id/action", async (request, response, next) => {
  try {
    assertOperationRequest(request, "codex-background-action");
    requireCodexBackgroundAccess(request);
    const runtime = await runtimeForRequest(request);
    const store = requireCodexBackgroundTaskStore(runtime);
    const action = String(request.body?.action || "");
    let task;
    if (action === "cancel") task = await runtime.cancelBackgroundTask(request.params.id);
    else if (action === "pause") task = await store.pause(request.params.id);
    else if (action === "resume") task = await store.resume(request.params.id);
    else if (action === "runNow") task = await store.resume(request.params.id, { runNow: true });
    else if (action === "retry") task = await store.retry(request.params.id);
    else if (action === "schedule") task = await store.updateSchedule(request.params.id, request.body?.schedule);
    else if (action === "retrySettings") task = await store.updateRetry(request.params.id, request.body);
    else throw httpError(400, "Codex 后台任务操作无效");
    runtime.scheduleBackgroundTaskPump(0);
    runtime.broadcastBackgroundTask(action, request.params.id);
    response.json({ task });
  } catch (error) {
    next(error);
  }
});

