app.get("/api/codex/mcp/protocol-2026", async (request, response, next) => {
  try {
    requireCodexMcpAccess(request);
    const runtime = await runtimeForRequest(request);
    assertOfficialBridgeReady(runtime);
    const [features, configRead] = await Promise.all([
      runtime.bridge.request(
        "experimentalFeature/list",
        { limit: 200 },
        { timeoutMs: 30_000 },
      ),
      runtime.bridge.request(
        "config/read",
        { includeLayers: true, cwd: runtime.defaultProject },
        { timeoutMs: 30_000 },
      ),
    ]);
    const feature = Array.isArray(features?.data)
      ? features.data.find((entry) => entry?.name === "mcp_2026_07_28")
      : null;
    response.setHeader("Cache-Control", "no-store");
    response.json({
      supported: Boolean(feature),
      stage: typeof feature?.stage === "string" ? feature.stage : null,
      persistedEnabled: configRead?.config?.features?.mcp_2026_07_28 === true,
      runtimeEnabled: feature?.enabled === true,
      appliesTo: "new-app-server-and-tasks",
    });
  } catch (error) {
    next(error);
  }
});

app.put("/api/codex/mcp/protocol-2026", async (request, response, next) => {
  try {
    assertOperationRequest(request, "codex-mcp-protocol-2026");
    requireAdmin(request);
    requireCodexMcpAccess(request);
    if (
      !request.body
      || typeof request.body !== "object"
      || Array.isArray(request.body)
      || Object.keys(request.body).some((key) => key !== "enabled")
      || typeof request.body.enabled !== "boolean"
    ) throw httpError(400, "MCP 2026 协议设置无效");
    const runtime = await runtimeForRequest(request);
    assertOfficialBridgeReady(runtime);
    const features = await runtime.bridge.request(
      "experimentalFeature/list",
      { limit: 200 },
      { timeoutMs: 30_000 },
    );
    const feature = Array.isArray(features?.data)
      ? features.data.find((entry) => entry?.name === "mcp_2026_07_28")
      : null;
    if (!feature) throw httpError(409, "当前 Codex 版本未提供 MCP 2026-07-28 功能");
    const configRead = await runtime.bridge.request(
      "config/read",
      { includeLayers: true, cwd: runtime.defaultProject },
      { timeoutMs: 30_000 },
    );
    const metadata = userCodexMemoryConfigMetadata(configRead);
    try {
      await runtime.bridge.request(
        "config/batchWrite",
        {
          edits: [{
            keyPath: "features.mcp_2026_07_28",
            value: request.body.enabled,
            mergeStrategy: "replace",
          }],
          reloadUserConfig: true,
          ...(metadata.filePath ? { filePath: metadata.filePath } : {}),
          ...(metadata.version ? { expectedVersion: metadata.version } : {}),
        },
        { timeoutMs: 30_000 },
      );
    } catch (error) {
      if (/version|stale|changed|conflict/i.test(String(error?.message || ""))) {
        throw httpError(409, "Codex 配置已在其他位置变化，请刷新后重试");
      }
      throw error;
    }
    response.json({
      name: feature.name,
      stage: feature.stage,
      enabled: request.body.enabled,
      runtimeEnabled: feature.enabled === true,
      appliesTo: "new-app-server-and-tasks",
      persisted: true,
    });
  } catch (error) {
    next(error);
  }
});

app.get("/api/codex/provider-features", async (request, response, next) => {
  try {
    const runtime = await runtimeForRequest(request);
    assertOfficialBridgeReady(runtime);
    const [accountResult, featureResult] = await Promise.all([
      runtime.bridge.request("account/read", { refreshToken: false }, { timeoutMs: 30_000 }),
      runtime.bridge.request("experimentalFeature/list", { limit: 200 }, { timeoutMs: 30_000 }),
    ]);
    const account = sanitizeOfficialAccount(accountResult).account;
    const remoteCompaction = Array.isArray(featureResult?.data)
      ? featureResult.data.find((entry) => entry?.name === "remote_compaction_v2")
      : null;
    const bedrockActive = account?.type === "amazonBedrock";
    response.setHeader("Cache-Control", "no-store");
    response.json({
      providerType: account?.type || null,
      bedrock: {
        active: bedrockActive,
        cachedWebSearch: bedrockActive,
        remoteCompaction: bedrockActive && remoteCompaction?.enabled !== false,
        remoteCompactionStage: bedrockActive && typeof remoteCompaction?.stage === "string"
          ? remoteCompaction.stage
          : null,
      },
    });
  } catch (error) {
    next(error);
  }
});

