app.post("/api/windows-host/calls", async (request, response, next) => {
  try {
    assertOperationRequest(request, "windows-host-call");
    requireWindowsHost();
    const pluginId = String(request.body?.pluginId || "");
    requireWindowsPlugin(request, pluginId);
    const normalizedParams = normalizeWindowsHostCall(pluginId, request.body?.method, request.body?.params || {});
    const leaseInput = windowsLeaseInput(request, request.body, { includeEpoch: true });
    const lease = windowsDeviceBroker.renewLease(
      leaseInput,
      pluginId === "creator-worker" ? 15 * 60_000 : 60_000,
    );
    let creatorJob = null;
    if (pluginId === "creator-worker" && request.body?.method === "creator.job.run") {
      creatorJob = await windowsCreatorJobStore.begin(lease, normalizedParams);
      if (!creatorJob.created) {
        response.json({ deduplicated: true, job: creatorJob.job, result: creatorJob.job.result });
        return;
      }
      await windowsCreatorJobStore.markRunning(lease, normalizedParams.jobId);
    }
    try {
      const result = await windowsDeviceBroker.call({
        ...leaseInput,
        method: request.body?.method,
        params: normalizedParams,
        timeoutMs: pluginId === "creator-worker" ? 15 * 60_000 : 30_000,
      });
      if (creatorJob) {
        const completion = creatorJobCompletion(result);
        const finished = await windowsCreatorJobStore.finish(lease, normalizedParams.jobId, completion);
        response.json({ result, job: finished.job });
        return;
      }
      response.json({ result });
    } catch (error) {
      if (creatorJob) {
        await windowsCreatorJobStore.finish(lease, normalizedParams.jobId, {
          status: "failed",
          summary: "Windows Host 调用中断，任务未自动重试",
          outputPath: null,
        }).catch(() => {});
      }
      throw error;
    }
  } catch (error) {
    next(error);
  }
});

