app.post("/api/plugins/secure-ssh-access/access", async (request, response, next) => {
  const clientKey = authClientKey(request);
  try {
    assertOperationRequest(request, "ssh-authorize");
    requireAdmin(request);
    assertPluginEnabled("secure-ssh-access");
    const retryAfter = sshRetryAfter(clientKey);
    if (retryAfter > 0) {
      response.setHeader("Retry-After", String(retryAfter));
      throw httpError(429, "SSH 密码尝试过多，请稍后再试");
    }
    const record = await temporarySshAccess.authorize(request.body || {});
    clearSshFailures(clientKey);
    response.status(201).json({ record });
  } catch (error) {
    if (error.sshAttemptFailed === true) recordSshFailure(clientKey);
    next(error);
  } finally {
    if (request.body && typeof request.body === "object") request.body.password = "";
  }
});

