app.delete("/api/projects", async (request, response, next) => {
  try {
    assertOperationRequest(request, "project-remove");
    if (RESCUE_MODE) throw httpError(404, "备用窗口不提供工程删除");
    const runtime = await runtimeForRequest(request);
    if (!runtime.taskIsIdle()) throw httpError(409, "当前仍有任务运行，不能移除工程");
    const projectPath = path.resolve(String(request.body?.project || ""));
    if (request.body?.confirmation !== projectPath) throw httpError(400, "工程移除确认不匹配");
    const storageRoot = projectRootForPath(runtime.projectRoots, projectPath);
    if (
      !storageRoot
      || projectPath === storageRoot
      || projectPath === runtime.defaultProject
      || projectPath === SOURCE_DIR
      || pathIsWithin(SOURCE_DIR, projectPath)
      || path.dirname(projectPath) !== path.resolve(storageRoot)
      || path.basename(projectPath).startsWith(".")
    ) {
      throw httpError(409, "不能移除系统工程、工程根目录、默认工程或隐藏目录");
    }
    await assertOwnedProjectDirectory(projectPath, runtime);
    const projectStat = await fs.lstat(projectPath);
    if (!projectStat.isDirectory() || projectStat.isSymbolicLink()) {
      throw httpError(403, "不允许移除符号链接或非目录工程");
    }
    const managedWorktree = runtime.worktreeStore?.list().find((worktree) => (
      worktree.state !== "deleted" && path.resolve(worktree.projectPath) === projectPath
    ));
    if (managedWorktree) throw httpError(409, "工程仍有 Worktree，请先处理 Worktree 后再移除");
    const realPath = await fs.realpath(projectPath);
    const trashId = crypto.randomUUID();
    const trashDirectory = path.join(runtime.user.stateDirectory, "project-trash", trashId);
    await fs.mkdir(trashDirectory, { recursive: true, mode: 0o700 });
    const trashPath = path.join(trashDirectory, path.basename(projectPath));
    await fs.rename(realPath, trashPath);
    await recordOpsEvent({
      type: "project.removed",
      severity: "warning",
      source: "task",
      title: "工程已移入可恢复回收区",
      detail: `用户：${runtime.user.username} · 工程：${projectPath} · 回收编号：${trashId}`,
    });
    response.json({
      project: { path: projectPath, name: path.basename(projectPath) },
      trashId,
      recoverable: true,
    });
  } catch (error) {
    next(error);
  }
});

