app.post(
  "/api/threads/import",
  express.raw({ type: "application/octet-stream", limit: THREAD_IMPORT_LIMIT_BYTES }),
  async (request, response, next) => {
    let runtime = null;
    let codexThreadId = null;
    try {
      assertOperationRequest(request, "thread-import");
      runtime = await runtimeForRequest(request);
      if (!runtime.bridge.ready) throw httpError(503, "Codex 服务尚未就绪");
      const projectPath = path.resolve(String(request.query.project || ""));
      await assertSafeProjectDirectory(projectPath, runtime);
      if (!Buffer.isBuffer(request.body)) throw httpError(415, "只支持 JSON 或 Markdown 对话文件");
      let filename = "";
      try {
        filename = decodeURIComponent(String(request.get("x-codex-import-filename") || ""));
      } catch {
        throw httpError(400, "导入文件名无效");
      }
      const transcript = parseThreadImport(request.body, {
        filename,
        contentType: request.get("x-codex-import-type") || "",
      });
      const importRequestId = normalizeImportRequestId(
        request.get("x-codex-import-request-id"),
      );
      const startParams = { cwd: projectPath, ephemeral: false };
      const started = await runtime.submitCodexRpc({
        submissionType: "thread-start",
        clientSubmissionId: `thread-import:${importRequestId || crypto.randomUUID()}:thread`,
        method: "thread/start",
        params: startParams,
        timeoutMs: CONVERSATION_SUBMISSION_TIMEOUT_MS,
      });
      codexThreadId = started?.thread?.id;
      if (typeof codexThreadId !== "string" || !codexThreadId) throw new Error("Codex 未返回新对话 ID");
      await injectImportedTranscript(runtime, codexThreadId, transcript, {
        submissionPrefix: `thread-import:${importRequestId || codexThreadId}`,
      });
      const record = runtime.threadImportStore.findByCodexThreadId(codexThreadId)
        || await runtime.threadImportStore.create({
          ...transcript,
          cwd: projectPath,
          codexThreadId,
        });
      runtime.rememberImportedThread(record);
      response.status(201).json({ thread: importedThreadSummary(record), format: /\.json$/i.test(filename) ? "json" : "markdown" });
    } catch (error) {
      if (runtime && codexThreadId) {
        await runtime.bridge.request("thread/delete", { threadId: codexThreadId }, { timeoutMs: 10_000 }).catch(() => {});
      }
      next(error);
    } finally {
      request.completePersistentStateOperation?.();
    }
  },
);

app.get("/api/threads/:threadId/export", async (request, response, next) => {
  try {
    const runtime = await runtimeForRequest(request);
    const imported = runtime.threadImportStore.get(request.params.threadId);
    if (!imported && isImportedThreadId(request.params.threadId)) throw httpError(404, "导入对话不存在");
    if (!imported && !runtime.bridge.ready) throw httpError(503, "Codex 服务尚未就绪");
    const thread = imported
      ? await readFullImportedThread(runtime, imported)
      : (await runtime.bridge.request("thread/read", {
        threadId: request.params.threadId,
        includeTurns: true,
      }))?.thread;
    const exported = buildThreadExport(thread);
    const format = request.query.format === "json" ? "json" : "md";
    const filename = `${sanitizeDownloadName(exported.name || request.params.threadId)}.${format}`;
    response.setHeader("Content-Disposition", `attachment; filename="${filename}"`);
    response.setHeader("Cache-Control", "no-store");
    if (format === "json") {
      response.type("application/json").send(`${JSON.stringify(exported, null, 2)}\n`);
    } else {
      response.type("text/markdown").send(renderThreadMarkdown(exported));
    }
  } catch (error) {
    next(error);
  }
});

