app.post("/api/threads/import-snapshots/:threadId/restore", async (request, response, next) => {
  try {
    assertOperationRequest(request, "thread-import-snapshot-restore");
    const runtime = await runtimeForRequest(request);
    const source = runtime.threadImportStore.get(request.params.threadId);
    if (!source?.materialized) throw httpError(404, "迁移快照不存在");
    await assertSafeProjectDirectory(source.cwd, runtime);
    const transcript = await runtime.threadImportStore.read(source.id);
    if (!transcript) throw httpError(404, "迁移快照正文不存在");
    const record = await runtime.threadImportStore.createMigration({
      name: `${source.name} 恢复副本`,
      cwd: source.cwd,
      turns: transcript.turns,
      codexThreadId: `snapshot-restore-${crypto.randomUUID()}`,
      createdAt: source.createdAt,
      updatedAt: Math.floor(Date.now() / 1_000),
      archived: false,
    });
    runtime.rememberImportedThread(record);
    response.status(201).json({ thread: importedThreadSummary(record), sourceSnapshotId: source.id });
  } catch (error) {
    next(error);
  }
});

app.get("/api/providers", async (_request, response, next) => {
  try {
    const runtime = await runtimeForRequest(_request);
    if (RESCUE_MODE) await runtime.providerStore.reload();
    const storedSnapshot = runtime.providerStore.snapshot();
    const snapshot = RESCUE_MODE ? { ...storedSnapshot, fallback: null } : storedSnapshot;
    let currentProviderId = snapshot.activeId ? managedProviderId(snapshot.activeId) : snapshot.fallback?.providerId || null;
    let currentModel = null;
    let currentProvider = null;
    if (runtime.bridge.ready) {
      try {
        const result = await runtime.bridge.request("config/read", { includeLayers: false, cwd: runtime.defaultProject });
        currentProviderId = result.config?.model_provider || currentProviderId;
        currentModel = result.config?.model || null;
        currentProvider = discoverCodexProvider(result.config, snapshot.profiles);
      } catch {
        // The stored state remains sufficient while the bridge is reconnecting.
      }
    }
    response.json({
      ...snapshot,
      currentProviderId,
      currentModel,
      currentProvider,
      canEdit: canEditProviders(_request),
      configurationRequired: RESCUE_MODE
        ? !snapshot.activeId
        : !runtime.legacy && !snapshot.activeId && !snapshot.fallback,
      rescueProviderIsolated: RESCUE_MODE,
      routing: providerRoutingPublicSnapshot(runtime),
    });
  } catch (error) {
    next(error);
  }
});

