app.post("/api/providers/failover/check", async (request, response, next) => {
  let release = null;
  let runtime = null;
  let target = null;
  try {
    assertOperationRequest(request, "provider-failover-check");
    runtime = await runtimeForRequest(request);
    if (!runtime.providerRoutingStore) throw httpError(404, "当前窗口不提供供应商连接检查");
    const key = typeof request.body?.key === "string" ? request.body.key : "";
    target = providerRoutingCatalog(runtime).find((entry) => entry.key === key) || null;
    if (!target) throw httpError(403, "供应商检查目标未授权或已经失效");
    release = beginProviderModelQuery(runtime.user.id);
    if (target.kind === "managed") {
      assertAuthorizedManagedProvider(runtime, target.id);
      const profile = runtime.providerStore.getProfile(target.id);
      if (!profile) throw httpError(404, "API 供应商不存在");
      const models = await listProviderModels(profile);
      if (!models.length || (target.model && !models.includes(target.model))) {
        throw httpError(409, "API 供应商没有返回当前模型");
      }
    } else if (target.kind === "official") {
      if (target.active) {
        const quota = await refreshOfficialQuotaCache(runtime, { timeoutMs: 15_000, force: true });
        const account = runtime.officialAccountStore.snapshot().accounts
          .find((entry) => entry.id === target.id);
        const used = maximumOfficialQuotaUsed(quota?.rateLimits, account);
        if (quota?.requiresOpenaiAuth || account?.credentialStatus === "invalid") {
          throw httpError(401, "官方账号登录已失效");
        }
        if (Number.isFinite(used) && used >= 100) throw httpError(429, "官方账号额度已用尽");
      } else if (target.credentialStatus === "invalid") {
        throw httpError(401, "官方账号登录已失效");
      }
    } else {
      if (!target.active) throw httpError(409, "请切换到此配置后再检查连接");
      const models = await runtime.bridge.request(
        "model/list",
        { limit: 100, includeHidden: false },
        { timeoutMs: 20_000 },
      );
      if (!Array.isArray(models?.data) || !models.data.length) {
        throw httpError(503, "Codex 原配置没有返回可用模型");
      }
    }
    await runtime.providerRoutingStore.recordHealth(target.key, {
      status: "valid",
      code: "models-ready",
    });
    const snapshot = providerRoutingPublicSnapshot(runtime);
    await runtime.broadcastProviderRouting();
    response.setHeader("Cache-Control", "no-store");
    response.json(snapshot);
  } catch (error) {
    if (runtime?.providerRoutingStore && target?.key) {
      const code = providerFailoverErrorCode(error);
      await runtime.providerRoutingStore.recordHealth(target.key, {
        status: ["quota", "rate-limit", "capacity"].includes(code) ? "limited" : "invalid",
        code,
      }).catch(() => {});
      await runtime.broadcastProviderRouting().catch(() => {});
    }
    next(error?.statusCode
      ? error
      : httpError(502, "供应商连接检查失败，请核对 API 地址、凭据和网络"));
  } finally {
    release?.();
    request.completePersistentStateOperation?.();
  }
});

app.put("/api/providers/failover", async (request, response, next) => {
  try {
    assertOperationRequest(request, "provider-failover-settings");
    const runtime = await runtimeForRequest(request);
    if (!runtime.providerRoutingStore) throw httpError(404, "当前窗口不提供供应商故障切换");
    if (!Array.isArray(request.body?.priority) || request.body.priority.length > 40) {
      throw httpError(400, "供应商优先级必须是最多 40 项的列表");
    }
    const current = runtime.providerRoutingStore.settingsSnapshot();
    const enabling = current.automaticFailover !== true && request.body?.automaticFailover === true;
    if (
      enabling
      && (
        request.body?.acknowledgeIdentityAndBilling !== true
        || request.body?.confirmation !== "启用自动故障切换"
      )
    ) {
      throw httpError(400, "开启自动故障切换前必须确认身份与计费可能变化");
    }
    const catalog = providerRoutingCatalog(runtime);
    const eligibleKeys = catalog.filter((target) => target.eligible).map((target) => target.key);
    await runtime.providerRoutingStore.updateSettings({
      automaticFailover: request.body?.automaticFailover === true,
      priority: request.body.priority,
    }, { eligibleKeys });
    if (current.automaticFailover && request.body?.automaticFailover !== true) {
      clearTimeout(runtime.providerFailoverTimer);
      runtime.providerFailoverTimer = null;
      const pending = runtime.providerRoutingStore.snapshot().pending;
      if (pending) {
        await runtime.providerRoutingStore.recordAudit({
          threadId: pending.threadId,
          fromKey: pending.currentKey,
          reason: pending.reason,
          result: "skipped",
          code: "disabled",
        });
        await runtime.providerRoutingStore.setPendingFailover(null);
      }
    } else if (request.body?.automaticFailover === true) {
      runtime.schedulePendingProviderFailover(0);
    }
    const snapshot = providerRoutingPublicSnapshot(runtime);
    await runtime.broadcastProviderRouting();
    response.setHeader("Cache-Control", "no-store");
    response.json(snapshot);
  } catch (error) {
    next(error);
  } finally {
    if (request.body && typeof request.body === "object") request.body.confirmation = "";
  }
});

