app.post("/api/claude/component/install", async (request, response, next) => {
  try {
    assertOperationRequest(request, "claude-component-install");
    requireAdmin(request);
    if (RESCUE_MODE) throw httpError(404, "备用窗口不提供 Claude Code 组件安装");
    if (claudeInstallLaunchInProgress) throw httpError(409, "Claude Code 安装任务正在启动");
    const component = await claudeComponentSnapshot();
    if (!component.installSupported) throw httpError(409, "当前服务器架构不支持网页安装 Claude Code");
    if (component.pendingDecision) throw httpError(409, "请先决定保留新版或恢复上一版 Claude Code");
    let repair = false;
    if (component.ready) {
      const compatibility = await claudeCompatibilitySnapshot({ refresh: true });
      repair = compatibility.activationAllowed !== true;
    }
    claudeInstallLaunchInProgress = true;
    claudeCompatibilityCache = null;
    try {
      const launch = await launchClaudeInstallWorker({ repair });
      void recordOpsEvent({
        type: "claude.component_install_started",
        severity: "info",
        source: "deployment",
        title: "Claude Code 可选组件安装已启动",
        detail: `操作账号：${request.user.username}`,
      }).catch(() => {});
      response.status(202).json({ ok: true, ...launch });
    } finally {
      claudeInstallLaunchInProgress = false;
    }
  } catch (error) {
    next(error);
  }
});

app.post("/api/claude/component/decision", async (request, response, next) => {
  try {
    assertOperationRequest(request, "claude-component-decision");
    requireAdmin(request);
    if (RESCUE_MODE) throw httpError(404, "备用窗口不提供 Claude Code 组件管理");
    const decision = request.body?.decision;
    if (!["keep", "rollback"].includes(decision)) throw httpError(400, "Claude Code 版本决定无效");
    if (claudeInstallLaunchInProgress) throw httpError(409, "Claude Code 组件任务正在启动");
    const component = await claudeComponentSnapshot();
    if (!component.pendingDecision) throw httpError(409, "当前没有待决定的 Claude Code 升级");
    claudeInstallLaunchInProgress = true;
    claudeCompatibilityCache = null;
    try {
      const launch = await launchClaudeInstallWorker({ decision });
      response.status(202).json({ ok: true, decision, ...launch });
    } finally {
      claudeInstallLaunchInProgress = false;
    }
  } catch (error) {
    next(error);
  }
});

