app.get("/api/claude", async (request, response, next) => {
  try {
    const runtime = await runtimeForRequest(request);
    if (!runtime.claudeRuntime) throw httpError(404, "备用窗口保持 Codex 运行时");
    const permissions = {
      runtime: canUseClaudePermission(request, "claudeRuntime"),
      officialLogin: canUseClaudePermission(request, "claudeOfficialLogin"),
      providers: canUseClaudePermission(request, "claudeProviders"),
      extensions: canUseClaudePermission(request, "claudeExtensions"),
      mcp: canUseClaudePermission(request, "claudeMcp"),
      hooks: canUseClaudePermission(request, "claudeHooks"),
      memory: canUseClaudePermission(request, "claudeMemory"),
      background: canUseClaudePermission(request, "claudeBackground"),
      worktree: canUseClaudePermission(request, "claudeWorktree"),
      proxy: canUseClaudePermission(request, "claudeProxy"),
      structuredOutput: canUseClaudePermission(request, "claudeStructuredOutput"),
      ultraReview: canUseClaudePermission(request, "claudeUltraReview"),
      projectPurge: canUseClaudePermission(request, "claudeProjectPurge"),
      betaHeaders: canUseClaudePermission(request, "claudeBetaHeaders"),
    };
    const [officialStatus, mcpServers, compatibility] = await Promise.all([
      permissions.officialLogin
        ? runtime.claudeRuntime.officialStatus()
        : Promise.resolve({ loggedIn: false, restricted: true }),
      permissions.mcp
        ? runtime.claudeRuntime.listMcpServers()
        : Promise.resolve([]),
      claudeCompatibilitySnapshot(),
    ]);
    const providerSnapshot = permissions.providers
      ? runtime.claudeStore.snapshot()
      : { activeId: null, profiles: [] };
    const publicRuntime = publicClaudeRuntimeStatus(runtime.user, runtime.claudeRuntime.snapshot());
    const official = publicClaudeOfficialStatus(runtime.user, officialStatus);
    response.setHeader("Cache-Control", "no-store");
    response.json({
      ...providerSnapshot,
      official,
      mcpServers,
      compatibility,
      taskSettings: runtime.claudeRuntime.taskSettingsSnapshot(),
      permissions,
      canEdit: permissions.providers,
      runtime: publicRuntime,
    });
  } catch (error) {
    next(error);
  }
});

