app.post("/api/claude/background-agents", async (request, response, next) => {
  try {
    assertOperationRequest(request, "claude-background-start");
    const runtime = await runtimeForRequest(request);
    requireClaudeRuntime(runtime);
    const cwd = await validateClaudeBackgroundCwd(request.body?.cwd, runtime);
    const options = normalizeClaudeBackgroundOptions(request.body || {});
    options.additionalDirectories = await validateClaudeAdditionalDirectories(
      options.additionalDirectories,
      runtime,
      cwd,
    );
    assertClaudePermissionMode(runtime, options.permissionMode);
    assertClaudeAgentAccess(runtime, options.agent);
    assertClaudeSessionPluginAccess(runtime, options);
    assertClaudeMcpSessionConfigAccess(runtime, options);
    if (options.includeHooks === true) requireClaudeAccess(request, "claudeHooks");
    const agent = await runtime.withTaskAdmission(async () => {
      await assertQuotaAvailable(runtime);
      await assertTokenQuotaAvailable(runtime);
      return runtime.claudeRuntime.startBackgroundAgent({ ...options, cwd });
    });
    response.status(201).json({
      agent,
    });
  } catch (error) {
    next(error);
  }
});

