app.post("/api/claude/providers/probe", async (request, response, next) => {
  let release = null;
  try {
    assertOperationRequest(request, "claude-provider-probe");
    requireClaudeAccess(request, "claudeProviders");
    const runtime = await runtimeForRequest(request);
    requireClaudeRuntime(runtime);
    const input = request.body && typeof request.body === "object" ? request.body : {};
    const id = typeof input.id === "string" && input.id ? input.id : null;
    const stored = id ? runtime.claudeStore.getProfile(id) : null;
    if (id && !stored) throw httpError(404, "Claude API 供应商不存在");
    if (input.baseUrl !== undefined && (typeof input.baseUrl !== "string" || input.baseUrl.length > 2048)) {
      throw httpError(400, "Claude Base URL 无效");
    }
    if (input.apiKey !== undefined && (typeof input.apiKey !== "string" || input.apiKey.length > 4096)) {
      throw httpError(400, "Claude API Key 无效");
    }
    const baseUrl = typeof input.baseUrl === "string" && input.baseUrl.trim()
      ? input.baseUrl.trim()
      : stored?.baseUrl;
    const apiKey = typeof input.apiKey === "string" && input.apiKey.trim()
      ? input.apiKey.trim()
      : stored?.apiKey;
    release = beginProviderModelQuery(runtime.user.id);
    response.setHeader("Cache-Control", "no-store");
    response.json(await probeClaudeProvider({ baseUrl, apiKey }));
  } catch (error) {
    next(error);
  } finally {
    release?.();
    request.completePersistentStateOperation?.();
  }
});

