app.post("/api/claude/official/login/start", async (request, response, next) => {
  try {
    assertOperationRequest(request, "claude-official-login-start");
    requireClaudeAccess(request, "claudeOfficialLogin");
    const runtime = await runtimeForRequest(request);
    requireClaudeRuntime(runtime);
    const browserManager = requireClaudeOfficialLoginBrowser();
    if (!runtime.claudeRuntime.snapshot().officialLoginRunning) {
      await browserManager.close(runtime.user.id);
    }
    const login = await runtime.claudeRuntime.startOfficialLogin(request.body?.accountId);
    try {
      const browser = await browserManager.start({
        userId: runtime.user.id,
        loginId: login.loginId,
        authUrl: login.authorizationUrl,
        viewport: request.body?.viewport,
        proxy: login.accountId
          ? runtime.claudeOfficialAccountStore?.privateProxy(login.accountId)
          : null,
      });
      response.status(202).json({
        login: {
          running: true,
          accountId: login.accountId,
          requiresCode: login.requiresCode === true,
          codeSubmitted: login.codeSubmitted === true,
          expiresAt: login.expiresAt,
          browser,
        },
      });
    } catch (error) {
      await runtime.claudeRuntime.cancelOfficialLogin(login.loginId);
      throw error;
    }
  } catch (error) {
    next(error);
  }
});

