app.put("/api/providers/official/accounts/:id/proxy", async (request, response, next) => {
  let runtime = null;
  let previousProxy = null;
  let previousHealth = null;
  let changedActive = false;
  try {
    assertOperationRequest(request, "official-proxy-save");
    requireOfficialAccountAccess(request);
    runtime = await runtimeForRequest(request);
    assertOfficialBridgeReady(runtime);
    const store = runtime.officialAccountStore;
    if (!store) throw httpError(409, "当前窗口不支持官方账号代理");
    const accountId = request.params.id;
    previousProxy = store.privateProxy(accountId);
    previousHealth = store.proxyHealth(accountId);
    const proxy = requestedOfficialProxy(runtime, {
      ...(request.body || {}),
      proxyAccountId: accountId,
    });
    const health = proxy ? await testOfficialProxyForRuntime(proxy) : null;
    changedActive = store.snapshot().activeId === accountId;
    if (changedActive) {
      if (runtime.providerSwitchInProgress) throw httpError(409, "正在切换 API 供应商");
      if (officialAccountActions.pendingLogin(runtime.user.id, runtime.officialAccountContext())) {
        throw httpError(409, "请先完成或取消当前官方登录");
      }
      runtime.providerSwitchInProgress = true;
      if (!runtime.taskIsIdle()) {
        throw httpError(409, "当前任务执行中，完成或终止后才能切换账号代理");
      }
    }
    await store.setProxy(accountId, proxy, health);
    if (changedActive) await configureRuntimeOfficialProxy(runtime, proxy, { restart: true });
    response.json({ authorized: true, ...await officialAccountSnapshot(runtime) });
  } catch (error) {
    if (changedActive) {
      try {
        await runtime.officialAccountStore?.setProxy(request.params.id, previousProxy, previousHealth);
        await configureRuntimeOfficialProxy(runtime, previousProxy, { restart: true });
      } catch {}
    }
    next(officialProxyFailure(error));
  } finally {
    if (runtime && changedActive) runtime.providerSwitchInProgress = false;
    if (request.body?.proxy && typeof request.body.proxy === "object") request.body.proxy.password = "";
  }
});

app.post("/api/providers/official/login/start", async (request, response, next) => {
  let runtime = null;
  let result = null;
  let selectedProxy = null;
  let restoreProxy = null;
  let proxyConfigurationAttempted = false;
  let loginContext = null;
  try {
    assertOperationRequest(request, "official-login-start");
    requireOfficialAccountAccess(request);
    runtime = await runtimeForRequest(request);
    if (runtime.providerSwitchInProgress) throw httpError(409, "正在切换 API 供应商");
    assertOfficialBridgeReady(runtime);
    runtime.providerSwitchInProgress = true;
    if (!runtime.taskIsIdle()) throw httpError(409, "当前任务执行中，完成或终止后才能开始官方登录");
    const browserManager = requireOfficialLoginBrowser();
    const existing = officialAccountActions.pendingLogin(
      runtime.user.id,
      runtime.officialAccountContext(),
    );
    if (existing) {
      const decorated = decoratePendingOfficialLogin(runtime.user.id, existing);
      if (decorated?.browser?.active) {
        response.json({ pendingLogin: decorated });
        return;
      }
      const stale = officialAccountActions.discardLogin(
        runtime.user.id,
        null,
        runtime.officialAccountContext(),
      );
      if (stale) {
        await runtime.bridge.request("account/login/cancel", { loginId: stale.loginId }, { timeoutMs: 15_000 }).catch(() => {});
        await restoreOfficialProxyAfterLogin(runtime, stale);
      }
    }
    runtime.bumpOfficialAccountEpoch();
    selectedProxy = requestedOfficialProxy(runtime, request.body || {});
    restoreProxy = runtime.officialAccountStore?.privateProxy() || null;
    const proxyHealth = selectedProxy ? await testOfficialProxyForRuntime(selectedProxy) : null;
    runtime.officialCredentialFailureCount = 0;
    proxyConfigurationAttempted = true;
    await configureRuntimeOfficialProxy(runtime, selectedProxy, { restart: true });
    await runtime.waitForAuthHandoffIdle();
    loginContext = runtime.officialAccountContext();
    result = await runtime.bridge.request(
      "account/login/start",
      {
        type: "chatgpt",
        codexStreamlinedLogin: true,
        useHostedLoginSuccessPage: true,
        appBrand: "codex",
      },
      { timeoutMs: 30_000 },
    );
    if (!runtime.officialAccountContextIsCurrent(loginContext)) {
      throw httpError(409, "官方账号已切换，请重新开始登录");
    }
    const pendingLogin = officialAccountActions.rememberLogin(runtime.user.id, result, {
      proxy: selectedProxy,
      proxyHealth,
      restoreProxy,
      accountContext: loginContext,
    });
    try {
      const browser = await browserManager.start({
        userId: runtime.user.id,
        loginId: result.loginId,
        authUrl: result.authUrl,
        viewport: request.body?.viewport,
        proxy: selectedProxy,
      });
      response.status(201).json({ pendingLogin: { ...pendingLogin, browser } });
    } catch (error) {
      const pending = officialAccountActions.discardLogin(
        runtime.user.id,
        result.loginId,
        loginContext,
      );
      await runtime.bridge.request(
        "account/login/cancel",
        { loginId: result.loginId },
        { timeoutMs: 15_000 },
      ).catch(() => {});
      await restoreOfficialProxyAfterLogin(runtime, pending);
      proxyConfigurationAttempted = false;
      throw error;
    }
  } catch (error) {
    const contextCurrent = runtime
      && (!loginContext || runtime.officialAccountContextIsCurrent(loginContext));
    if (runtime && proxyConfigurationAttempted && contextCurrent) {
      const pending = officialAccountActions.discardLogin(
        runtime.user.id,
        result?.loginId || null,
        loginContext || undefined,
      );
      if (result?.loginId) {
        await runtime.bridge.request(
          "account/login/cancel",
          { loginId: result.loginId },
          { timeoutMs: 15_000 },
        ).catch(() => {});
      }
      if (pending) await restoreOfficialProxyAfterLogin(runtime, pending);
      else await configureRuntimeOfficialProxy(runtime, restoreProxy, { restart: true }).catch(() => {});
    }
    next(error?.proxyCode ? officialProxyFailure(error) : officialAccountError(error, "无法开始官方登录"));
  } finally {
    if (runtime) runtime.providerSwitchInProgress = false;
    if (request.body?.proxy && typeof request.body.proxy === "object") request.body.proxy.password = "";
  }
});

