app.get("/api/providers/official/login/browser/stream", (request, response, next) => {
  let unsubscribe = null;
  let heartbeat = null;
  let ready = false;
  let blocked = false;
  let pending = null;
  let closed = false;

  const writePayload = (payload) => {
    if (closed || response.destroyed || response.writableEnded) return;
    if (payload?.type === "closed") {
      response.write(`data: ${JSON.stringify(payload)}\n\n`);
      response.end();
      return;
    }
    if (blocked) {
      pending = payload;
      return;
    }
    blocked = !response.write(`data: ${JSON.stringify(payload)}\n\n`);
  };
  const listener = (payload) => {
    if (!ready) {
      pending = payload;
      return;
    }
    writePayload(payload);
  };
  const cleanup = () => {
    if (closed) return;
    closed = true;
    clearInterval(heartbeat);
    unsubscribe?.();
    unsubscribe = null;
    pending = null;
  };

  try {
    requireOfficialAccountAccess(request);
    unsubscribe = requireOfficialLoginBrowser().subscribe(request.user.id, listener);
    response.status(200);
    response.setHeader("Content-Type", "text/event-stream; charset=utf-8");
    response.setHeader("Cache-Control", "no-store, no-cache, must-revalidate, no-transform");
    response.setHeader("Pragma", "no-cache");
    response.setHeader("Connection", "keep-alive");
    response.setHeader("X-Accel-Buffering", "no");
    response.flushHeaders?.();
    response.write("retry: 1000\n\n");
    ready = true;
    if (pending) {
      const initial = pending;
      pending = null;
      writePayload(initial);
    }
    heartbeat = setInterval(() => {
      if (!blocked && !response.destroyed && !response.writableEnded) response.write(": keepalive\n\n");
    }, 15_000);
    heartbeat.unref?.();
    response.on("drain", () => {
      blocked = false;
      if (!pending) return;
      const latest = pending;
      pending = null;
      writePayload(latest);
    });
    response.on("close", cleanup);
    response.on("error", cleanup);
  } catch (error) {
    cleanup();
    next(error);
  }
});

