app.post("/api/providers/official/activate", async (request, response, next) => {
  try {
    assertOperationRequest(request, "official-activate");
    requireOfficialAccountAccess(request);
    const runtime = await runtimeForRequest(request);
    if (runtime.providerSwitchInProgress) throw httpError(409, "正在切换 API 供应商");
    assertOfficialBridgeReady(runtime);
    runtime.providerSwitchInProgress = true;
    if (!runtime.taskIsIdle()) throw httpError(409, "其他项目仍有任务运行，完成或终止后才能切换供应商");
    const account = await readOfficialAccount(runtime);
    if (account.account?.type !== "chatgpt") throw httpError(409, "请先完成官方账号登录");
    const snapshot = runtime.providerStore.snapshot();
    let officialModel = snapshot.fallback?.providerId === "openai" ? snapshot.fallback.model : null;
    if (!snapshot.fallback && !snapshot.activeId) {
      const current = await runtime.bridge.request("config/read", {
        includeLayers: false,
        cwd: runtime.defaultProject,
      });
      if (!current.config?.model_provider || current.config.model_provider === "openai") {
        officialModel = current.config?.model || null;
      }
    }
    await runtime.providerStore.setFallback(
      { providerId: "openai", model: officialModel },
      { replace: true },
    );
    const activated = await activateFallbackProvider(runtime);
    await runtime.broadcastProviderRouting();
    response.json(activated);
  } catch (error) {
    next(officialAccountError(error, "无法启用官方配置"));
  } finally {
    const runtime = runtimeByUserId.get(request.user?.id);
    if (runtime) runtime.providerSwitchInProgress = false;
  }
});

