app.post("/api/providers/official/workspace-messages/read", async (request, response, next) => {
  try {
    assertOperationRequest(request, "official-workspace-messages-read");
    requireOfficialAccountAccess(request);
    requireCodexWorkspaceMessages(request);
    const runtime = await runtimeForRequest(request);
    assertOfficialBridgeReady(runtime);
    const storeSnapshot = runtime.officialAccountStore?.snapshot();
    const accountId = storeSnapshot?.activeId || null;
    if (!accountId) throw httpError(409, "当前没有活动的官方账号");
    const current = runtime.officialQuotaCache?.workspaceMessages;
    if (!current) throw httpError(409, "请先刷新官方账号消息");
    const messageIds = current?.messages?.map((message) => message.messageId) || [];
    await runtime.officialAccountStore.acknowledgeWorkspaceMessages(messageIds, { accountId });
    if (
      runtime.officialQuotaCache?.workspaceMessages === current
      && runtime.officialAccountStore.snapshot().activeId === accountId
    ) {
      runtime.officialQuotaCache.workspaceMessages = {
        ...runtime.officialQuotaCache.workspaceMessages,
        unreadCount: 0,
        messages: runtime.officialQuotaCache.workspaceMessages.messages.map((message) => ({
          ...message,
          unread: false,
        })),
      };
    }
    response.json({
      ok: true,
      workspaceMessages: publicOfficialWorkspaceMessages(runtime),
    });
  } catch (error) {
    next(officialAccountError(error, "无法确认工作区消息"));
  }
});

app.post("/api/providers/official/credits-nudge", async (request, response, next) => {
  const creditType = request.body?.creditType;
  let progressKey = null;
  let runtime = null;
  let accountId = null;
  let attempted = false;
  try {
    assertOperationRequest(request, "official-credits-nudge");
    requireOfficialAccountAccess(request);
    requireCodexWorkspaceMessages(request);
    if (!["credits", "usage_limit"].includes(creditType)) {
      throw httpError(400, "额度提醒类型无效");
    }
    if (request.body?.confirmation !== "发送额度提醒") {
      throw httpError(400, "请输入“发送额度提醒”完成确认");
    }
    runtime = await runtimeForRequest(request);
    assertOfficialBridgeReady(runtime);
    const snapshot = runtime.officialAccountStore?.snapshot();
    const active = snapshot?.accounts?.find((account) => account.id === snapshot.activeId);
    if (!active || active.credentialStatus === "invalid") {
      throw httpError(409, "当前官方账号登录已失效，请重新登录");
    }
    accountId = active.id;
    const quota = await refreshOfficialQuotaCache(runtime, { timeoutMs: 15_000, force: true });
    if (
      quota.account?.type !== "chatgpt"
      || quota.workspaceMessages?.featureEnabled !== true
      || runtime.officialAccountStore.snapshot().activeId !== accountId
    ) {
      throw httpError(409, "当前官方账号未开放额度提醒");
    }
    progressKey = `${request.user?.id || "unknown"}:${accountId}:${creditType}`;
    if (officialCreditsNudgesInProgress.has(progressKey)) {
      throw httpError(409, "额度提醒正在发送，请勿重复提交");
    }
    officialCreditsNudgesInProgress.add(progressKey);
    const cooldown = runtime.officialAccountStore.creditsNudgeCooldown(
      creditType,
      OFFICIAL_CREDITS_NUDGE_COOLDOWN_MS,
      { accountId },
    );
    if (!cooldown.allowed) {
      const seconds = Math.max(1, Math.ceil(cooldown.retryAfterMs / 1_000));
      response.setHeader("Retry-After", String(seconds));
      throw httpError(429, `额度提醒已发送，请在 ${Math.ceil(seconds / 60)} 分钟后重试`);
    }
    attempted = true;
    await runtime.bridge.request(
      "account/sendAddCreditsNudgeEmail",
      { creditType },
      { timeoutMs: 30_000 },
    );
    const result = await runtime.officialAccountStore.recordCreditsNudge(
      creditType,
      "sent",
      { accountId },
    );
    response.json({
      ok: true,
      creditType: result.creditType,
      sentAt: result.at,
      cooldownUntil: result.at + OFFICIAL_CREDITS_NUDGE_COOLDOWN_MS,
    });
  } catch (error) {
    if (runtime && attempted && accountId && ["credits", "usage_limit"].includes(creditType)) {
      await runtime.officialAccountStore?.recordCreditsNudge(
        creditType,
        "failed",
        { accountId },
      ).catch(() => {});
    }
    next(officialAccountError(error, "无法发送额度提醒"));
  } finally {
    if (progressKey) officialCreditsNudgesInProgress.delete(progressKey);
    if (request.body && typeof request.body === "object") request.body.confirmation = "";
  }
});

