app.post("/api/codex/feedback/upload", async (request, response, next) => {
  let releaseUpload = null;
  let previewRecord = null;
  let runtime = null;
  try {
    assertOperationRequest(request, "codex-feedback-upload");
    requireCodexFeedbackAccess(request);
    if (request.body?.confirmation !== "submit-safe-feedback") {
      throw httpError(400, "请先检查脱敏预览并确认上传");
    }
    const previewId = String(request.body?.previewId || "");
    if (!/^feedback-[a-f0-9]{24}$/.test(previewId)) throw httpError(400, "反馈预览编号无效");
    pruneCodexFeedbackPreviews();
    previewRecord = codexFeedbackPreviews.get(previewId) || null;
    if (!previewRecord || previewRecord.userId !== request.user?.id) {
      throw httpError(404, "反馈预览已失效，请重新生成");
    }
    codexFeedbackPreviews.delete(previewId);
    runtime = await runtimeForRequest(request);
    assertOfficialBridgeReady(runtime);
    releaseUpload = beginCodexFeedbackUpload(runtime.user.id);
    const attachment = codexFeedbackAttachment(previewRecord.preview);
    let attachmentPath = null;
    try {
      if (attachment) attachmentPath = await writeCodexFeedbackAttachment(runtime, attachment);
      await runtime.bridge.request(
        "feedback/upload",
        codexFeedbackUploadParams(previewRecord.preview, attachmentPath),
        { timeoutMs: 60_000 },
      );
    } finally {
      if (attachmentPath) await fs.unlink(attachmentPath).catch(() => {});
    }
    const submittedAt = Date.now();
    void recordCodexFeedbackOpsEvent({
      request,
      status: "success",
      classification: previewRecord.preview.classification,
    });
    response.status(201).json({ ok: true, submittedAt });
  } catch (error) {
    if (previewRecord) {
      void recordCodexFeedbackOpsEvent({
        request,
        status: "failed",
        classification: previewRecord.preview.classification,
      });
    }
    next(codexFeedbackUploadError(error));
  } finally {
    releaseUpload?.();
    if (request.body && typeof request.body === "object") request.body.confirmation = "";
  }
});

