app.post("/api/images/compatibility-probe", async (request, response) => {
  const abortController = new AbortController();
  let completed = false;
  const cancel = () => {
    if (!completed && !abortController.signal.aborted) abortController.abort();
  };
  request.once("aborted", cancel);
  response.once("close", cancel);
  try {
    assertOperationRequest(request, "image-api-probe");
    requireProviderEditor(request);
    if (!request.user?.legacy && !["owner", "admin"].includes(request.user?.role)) {
      throw imageExecutionError(403, "IMAGE_PROBE_FORBIDDEN", "只有管理员可以运行可能计费的图片兼容性探测");
    }
    if (request.body?.acknowledgeCharges !== true) {
      throw imageExecutionError(400, "IMAGE_PROBE_ACKNOWLEDGEMENT_REQUIRED", "必须确认兼容性探测会向供应商发起可能计费的真实请求");
    }
    if (!imageExecutionQueue || !imageWorkerRunner) {
      throw imageExecutionError(503, "IMAGE_WORKER_UNAVAILABLE", "独立图片 Worker 当前不可用");
    }
    const runtime = await runtimeForRequest(request);
    const imageApi = privateImageApiSnapshot(runtime.providerStore.getImageApi());
    if (!imageApi) throw imageExecutionError(409, "IMAGE_PROVIDER_NOT_CONFIGURED", "请先保存图片供应商配置");
    const tests = normalizeImageCompatibilityProbeTests(request.body?.tests, imageApi);
    const browserSessionId = browserSessionIdentity(request);
    const admitted = imageExecutionQueue.enqueue({
      identity: { userId: runtime.user.id, browserSessionId },
      payload: {
        kind: "compatibility-probe",
        imageApi,
        probe: {
          tests,
          quality: "low",
          user: createImageProviderUserIdentifier({ userId: runtime.user.id, secret: SESSION_TOKEN }),
        },
        probeContext: {
          userId: runtime.user.id,
          authSession: normalizeImageTaskAuthSession(request.authSession, runtime.user.id),
        },
      },
    }, {
      signal: abortController.signal,
      onEvent: (event) => {
        if (event.type === "usage" && event.usage) {
          recordImageUsage(runtime, ["generate", "edit", "outpaint"].includes(event.operation)
            ? event.operation
            : "generate", event.usage);
        }
      },
    });
    const result = await admitted.promise;
    completed = true;
    response.setHeader("Cache-Control", "no-store");
    response.status(200).json(result.response);
  } catch (error) {
    completed = true;
    sendImageExecutionError(response, error);
  } finally {
    request.off("aborted", cancel);
    response.off("close", cancel);
    request.completePersistentStateOperation?.();
  }
});

