app.get("/api/images/v2/partial/:token", async (request, response, next) => {
  let opened = null;
  let streamOwnsHandle = false;
  try {
    if (!imagePartialPreviewStore) throw httpError(404, "救援窗口不提供图片流式预览");
    opened = await imagePartialPreviewStore.open(request.params.token, {
      userId: request.user.id,
      browserSessionId: browserSessionIdentity(request),
      windowId: request.query.windowId,
      operationId: request.query.operationId,
    });
    response.status(200);
    response.setHeader("Content-Type", opened.metadata.mediaType);
    response.setHeader("Content-Length", String(opened.metadata.size));
    response.setHeader("Cache-Control", "private, no-store, max-age=0");
    response.setHeader("X-Content-Type-Options", "nosniff");
    response.setHeader("Cross-Origin-Resource-Policy", "same-origin");
    const stream = opened.handle.createReadStream({ autoClose: true });
    streamOwnsHandle = true;
    await new Promise((resolve, reject) => {
      let settled = false;
      const finish = (error = null) => {
        if (settled) return;
        settled = true;
        stream.off("error", onError);
        response.off("finish", onFinish);
        response.off("close", onClose);
        if (error) reject(error);
        else resolve();
      };
      const onError = (error) => finish(error);
      const onFinish = () => finish();
      const onClose = () => {
        if (!response.writableEnded) stream.destroy();
        finish();
      };
      stream.once("error", onError);
      response.once("finish", onFinish);
      response.once("close", onClose);
      stream.pipe(response);
    });
  } catch (error) {
    if (response.headersSent) response.destroy(error);
    else next(error);
  } finally {
    if (opened?.handle && !streamOwnsHandle) await opened.handle.close().catch(() => {});
  }
});

app.post("/api/images/v2/execute", async (request, response) => {
  const abortController = new AbortController();
  let completed = false;
  const cancel = () => {
    if (!completed && !abortController.signal.aborted) abortController.abort();
  };
  request.once("aborted", cancel);
  response.once("close", cancel);
  try {
    assertOperationRequest(request, "image-execute");
    const runtime = await runtimeForRequest(request);
    const requestIdentity = imageBrowserRequestIdentity(request.body);
    if (request.body?.stream !== true) {
      const result = await executeImageForRuntime(runtime, request.body || {}, {
        signal: abortController.signal,
        browserSessionId: browserSessionIdentity(request),
        authSession: request.authSession,
        ...requestIdentity,
      });
      completed = true;
      response.status(201).json(result);
      return;
    }
    response.status(200);
    response.setHeader("Content-Type", "text/event-stream; charset=utf-8");
    response.setHeader("Cache-Control", "no-store, no-transform");
    response.setHeader("Connection", "keep-alive");
    response.setHeader("X-Accel-Buffering", "no");
    response.flushHeaders();
    const result = await executeImageForRuntime(runtime, request.body || {}, {
      signal: abortController.signal,
      browserSessionId: browserSessionIdentity(request),
      authSession: request.authSession,
      ...requestIdentity,
      onPartial: (event) => writeImageSseEvent(response, "partial", event),
    });
    await writeImageSseEvent(response, "completed", { type: "completed", ...result });
    completed = true;
    response.end();
  } catch (error) {
    if (response.headersSent && !response.writableEnded) {
      await writeImageSseEvent(response, "error", {
        type: "error",
        error: serializedImageExecutionError(error),
      }).catch(() => {});
      completed = true;
      response.end();
    } else {
      completed = true;
      sendImageExecutionError(response, error);
    }
  } finally {
    request.off("aborted", cancel);
    response.off("close", cancel);
    request.completePersistentStateOperation?.();
  }
});

app.post("/api/images/generate", async (request, response, next) => {
  const abortController = new AbortController();
  let completed = false;
  const cancel = () => {
    if (!completed && !abortController.signal.aborted) abortController.abort();
  };
  request.once("aborted", cancel);
  response.once("close", cancel);
  try {
    assertOperationRequest(request, "image-generate");
    const runtime = await runtimeForRequest(request);
    const result = await generateImageForRuntime(runtime, request.body || {}, {
      signal: abortController.signal,
    });
    completed = true;
    response.status(201).json(result);
  } catch (error) {
    completed = true;
    next(error);
  } finally {
    request.off("aborted", cancel);
    response.off("close", cancel);
    request.completePersistentStateOperation?.();
  }
});

async function generateImageForRuntime(runtime, input = {}, { signal = null } = {}) {
  const result = await executeImageForRuntime(runtime, {
    operation: "generate",
    prompt: input.prompt,
    project: input.project,
    destination: input.outputPath,
    n: 1,
    outputFormat: "png",
    stream: false,
  }, { legacy: true, signal });
  const output = result.outputs[0];
  return {
    attachment: {
      name: path.basename(output.path),
      path: output.path,
      relativePath: output.relativePath,
      size: output.size,
      mediaType: output.mediaType,
      previewUrl: output.previewUrl,
    },
    revisedPrompt: output.revisedPrompt,
    model: result.requested.model,
    size: `${output.width}x${output.height}`,
    requestedSize: result.requested.size,
    width: output.width,
    height: output.height,
    quality: result.requested.quality,
  };
}

async function executeImageForRuntime(runtime, input = {}, {
  legacy = false,
  signal = null,
  browserSessionId = null,
  authSession = null,
  windowId = null,
  operationId = null,
  onPartial = null,
} = {}) {
  if (!imageExecutionQueue || !imageWorkerRunner) {
    throw imageExecutionError(503, "IMAGE_WORKER_UNAVAILABLE", "独立图片 Worker 当前不可用");
  }
  const sessionExecution = createImageSessionExecutionSignal(signal, authSession, runtime.user.id);
  try {
    return await executeQueuedImageForRuntime(runtime, input, {
      legacy,
      signal: sessionExecution.signal,
      browserSessionId,
      authSession: sessionExecution.authSession,
      windowId,
      operationId,
      onPartial,
    });
  } finally {
    sessionExecution.close();
  }
}

async function executeQueuedImageForRuntime(runtime, input = {}, {
  legacy = false,
  signal = null,
  browserSessionId = null,
  authSession = null,
  windowId = null,
  operationId = null,
  onPartial = null,
} = {}) {
  let workerResult = null;
  let quotaReservation = null;
  let usageRecorded = false;
  let usageOperation = "generate";
  const recordUsageOnce = (usage) => {
    if (usageRecorded || !usage) return;
    usageRecorded = true;
    recordImageUsage(runtime, usageOperation, usage);
  };

  try {
    assertImageExecutionActive(signal);
    await assertImageTaskSessionActive(authSession, runtime.user.id);
    const imageApi = privateImageApiSnapshot(runtime.providerStore.getImageApi());
    if (!imageApi) {
      throw imageExecutionError(
        409,
        "IMAGE_PROVIDER_NOT_CONFIGURED",
        "当前账号尚未配置图片供应商，请联系管理员分配或在供应商设置中选择",
      );
    }
    const requestOptions = normalizeImageExecutionInput(input, imageApi, { legacy });
    usageOperation = requestOptions.operation;
    const projectPath = normalizeImageProjectPath(requestOptions.project);
    const authorized = await assertWritableImageProjectDirectory(projectPath, runtime);
    const projectRealPath = authorized.realPath;
    const fileOwner = authorized.share
      ? multiUserStore.getUser(authorized.share.sourceUserId)
      : runtime.user;
    const quotaRuntime = authorized.share
      ? await runtimeForUser(authorized.share.sourceUserId)
      : runtime;
    const relativeOutputPaths = generatedImageRelativePaths(
      requestOptions.destination,
      requestOptions.outputFormat,
      requestOptions.n,
    );
    const storedPaths = relativeOutputPaths.map((relativePath) => (
      path.join(projectRealPath, ...relativePath.split("/"))
    ));
    const admissionAnchor = await openExpectedImageProjectAnchor(projectRealPath);
    let projectIdentity;
    try {
      projectIdentity = await imageProjectIdentity(admissionAnchor);
      await prepareImageOutputPaths(admissionAnchor, storedPaths, fileOwner);
    } finally {
      await admissionAnchor.close().catch(() => {});
    }
    assertImageExecutionActive(signal);
    await assertTokenQuotaAvailable(runtime);
    const reserveBytes = Math.min(
      Number.MAX_SAFE_INTEGER,
      requestOptions.n * imageApi.limits.maxOutputBytesPerImage,
    );
    quotaReservation = await reserveImageQuota(quotaRuntime, {
      jobId: crypto.randomBytes(18).toString("hex"),
      bytes: reserveBytes,
    });

    const payload = {
      imageApi,
      request: {
        ...requestOptions,
        user: createImageProviderUserIdentifier({ userId: runtime.user.id, secret: SESSION_TOKEN }),
      },
      sources: [],
      mask: null,
      context: {
        userId: runtime.user.id,
        projectPath,
        projectRealPath,
        projectIdentity,
        sourcePaths: requestOptions.sourcePaths,
        maskPath: requestOptions.maskPath,
        relativeOutputPaths,
        reserveBytes,
        quotaReservation,
        authSession,
        windowId,
        operationId,
      },
    };
    const admitted = imageExecutionQueue.enqueue({
      identity: { userId: runtime.user.id, browserSessionId },
      payload,
    }, {
      signal,
      onEvent: async (event) => {
        if (event.type === "usage") recordUsageOnce(event.usage);
        if (event.type !== "partial" || typeof onPartial !== "function") return;
        if (!imagePartialPreviewStore || !browserSessionId) {
          throw imageExecutionError(503, "IMAGE_PARTIAL_PREVIEW_UNAVAILABLE", "图片流式预览授权不可用");
        }
        const staged = await imagePartialPreviewStore.stage({
          sourcePath: event.file.absolutePath,
          expected: {
            size: event.file.size,
            sha256: event.file.sha256,
            format: event.file.format,
            width: event.file.width,
            height: event.file.height,
            mediaType: event.file.mediaType,
          },
          userId: runtime.user.id,
          browserSessionId,
          windowId,
          operationId,
        });
        const partial = staged.metadata;
        await onPartial({
          type: "partial",
          index: event.index,
          url: `/api/images/v2/partial/${encodeURIComponent(staged.token)}`,
          width: partial.width,
          height: partial.height,
          format: partial.format,
          mediaType: partial.mediaType,
          size: partial.size,
          requested: imageExecutionRequestMetadata(
            requestOptions,
            imageApi.model,
            {
              size: `${partial.width}x${partial.height}`,
              providerSize: `${partial.width}x${partial.height}`,
            },
          ),
          providerRequestId: event.providerRequestId,
        });
      },
    });
    workerResult = await admitted.promise;
    recordUsageOnce(workerResult.response?.usage);
    return { ...workerResult.response, jobId: admitted.id };
  } catch (error) {
    recordUsageOnce(error?.providerUsage);
    throw normalizeImageExecutionError(error);
  } finally {
    if (quotaReservation) imageQuotaReservations?.release(quotaReservation);
  }
}

async function runMapImageCandidateJob(job, { signal = null, onEvent = null } = {}) {
  if (job.request?.operation === "crop") {
    return runLocalMapImageCropCandidateJob(job, { signal, onEvent });
  }
  if (!imageExecutionQueue || !imageWorkerRunner || !mapFileSessions) {
    throw imageExecutionError(503, "MAP_IMAGE_WORKER_UNAVAILABLE", "地图专用生图 Worker 当前不可用");
  }
  let quotaReservation = null;
  let usageRecorded = false;
  let usageOperation = "generate";
  const recordUsageOnce = (usage) => {
    if (usageRecorded || !usage) return;
    usageRecorded = true;
    void runtimeForUser(job.identity.userId)
      .then((runtime) => recordImageUsage(runtime, usageOperation, usage))
      .catch(() => {});
  };
  try {
    assertImageExecutionActive(signal);
    const runtime = await runtimeForUser(job.identity.userId);
    const authSession = normalizeImageTaskAuthSession(
      job.executionContext?.authSession,
      runtime.user.id,
    );
    await assertImageTaskSessionActive(authSession, runtime.user.id);
    const imageApi = privateImageApiSnapshot(
      job.executionContext?.imageApiSnapshot || runtime.providerStore.getImageApi(),
    );
    if (!imageApi) {
      throw imageExecutionError(
        409,
        "IMAGE_PROVIDER_NOT_CONFIGURED",
        "当前账号尚未配置图片供应商，请联系管理员分配或在供应商设置中选择",
      );
    }
    const inputRefs = normalizeInternalMapImageInputRefs(job.executionContext?.inputRefs);
    const requestOptions = normalizeMapImageExecutionRequest(
      job.request,
      job.mapContext,
      imageApi,
      { inputRefs },
    );
    usageOperation = requestOptions.operation;
    if (inputRefs) {
      await authorizeMapImageInputRefs({
        identity: job.identity,
        mapContext: job.mapContext,
        editorStateId: job.executionContext?.editorStateId,
        inputRefs,
        imageApi,
      });
      requestOptions.sourcePaths = [];
      requestOptions.maskPath = null;
    } else {
      const sourcePaths = authorizeMapImageSources({
        identity: job.identity,
        mapContext: job.mapContext,
        sourcePaths: requestOptions.sourcePaths,
        maskPath: requestOptions.maskPath,
      });
      requestOptions.sourcePaths = sourcePaths.sources;
      requestOptions.maskPath = sourcePaths.mask;
    }
    const authorized = await assertWritableImageProjectDirectory(job.mapContext.projectPath, runtime);
    const projectRealPath = authorized.realPath;
    const quotaRuntime = authorized.share
      ? await runtimeForUser(authorized.share.sourceUserId)
      : runtime;
    const projectAnchor = await openExpectedImageProjectAnchor(projectRealPath);
    let projectIdentity;
    try {
      projectIdentity = await imageProjectIdentity(projectAnchor);
    } finally {
      await projectAnchor.close().catch(() => {});
    }
    await assertTokenQuotaAvailable(runtime);
    const reserveBytes = Math.min(
      Number.MAX_SAFE_INTEGER,
      requestOptions.n * imageApi.limits.maxOutputBytesPerImage,
    );
    quotaReservation = await reserveImageQuota(quotaRuntime, {
      jobId: crypto.randomBytes(18).toString("hex"),
      bytes: reserveBytes,
    });
    const payload = {
      kind: "map-image-candidate",
      imageApi,
      request: {
        ...requestOptions,
        user: createImageProviderUserIdentifier({ userId: runtime.user.id, secret: SESSION_TOKEN }),
      },
      sources: [],
      mask: null,
      context: {
        userId: runtime.user.id,
        browserSessionId: job.identity.browserSessionId,
        editorInstanceId: job.identity.editorInstanceId,
        projectPath: job.mapContext.projectPath,
        projectRealPath,
        projectIdentity,
        sourcePaths: requestOptions.sourcePaths,
        maskPath: requestOptions.maskPath,
        inputRefs,
        editorStateId: job.executionContext?.editorStateId ?? null,
        selectionTarget: job.executionContext?.selectionTarget ?? null,
        selectionRequest: job.executionContext?.selectionRequest ?? null,
        reserveBytes,
        quotaReservation,
        authSession,
        mapContext: job.mapContext,
      },
    };
    const admitted = imageExecutionQueue.enqueue({
      identity: {
        userId: runtime.user.id,
        browserSessionId: job.identity.browserSessionId,
        clientOperationId: job.id,
      },
      payload,
    }, {
      signal,
      onEvent: async (event) => {
        if (event.type === "usage") recordUsageOnce(event.usage);
        if (typeof onEvent === "function") await onEvent(event);
      },
    });
    await onEvent?.({ type: "phase", phase: "queued" });
    const result = await admitted.promise;
    recordUsageOnce(result.usage);
    return result;
  } catch (error) {
    recordUsageOnce(error?.providerUsage);
    throw normalizeImageExecutionError(error);
  } finally {
    if (quotaReservation) imageQuotaReservations?.release(quotaReservation);
  }
}

async function runLocalMapImageCropCandidateJob(job, { signal = null, onEvent = null } = {}) {
  let descriptor = null;
  try {
    assertImageExecutionActive(signal);
    const runtime = await runtimeForUser(job.identity.userId);
    const authSession = normalizeImageTaskAuthSession(
      job.executionContext?.authSession,
      runtime.user.id,
    );
    await assertImageTaskSessionActive(authSession, runtime.user.id);
    const request = normalizeMapImageCropRequest(job.request);
    const inputRefs = normalizeInternalMapImageInputRefs(job.executionContext?.inputRefs);
    if (!inputRefs || inputRefs.source.length !== 1 || inputRefs.mask) {
      throw imageExecutionError(400, "INVALID_MAP_IMAGE_CROP", "纯裁剪任务的临时输入清单无效");
    }
    await onEvent?.({ type: "phase", phase: "preparing" });
    await authorizeMapImageInputRefs({
      identity: job.identity,
      mapContext: job.mapContext,
      editorStateId: job.executionContext?.editorStateId,
      inputRefs,
      imageApi: null,
      localOnly: true,
    });
    const source = inputRefs.source[0];
    const targetWidth = request.sourceSize.width - request.sourceCrop.left - request.sourceCrop.right;
    const targetHeight = request.sourceSize.height - request.sourceCrop.top - request.sourceCrop.bottom;
    if (source.format !== "png" || source.width !== targetWidth || source.height !== targetHeight) {
      throw imageExecutionError(409, "MAP_IMAGE_CROP_DIMENSIONS_MISMATCH", "裁剪临时输入尺寸已经变化");
    }
    descriptor = await mapImageInputs.authorize({
      inputId: source.id,
      identity: job.identity,
      mapSessionId: job.mapContext.mapSessionId,
      mapVersion: job.mapContext.version,
      editorStateId: job.executionContext?.editorStateId,
      purpose: "input-crop-read",
    });
    const actual = descriptor.metadata;
    if (actual.sha256 !== source.sha256 || actual.totalBytes !== source.size
      || actual.width !== targetWidth || actual.height !== targetHeight || actual.mediaType !== "image/png") {
      throw imageExecutionError(409, "MAP_IMAGE_INPUT_CHANGED", "裁剪临时输入元数据已经变化");
    }
    await onEvent?.({ type: "phase", phase: "postprocessing" });
    const crop = request.sourceCrop;
    const result = {
      files: [{
        sourcePath: descriptor.absolutePath,
        name: "crop.png",
        mediaType: "image/png",
        format: "png",
        width: targetWidth,
        height: targetHeight,
        size: source.size,
      }],
      requested: {
        operation: "crop",
        sourceSize: `${request.sourceSize.width}x${request.sourceSize.height}`,
        requestedCanvas: `${targetWidth}x${targetHeight}`,
        outputFormat: "png",
        sourceConsumed: true,
        postprocess: [`crop:${crop.top},${crop.right},${crop.bottom},${crop.left}`],
      },
      dispose: descriptor.release,
    };
    descriptor = null;
    return result;
  } catch (error) {
    await descriptor?.release().catch(() => {});
    throw normalizeImageExecutionError(error);
  }
}

function normalizeMapImageExecutionRequest(input, mapContext, imageApi, { inputRefs = null } = {}) {
  if (!input || typeof input !== "object" || Array.isArray(input)) {
    throw imageExecutionError(400, "INVALID_MAP_IMAGE_REQUEST", "地图生图参数无效");
  }
  if (input.stream === true || Number(input.partialImages || 0) > 0) {
    throw imageExecutionError(
      400,
      "MAP_IMAGE_STREAMING_UNAVAILABLE",
      "地图候选区暂不接收流式局部图片",
    );
  }
  if (
    Object.hasOwn(input, "project")
    || Object.hasOwn(input, "destination")
    || Object.hasOwn(input, "outputPath")
    || Object.hasOwn(input, "user")
  ) {
    throw imageExecutionError(
      400,
      "INVALID_MAP_IMAGE_REQUEST",
      "地图生图任务不能覆盖工程、发布路径或供应商用户标识",
    );
  }
  const operation = String(input.operation || "generate").trim();
  const normalizedInput = {
    ...input,
    project: mapContext.projectPath,
    stream: false,
    partialImages: 0,
  };
  if (inputRefs) {
    if (operation === "generate") {
      throw imageExecutionError(400, "INVALID_MAP_IMAGE_INPUTS", "生成操作不能附带临时源图片");
    }
    const sourceCount = inputRefs.source.length;
    if (!sourceCount) throw imageExecutionError(400, "INVALID_MAP_IMAGE_INPUTS", "编辑或扩图需要临时源图片");
    // normalizeImageExecutionInput owns all provider option validation. Use
    // opaque, task-local relative names only for that validation, then remove
    // them before the request is sent to the Worker; actual bytes are staged
    // from MapImageInputStore into its fixed input directory.
    normalizedInput.sourcePaths = inputRefs.source.map((entry, index) => `__map-input__/source-${index + 1}.${entry.format || "png"}`);
    if (inputRefs.mask) normalizedInput.maskPath = `__map-input__/mask.${inputRefs.mask.format || "png"}`;
  }
  const normalized = normalizeImageExecutionInput(normalizedInput, imageApi);
  if (inputRefs) {
    normalized.sourcePaths = [];
    normalized.maskPath = null;
  }
  return normalized;
}

async function runQueuedImageTask(job, { signal = null, onEvent = null } = {}) {
  if (job.payload?.kind === "compatibility-probe") {
    return runQueuedImageCompatibilityProbe(job, { signal, onEvent });
  }
  if (job.payload?.kind === "map-image-candidate") {
    return runQueuedMapImageCandidateTask(job, { signal, onEvent });
  }
  let workerLease = null;
  let projectAnchor = null;
  try {
    workerLease = await imageWorkerRunner(job, { signal, onEvent });
    assertImageExecutionActive(signal);
    const payload = job.payload;
    const context = payload?.context;
    const requestOptions = payload?.request;
    const imageApi = payload?.imageApi;
    if (
      !context
      || context.userId !== job.identity.userId
      || !requestOptions
      || !imageApi
      || !Array.isArray(context.relativeOutputPaths)
      || context.relativeOutputPaths.length !== requestOptions.n
    ) {
      throw imageExecutionError(400, "INVALID_IMAGE_TASK_CONTEXT", "图片任务提交上下文无效");
    }
    if (!Array.isArray(workerLease.files) || workerLease.files.length !== requestOptions.n) {
      throw imageExecutionError(
        502,
        "IMAGE_OUTPUT_COUNT_MISMATCH",
        "图片供应商返回的图片数量与请求不符",
        {
          requestedCount: requestOptions.n,
          actualCount: Array.isArray(workerLease.files) ? workerLease.files.length : 0,
        },
      );
    }

    const user = multiUserStore.getUser(context.userId)
      || (context.userId === legacyUser.id ? legacyUser : null);
    if (!user || user.status !== "active") {
      throw imageExecutionError(403, "IMAGE_USER_UNAVAILABLE", "图片任务所属账号不可用");
    }
    const runtime = await runtimeForUser(user.id);
    await assertImageTaskSessionActive(context.authSession, user.id);
    const authorized = await assertWritableImageProjectDirectory(context.projectPath, runtime);
    if (authorized.realPath !== context.projectRealPath) {
      throw imageExecutionError(409, "IMAGE_PROJECT_CHANGED", "图片任务排队后工程位置发生变化");
    }
    const fileOwner = authorized.share
      ? multiUserStore.getUser(authorized.share.sourceUserId)
      : runtime.user;
    if (!fileOwner || (!fileOwner.legacy && fileOwner.status !== "active")) {
      throw imageExecutionError(403, "IMAGE_PROJECT_OWNER_UNAVAILABLE", "图片工程所有者账号不可用");
    }
    const quotaRuntime = authorized.share
      ? await runtimeForUser(authorized.share.sourceUserId)
      : runtime;
    assertImageQuotaOwner(context.quotaReservation, quotaRuntime);
    await reserveImageQuota(quotaRuntime, context.quotaReservation);
    const totalOutputBytes = workerLease.files.reduce((total, file) => total + file.size, 0);
    if (context.quotaReservation && totalOutputBytes > context.quotaReservation.reservedBytes) {
      throw imageExecutionError(
        413,
        "IMAGE_QUOTA_RESERVATION_EXCEEDED",
        "图片任务的实际输出超过预留空间上限",
      );
    }

    const storedPaths = context.relativeOutputPaths.map((relativePath) => (
      path.join(context.projectRealPath, ...relativePath.split("/"))
    ));
    projectAnchor = await openExpectedImageProjectAnchor(
      context.projectRealPath,
      context.projectIdentity,
    );
    await prepareImageOutputPaths(projectAnchor, storedPaths, fileOwner);
    assertImageExecutionActive(signal);

    let publishedBatch;
    try {
      publishedBatch = await publishImageFileBatch({
        outputs: workerLease.files.map((file, index) => ({
          sourcePath: file.absolutePath,
          targetPath: storedPaths[index],
          expected: file,
          mode: 0o640,
          uid: !fileOwner.legacy && Number.isInteger(fileOwner.uid) ? fileOwner.uid : null,
          gid: !fileOwner.legacy && Number.isInteger(fileOwner.gid) ? fileOwner.gid : null,
        })),
        maxBytesPerFile: imageApi.limits.maxOutputBytesPerImage,
        maxTotalBytes: Math.min(
          Number.MAX_SAFE_INTEGER,
          requestOptions.n * imageApi.limits.maxOutputBytesPerImage,
        ),
      }, { projectAnchor });
    } catch (error) {
      throw normalizeImageBatchPublishError(error);
    }
    if (context.quotaReservation) {
      imageQuotaReservations.settle({
        ownerId: context.quotaReservation.ownerId,
        jobId: context.quotaReservation.jobId,
        actualBytes: totalOutputBytes,
      });
    }

    const outputs = publishedBatch.map((published, index) => ({
      path: storedPaths[index],
      relativePath: context.relativeOutputPaths[index],
      previewUrl: `/api/files/image?path=${encodeURIComponent(storedPaths[index])}`,
      mediaType: published.mediaType,
      width: published.width,
      height: published.height,
      format: published.format,
      size: published.size,
      sha256: published.sha256,
      revisedPrompt: workerLease.files[index].revisedPrompt,
    }));
    directorySizeCache.clear();
    const response = {
      outputs,
      requested: imageExecutionRequestMetadata(
        requestOptions,
        imageApi.model,
        workerLease.requested,
      ),
      usage: workerLease.usage,
      providerRequestId: workerLease.providerRequestId,
      provider: "wfl",
      operation: requestOptions.operation,
      sourceConsumed: requestOptions.operation !== "generate",
      inputImageTokens: Number.isSafeInteger(workerLease.usage?.inputImageTokens)
        ? workerLease.usage.inputImageTokens
        : 0,
    };
    return {
      response,
      files: outputs.map((output) => ({
        path: output.relativePath,
        size: output.size,
        sha256: output.sha256,
        mediaType: output.mediaType,
      })),
    };
  } finally {
    await projectAnchor?.close().catch(() => {});
    await workerLease?.dispose?.().catch(() => {});
  }
}

async function runQueuedMapImageCandidateTask(job, { signal = null, onEvent = null } = {}) {
  let workerLease = null;
  try {
    workerLease = await imageWorkerRunner(job, { signal, onEvent });
    assertImageExecutionActive(signal);
    const context = job.payload?.context;
    const requestOptions = job.payload?.request;
    if (
      !context
      || context.userId !== job.identity.userId
      || !context.mapContext
      || !requestOptions
      || requestOptions.n !== workerLease.files?.length
    ) {
      throw imageExecutionError(400, "INVALID_MAP_IMAGE_TASK_CONTEXT", "地图生图任务上下文无效");
    }
    await authorizeQueuedMapImageContext(context, job.identity, job.payload?.imageApi, job.payload?.request);
    const lease = workerLease;
    workerLease = null;
    return {
      files: lease.files.map((file) => ({
        sourcePath: file.absolutePath,
        name: path.basename(file.path),
        size: file.size,
        sha256: file.sha256,
        mediaType: file.mediaType,
        format: file.format,
        width: file.width,
        height: file.height,
        revisedPrompt: file.revisedPrompt,
      })),
      usage: lease.usage,
      providerRequestId: lease.providerRequestId,
      requested: lease.requested,
      dispose: lease.dispose,
    };
  } finally {
    await workerLease?.dispose?.().catch(() => {});
  }
}

async function runQueuedImageCompatibilityProbe(job, { signal = null, onEvent = null } = {}) {
  let workerLease = null;
  try {
    workerLease = await imageWorkerRunner(job, { signal, onEvent });
    assertImageExecutionActive(signal);
    const context = job.payload?.probeContext;
    if (!context || context.userId !== job.identity.userId) {
      throw imageExecutionError(400, "INVALID_IMAGE_TASK_CONTEXT", "图片兼容性探测上下文无效");
    }
    const user = multiUserStore.getUser(context.userId)
      || (context.userId === legacyUser.id ? legacyUser : null);
    if (!user || user.status !== "active" || (!user.legacy && !["owner", "admin"].includes(user.role))) {
      throw imageExecutionError(403, "IMAGE_PROBE_FORBIDDEN", "当前账号不能读取图片兼容性探测结果");
    }
    await assertImageTaskSessionActive(context.authSession, user.id);
    const report = sanitizeImageCompatibilityProbeReport(workerLease.requested?.probeReport);
    if (!report) throw imageExecutionError(502, "IMAGE_PROBE_RESPONSE_INVALID", "图片 Worker 返回了无效的兼容性探测报告");
    return { response: { report, jobId: job.id }, files: [] };
  } finally {
    await workerLease?.dispose?.().catch(() => {});
  }
}

async function prepareQueuedImageWorkerTask(job, {
  inputDirectory,
  signal = null,
} = {}) {
  assertImageExecutionActive(signal);
  const payload = structuredClone(job.payload);
  if (payload.kind === "compatibility-probe") {
    const context = payload.probeContext;
    delete payload.probeContext;
    if (!context || context.userId !== job.identity.userId || !payload.imageApi || !payload.probe) {
      throw imageExecutionError(400, "INVALID_IMAGE_TASK_CONTEXT", "图片兼容性探测上下文无效");
    }
    const user = multiUserStore.getUser(context.userId)
      || (context.userId === legacyUser.id ? legacyUser : null);
    if (!user || user.status !== "active" || (!user.legacy && !["owner", "admin"].includes(user.role))) {
      throw imageExecutionError(403, "IMAGE_PROBE_FORBIDDEN", "当前账号不能运行图片兼容性探测");
    }
    await assertImageTaskSessionActive(context.authSession, user.id);
    await assertTokenQuotaAvailable(await runtimeForUser(user.id));
    return payload;
  }
  const context = payload.context;
  delete payload.context;
  if (!context || context.userId !== job.identity.userId) {
    throw imageExecutionError(400, "INVALID_IMAGE_TASK_CONTEXT", "图片任务上下文无效");
  }
  if (payload.kind === "map-image-candidate") {
    await authorizeQueuedMapImageContext(context, job.identity, payload.imageApi, payload.request);
  }
  const user = multiUserStore.getUser(context.userId)
    || (context.userId === legacyUser.id ? legacyUser : null);
  if (!user || user.status !== "active") {
    throw imageExecutionError(403, "IMAGE_USER_UNAVAILABLE", "图片任务所属账号不可用");
  }
  const runtime = await runtimeForUser(user.id);
  await assertImageTaskSessionActive(context.authSession, user.id);
  const authorized = await assertWritableImageProjectDirectory(context.projectPath, runtime);
  if (authorized.realPath !== context.projectRealPath) {
    throw imageExecutionError(409, "IMAGE_PROJECT_CHANGED", "图片任务排队后工程位置发生变化");
  }
  const quotaRuntime = authorized.share
    ? await runtimeForUser(authorized.share.sourceUserId)
    : runtime;
  assertImageQuotaOwner(context.quotaReservation, quotaRuntime);
  await assertTokenQuotaAvailable(runtime);
  await reserveImageQuota(quotaRuntime, context.quotaReservation);

  const projectAnchor = await openExpectedImageProjectAnchor(
    context.projectRealPath,
    context.projectIdentity,
  );
  try {
    let stagedInputBytes = 0;
    const stage = async (relativePath, filename, label) => {
      assertImageExecutionActive(signal);
      const candidate = path.join(context.projectPath, ...relativePath.split("/"));
      const { targetPath } = await resolveResourceTarget(context.projectPath, candidate, runtime, {
        symlinkError: () => imageExecutionError(403, "IMAGE_SOURCE_SYMLINK", `${label}路径不能经过符号链接`),
      });
      const anchoredTarget = await projectAnchor.resolveTarget(targetPath, { createParents: false });
      const destinationPath = path.join(inputDirectory, filename);
      let staged;
      try {
        staged = await stageSecureProjectImage({
          projectRealPath: context.projectRealPath,
          targetPath: anchoredTarget.targetPath,
          relativePath,
          maxBytes: payload.imageApi.limits.maxInputBytesPerImage,
          destinationPath,
        });
      } catch (error) {
        throw normalizeQueuedImageStageError(error, label);
      } finally {
        await anchoredTarget.close();
      }
      stagedInputBytes += staged.size;
      if (stagedInputBytes > payload.imageApi.limits.maxInputBytesTotal) {
        throw imageExecutionError(
          413,
          "IMAGE_INPUTS_TOO_LARGE",
          "输入图片总大小超过管理员设置的限制",
        );
      }
      return {
        path: staged.destinationPath,
        filename: path.basename(relativePath),
        size: staged.size,
        dev: String(staged.destination.dev),
        ino: String(staged.destination.ino),
      };
    };
    payload.sources = [];
    if (context.inputRefs) {
      const refs = normalizeInternalMapImageInputRefs(context.inputRefs);
      await authorizeMapImageInputRefs({
        identity: {
          userId: context.userId,
          browserSessionId: context.browserSessionId,
          editorInstanceId: context.editorInstanceId,
        },
        mapContext: context.mapContext,
        editorStateId: context.editorStateId,
        inputRefs: refs,
        imageApi: payload.imageApi,
      });
      for (const [index, ref] of refs.source.entries()) {
        const extension = ref.format || "png";
        const destinationPath = path.join(inputDirectory, `source-${index + 1}.${extension}`);
        const staged = await mapImageInputs.stageTo({
          inputId: ref.id,
          identity: {
            userId: context.userId,
            browserSessionId: context.browserSessionId,
            editorInstanceId: context.editorInstanceId,
          },
          mapSessionId: context.mapContext.mapSessionId,
          mapVersion: context.mapContext.version,
          editorStateId: context.editorStateId,
          destinationPath,
          maxBytes: payload.imageApi.limits.maxInputBytesPerImage,
          signal,
        });
        stagedInputBytes += staged.bytes;
        payload.sources.push({
          path: destinationPath,
          filename: `source-${index + 1}.${extension}`,
          size: staged.bytes,
          mediaType: staged.mediaType,
        });
      }
      if (refs.mask) {
        const extension = refs.mask.format || "png";
        const destinationPath = path.join(inputDirectory, `mask.${extension}`);
        const staged = await mapImageInputs.stageTo({
          inputId: refs.mask.id,
          identity: {
            userId: context.userId,
            browserSessionId: context.browserSessionId,
            editorInstanceId: context.editorInstanceId,
          },
          mapSessionId: context.mapContext.mapSessionId,
          mapVersion: context.mapContext.version,
          editorStateId: context.editorStateId,
          destinationPath,
          maxBytes: payload.imageApi.limits.maxInputBytesPerImage,
          signal,
        });
        stagedInputBytes += staged.bytes;
        payload.mask = {
          path: destinationPath,
          filename: `mask.${extension}`,
          size: staged.bytes,
          mediaType: staged.mediaType,
        };
      } else {
        payload.mask = null;
      }
      if (stagedInputBytes > payload.imageApi.limits.maxInputBytesTotal) {
        throw imageExecutionError(413, "IMAGE_INPUTS_TOO_LARGE", "输入图片总大小超过管理员设置的限制");
      }
    } else {
      for (const [index, relativePath] of context.sourcePaths.entries()) {
        const extension = path.posix.extname(relativePath).toLowerCase();
        payload.sources.push(await stage(relativePath, `source-${index + 1}${extension}`, "源图片"));
      }
      payload.mask = context.maskPath
        ? await stage(
          context.maskPath,
          `mask${path.posix.extname(context.maskPath).toLowerCase()}`,
          "蒙版",
        )
        : null;
    }
    return payload;
  } finally {
    await projectAnchor.close().catch(() => {});
  }
}

function normalizeQueuedImageStageError(error, label) {
  if (!(error instanceof ImageSecureInputError)) return error;
  if (["SYMLINK", "DESTINATION_SYMLINK"].includes(error.code)) {
    return imageExecutionError(403, "IMAGE_SOURCE_SYMLINK", `${label}路径不能经过符号链接`, {}, error);
  }
  if (error.code === "NOT_FILE") {
    return imageExecutionError(400, "INVALID_IMAGE_SOURCE", `${label}必须是图片文件`, {}, error);
  }
  if (error.code === "TOO_LARGE") {
    return imageExecutionError(413, "IMAGE_SOURCE_TOO_LARGE", `${label}超过管理员设置的单图大小限制`, {}, error);
  }
  return imageExecutionError(500, "IMAGE_SOURCE_STAGE_FAILED", `${label}无法安全送入图片 Worker`, {}, error);
}

async function assertWritableImageProjectDirectory(projectPath, runtime) {
  try {
    return await assertWritableProjectDirectory(projectPath, runtime);
  } catch (error) {
    if (error?.statusCode === 400) {
      throw imageExecutionError(
        400,
        "INVALID_IMAGE_PROJECT",
        "图片工程路径无效或当前账号无权访问",
        {},
        error,
      );
    }
    if (error?.statusCode === 403) {
      throw imageExecutionError(
        403,
        "IMAGE_PROJECT_NOT_WRITABLE",
        "当前账号无权写入这个图片工程",
        {},
        error,
      );
    }
    throw error;
  }
}

function imageBrowserRequestIdentity(input) {
  if (!input || typeof input !== "object" || Array.isArray(input)) {
    throw imageExecutionError(400, "INVALID_IMAGE_REQUEST", "图片请求参数无效");
  }
  return {
    windowId: imageAuthorizationNonce(input.windowId, "图片窗口标识"),
    operationId: imageAuthorizationNonce(input.operationId, "图片操作标识"),
  };
}

function imageAuthorizationNonce(value, label) {
  const nonce = typeof value === "string" ? value : "";
  if (!/^[a-f0-9]{64}$/.test(nonce)) {
    throw imageExecutionError(400, "INVALID_IMAGE_AUTHORIZATION_NONCE", `${label}无效`);
  }
  return nonce;
}

function createImageSessionExecutionSignal(signal, authSession, userId) {
  const normalized = normalizeImageTaskAuthSession(authSession, userId);
  if (!normalized) return { signal, authSession: null, close() {} };

  const controller = new AbortController();
  let expiryTimer = null;
  const abort = () => {
    if (!controller.signal.aborted) controller.abort();
  };
  const scheduleExpiry = () => {
    const remaining = normalized.expiresAt - Date.now();
    if (remaining <= 0) {
      abort();
      return;
    }
    expiryTimer = setTimeout(scheduleExpiry, Math.min(remaining, 24 * 60 * 60 * 1_000));
    expiryTimer.unref?.();
  };
  if (signal?.aborted) abort();
  else signal?.addEventListener?.("abort", abort, { once: true });
  scheduleExpiry();
  return {
    signal: controller.signal,
    authSession: normalized,
    close() {
      clearTimeout(expiryTimer);
      signal?.removeEventListener?.("abort", abort);
    },
  };
}

function normalizeImageTaskAuthSession(value, userId) {
  if (value == null) return null;
  if (
    !value
    || typeof value !== "object"
    || Array.isArray(value)
    || typeof value.id !== "string"
    || !/^[A-Za-z0-9_-]{8,256}$/.test(value.id)
    || value.userId !== userId
    || !Number.isFinite(value.expiresAt)
    || !["primary", "fallback"].includes(value.source)
  ) {
    throw imageExecutionError(403, "INVALID_IMAGE_SESSION", "图片任务登录会话无效");
  }
  return {
    id: value.id,
    userId: value.userId,
    expiresAt: value.expiresAt,
    source: value.source,
  };
}

async function assertImageTaskSessionActive(authSession, userId) {
  if (!authSession) return;
  const normalized = normalizeImageTaskAuthSession(authSession, userId);
  if (!await multiUserStore.sessionIsActive(normalized)) {
    throw imageExecutionError(401, "IMAGE_SESSION_REVOKED", "图片任务登录会话已失效");
  }
}

async function imageProjectIdentity(anchor) {
  await anchor.assertIdentity();
  return {
    dev: String(anchor.device),
    ino: String(anchor.inode),
  };
}

async function openExpectedImageProjectAnchor(projectRealPath, expectedIdentity = null) {
  let anchor = null;
  try {
    if (expectedIdentity && (
      !/^[0-9]+$/.test(expectedIdentity.dev || "")
      || !/^[0-9]+$/.test(expectedIdentity.ino || "")
    )) {
      throw imageExecutionError(400, "INVALID_IMAGE_TASK_CONTEXT", "图片工程身份无效");
    }
    anchor = await openImageProjectAnchor(projectRealPath);
    const current = await imageProjectIdentity(anchor);
    if (expectedIdentity && (
      current.dev !== expectedIdentity.dev
      || current.ino !== expectedIdentity.ino
    )) {
      throw imageExecutionError(409, "IMAGE_PROJECT_CHANGED", "图片任务排队后工程身份发生变化");
    }
    return anchor;
  } catch (error) {
    await anchor?.close().catch(() => {});
    if (error?.code === "INVALID_IMAGE_TASK_CONTEXT" || error?.code === "IMAGE_PROJECT_CHANGED") throw error;
    if (["IMAGE_PROJECT_SYMLINK", "ENOENT", "ENOTDIR", "ELOOP"].includes(error?.code)) {
      throw imageExecutionError(409, "IMAGE_PROJECT_CHANGED", "图片任务排队后工程身份发生变化", {}, error);
    }
    throw error;
  }
}

async function reserveImageQuota(runtime, reservation) {
  if (runtime.legacy || !Number.isSafeInteger(runtime.user.quotaBytes)) return null;
  if (!imageQuotaReservations) {
    throw imageExecutionError(503, "IMAGE_QUOTA_RESERVATIONS_UNAVAILABLE", "图片空间预留组件不可用");
  }
  const jobId = String(reservation?.jobId || "");
  const bytes = reservation?.reservedBytes ?? reservation?.bytes;
  const ownerId = reservation?.ownerId ?? runtime.user.id;
  if (ownerId !== runtime.user.id) {
    throw imageExecutionError(409, "IMAGE_QUOTA_OWNER_CHANGED", "图片工程配额所有者发生变化");
  }
  const limitBytes = runtime.user.quotaBytes;
  const currentUsedBytes = await directorySize(
    quotaUsageRoot(runtime),
    limitBytes === Number.MAX_SAFE_INTEGER ? limitBytes : limitBytes + 1,
  );
  return imageQuotaReservations.reserve({
    ownerId,
    jobId,
    bytes,
    currentUsedBytes,
    limitBytes,
  });
}

function assertImageQuotaOwner(reservation, runtime) {
  const quotaManaged = !runtime.legacy && Number.isSafeInteger(runtime.user.quotaBytes);
  if (!quotaManaged) {
    if (reservation) throw imageExecutionError(409, "IMAGE_QUOTA_OWNER_CHANGED", "图片工程配额模式发生变化");
    return;
  }
  if (!reservation || reservation.ownerId !== runtime.user.id) {
    throw imageExecutionError(409, "IMAGE_QUOTA_OWNER_CHANGED", "图片工程配额所有者发生变化");
  }
}

function imageExecutionRequestMetadata(requestOptions, model, workerMetadata = null) {
  const worker = workerMetadata && typeof workerMetadata === "object" && !Array.isArray(workerMetadata)
    ? workerMetadata
    : {};
  const legacyProviderSize = typeof workerMetadata === "string" ? workerMetadata : null;
  const finalSize = imageMetadataSize(worker.size)
    || imageMetadataSize(worker.requestedCanvas)
    || (requestOptions.operation === "outpaint" ? null : requestOptions.size);
  const providerSize = imageMetadataSize(worker.providerSize)
    || imageMetadataSize(legacyProviderSize)
    || finalSize;
  const sourceSize = imageMetadataSize(worker.sourceSize);
  const postprocess = Array.isArray(worker.postprocess)
    ? worker.postprocess
      .filter((entry) => typeof entry === "string" && /^[A-Za-z0-9:,.>_-]{1,200}$/u.test(entry))
      .slice(0, 32)
    : [];
  return {
    provider: "wfl",
    operation: requestOptions.operation,
    model,
    ...(safeRevision(worker.providerProfileRevision)
      ? { providerProfileRevision: safeRevision(worker.providerProfileRevision) }
      : {}),
    ...(safeRevision(worker.configurationRevision)
      ? { configurationRevision: safeRevision(worker.configurationRevision) }
      : {}),
    prompt: requestOptions.prompt,
    n: requestOptions.n,
    size: finalSize,
    requestedSize: requestOptions.operation === "outpaint" ? null : requestOptions.size,
    providerSize,
    sourceSize,
    requestedCanvas: finalSize,
    postprocess,
    quality: requestOptions.quality,
    outputFormat: requestOptions.outputFormat,
    ...(requestOptions.outputFormat === "png"
      ? {}
      : { outputCompression: requestOptions.outputCompression }),
    background: requestOptions.background,
    moderation: requestOptions.moderation,
    partialImages: requestOptions.partialImages,
    stream: requestOptions.stream,
    sourceConsumed: requestOptions.operation !== "generate",
    ...(requestOptions.maskPath ? {
      maskMode: requestOptions.maskMode,
      maskFeather: requestOptions.maskFeather,
    } : {}),
    ...(requestOptions.operation === "outpaint" ? {
      preserveSource: requestOptions.preserveSource,
      blendMargin: requestOptions.blendMargin,
      alignmentPolicy: requestOptions.alignmentPolicy,
    } : {}),
  };
}

function safeRevision(value) {
  const text = typeof value === "string" ? value.trim() : "";
  return /^[a-f0-9]{32,64}$/u.test(text) ? text : null;
}

function imageMetadataSize(value) {
  const normalized = typeof value === "string" ? value.trim() : "";
  return /^(?:auto|[1-9]\d{0,4}x[1-9]\d{0,4})$/u.test(normalized) ? normalized : null;
}

function normalizeImageCompatibilityProbeTests(value, imageApi) {
  if (!Array.isArray(value) || value.length < 1 || value.length > 5) {
    throw imageExecutionError(400, "INVALID_IMAGE_COMPATIBILITY_PROBE", "请选择 1-5 个兼容性探测项目");
  }
  const available = new Set(["generate-standard"]);
  if (imageApi.capabilities.operations.includes("edit")) available.add("edit-standard");
  if (imageApi.capabilities.operations.includes("edit") && imageApi.capabilities.mask) available.add("edit-mask");
  if (imageApi.capabilities.operations.includes("outpaint")) {
    available.add("outpaint-standard");
    available.add("outpaint-custom");
  }
  const tests = [...new Set(value.map((entry) => String(entry || "").trim()))];
  if (tests.some((entry) => !available.has(entry))) {
    throw imageExecutionError(400, "INVALID_IMAGE_COMPATIBILITY_PROBE", "探测项目不在当前显式图片能力范围内");
  }
  return tests;
}

function sanitizeImageCompatibilityProbeReport(value) {
  if (!value || typeof value !== "object" || Array.isArray(value) || value.kind !== "wfl-image-compatibility-probe") {
    return null;
  }
  const tests = Array.isArray(value.tests) ? value.tests.slice(0, 5).flatMap((entry) => {
    if (!entry || typeof entry !== "object" || Array.isArray(entry)) return [];
    const id = typeof entry.id === "string" && /^[a-z-]{1,64}$/.test(entry.id) ? entry.id : null;
    const operation = ["generate", "edit", "outpaint"].includes(entry.operation) ? entry.operation : null;
    const requestedSize = imageMetadataSize(entry.requestedSize);
    if (!id || !operation || !requestedSize || typeof entry.ok !== "boolean") return [];
    const result = {
      id,
      operation,
      requestedSize,
      expectedSize: imageMetadataSize(entry.expectedSize) || requestedSize,
      customSize: entry.customSize === true,
      mask: entry.mask === true,
      ok: entry.ok,
      durationMs: Number.isSafeInteger(entry.durationMs) && entry.durationMs >= 0
        ? Math.min(entry.durationMs, 3_600_000)
        : null,
      providerRequestId: typeof entry.providerRequestId === "string"
        && /^[A-Za-z0-9][A-Za-z0-9._:-]{0,199}$/.test(entry.providerRequestId)
        ? entry.providerRequestId
        : null,
      usage: sanitizeImageProbeUsage(entry.usage),
    };
    if (!entry.ok && entry.error && typeof entry.error === "object") {
      result.error = {
        code: typeof entry.error.code === "string" && /^[A-Z][A-Z0-9_]{0,63}$/.test(entry.error.code)
          ? entry.error.code
          : "IMAGE_PROVIDER_ERROR",
        message: String(entry.error.message || "图片兼容性探测失败").slice(0, 1_000),
        reason: typeof entry.error.reason === "string" && /^[A-Za-z0-9._:-]{1,100}$/.test(entry.error.reason)
          ? entry.error.reason
          : null,
        providerStatusCode: Number.isInteger(entry.error.providerStatusCode)
          && entry.error.providerStatusCode >= 400
          && entry.error.providerStatusCode <= 599
          ? entry.error.providerStatusCode
          : null,
        retryable: entry.error.retryable === true,
      };
    }
    return [result];
  }) : [];
  if (!tests.length) return null;
  const recommendations = value.recommendations && typeof value.recommendations === "object"
    ? {
        mask: value.recommendations.mask === true,
        edit: value.recommendations.edit === true,
        outpaint: value.recommendations.outpaint === true,
        outpaintCustomSize: value.recommendations.outpaintCustomSize === true,
        note: "这是管理员显式探测结果，只提供建议；不会自动修改供应商能力声明。",
      }
    : null;
  return {
    kind: "wfl-image-compatibility-probe",
    generatedAt: Number.isFinite(Date.parse(value.generatedAt)) ? new Date(value.generatedAt).toISOString() : null,
    model: typeof value.model === "string" && !/[\u0000-\u001f\u007f]/.test(value.model)
      ? value.model.slice(0, 200)
      : null,
    tests,
    recommendations,
    usage: sanitizeImageProbeUsage(value.usage),
  };
}

function sanitizeImageProbeUsage(value) {
  if (!value || typeof value !== "object" || Array.isArray(value)) return null;
  const result = {};
  for (const key of [
    "inputTokens", "inputTextTokens", "inputImageTokens", "cachedInputTokens",
    "outputTokens", "reasoningOutputTokens", "totalTokens",
  ]) {
    if (Number.isSafeInteger(value[key]) && value[key] >= 0) result[key] = value[key];
  }
  return Object.keys(result).length ? result : null;
}

function publicImageCapabilities(imageApi) {
  const configured = imageApi?.configured === true;
  const capabilities = imageApi?.capabilities || {};
  const limits = imageApi?.limits || {};
  const operationCapabilities = configured
    ? structuredClone(imageApi?.operationCapabilities || {})
    : {};
  return {
    enabled: configured,
    requestMode: normalizeImageRequestMode(imageApi?.requestMode),
    schemaVersion: imageApi?.schemaVersion || 2,
    presetId: imageApi?.preset || "generation-only",
    operations: configured ? [...(capabilities.operations || [])] : [],
    features: {
      localCrop: true,
      mask: configured && capabilities.mask === true,
      multiInput: configured && capabilities.multiInput === true,
      multiOutput: configured && Number(limits.maxOutputs) > 1,
      streaming: configured && capabilities.streaming === true,
      customSize: configured && Object.values(operationCapabilities)
        .some((entry) => entry?.customSize === true),
      inputFidelity: false,
      strictMask: configured
        && capabilities.operations?.includes("edit")
        && capabilities.mask === true,
      seamlessOutpaint: configured && capabilities.operations?.includes("outpaint"),
    },
    operationCapabilities,
    surfaces: {
      browser: { streaming: configured && capabilities.streaming === true },
      mcp: { streaming: false, partialImages: false },
    },
    defaults: structuredClone(imageApi?.defaults || {}),
    limits: structuredClone(limits),
    options: {
      sizes: [...(limits.fixedSizes || [])],
      inputFormats: [...(capabilities.inputFormats || [])],
      outputFormats: [...(capabilities.outputFormats || [])],
      qualities: [...(capabilities.qualities || [])],
      backgrounds: [...(capabilities.backgrounds || [])],
      moderations: [...(capabilities.moderations || [])],
      inputFidelities: [],
    },
  };
}

function privateImageApiSnapshot(imageApi) {
  return imageApi ? structuredClone(imageApi) : null;
}

function normalizeImageExecutionInput(input, imageApi, { legacy = false } = {}) {
  if (!input || typeof input !== "object" || Array.isArray(input)) {
    throw imageExecutionError(400, "INVALID_IMAGE_REQUEST", "图片请求参数无效");
  }
  const operation = legacy ? "generate" : String(input.operation || "generate").trim();
  if (!imageApi.capabilities.operations.includes(operation)) {
    throw imageExecutionError(409, "IMAGE_OPERATION_UNAVAILABLE", "当前图片供应商未启用这个操作");
  }
  const requestMode = legacy ? "managed" : normalizeImageRequestMode(imageApi.requestMode);
  const passthrough = requestMode !== "managed";
  let providerParameters;
  try {
    providerParameters = normalizeImageProviderParameters(input.providerParameters);
  } catch (error) {
    throw imageExecutionError(400, "INVALID_IMAGE_PROVIDER_PARAMETERS", error.message, {}, error);
  }
  if (!passthrough && Object.keys(providerParameters).length) {
    throw imageExecutionError(400, "INVALID_IMAGE_PROVIDER_PARAMETERS", "标准管理模式不接受供应商原生参数");
  }
  const prompt = typeof input.prompt === "string" ? input.prompt.trim() : "";
  const maxPromptCharacters = Number.isSafeInteger(imageApi.limits.maxPromptCharacters)
    ? imageApi.limits.maxPromptCharacters
    : 4_000;
  if (!prompt || prompt.length > maxPromptCharacters) {
    throw imageExecutionError(
      400,
      "INVALID_IMAGE_PROMPT",
      `图片描述必须为 1-${maxPromptCharacters} 个字符`,
    );
  }
  const nField = imageRequestField(input, providerParameters, "n", ["n"], imageApi.defaults.n, legacy || !passthrough);
  const n = legacy
    ? 1
    : imageBoundedInteger(
      providerParameterNumber(nField, 1),
      imageApi.defaults.n,
      1,
      passthrough ? 100 : imageApi.limits.maxOutputs,
      "输出图片数量",
    );
  const qualityField = imageRequestField(
    input,
    providerParameters,
    "quality",
    ["quality"],
    imageApi.defaults.quality,
    legacy || !passthrough,
  );
  const quality = qualityField.value;
  const outputFormatField = imageRequestField(
    input,
    providerParameters,
    "outputFormat",
    ["output_format", "outputFormat"],
    legacy ? "png" : imageApi.defaults.outputFormat,
    legacy || !passthrough,
  );
  const outputFormat = normalizeLocalImageFormat(outputFormatField.value);
  const outputCompressionField = imageRequestField(
    input,
    providerParameters,
    "outputCompression",
    ["output_compression", "outputCompression"],
    imageApi.defaults.outputCompression,
    legacy || !passthrough,
  );
  const outputCompression = normalizeLocalImageCompression(outputCompressionField.value, imageApi.defaults.outputCompression);
  const backgroundField = imageRequestField(
    input,
    providerParameters,
    "background",
    ["background"],
    imageApi.defaults.background,
    legacy || !passthrough,
  );
  const background = backgroundField.value;
  if (!passthrough && background === "transparent" && outputFormat === "jpeg") {
    throw imageExecutionError(400, "INVALID_IMAGE_BACKGROUND", "透明背景只支持 PNG 或 WebP 输出");
  }
  const moderationField = imageRequestField(
    input,
    providerParameters,
    "moderation",
    ["moderation"],
    imageApi.defaults.moderation,
    legacy || !passthrough,
  );
  const moderation = moderationField.value;
  const streamField = imageRequestField(input, providerParameters, "stream", ["stream"], undefined, false);
  const stream = !legacy && (streamField.value === true || streamField.value === "true");
  if (stream && !passthrough && imageApi.capabilities.streaming !== true) {
    throw imageExecutionError(409, "IMAGE_STREAMING_UNAVAILABLE", "当前图片供应商未启用流式预览");
  }
  const partialImagesField = imageRequestField(
    input,
    providerParameters,
    "partialImages",
    ["partial_images", "partialImages"],
    imageApi.defaults.partialImages,
    stream && !passthrough,
  );
  const partialImages = stream
    ? imageBoundedInteger(
      providerParameterNumber(partialImagesField, 0),
      imageApi.defaults.partialImages,
      0,
      passthrough ? 100 : imageApi.limits.maxPartialImages,
      "局部预览数量",
    )
    : 0;
  const inputFidelityField = imageRequestField(
    input,
    providerParameters,
    "inputFidelity",
    ["input_fidelity", "inputFidelity"],
    undefined,
    false,
  );
  const inputFidelity = inputFidelityField.value == null || inputFidelityField.value === ""
    ? undefined
    : inputFidelityField.value;
  if (!passthrough && inputFidelity) {
    throw imageExecutionError(400, "IMAGE_OPTION_UNAVAILABLE", "当前图片预设不允许修改输入保真度");
  }
  const sizeField = imageRequestField(
    input,
    providerParameters,
    "size",
    ["size"],
    imageApi.defaults.size,
    legacy || !passthrough,
  );
  const size = operation === "outpaint"
    ? null
    : passthrough
      ? normalizeLocalImageSize(sizeField.value)
      : normalizeImageRequestSize(sizeField.value, imageApi, operation);
  const sourcePaths = normalizeImageSourcePaths(input, operation, imageApi.limits.maxInputImages);
  const maskPath = normalizeOptionalImageRelativePath(input.maskPath, "蒙版路径");
  if (operation === "generate" && (sourcePaths.length || maskPath || input.outpaint != null || input.expand != null)) {
    throw imageExecutionError(400, "INVALID_IMAGE_REQUEST", "生成操作不能包含源图片、蒙版或扩图参数");
  }
  if (operation === "edit" && input.outpaint != null) {
    throw imageExecutionError(400, "INVALID_IMAGE_REQUEST", "编辑操作不能包含扩图参数");
  }
  if (operation === "outpaint" && maskPath) {
    throw imageExecutionError(400, "INVALID_IMAGE_REQUEST", "扩图蒙版由系统根据四边扩展范围生成");
  }
  if (operation === "edit" && !maskPath && (input.maskMode != null || input.maskFeather != null)) {
    throw imageExecutionError(400, "INVALID_IMAGE_MASK", "蒙版模式和羽化参数必须同时指定蒙版图片");
  }
  const maskMode = operation === "edit" && maskPath
    ? imageMode(input.maskMode, "strict", ["strict", "soft"], "蒙版模式")
    : "soft";
  if (maskMode === "soft" && input.maskFeather != null) {
    throw imageExecutionError(400, "INVALID_IMAGE_MASK", "软蒙版模式不接受服务端羽化参数");
  }
  const maskFeather = operation === "edit" && maskPath && maskMode === "strict"
    ? imageBoundedInteger(input.maskFeather, 0, 0, 128, "蒙版羽化像素")
    : 0;
  const preserveSource = operation === "outpaint"
    ? imageMode(input.preserveSource, "exact", ["exact", "seamless"], "原图保留模式")
    : null;
  if (operation === "outpaint" && preserveSource !== "seamless" && input.blendMargin != null) {
    throw imageExecutionError(400, "INVALID_OUTPAINT", "只有无缝扩图模式可以指定过渡宽度");
  }
  const blendMargin = operation === "outpaint" && preserveSource === "seamless"
    ? imageBoundedInteger(input.blendMargin, 64, 1, 512, "无缝扩图过渡宽度")
    : 0;
  const alignmentPolicy = operation === "outpaint"
    ? imageMode(
      input.alignmentPolicy,
      "reject",
      ["reject", "pad-and-crop", "rescale-and-crop"],
      "扩图尺寸对齐策略",
    )
    : null;
  return {
    operation,
    requestMode,
    prompt,
    project: input.project,
    destination: input.destination ?? input.outputPath,
    sourcePaths,
    maskPath,
    outpaint: operation === "outpaint" ? normalizeOutpaintExpansion(input.outpaint ?? input.expand) : null,
    n,
    size,
    quality,
    outputFormat,
    outputCompression,
    background,
    moderation,
    inputFidelity,
    stream,
    partialImages,
    maskMode,
    maskFeather,
    preserveSource,
    blendMargin,
    alignmentPolicy,
    providerParameters,
    providerRequest: {
      n: nField.sendValue,
      size: operation === "outpaint" ? undefined : sizeField.sendValue,
      quality: qualityField.sendValue,
      outputFormat: outputFormatField.sendValue,
      outputCompression: outputCompressionField.sendValue,
      background: backgroundField.sendValue,
      moderation: moderationField.sendValue,
      inputFidelity: inputFidelityField.sendValue,
      stream: streamField.sendValue,
      partialImages: partialImagesField.sendValue,
    },
    outputFormatSpecified: outputFormatField.provided,
  };
}

function normalizeImageRequestMode(value) {
  const normalized = String(value || "managed").trim();
  if (!["managed", "partial", "passthrough"].includes(normalized)) return "managed";
  return normalized;
}

function imageRequestField(input, providerParameters, inputKey, providerKeys, fallback, useFallback) {
  if (Object.hasOwn(input, inputKey) && input[inputKey] !== undefined && input[inputKey] !== null) {
    return { value: input[inputKey], sendValue: input[inputKey], provided: true };
  }
  if (hasImageProviderParameter(providerParameters, providerKeys)) {
    return {
      value: imageProviderParameter(providerParameters, providerKeys),
      sendValue: undefined,
      provided: true,
    };
  }
  return {
    value: useFallback ? fallback : undefined,
    sendValue: useFallback ? fallback : undefined,
    provided: false,
  };
}

function providerParameterNumber(field, fallback) {
  const number = Number(field.value);
  return Number.isSafeInteger(number) ? number : fallback;
}

function normalizeLocalImageFormat(value) {
  const normalized = String(value || "").trim().toLowerCase();
  return ["png", "jpeg", "webp"].includes(normalized) ? normalized : "png";
}

function normalizeLocalImageCompression(value, fallback) {
  const number = Number(value);
  return Number.isSafeInteger(number) && number >= 0 && number <= 100 ? number : fallback;
}

function normalizeLocalImageSize(value) {
  const normalized = String(value || "").trim();
  return normalized === "auto" || /^\d{1,5}x\d{1,5}$/u.test(normalized) ? normalized : "auto";
}

function normalizeImageProjectPath(value) {
  const raw = typeof value === "string" ? value.trim() : "";
  if (!raw || raw.length > 4_096 || !path.isAbsolute(raw) || /[\u0000\r\n]/.test(raw)) {
    throw imageExecutionError(400, "INVALID_PROJECT_PATH", "图片操作必须指定当前工程的绝对路径");
  }
  return path.resolve(raw);
}

function normalizeImageSourcePaths(input, operation, maximum) {
  if (operation === "generate") return [];
  const raw = operation === "outpaint"
    ? (Array.isArray(input.sourcePaths) ? input.sourcePaths : input.sourcePath ? [input.sourcePath] : [])
    : input.sourcePaths;
  const requiredMaximum = operation === "outpaint" ? 1 : maximum;
  if (!Array.isArray(raw) || raw.length < 1 || raw.length > requiredMaximum) {
    throw imageExecutionError(
      400,
      "INVALID_IMAGE_SOURCE",
      operation === "outpaint" ? "扩图需要一张工程内源图片" : `编辑需要 1-${requiredMaximum} 张工程内源图片`,
    );
  }
  return raw.map((value) => normalizeImageRelativePath(value, "源图片路径"));
}

function normalizeOptionalImageRelativePath(value, label) {
  return value == null || value === "" ? null : normalizeImageRelativePath(value, label);
}

function normalizeImageRelativePath(value, label) {
  const requested = typeof value === "string" ? value.trim() : "";
  if (
    !requested
    || requested.length > 1_024
    || requested.includes("\\")
    || /[\u0000-\u001f\u007f]/.test(requested)
    || path.posix.isAbsolute(requested)
    || /^[A-Za-z][A-Za-z0-9+.-]*:/.test(requested)
  ) throw imageExecutionError(400, "INVALID_PROJECT_FILE_PATH", `${label}必须是工程内相对路径`);
  const normalized = path.posix.normalize(requested.replace(/^\.\//, ""));
  if (
    !normalized
    || normalized === "."
    || normalized === ".."
    || normalized.startsWith("../")
    || normalized.split("/").some((segment) => HIDDEN_RESOURCE_NAMES.has(segment))
  ) throw imageExecutionError(400, "INVALID_PROJECT_FILE_PATH", `${label}必须是工程内相对路径`);
  return normalized;
}

function normalizeOutpaintExpansion(value) {
  if (!value || typeof value !== "object" || Array.isArray(value)) {
    throw imageExecutionError(400, "INVALID_OUTPAINT_EXPANSION", "扩图必须指定四边扩展像素");
  }
  const result = {};
  let total = 0;
  for (const side of ["top", "right", "bottom", "left"]) {
    const pixels = Number(value[side] ?? 0);
    if (!Number.isSafeInteger(pixels) || pixels < 0 || pixels > 3_840) {
      throw imageExecutionError(400, "INVALID_OUTPAINT_EXPANSION", "扩图边距必须是 0-3840 的整数");
    }
    result[side] = pixels;
    total += pixels;
  }
  if (!total) throw imageExecutionError(400, "INVALID_OUTPAINT_EXPANSION", "至少需要扩展一侧");
  return result;
}

function normalizeMapImageSourceCrop(value) {
  if (!value || typeof value !== "object" || Array.isArray(value)) {
    throw imageExecutionError(400, "INVALID_MAP_IMAGE_SOURCE_CROP", "裁剪预处理参数无效");
  }
  const result = {};
  let total = 0;
  for (const side of ["top", "right", "bottom", "left"]) {
    const pixels = Number(value[side] ?? 0);
    if (!Number.isSafeInteger(pixels) || pixels < 0 || pixels > 3_840) {
      throw imageExecutionError(400, "INVALID_MAP_IMAGE_SOURCE_CROP", "裁剪边距必须是 0-3840 的整数");
    }
    result[side] = pixels;
    total += pixels;
  }
  if (!total) throw imageExecutionError(400, "INVALID_MAP_IMAGE_SOURCE_CROP", "裁剪预处理至少需要裁掉一侧");
  return result;
}

function normalizeMapImageCropRequest(value) {
  if (!isRecord(value) || String(value.operation || "") !== "crop") {
    throw imageExecutionError(400, "INVALID_MAP_IMAGE_CROP", "纯裁剪请求无效");
  }
  const allowed = new Set(["n", "operation", "outputFormat", "sourceCrop", "sourceSize"]);
  if (Object.keys(value).some((key) => !allowed.has(key))) {
    throw imageExecutionError(400, "INVALID_MAP_IMAGE_CROP", "纯裁剪请求包含不允许的参数");
  }
  if (value.n !== 1 || value.outputFormat !== "png") {
    throw imageExecutionError(400, "INVALID_MAP_IMAGE_CROP", "纯裁剪只能生成一个 PNG 候选");
  }
  const width = Number(value.sourceSize?.width);
  const height = Number(value.sourceSize?.height);
  if (!Number.isSafeInteger(width) || !Number.isSafeInteger(height)
    || width < 1 || height < 1 || width > 16_384 || height > 16_384) {
    throw imageExecutionError(400, "INVALID_MAP_IMAGE_CROP", "纯裁剪源图尺寸无效");
  }
  const sourceCrop = normalizeMapImageSourceCrop(value.sourceCrop);
  const targetWidth = width - sourceCrop.left - sourceCrop.right;
  const targetHeight = height - sourceCrop.top - sourceCrop.bottom;
  if (targetWidth < 1 || targetHeight < 1) {
    throw imageExecutionError(400, "INVALID_MAP_IMAGE_CROP", "纯裁剪后至少需要保留 1×1 像素");
  }
  return Object.freeze({
    operation: "crop",
    sourceSize: Object.freeze({ width, height }),
    sourceCrop: Object.freeze(sourceCrop),
    outputFormat: "png",
    n: 1,
  });
}

function normalizeImageRequestSize(value, imageApi, operation) {
  const normalized = String(value || "").trim();
  const operationCapability = imageApi.operationCapabilities?.[operation] || {
    customSize: !imageApi.limits.fixedSizes?.length,
    sizes: imageApi.limits.fixedSizes || [],
  };
  if (operationCapability.sizes?.includes(normalized)) return normalized;
  if (operationCapability.customSize !== true) {
    throw imageExecutionError(
      400,
      "IMAGE_PROVIDER_SIZE_UNSUPPORTED",
      `当前供应商的 ${operation} 操作不支持尺寸 ${normalized}`,
      {
        stage: "local_prepare",
        operation,
        requestedSize: normalized,
        supportedSizes: [...(operationCapability.sizes || [])],
        customSize: operationCapability.customSize === true,
        reason: "provider_size_unsupported",
        retryable: false,
      },
    );
  }
  if (normalized === "auto" && imageApi.limits.size?.allowAuto) return normalized;
  assertImageSizeWithinLimits(normalized, imageApi.limits.size);
  return normalized;
}

function imageMode(value, fallback, allowed, label) {
  const normalized = String(value ?? fallback).trim();
  if (!allowed.includes(normalized)) {
    throw imageExecutionError(400, "INVALID_IMAGE_OPTION", `${label}无效`);
  }
  return normalized;
}

function assertImageSizeWithinLimits(value, limits) {
  const match = /^(\d{1,4})x(\d{1,4})$/.exec(String(value || ""));
  if (!match || !limits) throw imageExecutionError(400, "INVALID_IMAGE_SIZE", "图片尺寸格式不正确");
  const width = Number(match[1]);
  const height = Number(match[2]);
  const pixels = width * height;
  if (
    width > limits.maxWidth
    || height > limits.maxHeight
    || width % limits.dimensionMultiple !== 0
    || height % limits.dimensionMultiple !== 0
    || Math.max(width / height, height / width) > limits.maxAspectRatio
    || pixels < limits.minPixels
    || pixels > limits.maxPixels
  ) throw imageExecutionError(400, "INVALID_IMAGE_SIZE", "图片尺寸不符合当前管理员预设限制");
  return { width, height };
}

function imageEnum(value, fallback, allowed, label) {
  const normalized = String(value ?? fallback).trim();
  if (!allowed.includes(normalized)) {
    throw imageExecutionError(400, "INVALID_IMAGE_OPTION", `当前图片预设不支持这个${label}`);
  }
  return normalized;
}

function imageBoundedInteger(value, fallback, minimum, maximum, label) {
  const number = Number(value ?? fallback);
  if (!Number.isSafeInteger(number) || number < minimum || number > maximum) {
    throw imageExecutionError(400, "INVALID_IMAGE_OPTION", `${label}必须是 ${minimum}-${maximum} 的整数`);
  }
  return number;
}

function generatedImageRelativePaths(value, format, count) {
  const extension = format === "jpeg" ? ".jpg" : `.${format}`;
  const requested = value == null ? "" : String(value).trim();
  let normalized;
  if (!requested) {
    const timestamp = new Date().toISOString().replace(/[-:]/g, "").replace(/\..+$/, "");
    normalized = `generated-images/generated-${timestamp}-${crypto.randomBytes(3).toString("hex")}${extension}`;
  } else {
    normalized = normalizeImageRelativePath(requested, "图片输出路径");
    const suppliedExtension = path.posix.extname(normalized).toLowerCase();
    const acceptedExtensions = format === "jpeg" ? [".jpg", ".jpeg"] : [extension];
    if (suppliedExtension && !acceptedExtensions.includes(suppliedExtension)) {
      throw imageExecutionError(400, "IMAGE_OUTPUT_FORMAT_MISMATCH", "图片输出路径扩展名与输出格式不符");
    }
    if (!suppliedExtension) normalized += extension;
  }
  if (count === 1) return [normalized];
  const suppliedExtension = path.posix.extname(normalized);
  const stem = normalized.slice(0, -suppliedExtension.length);
  return Array.from({ length: count }, (_, index) => `${stem}-${index + 1}${suppliedExtension}`);
}

async function prepareImageOutputPaths(projectAnchor, storedPaths, fileOwner) {
  await projectAnchor.assertIdentity();
  for (const storedPath of storedPaths) {
    const target = await projectAnchor.resolveTarget(storedPath, {
      directoryMode: 0o750,
      uid: !fileOwner?.legacy && Number.isInteger(fileOwner?.uid) ? fileOwner.uid : null,
      gid: !fileOwner?.legacy && Number.isInteger(fileOwner?.gid) ? fileOwner.gid : null,
    });
    try {
      await fs.lstat(target.targetPath);
      throw imageExecutionError(409, "IMAGE_OUTPUT_EXISTS", "图片输出文件已存在，请选择新的工程内路径");
    } catch (error) {
      if (error.code !== "ENOENT") throw error;
    } finally {
      await target.close();
    }
  }
  await projectAnchor.assertIdentity();
}

function recordImageUsage(runtime, operation, usage) {
  if (!usage) return;
  void recordOpsTraffic({
    kind: "usage",
    operation: operation === "generate" ? "images/generations" : "images/edits",
    status: "reported",
    success: true,
    userId: runtime.user.id,
    username: runtime.user.username,
    tokenUsage: usage,
  }).catch(() => {});
}

function assertImageExecutionActive(signal) {
  if (signal?.aborted) {
    throw imageExecutionError(499, "IMAGE_PROVIDER_CANCELLED", "图片请求已取消");
  }
}

function normalizeImageBatchPublishError(error) {
  const partialOutputs = sanitizeImagePartialOutputs(error?.partialOutputs);
  const rollbackFailures = sanitizeImageRollbackFailures(error?.rollbackFailures);
  if (error?.code === "IMAGE_PROJECT_CHANGED" || error?.code === "IMAGE_PROJECT_SYMLINK") {
    return imageExecutionError(
      409,
      "IMAGE_PROJECT_CHANGED",
      "图片任务提交时工程身份发生变化",
      {},
      error,
    );
  }
  if (error?.code === "IMAGE_OUTPUT_EXISTS" && rollbackFailures.length === 0) {
    return imageExecutionError(409, "IMAGE_OUTPUT_EXISTS", "图片输出文件已存在，请选择新的工程内路径");
  }
  if (partialOutputs.length || rollbackFailures.length) {
    return imageExecutionError(
      500,
      "IMAGE_OUTPUT_ROLLBACK_INCOMPLETE",
      "图片输出发布失败，回滚状态未完全确认",
      { partialOutputs, rollbackFailures },
      error,
    );
  }
  return imageExecutionError(500, "IMAGE_OUTPUT_PUBLISH_FAILED", "图片输出保存失败", {}, error);
}

function sanitizeImagePartialOutputs(value) {
  if (!Array.isArray(value)) return [];
  return value.slice(0, 10).flatMap((entry) => {
    const index = Number(entry?.index);
    const filename = safeImageRollbackFilename(entry?.filename);
    return Number.isSafeInteger(index) && index >= 0 && index < 10 && filename
      ? [{ index, filename }]
      : [];
  });
}

function sanitizeImageRollbackFailures(value) {
  if (!Array.isArray(value)) return [];
  const operations = new Set([
    "close-temporary",
    "remove-output",
    "remove-temporary",
    "sync-directory",
    "verify-output-removal",
  ]);
  return value.slice(0, 32).flatMap((entry) => {
    const operation = operations.has(entry?.operation) ? entry.operation : null;
    if (!operation) return [];
    const output = { operation };
    const index = Number(entry?.index);
    const filename = safeImageRollbackFilename(entry?.filename);
    if (Number.isSafeInteger(index) && index >= 0 && index < 10) output.index = index;
    if (filename) output.filename = filename;
    output.code = typeof entry?.code === "string" && /^[A-Z0-9_]{1,64}$/.test(entry.code)
      ? entry.code
      : "IMAGE_ROLLBACK_FAILED";
    return [output];
  });
}

function safeImageRollbackFilename(value) {
  const filename = typeof value === "string" ? value : "";
  return filename
    && filename.length <= 255
    && !/[\\/\u0000-\u001f\u007f]/.test(filename)
    ? filename
    : null;
}

function imageExecutionError(statusCode, code, message, details = {}, cause = null) {
  const error = new Error(message, cause ? { cause } : undefined);
  error.statusCode = statusCode;
  error.code = code;
  Object.assign(error, details);
  return error;
}

function normalizeImageExecutionError(error) {
  if (Number.isInteger(error?.statusCode) && typeof error?.code === "string") return error;
  if (error?.code === "IMAGE_OUTPUT_EXISTS") {
    return imageExecutionError(409, "IMAGE_OUTPUT_EXISTS", "图片输出文件已存在，请选择新的工程内路径");
  }
  if (error?.code === "INVALID_OUTPAINT" || error?.code === "INVALID_IMAGE") {
    return imageExecutionError(400, error.code, "图片数据无效", {}, error);
  }
  return error;
}

function sendImageExecutionError(response, error) {
  if (response.headersSent) return response.end();
  const normalized = normalizeImageExecutionError(error);
  const status = Number.isInteger(normalized?.statusCode) ? normalized.statusCode : 500;
  response.status(status).json({ error: serializedImageExecutionError(normalized) });
}

function serializedImageExecutionError(error) {
  const normalized = normalizeImageExecutionError(error);
  const status = Number.isInteger(normalized?.statusCode) ? normalized.statusCode : 500;
  const type = typeof normalized?.type === "string" && /^[A-Za-z0-9._:-]{1,100}$/.test(normalized.type)
    ? normalized.type
    : null;
  const safeDetails = {};
  for (const key of [
    "requestedFormat", "actualFormat", "requestedWidth", "requestedHeight",
    "actualWidth", "actualHeight", "requestedCount", "actualCount",
    "providerStatusCode", "moderationDetails", "outputFormat", "outputCompression",
  ]) {
    if (normalized?.[key] != null) safeDetails[key] = normalized[key];
  }
  for (const key of ["stage", "operation", "reason"]) {
    const value = typeof normalized?.[key] === "string" ? normalized[key] : "";
    if (/^[A-Za-z0-9][A-Za-z0-9._:-]{0,99}$/u.test(value)) safeDetails[key] = value;
  }
  const model = typeof normalized?.model === "string" ? normalized.model.trim().slice(0, 200) : "";
  if (model && !/[\u0000-\u001f\u007f]/u.test(model)) safeDetails.model = model;
  for (const key of ["requestedSize", "providerSize", "sourceSize"]) {
    const value = typeof normalized?.[key] === "string" ? normalized[key] : "";
    if (/^(?:auto|[1-9]\d{0,4}x[1-9]\d{0,4})$/u.test(value)) safeDetails[key] = value;
  }
  if (["strict", "soft"].includes(normalized?.maskMode)) safeDetails.maskMode = normalized.maskMode;
  if (["exact", "seamless"].includes(normalized?.preserveSource)) {
    safeDetails.preserveSource = normalized.preserveSource;
  }
  if (["reject", "pad-and-crop", "rescale-and-crop"].includes(normalized?.alignmentPolicy)) {
    safeDetails.alignmentPolicy = normalized.alignmentPolicy;
  }
  if (typeof normalized?.customSize === "boolean") safeDetails.customSize = normalized.customSize;
  if (Array.isArray(normalized?.supportedSizes)) {
    safeDetails.supportedSizes = [...new Set(normalized.supportedSizes
      .filter((value) => typeof value === "string" && /^(?:auto|[1-9]\d{0,4}x[1-9]\d{0,4})$/u.test(value)))]
      .slice(0, 64);
  }
  const partialOutputs = sanitizeImagePartialOutputs(normalized?.partialOutputs);
  const rollbackFailures = sanitizeImageRollbackFailures(normalized?.rollbackFailures);
  return {
    code: typeof normalized?.code === "string" ? normalized.code : "IMAGE_EXECUTION_FAILED",
    ...(type ? { type } : {}),
    message: status >= 500 && !Number.isInteger(normalized?.statusCode)
      ? "图片操作失败"
      : String(normalized?.message || "图片操作失败").slice(0, 2_000),
    retryable: normalized?.retryable === true,
    ...(normalized?.providerRequestId || normalized?.requestId
      ? { requestId: String(normalized.providerRequestId || normalized.requestId).slice(0, 200) }
      : {}),
    ...safeDetails,
    ...(partialOutputs.length ? { partialOutputs } : {}),
    ...(rollbackFailures.length ? { rollbackFailures } : {}),
  };
}

async function writeImageSseEvent(response, eventName, value) {
  if (response.destroyed || response.writableEnded) {
    throw imageExecutionError(499, "IMAGE_PROVIDER_CANCELLED", "图片流式请求已取消");
  }
  const payload = `event: ${eventName}\ndata: ${JSON.stringify(value)}\n\n`;
  if (!response.write(payload)) {
    await new Promise((resolve, reject) => {
      const cleanup = () => {
        response.off("drain", onDrain);
        response.off("close", onClose);
        response.off("error", onError);
      };
      const onDrain = () => {
        cleanup();
        resolve();
      };
      const onClose = () => {
        cleanup();
        reject(imageExecutionError(499, "IMAGE_PROVIDER_CANCELLED", "图片流式请求已取消"));
      };
      const onError = (error) => {
        cleanup();
        reject(error);
      };
      response.once("drain", onDrain);
      response.once("close", onClose);
      response.once("error", onError);
    });
  }
  response.flush?.();
}

function generatedImageRelativePath(value) {
  const requested = value == null ? "" : String(value).trim();
  if (!requested) {
    const timestamp = new Date().toISOString().replace(/[-:]/g, "").replace(/\..+$/, "");
    return `generated-images/generated-${timestamp}-${crypto.randomBytes(3).toString("hex")}.png`;
  }
  if (
    requested.length > 1_024
    || requested.includes("\\")
    || /[\u0000\r\n]/.test(requested)
    || path.posix.isAbsolute(requested)
  ) throw httpError(400, "图片输出路径必须是工程内的 PNG 相对路径");
  const normalized = path.posix.normalize(requested.replace(/^\.\//, ""));
  if (
    !normalized
    || normalized === "."
    || normalized === ".."
    || normalized.startsWith("../")
    || path.posix.extname(normalized).toLowerCase() !== ".png"
  ) throw httpError(400, "图片输出路径必须是工程内的 PNG 相对路径");
  return normalized;
}

app.post(
  "/api/uploads",
  express.raw({ type: "application/octet-stream", limit: UPLOAD_LIMIT_BYTES }),
  async (request, response, next) => {
    try {
      const runtime = await runtimeForRequest(request);
      if (typeof request.query.project !== "string" || !request.query.project) {
        throw httpError(400, "Project path is required");
      }
      const projectPath = path.resolve(request.query.project);
      const originalName = String(request.query.name || "");
      await assertWritableProjectDirectory(projectPath, runtime);
      if (!Buffer.isBuffer(request.body) || request.body.length === 0) {
        throw httpError(400, "Upload is empty");
      }
      await assertQuotaAvailable(runtime, request.body.length);

      const safeName = sanitizeUploadName(originalName);
      const uploadDir = path.join(projectPath, ".codex-uploads");
      const storedName = `${Date.now()}-${crypto.randomBytes(4).toString("hex")}-${safeName}`;
      const storedPath = path.join(uploadDir, storedName);
      await fs.mkdir(uploadDir, { recursive: true, mode: 0o700 });
      await fs.writeFile(storedPath, request.body, { flag: "wx", mode: 0o600 });
      const fileOwner = runtime.user;
      if (!fileOwner.legacy && Number.isInteger(fileOwner.uid) && Number.isInteger(fileOwner.gid)) {
        await Promise.all([
          fs.chown(uploadDir, fileOwner.uid, fileOwner.gid),
          fs.chown(storedPath, fileOwner.uid, fileOwner.gid),
        ]);
      }
      response.status(201).json({
        name: originalName,
        path: storedPath,
        size: request.body.length,
        mediaType: normalizeMediaType(request.headers["x-file-type"]),
        sha256: crypto.createHash("sha256").update(request.body).digest("hex"),
      });
    } catch (error) {
      next(error);
    } finally {
      request.completePersistentStateOperation?.();
    }
  },
);

app.get("/api/files/image", async (request, response, next) => {
  try {
    if (typeof request.query.path !== "string" || !request.query.path) {
      throw httpError(400, "File path is required");
    }
    const filePath = path.resolve(request.query.path);
    const runtime = await runtimeForRequest(request);
    const accessRoot = await accessibleImageRootForPath(filePath, runtime);
    if (!accessRoot || filePath === accessRoot.path) throw httpError(400, "Invalid file path");
    const realFilePath = await assertRealPathInside(accessRoot.realPath, filePath);
    const stat = await fs.stat(realFilePath);
    if (!stat.isFile() || stat.size > UPLOAD_LIMIT_BYTES) {
      throw httpError(413, "Image preview exceeds the safe size limit");
    }
    const mediaType = imageMediaType(realFilePath);
    if (!mediaType) throw httpError(415, "Only image files can be previewed");
    const previewRequested = typeof request.query.preview === "string" && Boolean(request.query.preview);
    const responsePath = previewRequested
      ? await cachedImagePreview(realFilePath, stat, webSettingsStore.imagePreview())
      : realFilePath;
    response.setHeader(
      "Cache-Control",
      previewRequested ? "private, max-age=86400" : "private, max-age=0, must-revalidate",
    );
    response.type(previewRequested ? "image/webp" : mediaType).sendFile(responsePath, { dotfiles: "allow" }, (error) => {
      if (error) next(error);
    });
  } catch (error) {
    next(error);
  }
});

app.get("/api/files/list", async (request, response, next) => {
  try {
    const runtime = await runtimeForRequest(request);
    const { projectPath, targetPath } = await resolveResourceTarget(request.query.project, request.query.path, runtime);
    const targetStat = await fs.stat(targetPath);
    if (!targetStat.isDirectory()) throw httpError(400, "Resource path is not a directory");
    const dirents = await fs.readdir(targetPath, { withFileTypes: true });
    const entries = await Promise.all(
      dirents
        .filter((entry) => !HIDDEN_RESOURCE_NAMES.has(entry.name))
        .map(async (entry) => {
          const entryPath = path.join(targetPath, entry.name);
          const type = entry.isDirectory() ? "directory" : entry.isFile() ? "file" : "other";
          let size = null;
          let modifiedAt = null;
          let version = null;
          let mode = null;
          if (type !== "other") {
            const stat = await fs.stat(entryPath);
            size = type === "file" ? stat.size : null;
            modifiedAt = stat.mtimeMs;
            version = resourceEntryVersion(stat);
            mode = stat.mode & 0o777;
          }
          return {
            name: entry.name,
            path: entryPath,
            relativePath: path.relative(projectPath, entryPath) || ".",
            type,
            size,
            modifiedAt,
            version,
            mode,
          };
        }),
    );
    entries.sort(resourceEntrySort);
    response.json({
      projectPath,
      directoryPath: targetPath,
      relativePath: path.relative(projectPath, targetPath) || ".",
      parentPath: targetPath === projectPath ? null : path.dirname(targetPath),
      writable: resourceProjectIsWritable(projectPath, runtime),
      entries,
    });
  } catch (error) {
    next(error);
  }
});

