app.get("/api/files/read", async (request, response, next) => {
  try {
    const runtime = await runtimeForRequest(request);
    const { projectPath, targetPath } = await resolveResourceTarget(request.query.project, request.query.path, runtime);
    const stat = await fs.stat(targetPath);
    if (!stat.isFile()) throw httpError(400, "Resource path is not a file");
    const preview = await readResourcePreview(targetPath, stat);
    response.json({
      name: path.basename(targetPath),
      path: targetPath,
      relativePath: path.relative(projectPath, targetPath),
      size: stat.size,
      modifiedAt: stat.mtimeMs,
      version: preview.version,
      editable: resourceProjectIsWritable(projectPath, runtime)
        && !preview.binary
        && !preview.truncated,
      content: preview.content,
      binary: preview.binary,
      truncated: preview.truncated,
      omittedBytes: preview.omittedBytes,
      nextOffset: preview.nextOffset,
      previewKind: resourcePreviewKind(targetPath, preview.binary),
      mode: stat.mode & 0o777,
      uid: stat.uid,
      gid: stat.gid,
    });
  } catch (error) {
    next(error);
  }
});

app.get("/api/files/read-chunk", async (request, response, next) => {
  try {
    const runtime = await runtimeForRequest(request);
    const { projectPath, targetPath } = await resolveResourceTarget(
      request.query.project,
      request.query.path,
      runtime,
    );
    const stat = await fs.stat(targetPath);
    if (!stat.isFile()) throw httpError(400, "Resource path is not a file");
    const offset = Number(request.query.offset);
    if (!Number.isSafeInteger(offset) || offset < 0 || offset >= stat.size) {
      throw httpError(400, "文件分段位置无效");
    }
    const chunk = await readResourceTextChunk(targetPath, stat, offset, FILE_PREVIEW_CHUNK_BYTES);
    response.setHeader("Cache-Control", "no-store");
    response.json({
      projectPath,
      path: targetPath,
      relativePath: path.relative(projectPath, targetPath),
      size: stat.size,
      modifiedAt: stat.mtimeMs,
      version: resourceEntryVersion(stat),
      content: chunk.content,
      offset,
      nextOffset: chunk.nextOffset,
      omittedBytes: Math.max(0, stat.size - chunk.nextOffset),
      eof: chunk.nextOffset >= stat.size,
    });
  } catch (error) {
    next(error);
  }
});

