app.put("/api/map-projects/sessions/:sessionId/character", async (request, response, next) => {
  try {
    assertOperationRequest(request, "map-project-character-save");
    if (!mapProjectSessions || !mapProjectResourceWriter) {
      throw httpError(404, "角色动画保存功能在救援窗口中不可用");
    }
    const contentType = String(request.get("content-type") || "").split(";", 1)[0].trim().toLowerCase();
    if (contentType !== "application/octet-stream") {
      throw httpError(415, "角色动画保存必须使用 application/octet-stream");
    }
    const declaredBytes = Number(request.get("content-length"));
    if (Number.isFinite(declaredBytes) && (declaredBytes <= 0 || declaredBytes > mapProjectResourceWriter.maxBytes)) {
      throw httpError(413, "角色动画清单超过管理员设置的保存上限");
    }
    const runtime = await runtimeForRequest(request);
    const context = await mapProjectContextForRequest(request, runtime);
    if (!context.writable || !resourceProjectIsWritable(context.projectPath, runtime)) {
      throw httpError(403, "当前账号没有这个地图工程的写权限");
    }
    await assertWritableProjectDirectory(context.projectPath, runtime);
    const relativePath = mapProjectSessions.authorizeRelativePath({
      sessionId: request.params.sessionId,
      identity: mapProjectSessionIdentity(request),
      relativePath: request.query.path,
      kind: "character",
    });
    const chunks = [];
    let bytes = 0;
    for await (const chunk of request) {
      bytes += chunk.length;
      if (bytes > mapProjectResourceWriter.maxBytes) throw httpError(413, "角色动画清单超过管理员设置的保存上限");
      chunks.push(chunk);
    }
    if (!bytes) throw httpError(400, "角色动画清单内容不能为空");
    let document;
    try {
      const source = new TextDecoder("utf-8", { fatal: true }).decode(Buffer.concat(chunks));
      document = JSON.parse(source.replace(/^\uFEFF/u, ""));
    } catch {
      throw httpError(422, "角色动画清单必须是有效的 UTF-8 JSON");
    }
    const character = await mapProjectResourceWriter.saveCharacterAnimation({
      projectPath: context.projectPath,
      resourceRoots: context.resourceRoots,
      relativePath,
      expectedVersion: request.get("x-wfl-project-resource-version"),
      document,
    });
    response.setHeader("Cache-Control", "no-store");
    response.status(character.created ? 201 : 200).json({
      projectSessionId: request.params.sessionId,
      character,
    });
  } catch (error) {
    next(error);
  } finally {
    request.completePersistentStateOperation?.();
  }
});

app.post("/api/map-projects/sessions/:sessionId/maps", async (request, response, next) => {
  try {
    assertOperationRequest(request, "map-project-map-create");
    if (!mapProjectSessions) throw httpError(404, "新建地图在救援窗口中不可用");
    const runtime = await runtimeForRequest(request);
    const context = await mapProjectContextForRequest(request, runtime);
    if (!context.writable || !resourceProjectIsWritable(context.projectPath, runtime)) {
      throw httpError(403, "当前账号没有这个地图工程的写权限");
    }
    await assertWritableProjectDirectory(context.projectPath, runtime);
    const relativePath = mapProjectSessions.authorizeRelativePath({
      sessionId: request.params.sessionId,
      identity: mapProjectSessionIdentity(request),
      relativePath: request.body?.relativePath,
      kind: "map",
    });
    const requestedTilesets = request.body?.tilesets ?? [];
    if (!Array.isArray(requestedTilesets) || requestedTilesets.length > 1) {
      throw httpError(400, "新建地图最多选择一个外部瓦片集");
    }
    const tilesets = [];
    for (const requestedPath of requestedTilesets) {
      const tilesetPath = mapProjectSessions.authorizeRelativePath({
        sessionId: request.params.sessionId,
        identity: mapProjectSessionIdentity(request),
        relativePath: requestedPath,
        kind: "tileset",
      });
      const { targetPath } = await resolveResourceTarget(
        context.projectPath,
        path.join(context.projectPath, ...tilesetPath.split("/")),
        runtime,
      );
      await inspectTiledTilesetInChild({
        candidatePath: targetPath,
        sourcePath: tilesetPath,
        projectPath: context.projectPath,
        memoryMb: MAP_SAVE_VALIDATION_MEMORY_MB,
        timeoutMs: MAP_SAVE_VALIDATION_TIMEOUT_MS,
      });
      tilesets.push(tilesetPath);
    }
    const map = await createTiledMap({
      projectPath: context.projectPath,
      relativePath,
      orientation: request.body?.orientation,
      infinite: request.body?.infinite === true,
      width: request.body?.width,
      height: request.body?.height,
      tilewidth: request.body?.tilewidth,
      tileheight: request.body?.tileheight,
      renderorder: request.body?.renderorder,
      initialLayerName: request.body?.initialLayerName,
      tilesets,
      backgroundcolor: request.body?.backgroundcolor,
      staggeraxis: request.body?.staggeraxis,
      staggerindex: request.body?.staggerindex,
      hexsidelength: request.body?.hexsidelength,
      skewx: request.body?.skewx,
      skewy: request.body?.skewy,
      targetVersion: request.body?.targetVersion,
    }, {
      maxTileBytes: mapSaveSessionConfig().maxBytes,
      validationMemoryMb: MAP_SAVE_VALIDATION_MEMORY_MB,
      validationTimeoutMs: MAP_SAVE_VALIDATION_TIMEOUT_MS,
    });
    response.setHeader("Cache-Control", "no-store");
    response.status(201).json({ projectSessionId: request.params.sessionId, map });
  } catch (error) {
    next(error);
  }
});

