app.post("/api/maps/sessions", async (request, response, next) => {
  try {
    assertOperationRequest(request, "map-session-open");
    if (!mapFileSessions) throw httpError(404, "地图编辑器在救援窗口中不可用");
    const runtime = await runtimeForRequest(request);
    const editorInstanceId = normalizeMapEditorInstanceId(request.body?.editorInstanceId);
    let projectPath;
    let targetPath;
    let projectFilePath = null;
    let projectResourceRoots;
    let projectSessionWritable = true;
    if (request.body?.projectSessionId) {
      if (!mapProjectSessions) throw httpError(404, "地图项目工作区在救援窗口中不可用");
      const projectContext = await mapProjectContextForRequest(request, runtime, request.body.projectSessionId);
      if (request.body?.project) {
        const expectedProject = await resolveResourceTarget(request.body.project, null, runtime);
        if (path.resolve(expectedProject.projectPath) !== path.resolve(projectContext.projectPath)) {
          throw httpError(403, "地图项目会话与当前工程不匹配");
        }
      }
      const relativePath = mapProjectSessions.authorizeRelativePath({
        sessionId: request.body.projectSessionId,
        identity: mapProjectSessionIdentity(request),
        relativePath: request.body?.path,
        kind: "map",
      });
      ({ projectPath, targetPath } = await resolveResourceTarget(
        projectContext.projectPath,
        path.join(projectContext.projectPath, ...relativePath.split("/")),
        runtime,
      ));
      projectSessionWritable = projectContext.writable;
      projectFilePath = projectContext.projectFilePath;
      projectResourceRoots = projectContext.resourceRoots;
    } else {
      ({ projectPath, targetPath } = await resolveResourceTarget(
        request.body?.project,
        request.body?.path,
        runtime,
      ));
    }
    const session = await mapFileSessions.open({
      identity: mapSessionIdentity(request, editorInstanceId),
      projectPath,
      targetPath,
      projectFilePath,
      projectResourceRoots,
      writable: projectSessionWritable && resourceProjectIsWritable(projectPath, runtime),
      config: mapReadSessionConfig(),
    });
    try {
      const manifest = await inspectTiledMapInChild({
        candidatePath: targetPath,
        sourcePath: session.relativePath,
        projectPath,
        memoryMb: MAP_SAVE_VALIDATION_MEMORY_MB,
        timeoutMs: MAP_SAVE_VALIDATION_TIMEOUT_MS,
      });
      if (manifest.version !== session.version) {
        throw httpError(409, "地图在资源清单校验期间发生变化，请重试");
      }
      mapFileSessions.setResources({
        sessionId: session.id,
        identity: mapSessionIdentity(request, editorInstanceId),
        version: session.version,
        resourcePaths: manifest.resources,
      });
    } catch (error) {
      mapFileSessions.close({
        sessionId: session.id,
        identity: mapSessionIdentity(request, editorInstanceId),
      });
      throw error;
    }
    response.status(201).json({ session });
  } catch (error) {
    next(error);
  }
});

