app.put("/api/maps/sessions/:sessionId/project-template", async (request, response, next) => {
  try {
    assertOperationRequest(request, "map-project-template-save");
    if (!mapFileSessions || !mapProjectResourceWriter) {
      throw httpError(404, "对象模板保存功能在救援窗口中不可用");
    }
    const contentType = String(request.get("content-type") || "").split(";", 1)[0].trim().toLowerCase();
    if (contentType !== "application/octet-stream") {
      throw httpError(415, "对象模板保存必须使用 application/octet-stream");
    }
    const declaredBytes = Number(request.get("content-length"));
    if (Number.isFinite(declaredBytes) && (declaredBytes <= 0 || declaredBytes > mapProjectResourceWriter.maxBytes)) {
      throw httpError(413, "对象模板超过管理员设置的保存上限");
    }
    const runtime = await runtimeForRequest(request);
    const editorInstanceId = normalizeMapEditorInstanceId(
      request.get("x-codex-desktop-editor-instance"),
    );
    const identity = mapSessionIdentity(request, editorInstanceId);
    const context = mapFileSessions.context({ sessionId: request.params.sessionId, identity });
    await assertWritableMapContext(context, runtime);
    if (!context.projectFilePath) throw httpError(404, "当前地图没有绑定 .tiled-project 素材目录");
    const chunks = [];
    let bytes = 0;
    for await (const chunk of request) {
      bytes += chunk.length;
      if (bytes > mapProjectResourceWriter.maxBytes) {
        throw httpError(413, "对象模板超过管理员设置的保存上限");
      }
      chunks.push(chunk);
    }
    if (!bytes) throw httpError(400, "对象模板内容不能为空");
    let document;
    try {
      const source = new TextDecoder("utf-8", { fatal: true }).decode(Buffer.concat(chunks));
      document = JSON.parse(source.replace(/^\uFEFF/u, ""));
    } catch {
      throw httpError(422, "对象模板必须是有效的 UTF-8 JSON");
    }
    const template = await mapProjectResourceWriter.saveTemplate({
      projectPath: context.projectPath,
      resourceRoots: context.projectResourceRoots,
      relativePath: request.query.path,
      expectedVersion: request.get("x-wfl-project-resource-version"),
      document,
    });
    response.setHeader("Cache-Control", "no-store");
    response.status(template.created ? 201 : 200).json({
      mapSessionId: request.params.sessionId,
      mapVersion: context.version,
      template,
    });
  } catch (error) {
    next(error);
  } finally {
    request.completePersistentStateOperation?.();
  }
});

app.put("/api/maps/sessions/:sessionId/project-composite", async (request, response, next) => {
  try {
    assertOperationRequest(request, "map-project-composite-save");
    if (!mapFileSessions || !mapProjectResourceWriter) {
      throw httpError(404, "组合素材保存功能在救援窗口中不可用");
    }
    const contentType = String(request.get("content-type") || "").split(";", 1)[0].trim().toLowerCase();
    if (contentType !== "application/octet-stream") {
      throw httpError(415, "组合素材保存必须使用 application/octet-stream");
    }
    const declaredBytes = Number(request.get("content-length"));
    if (Number.isFinite(declaredBytes) && (declaredBytes <= 0 || declaredBytes > mapProjectResourceWriter.maxBytes)) {
      throw httpError(413, "组合素材超过管理员设置的保存上限");
    }
    const runtime = await runtimeForRequest(request);
    const editorInstanceId = normalizeMapEditorInstanceId(request.get("x-codex-desktop-editor-instance"));
    const identity = mapSessionIdentity(request, editorInstanceId);
    const context = mapFileSessions.context({ sessionId: request.params.sessionId, identity });
    await assertWritableMapContext(context, runtime);
    if (!context.projectFilePath) throw httpError(404, "当前地图没有绑定 .tiled-project 素材目录");
    const chunks = [];
    let bytes = 0;
    for await (const chunk of request) {
      bytes += chunk.length;
      if (bytes > mapProjectResourceWriter.maxBytes) throw httpError(413, "组合素材超过管理员设置的保存上限");
      chunks.push(chunk);
    }
    if (!bytes) throw httpError(400, "组合素材内容不能为空");
    let document;
    try {
      const source = new TextDecoder("utf-8", { fatal: true }).decode(Buffer.concat(chunks));
      document = JSON.parse(source.replace(/^\uFEFF/u, ""));
    } catch {
      throw httpError(422, "组合素材必须是有效的 UTF-8 JSON");
    }
    const composite = await mapProjectResourceWriter.saveCompositeMap({
      projectPath: context.projectPath,
      resourceRoots: context.projectResourceRoots,
      relativePath: request.query.path,
      expectedVersion: request.get("x-wfl-project-resource-version"),
      document,
      validate: async ({ candidatePath, projectPath, relativePath }) => {
        const validation = await inspectTiledMapInChild({
          candidatePath,
          sourcePath: relativePath,
          projectPath,
          memoryMb: MAP_SAVE_VALIDATION_MEMORY_MB,
          timeoutMs: MAP_SAVE_VALIDATION_TIMEOUT_MS,
        });
        if (validation.errors?.length) throw httpError(422, "组合素材 Tiled 校验失败");
      },
    });
    response.setHeader("Cache-Control", "no-store");
    response.status(composite.created ? 201 : 200).json({
      mapSessionId: request.params.sessionId,
      mapVersion: context.version,
      composite,
    });
  } catch (error) {
    next(error);
  } finally {
    request.completePersistentStateOperation?.();
  }
});

