app.get("/api/map-tilesets/sessions/:sessionId/resource", async (request, response, next) => {
  try {
    if (!tilesetFileSessions) throw httpError(404, "瓦片集编辑器在救援窗口中不可用");
    const runtime = await runtimeForRequest(request);
    const editorInstanceId = normalizeMapEditorInstanceId(request.get("x-codex-desktop-editor-instance"));
    const identity = mapSessionIdentity(request, editorInstanceId);
    const context = tilesetFileSessions.context({ sessionId: request.params.sessionId, identity });
    await assertReadableMapContext(context, runtime);
    const resourcePath = tilesetFileSessions.authorizeResource({
      sessionId: request.params.sessionId,
      identity,
      resourcePath: request.query.path,
    });
    const { targetPath } = await resolveResourceTarget(
      context.projectPath,
      path.resolve(context.projectPath, resourcePath),
      runtime,
    );
    const stat = await fs.stat(targetPath);
    const extension = path.extname(targetPath).toLowerCase();
    if (!stat.isFile() || !MAP_RESOURCE_EXTENSIONS.has(extension)) {
      throw httpError(415, "瓦片集资源类型不受支持");
    }
    response.setHeader("Cache-Control", "no-store");
    if (extension === ".tsj") response.type("application/json; charset=utf-8");
    else if (extension === ".svg") response.type("image/svg+xml");
    response.sendFile(targetPath, { dotfiles: "deny" }, (error) => {
      if (error && !response.headersSent) next(error);
    });
  } catch (error) {
    next(error);
  }
});

