// Collaboration policy is WFL user state, never Tiled runtime data.  Reads
// return only the public project fingerprint/map path and ownership markers;
// writes use an optimistic revision so a policy change affects new saves and
// tasks without silently invalidating an already-running operation.
app.get("/api/maps/sessions/:sessionId/collaboration-policy", async (request, response, next) => {
  try {
    if (!mapFileSessions || !mapCollaborationPolicies) throw httpError(404, "地图协同策略在救援窗口中不可用");
    const editorInstanceId = normalizeMapEditorInstanceId(request.get("x-codex-desktop-editor-instance"));
    const identity = mapSessionIdentity(request, editorInstanceId);
    const context = mapFileSessions.context({ sessionId: request.params.sessionId, identity });
    const policy = mapCollaborationPolicies.get({
      userId: request.user.id,
      projectPath: context.projectPath,
      mapPath: context.relativePath,
    });
    response.setHeader("Cache-Control", "no-store");
    response.json({ policy });
  } catch (error) {
    next(error);
  }
});

