app.post("/api/map-ai/managed-authorizations/:authorizationId/transfer", async (request, response, next) => {
  try {
    assertOperationRequest(request, "map-ai-managed-authorization-transfer");
    if (!mapAiManagedAuthorizations) throw httpError(404, "地图 AI 托管在救援窗口中不可用");
    const body = request.body && typeof request.body === "object" && !Array.isArray(request.body) ? request.body : {};
    if (Object.keys(body).some((key) => !["targetThreadId", "expectedThreadId", "reason"].includes(key))) {
      throw httpError(400, "托管授权转交请求包含未知字段");
    }
    const runtime = await runtimeForRequest(request);
    const identity = managedMapAiIdentity(request);
    const current = mapAiManagedAuthorizations.taskContract({
      authorizationId: request.params.authorizationId,
      identity,
    });
    const previousThreadId = current.scope.threadId;
    const targetThreadId = normalizeMapAiThreadId(body.targetThreadId);
    const expectedThreadId = body.expectedThreadId === undefined
      ? previousThreadId
      : normalizeMapAiThreadId(body.expectedThreadId);
    await assertMapAiThreadProject(runtime, targetThreadId, current.scope.projectPath);
    const authorization = await mapAiManagedAuthorizations.transferThread({
      authorizationId: request.params.authorizationId,
      identity,
      targetThreadId,
      expectedThreadId,
      reason: body.reason || "用户显式转交托管授权",
    });
    // Old-thread tasks retain their immutable snapshot but can no longer pass
    // authority matching. Mark them canceled immediately so no scheduler can
    // leave a stale task looking resumable after the handoff.
    await mapAiManagedTasks?.cancelForAuthorization({
      authorizationId: request.params.authorizationId,
      threadId: previousThreadId,
      reason: "托管授权已转交到新 Thread，旧 Thread 任务已停止",
    });
    response.setHeader("Cache-Control", "no-store");
    response.json({ authorization });
  } catch (error) {
    next(error);
  }
});

app.post("/api/map-ai/managed-tasks", async (request, response, next) => {
  try {
    assertOperationRequest(request, "map-ai-managed-task-create");
    if (!mapAiManagedAuthorizations || !mapAiManagedTasks) throw httpError(404, "地图 AI 托管在救援窗口中不可用");
    const runtime = await runtimeForRequest(request);
    const identity = managedMapAiIdentity(request);
    const body = request.body && typeof request.body === "object" && !Array.isArray(request.body) ? request.body : {};
    const allowedKeys = new Set(["authorizationId", "clientOperationId", "request", "planSummary", "settingsSnapshot"]);
    if (Object.keys(body).some((key) => !allowedKeys.has(key))) throw httpError(400, "托管任务请求包含未知字段");
    const contract = mapAiManagedAuthorizations.taskContract({ authorizationId: body.authorizationId, identity });
    if (contract.scope.projectWide === true) {
      // Project grants intentionally do not carry a frozen map list. Reuse
      // the same live project operation path as the managed MCP adapter so an
      // HTTP client cannot accidentally fall back to `mapPaths[0]` and lose
      // asset-only or cross-map tasks.
      const plan = body.request?.patch && typeof body.request.patch === "object"
        ? body.request.patch
        : body.request;
      const action = plan?.format === "wfl-tiled-resource-patch"
        ? (contract.allowedOps.includes("apply_project_patch") ? "apply_project_patch" : "apply_tiled_resource_patch")
        : "apply_tiled_patch";
      const operation = await executeManagedProjectWideOperation(runtime, {
        action,
        authorizationId: body.authorizationId,
        patch: plan,
        clientOperationId: body.clientOperationId,
      }, contract);
      response.setHeader("Cache-Control", "no-store");
      response.status(operation.created ? 201 : 200).json({ created: operation.created, task: operation.task });
      return;
    }
    const mapPath = contract.scope.mapPaths[0];
    const projectPath = contract.scope.projectPath;
    await assertSafeProjectDirectory(projectPath, runtime);
    await assertMapAiThreadProject(runtime, contract.scope.threadId, projectPath);
    await assertManagedCollaborationPolicyCurrent({
      contract,
      projectPath,
      mapPath,
      requireWrite: contract.allowedOps.some((operation) => ["apply_tiled_patch", "apply_tiled_resource_patch"].includes(operation)),
    });
    const targetPath = path.join(projectPath, ...mapPath.split("/"));
      for (const scopedMapPath of contract.scope.mapPaths) {
      const scopedTarget = path.join(projectPath, ...scopedMapPath.split("/"));
      const inspected = await inspectMapFile(scopedTarget, { maxBytes: MAP_SAVE_MAX_BYTES });
      if (inspected.version !== contract.scope.mapVersions[scopedMapPath]) {
        throw httpError(409, `托管授权的地图 ${scopedMapPath} 基础版本已变化，请重新授权`);
      }
    for (const resourcePath of contract.scope.targetFiles || contract.scope.mapPaths) {
      if (contract.scope.mapPaths.includes(resourcePath)) continue;
      const expected = contract.scope.targetFileVersions?.[resourcePath];
      const target = path.join(projectPath, ...resourcePath.split("/"));
      const current = await inspectManagedResourceVersion(target).catch((error) => {
        if (expected === null && error?.statusCode === 404) return null;
        throw error;
      });
      if ((current?.version || null) !== expected) throw httpError(409, `托管资源 ${resourcePath} 基础版本已变化，请重新授权`);
    }
    }
    const result = await mapAiManagedTasks.create({
      identity,
      authority: {
        authorityMode: "managed",
        managedAuthorizationId: contract.id,
        threadId: contract.scope.threadId,
        projectPath,
        mapSessionId: null,
        mapPath,
        baseVersion: contract.scope.mapVersions[mapPath],
        mapPaths: contract.scope.mapPaths,
        mapVersions: contract.scope.mapVersions,
        targetFiles: contract.scope.targetFiles,
        targetFileVersions: contract.scope.targetFileVersions,
        allowedOps: contract.allowedOps,
        protectedTargets: contract.protectedTargets,
        collaborationPolicy: contract.collaborationPolicy,
        expiresAt: contract.expiresAt,
      },
      approvalSnapshot: contract.approvalSnapshot,
      settingsSnapshot: body.settingsSnapshot || {},
      clientOperationId: body.clientOperationId,
      request: body.request,
      planSummary: body.planSummary,
    });
    // Start only after the durable task contract exists. Execution is
    // idempotent and stops at the fixed approval gate for ask_each or
    // medium/high ai_review work; failures remain isolated to this task.
    if (result.created && mapAiManagedTaskExecutor && isExecutableManagedPlan(body.request)) {
      scheduleMapAiManagedTaskExecution({ taskId: result.task.id, identity });
    }
    response.setHeader("Cache-Control", "no-store");
    response.status(result.created ? 201 : 200).json(result);
  } catch (error) {
    next(error);
  }
});

function isExecutableManagedPlan(value) {
  const patch = value?.patch && typeof value.patch === "object" ? value.patch : value;
  return (patch?.format === "wfl-tiled-patch" && patch?.version === 1 && Array.isArray(patch.operations))
    || (patch?.format === "wfl-multi-map-patch" && patch?.version === 1 && Array.isArray(patch.maps))
    || (patch?.format === "wfl-tiled-resource-patch" && patch?.version === 1 && Array.isArray(patch.files));
}

