app.post("/api/map-ai/managed-tasks/:taskId/action", async (request, response, next) => {
  try {
    assertOperationRequest(request, "map-ai-managed-task-action");
    if (!mapAiManagedTasks) throw httpError(404, "地图 AI 托管在救援窗口中不可用");
    const body = request.body && typeof request.body === "object" && !Array.isArray(request.body) ? request.body : {};
    const allowedKeys = new Set(["action", "approvalId", "confirmation", "reason"]);
    if (Object.keys(body).some((key) => !allowedKeys.has(key))) throw httpError(400, "托管任务操作请求无效");
    const task = await mapAiManagedTasks.transition({
      taskId: request.params.taskId,
      identity: managedMapAiIdentity(request),
      ...body,
    });
    if (mapAiManagedTaskExecutor && ["approve", "resume"].includes(body.action)) {
      scheduleMapAiManagedTaskExecution({
        taskId: request.params.taskId,
        identity: managedMapAiIdentity(request),
      });
    }
    response.setHeader("Cache-Control", "no-store");
    // The transition is durable before the executor is scheduled. Do not hold
    // this request open while parsing/uploading a large map or running Tiled;
    // clients observe completion through the task snapshot/events endpoints.
    response.json({ task });
  } catch (error) {
    next(error);
  }
});

function scheduleMapAiManagedTaskExecution({ taskId, identity } = {}) {
  if (!mapAiManagedTaskExecutor || !taskId || !identity) return false;
  // A separate turn guarantees that the HTTP response can be flushed before
  // any map parsing, validation, or chunked save work begins. The executor has
  // its own idempotent queue, so duplicate scheduling is harmless.
  setImmediate(() => {
    void mapAiManagedTaskExecutor.execute({ taskId, identity }).catch(() => {});
  });
  return true;
}

app.post("/api/maps/sessions/:sessionId/ai-leases", async (request, response, next) => {
  try {
    assertOperationRequest(request, "map-ai-lease-grant");
    if (!mapAiAccess || !mapFileSessions) throw httpError(404, "地图 AI 工具在救援窗口中不可用");
    const runtime = await runtimeForRequest(request);
    const editorInstanceId = normalizeMapEditorInstanceId(
      request.get("x-codex-desktop-editor-instance") || request.body?.editorInstanceId,
    );
    const identity = mapSessionIdentity(request, editorInstanceId);
    const context = mapFileSessions.context({
      sessionId: request.params.sessionId,
      identity,
    });
    await assertWritableMapContext(context, runtime);
    const inspected = await inspectMapFile(context.targetPath, { maxBytes: MAP_SAVE_MAX_BYTES });
    if (inspected.version !== context.version) {
      throw httpError(409, "地图文件已经变化，请重新打开编辑器后授权");
    }
    const body = request.body && typeof request.body === "object" && !Array.isArray(request.body)
      ? request.body
      : {};
    const allowedKeys = new Set(["threadId", "allowedOps", "ttlMs", "editorStateId"]);
    if (Object.keys(body).some((key) => !allowedKeys.has(key))) {
      throw httpError(400, "地图 AI 授权请求包含未知字段");
    }
    const threadId = normalizeMapAiThreadId(body.threadId);
    await assertMapAiThreadProject(runtime, threadId, context.projectPath);
    const editorStateId = normalizeMapAiEditorStateId(body.editorStateId);
    const lease = await mapAiAccess.grantLease({
      userId: identity.userId,
      browserSessionId: identity.browserSessionId,
      threadId,
      projectPath: context.projectPath,
      mapSessionId: request.params.sessionId,
      mapVersion: context.version,
      editorInstanceId,
      editorStateId,
      allowedOps: body.allowedOps,
      ...(body.ttlMs === undefined ? {} : { ttlMs: body.ttlMs }),
    });
    response.setHeader("Cache-Control", "no-store");
    response.status(201).json({ lease: publicMapAiLease(lease) });
  } catch (error) {
    next(error);
  }
});

