app.post("/api/maps/sessions/:sessionId/ai-proposals", async (request, response, next) => {
  try {
    assertOperationRequest(request, "map-ai-proposal-create");
    if (!mapAiProposals) throw httpError(404, "地图 AI 补丁收件箱在救援窗口中不可用");
    const runtime = await runtimeForRequest(request);
    const { proposalContext } = await mapAiLeaseRequestContext(request, {
      runtime,
      operation: "propose_tiled_patch",
      requireWritable: true,
    });
    const body = request.body && typeof request.body === "object" && !Array.isArray(request.body)
      ? request.body
      : {};
    const allowedKeys = new Set(["patch", "patchSource"]);
    if (Object.keys(body).some((key) => !allowedKeys.has(key))) {
      throw httpError(400, "地图 AI 补丁提案请求包含未知字段");
    }
    if (Object.hasOwn(body, "patch") === Object.hasOwn(body, "patchSource")) {
      throw httpError(400, "地图 AI 补丁提案必须且只能包含 patch 或 patchSource");
    }
    // Use one authoritative policy snapshot for both validation and proposal
    // binding.  Reading the store twice left a small race where a policy could
    // change between the protected-target check and persistence, causing a
    // proposal validated against revision N to be stored as revision N+1.
    // Such a proposal would eventually be hidden by context matching, but the
    // server must never report a mismatched validation receipt as current.
    const collaborationPolicy = mapCollaborationPolicies?.contract({
      userId: request.user.id,
      projectPath: proposalContext.projectPath,
      mapPath: proposalContext.mapPath,
    }) || null;
    const collaborationPolicyRevision = Number(collaborationPolicy?.revision || 0);
    if (collaborationPolicyRevision !== Number(proposalContext.collaborationPolicyRevision || 0)) {
      throw httpError(409, "协同策略已经变化，请重新读取后提交地图 AI 提案");
    }
    if (collaborationPolicy) {
      const policy = collaborationPolicy;
      if (policy.targets.length) {
        const parsed = await readManagedTiledDocument(
          path.join(proposalContext.projectPath, ...proposalContext.mapPath.split("/")),
          proposalContext.mapPath,
        );
        const patch = parseTiledAiPatch(
          Object.hasOwn(body, "patchSource") ? body.patchSource : JSON.stringify(body.patch),
          { mapPath: proposalContext.mapPath, mapVersion: proposalContext.mapVersion, editorStateId: proposalContext.editorStateId },
        );
        const violations = findCollaborationOperationViolations(parsed.document, patch, policy, proposalContext.mapPath);
        if (violations.length) {
          const error = httpError(403, violations[0].message);
          error.code = violations[0].code || "MAP_COLLABORATION_HUMAN_OWNED";
          throw error;
        }
      }
    }
    const proposal = await mapAiProposals.create({
      ...proposalContext,
      collaborationPolicyRevision,
      ...(Object.hasOwn(body, "patchSource") ? { patchSource: body.patchSource } : { patch: body.patch }),
    });
    response.setHeader("Cache-Control", "no-store");
    response.status(201).json({ proposal });
  } catch (error) {
    next(error);
  }
});

