// Generic chunked resource candidate bridge. The upload is bound to the
// current editor window/map version and is copied into the opaque candidate
// store only after the complete payload has been validated. No absolute path,
// bytes or file handle is returned to the browser or MCP layer.
app.post("/api/maps/sessions/:sessionId/managed-resource-uploads", async (request, response, next) => {
  try {
    assertOperationRequest(request, "map-ai-resource-upload-start");
    if (!mapAiResourceUploads) throw httpError(503, "地图资源候选上传服务当前不可用");
    const runtime = await runtimeForRequest(request);
    const { identity, context } = await mapImageRequestContext(request, runtime);
    await assertWritableMapContext(context, runtime);
    const body = request.body && typeof request.body === "object" && !Array.isArray(request.body) ? request.body : {};
    const allowed = new Set(["path", "baseVersion", "totalBytes", "totalHash", "editorStateId", "threadId"]);
    if (Object.keys(body).some((key) => !allowed.has(key))) throw httpError(400, "资源候选上传请求包含未知字段");
    const threadId = normalizeMapAiThreadId(body.threadId);
    await assertMapAiThreadProject(runtime, threadId, context.projectPath);
    const relativePath = normalizeMapProjectRelativePath(body.path, { label: "托管资源" });
    if (!/(?:\.(?:tmj|tsj|tx|world|png|jpe?g|webp)|\.character\.json)$/iu.test(relativePath)) throw httpError(415, "资源候选扩展名不受支持");
    const baseVersion = body.baseVersion === null ? null : String(body.baseVersion || "").toLowerCase();
    if (baseVersion !== null && !/^[a-f0-9]{64}$/u.test(baseVersion)) throw httpError(400, "资源基础版本无效");
    const upload = await mapAiResourceUploads.create({
      identity,
      mapContext: { ...context, mapSessionId: request.params.sessionId },
      editorStateId: normalizeMapAiEditorStateId(body.editorStateId),
      relativePath,
      baseVersion,
      totalBytes: body.totalBytes,
      totalHash: body.totalHash,
      threadId,
    });
    response.status(201).json({ upload });
  } catch (error) { next(error); }
});

