app.post("/api/maps/sessions/:sessionId/managed-resource-uploads/:uploadId/commit", async (request, response, next) => {
  let source = null;
  try {
    assertOperationRequest(request, "map-ai-resource-upload-commit");
    if (!mapAiResourceUploads || !mapAiResourceCandidates) throw httpError(503, "地图资源候选服务当前不可用");
    const runtime = await runtimeForRequest(request);
    const { identity, context } = await mapImageRequestContext(request, runtime);
    // A commit is still part of the write workflow. Re-check the current
    // project permission at the retry boundary so a candidate receipt cannot
    // be replayed after the editor becomes read-only or the project is locked.
    await assertWritableMapContext(context, runtime);
    const body = request.body && typeof request.body === "object" && !Array.isArray(request.body) ? request.body : {};
    const allowed = new Set(["editorStateId", "threadId"]);
    if (Object.keys(body).some((key) => !allowed.has(key))) throw httpError(400, "资源候选提交请求包含未知字段");
    const editorStateId = normalizeMapAiEditorStateId(body.editorStateId);
    const threadId = normalizeMapAiThreadId(body.threadId || request.get("x-wfl-map-ai-thread"));
    const uploadId = String(request.params.uploadId || "");
    await assertMapAiThreadProject(runtime, threadId, context.projectPath);
    const committed = mapAiResourceUploads.committedCandidate({
      uploadId,
      identity,
      threadId,
      mapSessionId: request.params.sessionId,
      mapVersion: context.version,
      editorStateId,
      projectPath: context.projectPath,
    });
    if (committed) {
      let storedLease = null;
      try {
        storedLease = await mapAiResourceCandidates.resolve({
          candidateId: committed.candidate.candidateId,
          userId: identity.userId,
          projectPath: context.projectPath,
          threadId,
          relativePath: committed.candidate.path,
          baseVersion: committed.candidate.baseVersion,
        });
        const stored = storedLease.metadata;
        if (stored.path !== committed.candidate.path
          || stored.baseVersion !== committed.candidate.baseVersion
          || stored.sha256 !== committed.candidate.sha256
          || stored.size !== committed.candidate.size) {
          throw new Error("candidate receipt does not match stored candidate");
        }
      } catch (error) {
        mapAiResourceUploads.forgetCommitReceipt({ uploadId, identity, threadId, mapSessionId: request.params.sessionId, mapVersion: context.version, editorStateId });
        throw httpError(409, "地图资源候选已丢失，请重新上传");
      } finally {
        await storedLease?.release?.().catch(() => {});
      }
      response.status(200).json({ candidate: committed.candidate, idempotent: true });
      return;
    }
    // If the process stopped after the candidate store durably registered the
    // payload but before the upload-store receipt was written, recover the
    // same opaque candidate by the upload-scoped idempotency key. This path
    // never recreates a candidate and does not expose its private source.
    const registrationKey = mapAiUploadCandidateRegistrationKey(uploadId);
    const recoveredCandidate = mapAiResourceCandidates.findRegistration({
      userId: identity.userId,
      projectPath: context.projectPath,
      threadId,
      idempotencyKey: registrationKey,
    }) || (() => {
      const legacyKey = legacyMapAiUploadCandidateRegistrationKey(uploadId);
      return legacyKey
        ? mapAiResourceCandidates.findRegistration({
          userId: identity.userId,
          projectPath: context.projectPath,
          threadId,
          idempotencyKey: legacyKey,
        })
        : null;
    })();
    if (recoveredCandidate) {
      let recoveredLease = null;
      try {
        recoveredLease = await mapAiResourceCandidates.resolve({
          candidateId: recoveredCandidate.candidateId,
          userId: identity.userId,
          projectPath: context.projectPath,
          threadId,
          relativePath: recoveredCandidate.path,
          baseVersion: recoveredCandidate.baseVersion,
        });
      } catch (error) {
        throw httpError(409, "地图资源候选已丢失或内容已变化，请重新上传");
      } finally {
        await recoveredLease?.release?.().catch(() => {});
      }
      response.status(200).json({ candidate: recoveredCandidate, idempotent: true, recovered: true });
      return;
    }
    const upload = await mapAiResourceUploads.finalize({
      uploadId,
      identity,
      mapSessionId: request.params.sessionId,
      mapVersion: context.version,
      editorStateId,
      threadId,
      validate: async ({ path: candidatePath, relativePath }) => {
        const extension = path.posix.extname(relativePath).toLowerCase();
        if (extension === ".png" || extension === ".jpg" || extension === ".jpeg" || extension === ".webp") {
          const inspected = await inspectDecodedImageFile(candidatePath, { maxBytes: MAP_AI_RESOURCE_UPLOAD_MAX_BYTES });
          if (!inspected) throw httpError(422, "图片候选校验失败");
          return;
        }
        const validator = extension === ".tmj"
          ? inspectTiledMapInChild
          : extension === ".tsj"
            ? inspectTiledTilesetInChild
            : extension === ".tx"
              ? inspectTiledTemplateInChild
              : extension === ".world"
                ? inspectTiledWorldInChild
                : null;
        if (validator) {
          const result = await validator({ candidatePath, sourcePath: relativePath, projectPath: context.projectPath, memoryMb: MAP_SAVE_VALIDATION_MEMORY_MB, timeoutMs: MAP_SAVE_VALIDATION_TIMEOUT_MS });
          if (result.diagnostics?.some((entry) => entry.severity === "error") || result.errors?.length) throw httpError(422, "Tiled 资源候选校验失败");
        }
      },
    });
    source = await mapAiResourceUploads.openSource({ uploadId: upload.uploadId, identity, mapSessionId: request.params.sessionId, mapVersion: context.version, editorStateId, threadId });
    const candidate = await mapAiResourceCandidates.register({ userId: identity.userId, projectPath: context.projectPath, threadId, relativePath: upload.path, baseVersion: upload.baseVersion, sourcePath: source.sourcePath, size: upload.metadata?.size || upload.totalBytes, sha256: upload.metadata?.sha256 || upload.totalHash, idempotencyKey: registrationKey });
    // Candidate registration is the durable success boundary.  If removing
    // the browser upload staging directory has a transient filesystem error,
    // still return the opaque candidate and leave the upload for TTL/admin
    // cleanup; reporting a failure here would make a retry register a second
    // candidate for the same bytes.
    const committedResult = await mapAiResourceUploads.commitCandidate({
      uploadId: upload.uploadId,
      identity,
      threadId,
      mapSessionId: request.params.sessionId,
      mapVersion: context.version,
      editorStateId,
      candidate,
    });
    response.status(committedResult.idempotent ? 200 : 201).json({ candidate: committedResult.candidate || candidate, ...(committedResult.idempotent ? { idempotent: true } : {}) });
  } catch (error) { next(error); }
  finally { source?.release?.(); }
});

