app.post("/api/maps/sessions/:sessionId/image-jobs", async (request, response, next) => {
  let retainedInputs = [];
  let retainedReleased = false;
  try {
    assertOperationRequest(request, "map-image-start");
    const runtime = await runtimeForRequest(request);
    const { identity, context } = await mapImageRequestContext(request, runtime);
    await assertWritableMapContext(context, runtime);
    if (!mapImageJobs) throw httpError(503, "地图专用生图 Worker 尚未接入");
    const rawRequest = request.body?.request;
    const operation = String(rawRequest?.operation || "generate").trim();
    const localCrop = operation === "crop";
    const localCropRequest = localCrop ? normalizeMapImageCropRequest(rawRequest) : null;
    let imageApi = null;
    if (!localCrop) {
      const imageSettings = imageExecutionSettings?.snapshot();
      if (!imageSettings?.acceptNewTasks) {
        throw imageExecutionError(503, "IMAGE_QUEUE_PAUSED", "管理员已暂停接收新的图片任务");
      }
      if (imageSettings.config?.worker?.enabled !== true) {
        throw imageExecutionError(503, "IMAGE_WORKER_DISABLED", "图片 Worker 当前已由管理员关闭");
      }
      imageApi = privateImageApiSnapshot(runtime.providerStore.getImageApi());
      if (!imageApi) {
        throw imageExecutionError(409, "IMAGE_PROVIDER_NOT_CONFIGURED", "当前账号尚未配置图片供应商");
      }
    }
    const expectedVersion = String(request.body?.expectedVersion || context.version);
    if (expectedVersion !== context.version) {
      throw Object.assign(httpError(409, "地图生图版本与当前编辑会话不匹配"), { code: "map-version-conflict" });
    }
    const mapContext = {
      ...context,
      mapSessionId: request.params.sessionId,
      version: expectedVersion,
      writable: true,
    };
    const sourceCrop = localCrop ? localCropRequest.sourceCrop : rawRequest && Object.hasOwn(rawRequest, "sourceCrop")
      ? normalizeMapImageSourceCrop(rawRequest.sourceCrop)
      : null;
    const admittedRequest = localCropRequest || (sourceCrop ? { ...rawRequest, sourceCrop } : rawRequest);
    const inputSelection = normalizeMapImageInputSelection(request.body?.inputs);
    const hasSelectionTarget = request.body?.selectionTarget != null;
    const editorStateId = (inputSelection || hasSelectionTarget)
      ? normalizeMapImageEditorStateId(request.body?.editorStateId)
      : (request.body?.editorStateId == null ? null : normalizeMapImageEditorStateId(request.body.editorStateId));
    let inputRefs = null;
    let selectionContract = null;
    if (inputSelection) {
      if (operation === "generate") {
        throw imageExecutionError(400, "INVALID_MAP_IMAGE_INPUTS", "生成操作不能附带临时源图片");
      }
      if (localCrop && (inputSelection.sourceInputIds.length !== 1 || inputSelection.maskInputId)) {
        throw imageExecutionError(400, "INVALID_MAP_IMAGE_CROP", "纯裁剪必须使用一张当前窗口 PNG，不能附带蒙版");
      }
      const retained = await retainMapImageInputs({
        identity,
        mapContext,
        editorStateId,
        selection: inputSelection,
        imageApi,
        localOnly: localCrop,
      });
      retainedInputs = retained.leases;
      inputRefs = retained.refs;
    }
    if (localCrop && !inputRefs) {
      throw imageExecutionError(400, "INVALID_MAP_IMAGE_CROP", "纯裁剪必须上传当前窗口临时 PNG");
    }
    if (hasSelectionTarget) {
      if (localCrop) {
        throw imageExecutionError(400, "INVALID_MAP_IMAGE_CROP", "纯裁剪不接受地图瓦片选区目标");
      }
      selectionContract = await validateMapImageSelectionContract({
        target: request.body.selectionTarget,
        request: rawRequest,
        operation,
        expectedVersion,
        editorStateId,
        imageApi,
        mapContext,
      });
      if (inputRefs) assertMapImageSelectionInputDimensions(inputRefs, selectionContract, operation);
      if (!inputRefs && ["edit", "outpaint"].includes(operation)) {
        throw imageExecutionError(400, "MAP_IMAGE_SELECTION_INPUT_REQUIRED", "选区编辑或扩图必须使用当前窗口截取的临时源图片");
      }
    }
    if (sourceCrop && !localCrop && (operation !== "outpaint" || !inputRefs || hasSelectionTarget)) {
      throw imageExecutionError(
        400,
        "INVALID_MAP_IMAGE_SOURCE_CROP",
        "裁剪预处理只允许用于当前窗口上传的非地图选区扩图源图",
      );
    }
    if (inputRefs && (Object.hasOwn(rawRequest || {}, "sourcePath")
      || Object.hasOwn(rawRequest || {}, "sourcePaths")
      || Object.hasOwn(rawRequest || {}, "maskPath"))) {
      throw imageExecutionError(400, "INVALID_MAP_IMAGE_INPUTS", "临时输入任务不能同时指定工程图片路径");
    }
    const normalizedRequest = localCrop
      ? admittedRequest
      : normalizeMapImageExecutionRequest(
          admittedRequest,
          mapContext,
          imageApi,
          { inputRefs },
        );
    if (localCrop) {
      const source = inputRefs.source[0];
      const targetWidth = admittedRequest.sourceSize.width
        - admittedRequest.sourceCrop.left - admittedRequest.sourceCrop.right;
      const targetHeight = admittedRequest.sourceSize.height
        - admittedRequest.sourceCrop.top - admittedRequest.sourceCrop.bottom;
      if (source.format !== "png" || source.width !== targetWidth || source.height !== targetHeight) {
        throw imageExecutionError(
          409,
          "MAP_IMAGE_CROP_DIMENSIONS_MISMATCH",
          "上传的裁剪 PNG 尺寸与声明的非破坏裁剪结果不一致",
        );
      }
    }
    if (!inputRefs) {
      authorizeMapImageSources({
        identity,
        mapContext,
        sourcePaths: normalizedRequest.sourcePaths,
        maskPath: normalizedRequest.maskPath,
      });
    }
    const releaseRetainedInputs = async () => {
      if (retainedReleased) return;
      retainedReleased = true;
      await Promise.allSettled(retainedInputs.map((lease) => lease.release()));
    };
    const admitted = mapImageJobs.enqueue({
      identity,
      mapContext,
      request: admittedRequest,
      executionContext: {
        authSession: normalizeImageTaskAuthSession(request.authSession, runtime.user.id),
        // Freeze the provider contract at admission.  Administrator changes
        // affect only later jobs; this private snapshot never enters the
        // public candidate or conversation response.
        imageApiSnapshot: imageApi,
        editorStateId,
        inputRefs,
        // Persist only the authoritative target rebuilt from the current map;
        // the public job can later return this bounded coordinate contract so
        // a refreshed editor window can still apply the candidate correctly.
        selectionTarget: authoritativeMapImageSelectionTarget(selectionContract),
        selectionRequest: selectionContract ? structuredClone(admittedRequest) : null,
      },
      onFinalized: releaseRetainedInputs,
    });
    response.status(202).json({ job: admitted.job });
  } catch (error) {
    if (retainedInputs.length && !retainedReleased) {
      retainedReleased = true;
      await Promise.allSettled(retainedInputs.map((lease) => lease.release()));
    }
    next(error);
  }
});

