app.get("/api/maps/sessions/:sessionId/image-jobs/:jobId/files/:index", async (request, response, next) => {
  let opened = null;
  try {
    const runtime = await runtimeForRequest(request);
    const { identity, context } = await mapImageRequestContext(request, runtime);
    if (!mapImageJobs) throw httpError(503, "地图专用生图 Worker 尚未接入");
    const job = mapImageJobs.snapshot({ jobId: request.params.jobId, identity });
    if (job.mapSessionId !== request.params.sessionId) throw httpError(404, "地图生图任务不存在");
    opened = await mapImageJobs.openCandidateFile({
      jobId: request.params.jobId,
      identity,
      mapVersion: context.version,
      index: Number(request.params.index),
    });
    response.status(200);
    response.setHeader("Content-Type", opened.metadata.mediaType);
    response.setHeader("Content-Length", String(opened.metadata.size));
    response.setHeader("Cache-Control", "private, no-store, max-age=0");
    response.setHeader("X-Content-Type-Options", "nosniff");
    const handle = opened.handle;
    const stream = handle.createReadStream({ autoClose: false });
    const close = () => { void handle.close().catch(() => {}); };
    response.once("finish", close);
    response.once("close", close);
    stream.once("error", (error) => response.destroy(error));
    stream.pipe(response);
    opened = null;
  } catch (error) {
    if (opened?.handle) await opened.handle.close().catch(() => {});
    if (!response.headersSent) next(error);
    else response.destroy(error);
  }
});

