// Bridge a finished map-image candidate into the headless managed resource
// store. The client receives only an opaque candidateId; the staged path is
// copied server-side and never enters the task/MCP contract.
app.post("/api/maps/sessions/:sessionId/image-jobs/:jobId/managed-resource-candidate", async (request, response, next) => {
  try {
    assertOperationRequest(request, "map-ai-resource-candidate-register");
    const runtime = await runtimeForRequest(request);
    const { identity, context } = await mapImageRequestContext(request, runtime);
    if (!mapImageJobs || !mapAiResourceCandidates) throw httpError(503, "地图资源候选服务当前不可用");
    await assertWritableMapContext(context, runtime);
    const body = request.body && typeof request.body === "object" && !Array.isArray(request.body) ? request.body : {};
    const allowedKeys = new Set(["index", "path", "baseVersion", "threadId", "clientOperationId"]);
    if (Object.keys(body).some((key) => !allowedKeys.has(key))) throw httpError(400, "资源候选注册请求包含未知字段");
    const existing = mapImageJobs.snapshot({ jobId: request.params.jobId, identity });
    if (existing.mapSessionId !== request.params.sessionId) throw httpError(404, "地图生图任务不存在");
    const threadId = normalizeMapAiThreadId(body.threadId);
    await assertMapAiThreadProject(runtime, threadId, context.projectPath);
    const clientOperationId = normalizeDurableOperationRequestId(
      body.clientOperationId,
      "资源候选幂等操作 ID",
    );
    if (!clientOperationId) throw httpError(400, "资源候选注册必须提供幂等操作 ID");
    const imageIndex = Number(body.index);
    if (!Number.isSafeInteger(imageIndex) || imageIndex < 0) throw httpError(400, "图片候选索引无效");
    // The candidate store already provides durable, scoped idempotency.  Hash
    // the image-job/index/client tuple into its bounded key so a retry is
    // bound to this exact image task and output, while the store additionally
    // binds it to the user, project, Thread, destination path and base
    // version.  No raw job id or client token is persisted in a public value.
    const registrationKey = crypto.createHash("sha256")
      .update(`wfl-map-image-candidate-v1\0${request.params.jobId}\0${imageIndex}\0${clientOperationId}`)
      .digest("hex");
    const relativePath = normalizeMapProjectRelativePath(body.path, { label: "托管资源" });
    if (!/\.(?:png|jpe?g|webp)$/iu.test(relativePath)) throw httpError(415, "图片候选只能注册为 PNG、JPEG 或 WebP 资源");
    const baseVersion = body.baseVersion === null ? null : String(body.baseVersion || "").toLowerCase();
    if (baseVersion !== null && !/^[a-f0-9]{64}$/u.test(baseVersion)) throw httpError(400, "资源基础版本无效");
    const existingRegistration = mapAiResourceCandidates.findRegistration({
      userId: identity.userId,
      projectPath: context.projectPath,
      threadId,
      idempotencyKey: registrationKey,
    });
    if (existingRegistration) {
      if (existingRegistration.path !== relativePath || existingRegistration.baseVersion !== baseVersion) {
        throw httpError(409, "资源候选幂等操作 ID 已用于不同目标");
      }
      // A durable idempotency receipt is not itself proof that the staged
      // payload is still present and unchanged.  The candidate directory can
      // be tampered with, cleaned up by TTL, or partially removed while a
      // browser is retrying a lost response.  Re-resolve the exact scope so
      // the store re-checks expiry, ownership, target binding, size, and
      // SHA-256 before returning the receipt.  Never hand the caller stale
      // public metadata merely because the operation key was found.
      const resolved = await mapAiResourceCandidates.resolve({
        candidateId: existingRegistration.candidateId,
        userId: identity.userId,
        projectPath: context.projectPath,
        threadId,
        relativePath,
        baseVersion,
      });
      try {
        response.status(200).json({ candidate: resolved.metadata, idempotent: true });
      } finally {
        await resolved.release();
      }
      return;
    }
    const source = await mapImageJobs.openCandidateSource({
      jobId: request.params.jobId,
      identity,
      mapVersion: context.version,
      index: imageIndex,
    });
    const sourceExtension = source.metadata.format === "jpeg" ? ".jpg" : `.${String(source.metadata.format || "").toLowerCase()}`;
    if (path.posix.extname(relativePath).toLowerCase() !== sourceExtension && !(sourceExtension === ".jpg" && path.posix.extname(relativePath).toLowerCase() === ".jpeg")) {
      throw httpError(400, "候选图片格式与目标扩展名不一致");
    }
    const candidate = await mapAiResourceCandidates.register({
      userId: identity.userId,
      projectPath: context.projectPath,
      threadId,
      relativePath,
      baseVersion,
      sourcePath: source.sourcePath,
      size: source.metadata.size,
      sha256: source.metadata.sha256,
      idempotencyKey: registrationKey,
    });
    response.status(201).json({ candidate });
  } catch (error) {
    next(error);
  }
});

app.post("/api/maps/render-jobs", async (request, response, next) => {
  try {
    assertOperationRequest(request, "map-render-start");
    if (!mapFileSessions || !mapRenderJobs) throw httpError(404, "地图 Render Worker 在救援窗口中不可用");
    const runtime = await runtimeForRequest(request);
    const editorInstanceId = normalizeMapEditorInstanceId(
      request.get("x-codex-desktop-editor-instance"),
    );
    const identity = mapSessionIdentity(request, editorInstanceId);
    const mapSessionId = String(request.body?.mapSessionId || "");
    const context = mapFileSessions.context({ sessionId: mapSessionId, identity });
    await assertWritableMapContext(context, runtime);
    const expectedVersion = String(request.body?.expectedVersion || "");
    if (expectedVersion !== context.version) {
      throw Object.assign(httpError(409, "地图渲染版本与当前编辑会话不匹配"), {
        code: "map-version-conflict",
      });
    }
    const inspected = await inspectMapFile(context.targetPath);
    if (inspected.version !== context.version) {
      throw Object.assign(httpError(409, "地图已被其他窗口或任务修改，请重新打开后再导出"), {
        code: "map-version-conflict",
      });
    }
    await assertQuotaAvailable(runtime);
    const result = await mapRenderJobs.begin({
      identity,
      mapContext: { ...context, mapSessionId, writable: true },
      request: {
        kind: request.body?.kind,
        clientOperationId: request.body?.clientOperationId,
        outputRoot: request.body?.outputRoot,
        spec: request.body?.spec,
      },
    });
    response.status(result.created ? 201 : 200).json({ job: result.job, created: result.created });
  } catch (error) {
    next(error);
  }
});

