app.get("/api/maps/render-jobs/:jobId/file", async (request, response, next) => {
  try {
    if (!mapRenderJobs) throw httpError(404, "地图 Render Worker 在救援窗口中不可用");
    const runtime = await runtimeForRequest(request);
    const editorInstanceId = normalizeMapEditorInstanceId(
      request.get("x-codex-desktop-editor-instance") || request.query.editor,
    );
    const output = mapRenderJobs.outputFile({
      jobId: request.params.jobId,
      identity: mapSessionIdentity(request, editorInstanceId),
      filePath: request.query.path,
    });
    const candidate = path.resolve(
      output.projectPath,
      ...output.outputDirectory.split("/"),
      ...output.file.path.split("/"),
    );
    const { targetPath } = await resolveResourceTarget(output.projectPath, candidate, runtime);
    const stat = await fs.stat(targetPath);
    if (!stat.isFile()) throw httpError(404, "地图渲染输出文件不存在");
    response.setHeader("Content-Type", output.file.mediaType);
    response.setHeader("Content-Disposition", `attachment; filename="${sanitizeDownloadName(path.basename(targetPath))}"`);
    response.setHeader("ETag", `"${output.file.sha256}"`);
    response.setHeader("Cache-Control", "no-store");
    response.sendFile(targetPath, { dotfiles: "deny" }, (error) => {
      if (error && !response.headersSent) next(error);
    });
  } catch (error) {
    next(error);
  }
});

