async function commitMapDocumentThroughProjectTransaction({ request, saveId, identity, documentKind, fileSessions }) {
  if (!mapSaveSessions || !mapProjectResourceWriter || !fileSessions) {
    throw httpError(404, "地图项目事务保存功能在救援窗口中不可用");
  }
  const saveSnapshot = mapSaveSessions.snapshot({ saveId, identity, documentKind });
  const context = fileSessions.context({ sessionId: saveSnapshot.mapSessionId, identity });
  const saveInput = {
    saveId,
    identity,
    documentKind,
    authorize: async (mapContext) => {
      const runtime = await runtimeForRequest(request);
      await assertWritableMapContext(mapContext, runtime);
      if (mapCollaborationPolicies) {
        const live = mapCollaborationPolicies.contract({ userId: identity.userId, projectPath: mapContext.projectPath, mapPath: mapContext.relativePath });
        if (Number(live.revision || 0) !== Number(saveSnapshot.collaborationPolicyRevision || 0)) {
          throw Object.assign(httpError(409, "协同策略在保存期间发生变化，当前地图未提交"), { code: "MAP_COLLABORATION_POLICY_CONFLICT" });
        }
      }
    },
  };
  const candidate = await mapSaveSessions.prepareCandidate(saveInput);
  let revisionStage = null;
  let revisionError = null;
  try {
    try {
      revisionStage = await mapRevisions?.stageCurrent({
        projectPath: context.projectPath,
        relativePath: context.relativePath,
        targetPath: context.targetPath,
        expectedVersion: candidate.expectedVersion,
        reason: "manual-save",
        actor: { userId: identity.userId, browserSessionId: identity.browserSessionId },
      });
    } catch (error) {
      revisionError = { code: String(error?.code || "MAP_REVISION_STAGE_FAILED"), message: "修订快照未创建，地图保存仍继续" };
    }
    const transaction = await mapProjectResourceWriter.saveTransaction({
      projectPath: context.projectPath,
      resourceRoots: [""],
      validateReferences: true,
      validate: async () => {
        // The writer invokes validation after staging and immediately before
        // its final version re-check/publish sequence.  Revalidate the live
        // authority at this point so revocation or takeover cannot be bypassed
        // by a candidate prepared earlier.
        await saveInput.authorize(context);
      },
      files: [{
        relativePath: context.relativePath,
        candidatePath: candidate.candidatePath,
        candidateSize: candidate.size,
        candidateSha256: candidate.sha256,
        expectedVersion: candidate.expectedVersion,
      }],
    });
    const result = await mapSaveSessions.finalizeCandidate({
      ...saveInput,
      candidate,
      published: transaction.files?.[0],
    });
    let revision = null;
    if (revisionStage) {
      try {
        revision = await mapRevisions.commitStaged(revisionStage);
      } catch (error) {
        revisionError = { code: String(error?.code || "MAP_REVISION_COMMIT_FAILED"), message: "地图已保存，但修订快照未持久化" };
        await mapRevisions.disposeStaged(revisionStage).catch(() => {});
      }
      revisionStage = null;
    }
    return { context, result, transaction, revision, revisionError };
  } finally {
    if (revisionStage) await mapRevisions?.disposeStaged(revisionStage).catch(() => {});
  }
}

app.post("/api/maps/save-sessions", async (request, response, next) => {
  try {
    assertOperationRequest(request, "map-save-start");
    if (!mapFileSessions || !mapSaveSessions) throw httpError(404, "地图编辑器在救援窗口中不可用");
    const runtime = await runtimeForRequest(request);
    const editorInstanceId = normalizeMapEditorInstanceId(
      request.get("x-codex-desktop-editor-instance"),
    );
    const identity = mapSessionIdentity(request, editorInstanceId);
    const mapSessionId = String(request.body?.mapSessionId || "");
    const context = mapFileSessions.context({ sessionId: mapSessionId, identity });
    await assertWritableMapContext(context, runtime);
    const currentPolicy = mapCollaborationPolicies?.contract({ userId: request.user.id, projectPath: context.projectPath, mapPath: context.relativePath });
    const requestedPolicyRevision = request.body?.collaborationPolicyRevision == null
      ? Number(currentPolicy?.revision || 0)
      : Number(request.body.collaborationPolicyRevision);
    if (!Number.isSafeInteger(requestedPolicyRevision) || requestedPolicyRevision !== Number(currentPolicy?.revision || 0)) {
      throw httpError(409, "协同策略已经变化，请重新读取策略后保存地图");
    }
    const save = await mapSaveSessions.begin({
      identity,
      mapContext: { ...context, mapSessionId, writable: true, collaborationPolicyRevision: requestedPolicyRevision },
      expectedVersion: request.body?.expectedVersion,
      totalBytes: request.body?.totalBytes,
      totalHash: request.body?.totalHash,
      clientOperationId: request.body?.clientOperationId,
      config: mapSaveSessionConfig(),
    });
    response.status(201).json({ save });
  } catch (error) {
    next(error);
  }
});

