app.post("/api/maps/sessions/:sessionId/revisions/:revisionId/restore", async (request, response, next) => {
  try {
    assertOperationRequest(request, "map-revision-restore");
    if (request.body?.confirmation !== true) throw httpError(400, "恢复修订必须明确确认");
    if (!mapFileSessions || !mapSaveSessions || !mapRevisions || !mapProjectResourceWriter) {
      throw httpError(404, "地图修订恢复在救援窗口中不可用");
    }
    const runtime = await runtimeForRequest(request);
    const editorInstanceId = normalizeMapEditorInstanceId(request.get("x-codex-desktop-editor-instance"));
    const identity = mapSessionIdentity(request, editorInstanceId);
    const context = mapFileSessions.context({ sessionId: request.params.sessionId, identity });
    await assertWritableMapContext(context, runtime);
    const inspected = await inspectMapFile(context.targetPath, { maxBytes: MAP_SAVE_MAX_BYTES });
    const expectedCurrentVersion = String(request.body?.expectedCurrentVersion || "").toLowerCase();
    if (!/^[a-f0-9]{64}$/u.test(expectedCurrentVersion) || inspected.version !== expectedCurrentVersion || context.version !== expectedCurrentVersion) {
      throw httpError(409, "地图当前版本已变化，请刷新后再恢复修订");
    }
    const revision = mapRevisions.get({ revisionId: request.params.revisionId, projectPath: context.projectPath, relativePath: context.relativePath });
    if (revision.version === expectedCurrentVersion) {
      throw httpError(409, "目标修订已经是当前地图版本");
    }
    const materialized = await mapRevisions.materialize({ revisionId: revision.id, projectPath: context.projectPath, relativePath: context.relativePath });
    let save = null;
    try {
      save = await mapSaveSessions.begin({
        identity,
        mapContext: { ...context, mapSessionId: request.params.sessionId, writable: true },
        expectedVersion: expectedCurrentVersion,
        totalBytes: revision.size,
        totalHash: revision.version,
        clientOperationId: request.body?.clientOperationId || `restore-${revision.id}-${expectedCurrentVersion}`,
        config: mapSaveSessionConfig(),
      });
      const handle = await fs.open(materialized.candidatePath, "r");
      try {
        for (let index = 0; index < save.chunkCount; index += 1) {
          const size = Math.min(save.config.chunkBytes, save.totalBytes - index * save.config.chunkBytes);
          const buffer = Buffer.allocUnsafe(size);
          let offset = 0;
          while (offset < size) {
            const read = await handle.read(buffer, offset, size - offset, index * save.config.chunkBytes + offset);
            if (!read.bytesRead) throw httpError(409, "地图修订候选已损坏，请重试");
            offset += read.bytesRead;
          }
          await mapSaveSessions.uploadChunk({ saveId: save.id, identity, documentKind: "map", index, source: buffer, contentLength: size, chunkHash: crypto.createHash("sha256").update(buffer).digest("hex") });
        }
      } finally {
        await handle.close();
      }
      const committed = await commitMapDocumentThroughProjectTransaction({ request, saveId: save.id, identity, documentKind: "map", fileSessions: mapFileSessions });
      const session = await mapFileSessions.refresh({ sessionId: committed.result.mapSessionId, identity });
      response.setHeader("Cache-Control", "no-store");
      response.status(201).json({ revision, result: committed.result, transaction: committed.transaction, createdRevision: committed.revision, session });
    } finally {
      await mapRevisions.disposeStaged(materialized).catch(() => {});
      if (save?.id) await mapSaveSessions.abort({ saveId: save.id, identity, documentKind: "map" }).catch(() => {});
    }
  } catch (error) {
    next(error);
  }
});

