app.get("/api/files/archive", async (request, response, next) => {
  try {
    const runtime = await runtimeForRequest(request);
    const { projectPath, targetPath } = await resolveResourceTarget(
      request.query.project,
      request.query.path,
      runtime,
    );
    const stat = await fs.stat(targetPath);
    if (!stat.isDirectory()) throw httpError(400, "Resource path is not a directory");
    const isRoot = targetPath === projectPath;
    const archiveBase = sanitizeDownloadName(path.basename(targetPath));
    response.setHeader("Content-Type", "application/gzip");
    response.setHeader("Content-Disposition", `attachment; filename="${archiveBase}.tar.gz"`);
    response.setHeader("Cache-Control", "no-store");
    const spawnOptions = {
      cwd: isRoot ? targetPath : path.dirname(targetPath),
      stdio: ["ignore", "pipe", "pipe"],
    };
    if (!runtime.legacy && Number.isInteger(runtime.user.uid) && Number.isInteger(runtime.user.gid)) {
      spawnOptions.uid = runtime.user.uid;
      spawnOptions.gid = runtime.user.gid;
    }
    const archive = spawn("tar", [
      "--create",
      "--gzip",
      "--file=-",
      "--exclude=.git",
      "--exclude=.codex-desktop",
      "--exclude=.codex-runtime",
      "--exclude=.codex-uploads",
      "--exclude=.codex-trash",
      "--",
      isRoot ? "." : path.basename(targetPath),
    ], spawnOptions);
    let archiveError = "";
    archive.stderr.on("data", (chunk) => (archiveError = `${archiveError}${chunk}`.slice(-2_000)));
    request.on("aborted", () => archive.kill("SIGTERM"));
    response.on("close", () => {
      if (!response.writableEnded) archive.kill("SIGTERM");
    });
    archive.stdout.pipe(response);
    archive.on("error", next);
    archive.on("exit", (code) => {
      if (code && !response.writableEnded) {
        response.destroy(new Error(archiveError.trim() || "文件夹打包失败"));
      }
    });
  } catch (error) {
    next(error);
  }
});

app.post("/api/files/archive", async (request, response, next) => {
  try {
    const runtime = await runtimeForRequest(request);
    const projectPath = path.resolve(String(request.body?.project || ""));
    const values = Array.isArray(request.body?.paths) ? request.body.paths : [];
    if (!values.length || values.length > RESOURCE_ARCHIVE_SELECTION_LIMIT) {
      throw httpError(400, `请选择 1–${RESOURCE_ARCHIVE_SELECTION_LIMIT} 个文件或文件夹`);
    }
    const selected = [];
    for (const value of values) {
      const resolved = await resolveResourceTarget(projectPath, value, runtime);
      if (resolved.targetPath === resolved.projectPath) throw httpError(400, "多选下载不能包含工程根目录");
      const relative = path.relative(resolved.projectPath, resolved.targetPath);
      if (!selected.includes(relative)) selected.push(relative);
    }
    response.setHeader("Content-Type", "application/gzip");
    response.setHeader("Content-Disposition", `attachment; filename="WFL-Codex-selection-${Date.now()}.tar.gz"`);
    response.setHeader("Cache-Control", "no-store");
    streamResourceArchive(response, request, runtime, projectPath, selected);
  } catch (error) {
    next(error);
  }
});

app.put(
  "/api/files/write",
  express.text({ type: "text/plain", limit: FILE_EDIT_LIMIT_BYTES }),
  async (request, response, next) => {
    try {
      assertOperationRequest(request, "resource-file-save");
      const runtime = await runtimeForRequest(request);
      const { projectPath, targetPath } = await resolveResourceTarget(
        request.query.project,
        request.query.path,
        runtime,
      );
      const { share } = await assertWritableProjectDirectory(projectPath, runtime);
      const expectedVersion = String(request.headers["x-codex-desktop-file-version"] || "").trim();
      if (!/^[a-f0-9]{64}$/.test(expectedVersion)) throw httpError(400, "File version is required");
      if (typeof request.body !== "string") throw httpError(400, "File content must be UTF-8 text");

      const stat = await fs.stat(targetPath);
      if (!stat.isFile()) throw httpError(400, "Resource path is not a file");
      if (stat.size > FILE_EDIT_LIMIT_BYTES) throw httpError(413, "File is too large to edit");
      const current = await fs.readFile(targetPath);
      decodeResourceText(current);
      if (resourceFileVersion(current) !== expectedVersion) {
        throw httpError(409, "文件已被其他任务修改，请重新加载后再保存");
      }

      const updated = Buffer.from(request.body, "utf8");
      if (updated.includes(0)) throw httpError(415, "Binary files cannot be edited as text");
      if (updated.length > FILE_EDIT_LIMIT_BYTES) throw httpError(413, "File is too large to edit");
      const sourceUser = share ? multiUserStore.getUser(share.sourceUserId) : null;
      const quotaRuntime = sourceUser ? {
        legacy: Boolean(sourceUser.legacy),
        user: sourceUser,
        projectRoot: sourceUser.projectRoot,
      } : runtime;
      await assertQuotaAvailable(quotaRuntime, Math.max(0, updated.length - current.length));
      await writeResourceFileAtomic(targetPath, updated, stat);
      const updatedStat = await fs.stat(targetPath);
      response.json({
        name: path.basename(targetPath),
        path: targetPath,
        relativePath: path.relative(projectPath, targetPath),
        size: updated.length,
        modifiedAt: updatedStat.mtimeMs,
        version: resourceFileVersion(updated),
        editable: true,
        content: request.body,
      });
    } catch (error) {
      next(error);
    }
  },
);

app.post("/api/files/action", async (request, response, next) => {
  try {
    assertOperationRequest(request, "resource-file-action");
    const runtime = await runtimeForRequest(request);
    const action = String(request.body?.action || "");
    if (!["createDirectory", "createFile", "rename", "copy", "move", "delete"].includes(action)) {
      throw httpError(400, "文件操作无效");
    }
    const projectPath = path.resolve(String(request.body?.project || ""));
    const { share } = await assertWritableProjectDirectory(projectPath, runtime);
    const quotaRuntime = share ? await runtimeForUser(share.sourceUserId) : runtime;
    let result;

    if (action === "createDirectory" || action === "createFile") {
      const destination = await resolveResourceDestination(
        projectPath,
        request.body?.parentPath || projectPath,
        request.body?.name,
        runtime,
      );
      if (destination.exists) throw httpError(409, "同名文件或文件夹已存在");
      if (action === "createDirectory") {
        await fs.mkdir(destination.targetPath, { recursive: false, mode: 0o700 });
      } else {
        await assertQuotaAvailable(quotaRuntime);
        await fs.writeFile(destination.targetPath, Buffer.alloc(0), { flag: "wx", mode: 0o600 });
      }
      await inheritResourceOwnership(destination.targetPath, destination.parentPath);
      result = {
        action,
        entry: await resourceEntrySnapshot(projectPath, destination.targetPath),
      };
    } else {
      const source = await resolveResourceTarget(projectPath, request.body?.path, runtime);
      if (source.targetPath === projectPath) throw httpError(400, "不能对工程根目录执行此操作");
      const sourceStat = await fs.stat(source.targetPath);
      assertResourceExpectedVersion(sourceStat, request.body?.expectedVersion);

      if (action === "delete") {
        const trashDirectory = path.join(projectPath, ".codex-trash");
        await fs.mkdir(trashDirectory, { recursive: true, mode: 0o700 });
        await inheritResourceOwnership(trashDirectory, projectPath);
        const trashTarget = path.join(
          trashDirectory,
          `${Date.now()}-${crypto.randomBytes(4).toString("hex")}-${path.basename(source.targetPath)}`,
        );
        await fs.rename(source.targetPath, trashTarget);
        result = { action, recoverable: true };
      } else {
        const defaultName = action === "rename" ? request.body?.name : request.body?.name || path.basename(source.targetPath);
        const destination = await resolveResourceDestination(
          projectPath,
          action === "rename" ? path.dirname(source.targetPath) : request.body?.destinationPath,
          defaultName,
          runtime,
        );
        if (destination.exists) throw httpError(409, "目标位置已有同名文件或文件夹");
        if (destination.targetPath === source.targetPath) throw httpError(409, "源位置和目标位置相同");
        if (
          sourceStat.isDirectory()
          && isPathWithin(source.targetPath, destination.targetPath)
        ) {
          throw httpError(400, "不能把文件夹复制或移动到自身内部");
        }

        if (action === "copy") {
          const copiedBytes = sourceStat.isFile()
            ? sourceStat.size
            : (await inspectResourceTree(source.targetPath)).bytes;
          await assertQuotaAvailable(quotaRuntime, copiedBytes);
          try {
            await fs.cp(source.targetPath, destination.targetPath, {
              recursive: sourceStat.isDirectory(),
              force: false,
              errorOnExist: true,
              preserveTimestamps: true,
            });
            await inheritResourceOwnership(destination.targetPath, destination.parentPath, { recursive: true });
          } catch (error) {
            await fs.rm(destination.targetPath, { recursive: true, force: true }).catch(() => {});
            if (error?.code === "EEXIST") throw httpError(409, "目标位置已有同名文件或文件夹");
            throw error;
          }
        } else {
          await fs.rename(source.targetPath, destination.targetPath);
        }
        result = {
          action,
          entry: await resourceEntrySnapshot(projectPath, destination.targetPath),
        };
      }
    }

    directorySizeCache.clear();
    void recordOpsEvent({
      type: `resource.${action}`,
      severity: "info",
      source: "resource",
      title: "工程文件操作",
      detail: `用户：${runtime.user.username} · 操作：${action}`,
    }).catch(() => {});
    response.status(action.startsWith("create") ? 201 : 200).json(result);
  } catch (error) {
    if (["EEXIST", "ENOTEMPTY"].includes(error?.code)) next(httpError(409, "文件操作与外部修改发生冲突"));
    else if (error?.code === "ENOENT") next(httpError(409, "文件已被其他任务移动或删除"));
    else next(error);
  }
});

app.post(
  "/api/files/upload",
  express.raw({ type: "application/octet-stream", limit: UPLOAD_LIMIT_BYTES }),
  async (request, response, next) => {
    try {
      assertOperationRequest(request, "resource-file-upload");
      const runtime = await runtimeForRequest(request);
      const projectPath = path.resolve(String(request.query.project || ""));
      const { share } = await assertWritableProjectDirectory(projectPath, runtime);
      if (!Buffer.isBuffer(request.body)) throw httpError(400, "上传内容无效");
      const quotaRuntime = share ? await runtimeForUser(share.sourceUserId) : runtime;
      await assertQuotaAvailable(quotaRuntime, request.body.length);
      const destination = await resolveResourceDestination(
        projectPath,
        request.query.path || projectPath,
        request.query.name,
        runtime,
      );
      if (destination.exists) throw httpError(409, "同名文件已存在");
      await fs.writeFile(destination.targetPath, request.body, { flag: "wx", mode: 0o600 });
      await inheritResourceOwnership(destination.targetPath, destination.parentPath);
      directorySizeCache.clear();
      response.status(201).json({
        entry: await resourceEntrySnapshot(projectPath, destination.targetPath),
      });
    } catch (error) {
      if (error?.code === "EEXIST") next(httpError(409, "同名文件已存在"));
      else next(error);
    }
  },
);

