app.post("/api/preview/capture", async (request, response, next) => {
  const abortController = new AbortController();
  let capture = null;
  const disposeCapture = async () => {
    const current = capture;
    capture = null;
    await current?.dispose().catch(() => {});
  };
  const onAborted = () => abortController.abort();
  const onClosed = () => {
    if (!response.writableFinished) abortController.abort();
    void disposeCapture();
  };
  request.once("aborted", onAborted);
  response.once("close", onClosed);
  try {
    assertOperationRequest(request, "project-preview-capture");
    if (!mapRenderJobs) throw httpError(404, "项目截图在救援窗口中不可用");
    const config = publicOriginConfigStore?.snapshot();
    const requestOrigin = captureRequestOrigin(request);
    const allowedOrigins = config?.mode === "confirmed"
      ? config.previewOrigins
      : [requestOrigin];
    const target = normalizeCaptureUrl(request.body?.url, {
      baseOrigin: requestOrigin,
      allowedOrigins,
      allowedOriginPredicate: (origin) => isConfiguredPreviewOrigin(config, origin),
      allowLoopback: config?.mode !== "confirmed",
      requirePreviewPath: true,
    });
    const token = target.pathname.split("/")[2] || "";
    const preview = verifyProjectPreviewToken(token);
    if (preview.userId !== request.user?.id) throw httpError(403, "不能截图其他用户的项目预览");
    if (preview.previewOrigin && target.origin !== preview.previewOrigin) {
      throw httpError(403, "截图必须使用分配的预览 Origin");
    }
    if (!preview.previewOrigin && target.origin !== requestOrigin) {
      throw httpError(403, "沙箱截图必须使用当前实例 Origin");
    }
    capture = await mapRenderJobs.capturePreview({
      identity: mapSessionIdentity(request, "project-preview-capture"),
      capture: {
        url: target.href,
        config,
        requestOrigin,
        width: request.body?.width,
        height: request.body?.height,
        fullPage: request.body?.fullPage === true,
      },
    }, {
      signal: abortController.signal,
    });
    if (abortController.signal.aborted || response.destroyed) {
      await disposeCapture();
      return;
    }
    response.setHeader("Cache-Control", "no-store");
    response.setHeader("Content-Length", String(capture.size));
    response.type("png");
    response.sendFile(capture.filePath, {
      acceptRanges: false,
      cacheControl: false,
      dotfiles: "deny",
      lastModified: false,
    }, (error) => {
      request.off("aborted", onAborted);
      response.off("close", onClosed);
      void disposeCapture().finally(() => {
        if (!error) return;
        if (!response.headersSent) next(error);
        else response.destroy(error);
      });
    });
  } catch (error) {
    request.off("aborted", onAborted);
    response.off("close", onClosed);
    await disposeCapture();
    if (!response.destroyed) next(error);
  }
});

