async function rescueComponentSnapshot() {
  let operation = null;
  try {
    operation = JSON.parse(await fs.readFile(path.join(RELEASE_RUNTIME_DIR, "rescue-update.json"), "utf8"));
  } catch (error) {
    if (error.code !== "ENOENT") operation = { status: "unknown", error: "救援组件状态无法读取" };
  }
  let target = null;
  let version = null;
  let applicationVersion = null;
  try {
    target = await fs.realpath(path.join(RELEASE_RUNTIME_DIR, "rescue"));
    const [packageJson, manifest] = await Promise.all([
      fs.readFile(path.join(target, "package.json"), "utf8").then(JSON.parse),
      fs.readFile(path.join(target, ".codex-package.json"), "utf8").then(JSON.parse).catch(() => null),
    ]);
    version = manifest?.rescueVersion || packageJson.version || null;
    applicationVersion = packageJson.version || null;
  } catch {
    // A legacy installation may not have been migrated to the fixed link yet.
  }
  let availableVersion = null;
  try {
    const backendPort = Number((await fs.readFile(path.join(RELEASE_RUNTIME_DIR, "active-port"), "utf8")).trim());
    const target = await fs.realpath(path.join(RELEASE_RUNTIME_DIR, "slots", String(backendPort)));
    const [packageJson, manifest] = await Promise.all([
      fs.readFile(path.join(target, "package.json"), "utf8").then(JSON.parse),
      fs.readFile(path.join(target, ".codex-package.json"), "utf8").then(JSON.parse),
    ]);
    if (manifest.version === packageJson.version && manifest.capabilities?.includes("owner-rescue-v3")) {
      availableVersion = manifest.rescueVersion || packageJson.version;
    }
  } catch {
    // Only verified stable releases can be offered as a rescue component update.
  }
  let updateAvailable = false;
  if (availableVersion && version) {
    try {
      updateAvailable = rescueVersionIsNewer(availableVersion, version);
    } catch {
      // Invalid legacy metadata is shown but never offered as an upgrade target.
    }
  }
  return {
    activePort: 4321,
    target,
    version,
    applicationVersion,
    slots: [{
      port: 4321,
      active: true,
      target,
      version,
      applicationVersion,
    }],
    operation,
    availableVersion,
    updateAvailable,
    componentVersion: RESCUE_COMPONENT_VERSION,
    launchInProgress: rescueUpdateLaunchInProgress,
  };
}

async function assertRescueMainControlRequest(request) {
  if (RESCUE_MODE || !isDirectLoopbackRequest(request)) {
    throw httpError(404, "Not found");
  }
  const supplied = String(request.headers[RESCUE_MAIN_CONTROL_HEADER] || "");
  if (
    supplied.length !== SESSION_TOKEN.length
    || !crypto.timingSafeEqual(Buffer.from(supplied), Buffer.from(SESSION_TOKEN))
  ) {
    throw httpError(403, "Invalid rescue control credential");
  }
  if (!await backendPortIsSelected(RELEASE_RUNTIME_DIR, PORT)) {
    const error = httpError(409, "Main backend changed during rescue control");
    error.code = "ERR_RESCUE_MAIN_BACKEND_CHANGED";
    throw error;
  }
  if (BACKEND_INSTANCE_ID) {
    try {
      await backendAuthorityStore.assertCurrent({
        backendInstanceId: BACKEND_INSTANCE_ID,
        writerEpoch: BACKEND_WRITER_EPOCH,
        port: PORT,
      });
    } catch {
      const error = httpError(409, "Main backend writer authority changed during rescue control");
      error.code = "ERR_RESCUE_MAIN_BACKEND_CHANGED";
      throw error;
    }
  }
}

function withRescueWorktreeOperation(operation) {
  const result = rescueWorktreeOperation.then(operation, operation);
  rescueWorktreeOperation = result.catch(() => {});
  return result;
}

async function pathExistsForServer(candidate) {
  try {
    await fs.lstat(candidate);
    return true;
  } catch (error) {
    if (error?.code === "ENOENT") return false;
    throw error;
  }
}

async function rescueMainWorktreeState({ allowMissing = true } = {}) {
  if (RESCUE_MODE || !defaultRuntime.worktreeStore) throw httpError(404, "主站 Worktree 维护接口不可用");
  const store = defaultRuntime.worktreeStore;
  const sourceProjectPath = await fs.realpath(SOURCE_DIR);
  const binding = await rescueWorktreeBindingStore.read();
  let worktree = store.findByBinding(RESCUE_MAIN_WORKTREE_BINDING);
  if (binding && !worktree) {
    // A binding file can outlive a process restart that loaded an older
    // Worktree record without the binding field. Adopt only the exact record
    // and exact paths named by the owner-controlled binding file.
    const candidate = store.get(binding.worktreeId);
    if (
      candidate
      && !candidate.binding
      && path.resolve(candidate.projectPath) === sourceProjectPath
      && path.resolve(candidate.worktreePath) === binding.worktreePath
      && path.resolve(candidate.worktreeProjectPath) === binding.worktreeProjectPath
    ) {
      worktree = await store.setBinding(candidate.id, RESCUE_MAIN_WORKTREE_BINDING);
    }
  }
  if (!worktree && binding && !allowMissing) {
    throw httpError(409, "主站维护 Worktree 绑定记录不完整，请先检查运行目录");
  }
  if (worktree) {
    if (
      path.resolve(worktree.projectPath) !== sourceProjectPath
      || worktree.binding !== RESCUE_MAIN_WORKTREE_BINDING
      || (
        binding
        && (
          binding.worktreeId !== worktree.id
          || path.resolve(binding.worktreePath) !== path.resolve(worktree.worktreePath)
          || path.resolve(binding.worktreeProjectPath) !== path.resolve(worktree.worktreeProjectPath)
          || path.resolve(binding.sourceProjectPath) !== sourceProjectPath
        )
      )
    ) {
      throw httpError(409, "主站维护 Worktree 绑定路径不一致，已拒绝继续操作");
    }
  }
  return { store, sourceProjectPath, binding, worktree };
}

function rescueMainWorktreeBindingForRecord(worktree, sourceProjectPath) {
  return {
    version: RESCUE_WORKTREE_BINDING_VERSION,
    binding: RESCUE_MAIN_WORKTREE_BINDING,
    worktreeId: worktree.id,
    worktreePath: path.resolve(worktree.worktreePath),
    worktreeProjectPath: path.resolve(worktree.worktreeProjectPath),
    sourceProjectPath: path.resolve(sourceProjectPath),
    updatedAt: Date.now(),
  };
}

async function ensureRescueMainWorktree() {
  return withRescueWorktreeOperation(async () => {
    const current = await rescueMainWorktreeState({ allowMissing: true });
    let worktree = current.worktree;
    if (worktree) {
      if (worktree.state !== "ready") {
        if (!worktree.snapshot) throw httpError(409, "主站维护 Worktree 已丢失且没有可恢复快照");
        worktree = await current.store.restore(worktree.id);
      }
      const binding = rescueMainWorktreeBindingForRecord(worktree, current.sourceProjectPath);
      await rescueWorktreeBindingStore.write(binding);
      return { created: false, binding, worktree };
    }
    if (current.binding) {
      throw httpError(409, "主站维护 Worktree 绑定文件存在，但对应 Worktree 不可用");
    }
    const inspection = await current.store.inspectProject(current.sourceProjectPath);
    if (!inspection.repository) throw httpError(409, "主站源码不是 Git 仓库，无法创建维护 Worktree");
    worktree = await current.store.create({
      projectPath: current.sourceProjectPath,
      baseRef: "HEAD",
      includeUncommitted: false,
      permanent: true,
      label: "备用窗口 · 主站维护",
      binding: RESCUE_MAIN_WORKTREE_BINDING,
    });
    const binding = rescueMainWorktreeBindingForRecord(worktree, current.sourceProjectPath);
    try {
      await rescueWorktreeBindingStore.write(binding);
    } catch (error) {
      await current.store.remove(worktree.id, { snapshot: false }).catch(() => {});
      throw error;
    }
    return { created: true, binding, worktree };
  });
}

async function rescueMainWorktreeStatus() {
  const current = await rescueMainWorktreeState({ allowMissing: true });
  const source = {
    path: current.sourceProjectPath,
    status: null,
  };
  if (await pathExistsForServer(current.sourceProjectPath)) {
    source.status = await gitWorkspaceStatus(defaultRuntime, current.sourceProjectPath);
  }
  if (!current.worktree) {
    return {
      configured: false,
      binding: current.binding,
      source,
      worktree: null,
    };
  }
  const worktree = {
    ...current.worktree,
    status: current.worktree.state === "ready"
      ? await gitWorkspaceStatus(defaultRuntime, current.worktree.worktreeProjectPath)
      : null,
  };
  return {
    configured: true,
    binding: current.binding,
    source,
    worktree,
  };
}

async function rescueMainWorktreeDiff() {
  const current = await rescueMainWorktreeState({ allowMissing: false });
  if (!current.worktree || current.worktree.state !== "ready") {
    throw httpError(409, "主站维护 Worktree 尚未就绪");
  }
  const projectPath = current.worktree.worktreeProjectPath;
  const status = await gitWorkspaceStatus(defaultRuntime, projectPath);
  const [staged, unstaged, untracked] = await Promise.all([
    gitWorkspaceDiff(defaultRuntime, projectPath, { scope: "staged" }),
    gitWorkspaceDiff(defaultRuntime, projectPath, { scope: "unstaged" }),
    Promise.all(status.untracked.slice(0, 32).map((entry) => (
      gitWorkspaceDiff(defaultRuntime, projectPath, { scope: "untracked", path: entry.path })
    ))),
  ]);
  return {
    worktree: current.worktree,
    status,
    staged,
    unstaged,
    untracked,
    untrackedOmitted: Math.max(0, status.untracked.length - untracked.length),
  };
}

async function runRescueMainWorktreeCheck() {
  const current = await rescueMainWorktreeState({ allowMissing: false });
  if (!current.worktree || current.worktree.state !== "ready") {
    throw httpError(409, "主站维护 Worktree 尚未就绪");
  }
  const projectPath = current.worktree.worktreeProjectPath;
  const status = await gitWorkspaceStatus(defaultRuntime, projectPath);
  const whitespace = await runGitCommand(
    defaultRuntime,
    projectPath,
    ["diff", "--check", "HEAD", "--"],
    { allowExitCodes: [0, 1], maxBytes: 512 * 1024 },
  );
  const paths = [...new Set(status.files.map((entry) => entry.path))]
    .filter((entry) => /\.(?:[cm]?js|json)$/iu.test(entry))
    .slice(0, 64);
  const syntax = [];
  for (const relativePath of paths) {
    const absolutePath = path.resolve(projectPath, relativePath);
    try {
      await runChild(process.execPath, ["--check", absolutePath], {
        cwd: projectPath,
        timeoutMs: 10_000,
      });
      syntax.push({ path: relativePath, ok: true });
    } catch (error) {
      syntax.push({ path: relativePath, ok: false, error: String(error.message || "语法检查失败").slice(0, 2_000) });
    }
  }
  const result = {
    checkedAt: Date.now(),
    bounded: true,
    filesChecked: paths.length,
    filesOmitted: Math.max(0, status.files.length - paths.length),
    whitespace: { ok: whitespace.code === 0, output: String(whitespace.stdout || whitespace.stderr || "").slice(0, 8_000) },
    syntax,
    conflicts: status.files.filter((entry) => entry.indexStatus === "U" || entry.worktreeStatus === "U").map((entry) => entry.path),
  };
  result.ok = result.whitespace.ok
    && result.syntax.every((entry) => entry.ok)
    && result.conflicts.length === 0;
  return result;
}

async function mergeRescueMainWorktree(confirmation) {
  if (confirmation !== "合并主站维护 Worktree") {
    throw httpError(400, "请输入“合并主站维护 Worktree”完成管理员确认");
  }
  return withRescueWorktreeOperation(async () => {
    const current = await rescueMainWorktreeState({ allowMissing: false });
    if (!current.worktree || current.worktree.state !== "ready") {
      throw httpError(409, "主站维护 Worktree 尚未就绪");
    }
    const sourceStatus = await gitWorkspaceStatus(defaultRuntime, current.sourceProjectPath);
    if (sourceStatus.files.length) {
      throw httpError(409, "主站源码工作区不干净；请先保留或处理现有修改后再合并");
    }
    const sourceHead = await runGitCommand(defaultRuntime, current.sourceProjectPath, ["rev-parse", "HEAD"], { maxBytes: 16 * 1024 });
    if (sourceHead.stdout.trim() !== current.worktree.baseCommit) {
      throw httpError(409, "主站源码 HEAD 已变化，请重新创建维护 Worktree");
    }
    const check = await runRescueMainWorktreeCheck();
    if (!check.ok) throw httpError(409, "Worktree 检查未通过，请先修复检查结果");
    // Publish one direction only. A normal handoff would temporarily mark
    // the record as Local and then hand it back, creating a second mutation
    // window and allowing a failed second handoff to obscure which directory
    // the rescue binding is supposed to edit. publishToLocal verifies the
    // destination, updates the baseline, and keeps the record bound to the
    // independent Worktree throughout the merge.
    await current.store.publishToLocal(current.worktree.id);
    await rescueWorktreeBindingStore.write(
      rescueMainWorktreeBindingForRecord(current.store.get(current.worktree.id), current.sourceProjectPath),
    );
    return {
      ok: true,
      rebound: true,
      check,
      status: await rescueMainWorktreeStatus(),
    };
  });
}

function rescueMainTaskSnapshot() {
  const tasks = [];
  for (const runtime of allRuntimes()) {
    const providerSnapshot = runtime.providerStore?.snapshot?.() || {};
    const activeProvider = providerSnapshot.profiles?.find((entry) => entry.id === providerSnapshot.activeId);
    const providerName = activeProvider?.name || providerSnapshot.fallback?.name || "Codex 原配置";
    for (const task of runtime.taskStatus.list({ limit: 200 }).tasks) {
      if (!RESCUE_MAIN_ACTIVE_TASK_STATUSES.has(task.status) || !task.threadId) continue;
      tasks.push({
        id: `codex:${runtime.user.id}:${task.threadId}`,
        kind: "codex",
        userId: runtime.user.id,
        username: runtime.user.username,
        displayName: runtime.user.displayName || runtime.user.username,
        threadId: task.threadId,
        turnId: task.turnId || null,
        projectPath: task.cwd || null,
        providerName,
        status: task.status,
        phase: task.phase,
        startedAt: task.startedAt || task.queuedAt || null,
        updatedAt: task.updatedAt || null,
        interruptible: true,
      });
    }
    if (!runtime.claudeRuntime) continue;
    for (const session of runtime.claudeRuntime.listSessions()) {
      const task = publicTaskCenterClaudeSession(session);
      if (!task || !["inProgress", "paused", "retryWaiting", "stopping"].includes(task.status)) continue;
      tasks.push({
        id: `claude:${runtime.user.id}:${task.id}`,
        kind: "claude",
        userId: runtime.user.id,
        username: runtime.user.username,
        displayName: runtime.user.displayName || runtime.user.username,
        sessionId: task.id,
        name: task.name,
        projectPath: task.projectPath || null,
        providerName: task.provider?.name || "Claude",
        status: task.status,
        phase: task.status,
        startedAt: task.startedAt || null,
        updatedAt: task.updatedAt || null,
        interruptible: true,
      });
    }
  }
  tasks.sort((left, right) => (
    Number(right.startedAt || right.updatedAt || 0) - Number(left.startedAt || left.updatedAt || 0)
  ));
  return {
    ok: true,
    version: APP_VERSION,
    port: PORT,
    backendInstanceId: BACKEND_INSTANCE_ID,
    writerEpoch: BACKEND_WRITER_EPOCH,
    observedAt: Date.now(),
    tasks,
  };
}

async function listMainReferenceThreads() {
  if (RESCUE_MODE) throw httpError(404, "Not found");
  if (!defaultRuntime.bridge.ready) throw httpError(503, "主站 Codex 服务尚未就绪");
  const result = await requestThreadListAcrossProviders(defaultRuntime.bridge, {
    limit: 100,
    sortKey: "updated_at",
    sortDirection: "desc",
    archived: false,
  }, { timeoutMs: 30_000 });
  const merged = mergeImportedThreadList(defaultRuntime, result, {
    limit: 100,
    sortKey: "updated_at",
    sortDirection: "desc",
    archived: false,
  });
  return {
    sourceVersion: APP_VERSION,
    observedAt: Date.now(),
    threads: (Array.isArray(merged?.data) ? merged.data : []).slice(0, 100).map((thread) => ({
      id: String(thread.id),
      name: String(thread.name || thread.preview || "未命名主站对话").slice(0, 512),
      preview: String(thread.preview || "").slice(0, 2_000),
      cwd: typeof thread.cwd === "string" ? thread.cwd : null,
      updatedAt: thread.updatedAt || thread.updated_at || null,
      archived: thread.archived === true,
      readOnly: true,
    })),
  };
}

async function readMainReferenceThread(threadId) {
  if (RESCUE_MODE) throw httpError(404, "Not found");
  const normalized = normalizeRescueReferenceSourceId(threadId);
  if (!defaultRuntime.bridge.ready) throw httpError(503, "主站 Codex 服务尚未就绪");
  const imported = defaultRuntime.threadImportStore.get(normalized);
  const thread = imported
    ? await readFullImportedThread(defaultRuntime, imported)
    : (await defaultRuntime.bridge.request("thread/read", {
      threadId: normalized,
      includeTurns: true,
    }, { timeoutMs: 30_000 }))?.thread;
  if (!thread) throw httpError(404, "主站对话不存在");
  return {
    sourceVersion: APP_VERSION,
    observedAt: Date.now(),
    thread: {
      ...buildThreadExport(thread),
      cwd: typeof thread.cwd === "string" ? thread.cwd : null,
    },
  };
}

function normalizeRescueReferenceSourceId(value) {
  if (typeof value !== "string" || !value.trim() || value.length > 512 || /[\u0000\r\n]/u.test(value)) {
    throw httpError(400, "主站对话 ID 无效");
  }
  return value.trim();
}

function normalizeRescueReferenceTurnIds(value) {
  if (value == null) return [];
  if (!Array.isArray(value) || value.length > 100) throw httpError(400, "引用消息范围无效");
  return [...new Set(value.map((entry) => {
    if (typeof entry !== "string" || !entry || entry.length > 512 || /[\u0000\r\n]/u.test(entry)) {
      throw httpError(400, "引用消息 ID 无效");
    }
    return entry;
  }))];
}

function referenceTurnText(turn) {
  const lines = [];
  for (const item of Array.isArray(turn?.items) ? turn.items : []) {
    if (!item || typeof item !== "object") continue;
    const text = typeof item.text === "string"
      ? item.text
      : exportContentText(item.content);
    if (!text.trim()) continue;
    const label = ["user", "userMessage"].includes(item.type)
      ? "用户"
      : ["assistant", "agentMessage"].includes(item.type) ? "Codex" : item.type;
    lines.push(`${label}: ${text.trim()}`);
  }
  return lines.join("\n\n").slice(0, 100_000);
}

function normalizeRescueMainInterruptTarget(value) {
  if (!value || typeof value !== "object") throw httpError(400, "Invalid main task target");
  const kind = String(value.kind || "");
  if (!["codex", "claude"].includes(kind)) throw httpError(400, "Invalid main task kind");
  const userId = normalizeRescueControlIdentifier(value.userId, "user ID");
  const backendInstanceId = normalizeRescueControlIdentifier(value.backendInstanceId, "backend instance ID");
  const writerEpoch = Number(value.writerEpoch);
  if (!Number.isSafeInteger(writerEpoch) || writerEpoch < 1) throw httpError(400, "Invalid writer epoch");
  if (backendInstanceId !== BACKEND_INSTANCE_ID || writerEpoch !== BACKEND_WRITER_EPOCH) {
    throw httpError(409, "Main backend changed; refresh the active task list");
  }
  if (kind === "codex") {
    return {
      kind,
      userId,
      backendInstanceId,
      writerEpoch,
      threadId: normalizeRescueControlIdentifier(value.threadId, "thread ID"),
      turnId: value.turnId == null ? null : normalizeRescueControlIdentifier(value.turnId, "turn ID"),
    };
  }
  return {
    kind,
    userId,
    backendInstanceId,
    writerEpoch,
    sessionId: normalizeRescueControlIdentifier(value.sessionId, "session ID"),
  };
}

function normalizeRescueControlIdentifier(value, label) {
  const text = typeof value === "string" ? value.trim() : "";
  if (!text || text.length > 256 || /[\0\r\n]/.test(text)) throw httpError(400, `Invalid ${label}`);
  return text;
}

async function interruptRescueMainTask(target) {
  const runtime = runtimeByUserId.get(target.userId);
  if (!runtime) throw httpError(404, "Main task runtime is no longer active");
  if (target.kind === "claude") {
    const result = await runtime.claudeRuntime?.interrupt(target.sessionId);
    if (!result?.interrupted) throw httpError(409, "Claude task is no longer running");
    return result;
  }

  const task = runtime.taskStatus.snapshot(target.threadId);
  if (!RESCUE_MAIN_ACTIVE_TASK_STATUSES.has(task.status)) {
    throw httpError(409, "Codex task is no longer running");
  }
  if (task.status === "queued") {
    const cancelled = runtime.codexTaskAdmissions.cancel(target.threadId, "排队任务已由所有者从备用窗口终止");
    if (!cancelled) throw httpError(409, "Codex task has left the waiting queue; refresh and try again");
    return { interrupted: true, queued: true };
  }
  const publicThreadId = target.threadId;
  const nativeThreadId = runtime.nativeThreadIdForPublic(publicThreadId);
  let turnId = task.turnId || target.turnId;
  if (!turnId) {
    const turns = await runtime.bridge.request("thread/turns/list", {
      threadId: nativeThreadId,
      limit: 8,
      sortDirection: "desc",
      itemsView: "summary",
    }, { timeoutMs: 8_000 });
    turnId = turns.data?.find((turn) => codexTurnIsActive(turn?.status))?.id || null;
  }
  if (!turnId) throw httpError(409, "Codex task identity is still synchronizing; refresh and try again");
  return runtime.interruptTurn(nativeThreadId, turnId, { publicThreadId });
}

async function requestActiveMainControl(pathname, { method = "GET", body = null } = {}) {
  let lastError = null;
  for (let attempt = 0; attempt < 2; attempt += 1) {
    try {
      const port = await readActiveMainControlPort();
      let payload = body;
      if (method !== "GET") {
        const identity = await fetchMainControlPort(port, "/tasks");
        payload = {
          ...body,
          backendInstanceId: identity.backendInstanceId,
          writerEpoch: identity.writerEpoch,
        };
      }
      return await fetchMainControlPort(port, pathname, { method, body: payload });
    } catch (error) {
      lastError = error;
      if (attempt === 0 && [409, 502, 503].includes(error.statusCode)) continue;
      break;
    }
  }
  throw lastError || httpError(503, "Main task control is unavailable");
}

async function readActiveMainControlPort() {
  const port = Number((await fs.readFile(path.join(RELEASE_RUNTIME_DIR, "active-port"), "utf8")).trim());
  if (!MAIN_BACKEND_PORTS.includes(port)) throw httpError(503, "Main backend selector is unavailable");
  return port;
}

async function fetchMainControlPort(port, pathname, { method = "GET", body = null } = {}) {
  let response;
  try {
    response = await fetch(`http://127.0.0.1:${port}${RESCUE_MAIN_CONTROL_PREFIX}${pathname}`, {
      method,
      headers: {
        [RESCUE_MAIN_CONTROL_HEADER]: SESSION_TOKEN,
        ...(body ? { "Content-Type": "application/json" } : {}),
      },
      body: body ? JSON.stringify(body) : undefined,
      cache: "no-store",
      signal: AbortSignal.timeout(method === "GET" ? 5_000 : 15_000),
    });
  } catch {
    throw httpError(503, "Main backend is not reachable from the rescue component");
  }
  const data = await response.json().catch(() => ({}));
  if (!response.ok) {
    const error = httpError(response.status, data.error || "Main task control failed");
    if (typeof data.code === "string") error.code = data.code;
    throw error;
  }
  return data;
}

function launchDeploymentWorker(scriptName, args, {
  sourceDirectory = SOURCE_DIR,
  env,
  failureMessage,
  invalidResultMessage,
  timeoutMessage,
}) {
  return new Promise((resolve, reject) => {
    const child = spawn(process.execPath, [path.join(sourceDirectory, "scripts", scriptName), ...args], {
      cwd: sourceDirectory,
      env,
      stdio: ["ignore", "pipe", "pipe"],
      detached: true,
    });
    let stdout = "";
    let stderr = "";
    let settled = false;
    let timedOut = false;
    let forceKillTimer = null;
    const timeoutError = httpError(504, timeoutMessage);
    const finish = (error, value) => {
      if (settled) return;
      settled = true;
      clearTimeout(deadlineTimer);
      if (forceKillTimer) clearTimeout(forceKillTimer);
      if (error) reject(error);
      else resolve(value);
    };
    const deadlineTimer = setTimeout(() => {
      if (settled) return;
      timedOut = true;
      terminateChildProcess(child, "SIGTERM", { processGroup: true });
      forceKillTimer = setTimeout(() => {
        terminateChildProcess(child, "SIGKILL", { processGroup: true });
        finish(timeoutError);
      }, CHILD_TERMINATION_GRACE_MS);
      forceKillTimer.unref?.();
    }, DEPLOYMENT_LAUNCH_TIMEOUT_MS);
    deadlineTimer.unref?.();
    child.stdout.on("data", (chunk) => {
      stdout = `${stdout}${chunk}`.slice(-4_000);
    });
    child.stderr.on("data", (chunk) => {
      stderr = `${stderr}${chunk}`.slice(-4_000);
    });
    child.on("error", (error) => finish(timedOut ? timeoutError : error));
    child.on("close", (code) => {
      if (timedOut) {
        finish(timeoutError);
        return;
      }
      if (code !== 0) {
        finish(httpError(500, stderr.trim() || failureMessage));
        return;
      }
      try {
        const result = parseLauncherResult(stdout);
        finish(null, {
          unit: result.unit || null,
          status: result.status || "queued",
          ...(result.candidateId ? { candidateId: result.candidateId } : {}),
        });
      } catch {
        finish(httpError(500, invalidResultMessage));
      }
    });
  });
}

function assertOperationRequest(request, action) {
  if (request.get("x-codex-desktop-action") !== action) {
    throw httpError(403, "请求缺少操作确认标记");
  }
  assertSameOriginRequest(request);
}

function isWebdavPath(requestPath) {
  return requestPath === WEBDAV_PATH_PREFIX || requestPath.startsWith(`${WEBDAV_PATH_PREFIX}/`);
}

async function handleWebdavRequest(request, response, next) {
  const mutating = new Set(["PUT", "MKCOL", "DELETE", "MOVE", "COPY", "PROPPATCH"]);
  try {
    const runtime = await authenticateWebdavRequest(request, response);
    if (!runtime) return;
    switch (request.method.toUpperCase()) {
      case "OPTIONS":
        webdavOptions(response);
        return;
      case "PROPFIND":
        await webdavPropfind(request, response, runtime);
        return;
      case "GET":
      case "HEAD":
        await webdavGet(request, response, runtime);
        return;
      case "PUT":
        await webdavPut(request, response, runtime);
        return;
      case "MKCOL":
        await webdavMkcol(request, response, runtime);
        return;
      case "DELETE":
        await webdavDelete(request, response, runtime);
        return;
      case "MOVE":
      case "COPY":
        await webdavCopyMove(request, response, runtime);
        return;
      case "LOCK":
        webdavLock(response);
        return;
      case "UNLOCK":
        response.status(204).end();
        return;
      case "PROPPATCH":
        response.status(207).type("application/xml").send(webdavMultiStatus([]));
        return;
      default:
        response.setHeader("Allow", WEBDAV_ALLOW_METHODS);
        response.status(405).end();
    }
  } catch (error) {
    next(error);
  } finally {
    if (mutating.has(request.method.toUpperCase())) request.completePersistentStateOperation?.();
  }
}

const WEBDAV_ALLOW_METHODS = "OPTIONS, PROPFIND, GET, HEAD, PUT, MKCOL, DELETE, MOVE, COPY, LOCK, UNLOCK, PROPPATCH";

async function authenticateWebdavRequest(request, response) {
  if (RESCUE_MODE) {
    response.status(404).end();
    return null;
  }
  const multiUserEnabled = multiUserStore.modeSnapshot().enabled;
  if (!multiUserEnabled && !AUTH) {
    request.user = legacyUser;
    return runtimeForRequest(request);
  }

  const credentials = webdavBasicCredentials(request.get("authorization"));
  if (!credentials) {
    webdavChallenge(response);
    return null;
  }
  const clientKey = authClientKey(request);
  const retryAfter = authRetryAfter(clientKey);
  if (retryAfter > 0) {
    response.setHeader("Retry-After", String(retryAfter));
    response.status(429).end();
    return null;
  }

  let user = null;
  if (multiUserEnabled) {
    const stored = multiUserStore.findActiveUserByUsername(credentials.username);
    if (stored && multiUserStore.verifyPassword(stored.id, credentials.password)) {
      user = publicAccountUser(stored);
    }
  } else if (AUTH && verifyAuthCredentials(credentials.username, credentials.password, AUTH)) {
    user = legacyUser;
  }
  if (!user) {
    recordAuthFailure(clientKey);
    const blockedFor = authRetryAfter(clientKey);
    if (blockedFor > 0) response.setHeader("Retry-After", String(blockedFor));
    webdavChallenge(response, blockedFor > 0 ? 429 : 401);
    return null;
  }
  clearAuthFailures(clientKey);
  request.user = user;
  return runtimeForRequest(request);
}

function webdavBasicCredentials(header) {
  if (typeof header !== "string" || !header.startsWith("Basic ")) return null;
  let decoded;
  try {
    decoded = Buffer.from(header.slice(6), "base64").toString("utf8");
  } catch {
    return null;
  }
  const separator = decoded.indexOf(":");
  if (separator <= 0) return null;
  const username = decoded.slice(0, separator).trim();
  const password = decoded.slice(separator + 1);
  return username && password ? { username, password } : null;
}

function webdavChallenge(response, status = 401) {
  response.setHeader("WWW-Authenticate", `Basic realm="${WEBDAV_REALM}", charset="UTF-8"`);
  response.setHeader("Cache-Control", "no-store");
  response.status(status).end();
}

async function webdavPropfind(request, response, runtime) {
  const segments = webdavSegmentsFromPath(webdavRequestPath(request));
  const context = await webdavContextForSegments(segments, runtime);
  const current = await webdavResourceDescriptor(context, runtime);
  const entries = [current];
  const depth = String(request.get("depth") || "1").toLowerCase();
  if (!new Set(["0", "1", "infinity"]).has(depth)) {
    throw httpError(400, "WebDAV Depth 请求头无效");
  }
  if (depth !== "0" && current.collection) {
    entries.push(...await webdavChildDescriptors(context, runtime));
  }
  response.status(207);
  response.type("application/xml");
  response.send(webdavMultiStatus(entries));
}

async function webdavGet(request, response, runtime) {
  const segments = webdavSegmentsFromPath(webdavRequestPath(request));
  const context = await webdavContextForSegments(segments, runtime);
  if (context.root || context.projectRoot) throw httpError(405, "WebDAV 目录不能直接下载");
  const targetPath = await webdavExistingPath(context, runtime);
  const stat = await fs.stat(targetPath);
  if (!stat.isFile()) throw httpError(405, "WebDAV 目录不能直接下载");
  const projectRealPath = await fs.realpath(context.project.path);
  const realTargetPath = await assertRealPathInside(projectRealPath, targetPath);
  response.setHeader("Content-Type", webdavMimeType(targetPath));
  response.setHeader("Content-Length", String(stat.size));
  response.setHeader("Last-Modified", new Date(stat.mtimeMs).toUTCString());
  response.setHeader("Cache-Control", "private, max-age=0, must-revalidate");
  response.sendFile(realTargetPath, { dotfiles: "allow" }, (error) => {
    if (error && !response.headersSent) response.status(error.statusCode || 500).end();
  });
}

async function webdavPut(request, response, runtime) {
  const segments = webdavSegmentsFromPath(webdavRequestPath(request));
  const destination = await webdavDestinationForSegments(segments, runtime);
  const { share } = await assertWritableProjectDirectory(destination.project.path, runtime);
  let existingStat = null;
  if (destination.exists) {
    existingStat = await fs.lstat(destination.targetPath);
    if (existingStat.isSymbolicLink() || !existingStat.isFile()) {
      throw httpError(409, "只能覆盖已有普通文件");
    }
  }
  const declaredLength = Number(request.headers["content-length"]);
  if (Number.isSafeInteger(declaredLength) && declaredLength > WEBDAV_MAX_FILE_BYTES) {
    throw httpError(413, "WebDAV 文件超过安全上传上限");
  }
  const temporaryDirectory = path.join(runtime.user.stateDirectory, "webdav-upload");
  await fs.mkdir(temporaryDirectory, { recursive: true, mode: 0o700 });
  const temporaryPath = path.join(
    temporaryDirectory,
    `${Date.now()}-${crypto.randomBytes(8).toString("hex")}.tmp`,
  );
  let bytes = 0;
  try {
    const stream = createWriteStream(temporaryPath, { flags: "wx", mode: existingStat?.mode & 0o777 || 0o600 });
    const limiter = new Transform({
      transform(chunk, _encoding, callback) {
        bytes += chunk.length;
        if (bytes > WEBDAV_MAX_FILE_BYTES) {
          callback(httpError(413, "WebDAV 文件超过安全上传上限"));
          return;
        }
        callback(null, chunk);
      },
    });
    await pipeline(request, limiter, stream);
    const quotaRuntime = share ? await runtimeForUser(share.sourceUserId) : runtime;
    await assertQuotaAvailable(quotaRuntime, Math.max(0, bytes - Number(existingStat?.size || 0)));
    await inheritResourceOwnership(temporaryPath, destination.parentPath);
    await fs.rename(temporaryPath, destination.targetPath);
    directorySizeCache.clear();
    response.status(destination.exists ? 204 : 201).end();
  } finally {
    await fs.rm(temporaryPath, { force: true }).catch(() => {});
  }
}

async function webdavMkcol(request, response, runtime) {
  const segments = webdavSegmentsFromPath(webdavRequestPath(request));
  const destination = await webdavDestinationForSegments(segments, runtime);
  await assertWritableProjectDirectory(destination.project.path, runtime);
  if (destination.exists) throw httpError(405, "目标文件夹已经存在");
  await fs.mkdir(destination.targetPath, { recursive: false, mode: 0o700 });
  await inheritResourceOwnership(destination.targetPath, destination.parentPath);
  directorySizeCache.clear();
  response.status(201).end();
}

async function webdavDelete(request, response, runtime) {
  const segments = webdavSegmentsFromPath(webdavRequestPath(request));
  const context = await webdavContextForSegments(segments, runtime);
  if (context.root || context.projectRoot) throw httpError(403, "不能删除 WebDAV 工程根目录");
  await assertWritableProjectDirectory(context.project.path, runtime);
  const targetPath = await webdavExistingPath(context, runtime);
  const trashDirectory = path.join(context.project.path, ".codex-trash");
  await fs.mkdir(trashDirectory, { recursive: true, mode: 0o700 });
  await inheritResourceOwnership(trashDirectory, context.project.path);
  const trashTarget = path.join(
    trashDirectory,
    `${Date.now()}-${crypto.randomBytes(8).toString("hex")}-${path.basename(targetPath)}`,
  );
  await fs.rename(targetPath, trashTarget);
  directorySizeCache.clear();
  response.status(204).end();
}

async function webdavCopyMove(request, response, runtime) {
  const sourceSegments = webdavSegmentsFromPath(webdavRequestPath(request));
  const source = await webdavContextForSegments(sourceSegments, runtime);
  if (source.root || source.projectRoot) throw httpError(403, "不能复制或移动 WebDAV 工程根目录");
  const sourcePath = await webdavExistingPath(source, runtime);
  const destinationHeader = request.get("destination");
  if (!destinationHeader) throw httpError(400, "WebDAV Destination 请求头缺失");
  const requestOrigin = `${request.protocol}://${request.get("host")}`;
  let destinationUrl;
  try {
    destinationUrl = new URL(destinationHeader, requestOrigin);
  } catch {
    throw httpError(400, "WebDAV Destination 地址无效");
  }
  if (destinationUrl.host.toLowerCase() !== request.get("host")?.toLowerCase()) {
    throw httpError(403, "不能复制或移动到其他主机");
  }
  const destinationSegments = webdavSegmentsFromPath(destinationUrl.pathname);
  const destination = await webdavDestinationForSegments(destinationSegments, runtime);
  if (destination.project.path !== source.project.path) throw httpError(403, "不能跨工程复制或移动文件");
  const { share } = await assertWritableProjectDirectory(destination.project.path, runtime);
  if (path.resolve(sourcePath) === path.resolve(destination.targetPath)) throw httpError(409, "源文件和目标文件相同");
  const overwrite = String(request.get("overwrite") || "T").toUpperCase() !== "F";
  if (destination.exists && !overwrite) throw httpError(412, "目标文件已经存在");
  const sourceStat = await fs.lstat(sourcePath);
  if (sourceStat.isSymbolicLink() || (!sourceStat.isDirectory() && !sourceStat.isFile())) {
    throw httpError(403, "不能复制不可用的 WebDAV 文件类型");
  }
  if (sourceStat.isDirectory() && isPathWithin(sourcePath, destination.targetPath)) {
    throw httpError(409, "不能把文件夹复制或移动到自身内部");
  }

  let destinationStat = null;
  if (destination.exists) {
    destinationStat = await fs.lstat(destination.targetPath);
    if (destinationStat.isSymbolicLink() || (!destinationStat.isDirectory() && !destinationStat.isFile())) {
      throw httpError(409, "目标文件类型不可覆盖");
    }
  }

  if (request.method === "COPY") {
    const copiedBytes = sourceStat.isFile()
      ? sourceStat.size
      : (await inspectResourceTree(sourcePath)).bytes;
    const replacedBytes = !destinationStat
      ? 0
      : destinationStat.isFile()
        ? destinationStat.size
        : (await inspectResourceTree(destination.targetPath)).bytes;
    const quotaRuntime = share
      ? await runtimeForUser(share.sourceUserId)
      : runtime;
    // Check the net quota delta before removing an existing destination.  A
    // failed quota check must never turn an overwrite into data loss.
    await assertQuotaAvailable(quotaRuntime, copiedBytes - replacedBytes);
  }
  if (destination.exists) await fs.rm(destination.targetPath, { recursive: true, force: true });
  if (request.method === "COPY") {
    await fs.cp(sourcePath, destination.targetPath, {
      recursive: sourceStat.isDirectory(),
      force: false,
      errorOnExist: true,
      preserveTimestamps: true,
    });
    await inheritResourceOwnership(destination.targetPath, destination.parentPath, { recursive: true });
  } else {
    await fs.rename(sourcePath, destination.targetPath);
  }
  directorySizeCache.clear();
  response.status(destination.exists ? 204 : 201).end();
}

function webdavOptions(response) {
  response.setHeader("DAV", "1, 2");
  response.setHeader("Allow", WEBDAV_ALLOW_METHODS);
  response.setHeader("MS-Author-Via", "DAV");
  response.status(200).end();
}

function webdavLock(response) {
  const token = `opaquelocktoken:${crypto.randomUUID()}`;
  response.setHeader("Lock-Token", `<${token}>`);
  response.setHeader("Timeout", "Second-3600");
  response.status(200).type("application/xml").send(
    `<?xml version="1.0" encoding="utf-8"?><D:prop xmlns:D="DAV:"><D:lockdiscovery><D:activelock><D:locktype><D:write/></D:locktype><D:lockscope><D:exclusive/></D:lockscope><D:depth>Infinity</D:depth><D:timeout>Second-3600</D:timeout><D:locktoken><D:href>${escapeHtml(token)}</D:href></D:locktoken></D:activelock></D:lockdiscovery></D:prop>`,
  );
}

function webdavRequestPath(request) {
  return String(request.originalUrl || request.url || WEBDAV_PATH_PREFIX).split("?", 1)[0];
}

function webdavSegmentsFromPath(requestPath) {
  const pathname = String(requestPath || "").split("?", 1)[0];
  let suffix;
  if (pathname === WEBDAV_PATH_PREFIX || pathname === `${WEBDAV_PATH_PREFIX}/`) suffix = "";
  else if (pathname.startsWith(`${WEBDAV_PATH_PREFIX}/`)) suffix = pathname.slice(`${WEBDAV_PATH_PREFIX}/`.length);
  else throw httpError(400, "WebDAV 路径无效");
  if (!suffix) return [];
  return suffix.split("/").filter(Boolean).map((encoded) => {
    let value;
    try {
      value = decodeURIComponent(encoded);
    } catch {
      throw httpError(400, "WebDAV 路径编码无效");
    }
    if (
      !value
      || value === "."
      || value === ".."
      || value.includes("/")
      || value.includes("\\")
      || /[\u0000\u0001-\u001f\u007f]/.test(value)
    ) throw httpError(400, "WebDAV 路径无效");
    return value;
  });
}

function webdavProjectEntries(projects) {
  const usedNames = new Set();
  return projects.map((project) => {
    const baseName = String(project.name || project.id || "工程");
    let webdavName = baseName;
    if (usedNames.has(webdavName)) webdavName = `${baseName} (${project.id})`;
    let suffix = 2;
    while (usedNames.has(webdavName)) {
      webdavName = `${baseName} (${project.id}-${suffix})`;
      suffix += 1;
    }
    usedNames.add(webdavName);
    return { project, webdavName };
  });
}

async function webdavContextForSegments(segments, runtime) {
  if (!segments.length) return { root: true, project: null, projectRoot: false, targetPath: null, segments };
  // WebDAV is the mobile sync boundary. It must expose only projects owned by
  // the authenticated account; explicit browser project shares are not
  // implicitly mounted into a user's mobile drive.
  const entries = webdavProjectEntries(await listProjects(runtime, {
    includeShared: false,
    includeWorktrees: false,
  }));
  const projectEntry = entries.find((entry) => entry.webdavName === segments[0])
    || entries.find((entry) => entry.project.id === segments[0]);
  const project = projectEntry?.project;
  if (!project) throw httpError(404, "WebDAV 工程不存在");
  const projectPath = path.resolve(project.path);
  await assertSafeProjectDirectory(projectPath, runtime);
  const relativeSegments = segments.slice(1);
  if (relativeSegments.some((segment) => HIDDEN_RESOURCE_NAMES.has(segment))) {
    throw httpError(403, "WebDAV 路径受保护");
  }
  return {
    root: false,
    project,
    projectName: projectEntry.webdavName,
    projectRoot: relativeSegments.length === 0,
    targetPath: path.join(projectPath, ...relativeSegments),
    segments,
  };
}

async function webdavExistingPath(context, runtime) {
  if (context.root) throw httpError(400, "WebDAV 根目录不是文件");
  try {
    const resolved = await resolveResourceTarget(context.project.path, context.targetPath, runtime);
    return resolved.targetPath;
  } catch (error) {
    // Rclone probes a destination with PROPFIND before uploading. A new
    // destination is expected to return 404 so the client can continue with
    // PUT; leaking fs.realpath/lstat ENOENT turns that normal probe into a
    // retryable 500 and leaves Android uploads stuck at 0 bytes.
    if (error?.code === "ENOENT") throw httpError(404, "WebDAV 资源不存在");
    throw error;
  }
}

async function webdavDestinationForSegments(segments, runtime) {
  if (segments.length < 2) throw httpError(403, "WebDAV 工程根目录不可直接写入");
  const name = segments[segments.length - 1];
  const parent = await webdavContextForSegments(segments.slice(0, -1), runtime);
  if (parent.root || !parent.project) throw httpError(403, "WebDAV 工程根目录不可直接写入");
  await webdavExistingPath(parent, runtime);
  const destination = await resolveResourceDestination(
    parent.project.path,
    parent.targetPath,
    name,
    runtime,
  );
  return { ...destination, project: parent.project };
}

async function webdavResourceDescriptor(context, runtime) {
  if (context.root) {
    return {
      href: webdavHref([], true),
      displayName: "WFL Codex",
      collection: true,
      size: 0,
      modifiedAt: Date.now(),
      version: "wfl-webdav-root",
      mimeType: "httpd/unix-directory",
    };
  }
  const stat = await fs.lstat(await webdavExistingPath(context, runtime));
  if (stat.isSymbolicLink() || (!stat.isDirectory() && !stat.isFile())) throw httpError(403, "WebDAV 文件类型不可用");
  return {
    href: webdavHref(context.segments, stat.isDirectory()),
    displayName: context.projectRoot ? context.projectName : path.basename(context.targetPath),
    collection: stat.isDirectory(),
    size: stat.isFile() ? stat.size : 0,
    modifiedAt: stat.mtimeMs,
    version: resourceEntryVersion(stat),
    mimeType: stat.isDirectory() ? "httpd/unix-directory" : webdavMimeType(context.targetPath),
  };
}

async function webdavChildDescriptors(context, runtime) {
  if (context.root) {
    const projects = webdavProjectEntries(await listProjects(runtime, {
      includeShared: false,
      includeWorktrees: false,
    }));
    return projects.map(({ project, webdavName }) => ({
      href: webdavHref([webdavName], true),
      displayName: webdavName,
      collection: true,
      size: 0,
      modifiedAt: project.modifiedAt,
      version: `project-${project.id}`,
      mimeType: "httpd/unix-directory",
    }));
  }
  const directoryPath = await webdavExistingPath(context, runtime);
  const stat = await fs.stat(directoryPath);
  if (!stat.isDirectory()) return [];
  const names = await fs.readdir(directoryPath);
  const descriptors = [];
  for (const name of names) {
    if (HIDDEN_RESOURCE_NAMES.has(name)) continue;
    const childPath = path.join(directoryPath, name);
    const childStat = await fs.lstat(childPath);
    if (childStat.isSymbolicLink() || (!childStat.isDirectory() && !childStat.isFile())) continue;
    descriptors.push({
      href: webdavHref([...context.segments, name], childStat.isDirectory()),
      displayName: name,
      collection: childStat.isDirectory(),
      size: childStat.isFile() ? childStat.size : 0,
      modifiedAt: childStat.mtimeMs,
      version: resourceEntryVersion(childStat),
      mimeType: childStat.isDirectory() ? "httpd/unix-directory" : webdavMimeType(childPath),
    });
  }
  descriptors.sort((left, right) => {
    if (left.collection !== right.collection) return left.collection ? -1 : 1;
    return left.displayName.localeCompare(right.displayName, "zh-CN", { numeric: true });
  });
  return descriptors;
}

function webdavHref(segments, collection) {
  const encoded = [WEBDAV_PATH_PREFIX.slice(1), ...segments].map((segment) => encodeURIComponent(segment));
  return `/${encoded.join("/")}${collection ? "/" : ""}`;
}

function webdavMultiStatus(entries) {
  const responses = entries.map((entry) => `
    <D:response>
      <D:href>${escapeHtml(entry.href)}</D:href>
      <D:propstat>
        <D:prop>
          <D:displayname>${escapeHtml(entry.displayName)}</D:displayname>
          <D:resourcetype>${entry.collection ? "<D:collection/>" : ""}</D:resourcetype>
          <D:getcontentlength>${entry.size}</D:getcontentlength>
          <D:getcontenttype>${escapeHtml(entry.mimeType)}</D:getcontenttype>
          <D:getlastmodified>${new Date(entry.modifiedAt || Date.now()).toUTCString()}</D:getlastmodified>
          <D:getetag>&quot;${escapeHtml(entry.version)}&quot;</D:getetag>
        </D:prop>
        <D:status>HTTP/1.1 200 OK</D:status>
      </D:propstat>
    </D:response>`).join("");
  return `<?xml version="1.0" encoding="utf-8"?><D:multistatus xmlns:D="DAV:">${responses}</D:multistatus>`;
}

function webdavMimeType(filePath) {
  const extension = path.extname(filePath).toLowerCase();
  return {
    ".avif": "image/avif",
    ".csv": "text/csv",
    ".gif": "image/gif",
    ".html": "text/html; charset=utf-8",
    ".jpeg": "image/jpeg",
    ".jpg": "image/jpeg",
    ".json": "application/json",
    ".m4a": "audio/mp4",
    ".mp3": "audio/mpeg",
    ".mp4": "video/mp4",
    ".pdf": "application/pdf",
    ".png": "image/png",
    ".txt": "text/plain; charset=utf-8",
    ".webp": "image/webp",
    ".xml": "application/xml",
    ".zip": "application/zip",
  }[extension] || "application/octet-stream";
}

function assertSameOriginRequest(request) {
  const origin = request.get("origin");
  const expectedHost = trustedForwardedHeader(request, "x-forwarded-host") || request.headers.host;
  const expectedProtocol = trustedForwardedHeader(request, "x-forwarded-proto") || (request.secure ? "https" : "http");
  try {
    const parsed = new URL(origin);
    if (parsed.host.toLowerCase() !== expectedHost?.toLowerCase() || parsed.protocol !== `${expectedProtocol}:`) {
      throw new Error("origin mismatch");
    }
  } catch {
    throw httpError(403, "操作请求必须来自当前网页");
  }
}

function requireAdmin(request) {
  if (!request.user || !["owner", "admin"].includes(request.user.role)) {
    throw httpError(403, "当前账号没有管理员权限");
  }
}

function assertServerFileManagerAvailable() {
  if (RESCUE_MODE) throw httpError(404, "备用窗口不提供服务器文件管理器");
}

function recordServerFileOperation(request, action, targetPath) {
  const normalizedPath = normalizeServerFilePath(targetPath);
  return recordOpsEvent({
    type: `server_file.${action}`,
    severity: action === "delete" ? "warning" : "info",
    source: "server-file-manager",
    title: "服务器文件管理器操作",
    detail: `操作账号：${request.user.username} · 操作：${action} · 路径：${normalizedPath}`,
  }).catch(() => {});
}

function publicMapOpsProject(projectPath, runtime) {
  const resolved = path.resolve(projectPath);
  return Object.freeze({
    id: crypto.createHash("sha256").update(resolved).digest("hex").slice(0, 16),
    name: path.basename(resolved),
    isDefault: resolved === path.resolve(runtime.defaultProject),
  });
}

function requireWindowsHost() {
  if (RESCUE_MODE || !windowsDeviceStore || !windowsDeviceBroker || !windowsCreatorJobStore) {
    throw httpError(404, "Windows Host 不可用");
  }
}

function requirePersistentSshStore(runtime) {
  if (RESCUE_MODE || !runtime?.persistentSshServers) {
    throw httpError(404, "持久 SSH 服务器不可用");
  }
  return runtime.persistentSshServers;
}

async function windowsCompanionDownload() {
  requireWindowsHost();
  if (!windowsCompanionPackagePromise) {
    windowsCompanionPackagePromise = buildWindowsCompanionPackage(
      path.join(APP_DIR, "companion", "windows-host"),
    ).catch((error) => {
      windowsCompanionPackagePromise = null;
      throw error;
    });
  }
  return windowsCompanionPackagePromise;
}

function requireWindowsPlugin(request, pluginId) {
  requireWindowsHost();
  const id = String(pluginId || "");
  if (!WINDOWS_DEVICE_PLUGIN_IDS.has(id)) throw httpError(400, "Windows Host 插件不正确");
  if (!pluginStore.isAuthorized(id, request.user)) {
    throw httpError(403, "此 Windows Host 插件未安装、未启用或未向当前用户授权");
  }
  return id;
}

async function enforceWindowsPluginAuthorization(user) {
  if (!windowsDeviceBroker || !user) return;
  for (const pluginId of WINDOWS_DEVICE_PLUGIN_IDS) {
    if (!pluginStore.isAuthorized(pluginId, user)) {
      await windowsDeviceBroker.revokePlugin(user.id, pluginId);
    }
  }
}

function normalizeRequestedWindowsPlugins(value) {
  const pluginIds = Array.isArray(value) ? [...new Set(value.map(String))] : [];
  if (!pluginIds.length || pluginIds.some((pluginId) => !WINDOWS_DEVICE_PLUGIN_IDS.has(pluginId))) {
    throw httpError(400, "必须选择已支持的 Windows Host 插件");
  }
  return pluginIds.sort();
}

function browserSessionIdentity(request) {
  return request.authSession?.id || `legacy:${request.user.id}`;
}

function mapSessionIdentity(request, editorInstanceId) {
  return {
    userId: request.user.id,
    browserSessionId: browserSessionIdentity(request),
    editorInstanceId,
  };
}

function managedMapAiIdentity(request) {
  return {
    userId: String(request?.user?.id || ""),
    // A stable user-scoped identity is intentional for headless managed work;
    // browser-session cleanup must not revoke a task that was explicitly
    // authorized to continue after the editor closes.
    browserSessionId: `managed:${String(request?.user?.id || "")}`,
  };
}

function mapProjectSessionIdentity(request) {
  return {
    userId: request.user.id,
    browserSessionId: browserSessionIdentity(request),
  };
}

async function releaseMapBrowserSessionResources({ userId, browserSessionId }) {
  const identity = { userId: String(userId || ""), browserSessionId: String(browserSessionId || "") };
  const asynchronous = await Promise.allSettled([
    mapAiManagedAuthorizations?.revokeForBrowserSession({ ...identity, reason: "浏览器会话已结束" }),
    mapAiManagedTasks?.cancelForBrowserSession(identity),
    mapImageJobs?.cancelForBrowserSession(identity),
    mapRenderJobs?.cancelForBrowserSession(identity),
    mapSaveSessions?.closeForBrowserSession(identity),
    mapAiResourceUploads?.deleteForBrowserSession(identity),
  ]);
  for (const result of asynchronous) {
    if (result.status === "rejected") {
      console.error(`Unable to release map browser-session resource: ${result.reason?.message || result.reason}`);
    }
  }
  const inputCleanup = await Promise.resolve(mapImageInputs?.deleteForBrowserSession(identity)).catch((error) => {
    console.error(`Unable to release map browser-session image inputs: ${error.message}`);
    return null;
  });
  const closed = {
    maps: mapFileSessions?.closeForBrowserSession(identity).closed || 0,
    worlds: worldFileSessions?.closeForBrowserSession(identity).closed || 0,
    tilesets: tilesetFileSessions?.closeForBrowserSession(identity).closed || 0,
    projects: mapProjectSessions?.closeForBrowserSession(identity).closed || 0,
  };
  return Object.freeze({ closed: Object.freeze(closed), inputCleanup, asynchronous });
}

function scheduleMapBrowserSessionResourceRelease(identity) {
  const userId = String(identity?.userId || "");
  const browserSessionId = String(identity?.browserSessionId || "");
  const key = `${userId}\0${browserSessionId}`;
  const existing = mapBrowserSessionReleaseTasks.get(key);
  if (existing) return existing;
  const task = releaseMapBrowserSessionResources({ userId, browserSessionId }).finally(() => {
    if (mapBrowserSessionReleaseTasks.get(key) === task) mapBrowserSessionReleaseTasks.delete(key);
  });
  mapBrowserSessionReleaseTasks.set(key, task);
  return task;
}

async function releaseMapUserResources({ userId }) {
  const identity = { userId: String(userId || "") };
  const asynchronous = await Promise.allSettled([
    mapAiManagedAuthorizations?.revokeForUser({ userId: identity.userId, reason: "用户访问已撤销" }),
    mapAiManagedTasks?.cancelForUser(identity),
    mapImageJobs?.cancelForUser(identity),
    mapRenderJobs?.cancelForUser(identity),
    mapSaveSessions?.closeForUser(identity),
    mapAiResourceUploads?.deleteForUser(identity),
    mapAiResourceCandidates?.deleteForUser(identity),
  ]);
  for (const result of asynchronous) {
    if (result.status === "rejected") {
      console.error(`Unable to release map user resource: ${result.reason?.message || result.reason}`);
    }
  }
  const inputCleanup = await Promise.resolve(mapImageInputs?.deleteForUser(identity)).catch((error) => {
    console.error(`Unable to release map user image inputs: ${error.message}`);
    return null;
  });
  const closed = {
    maps: mapFileSessions?.closeForUser(identity).closed || 0,
    worlds: worldFileSessions?.closeForUser(identity).closed || 0,
    tilesets: tilesetFileSessions?.closeForUser(identity).closed || 0,
    projects: mapProjectSessions?.closeForUser(identity).closed || 0,
  };
  return Object.freeze({ closed: Object.freeze(closed), inputCleanup, asynchronous });
}

function scheduleMapUserResourceRelease(identity) {
  const userId = String(identity?.userId || "");
  const existing = mapUserReleaseTasks.get(userId);
  if (existing) return existing;
  const task = releaseMapUserResources({ userId }).finally(() => {
    if (mapUserReleaseTasks.get(userId) === task) mapUserReleaseTasks.delete(userId);
  });
  mapUserReleaseTasks.set(userId, task);
  return task;
}

async function mapProjectContextForRequest(request, runtime, sessionId = request.params.sessionId) {
  const context = mapProjectSessions.context({
    sessionId,
    identity: mapProjectSessionIdentity(request),
  });
  const resolved = await resolveResourceTarget(context.projectPath, null, runtime);
  if (path.resolve(resolved.projectPath) !== path.resolve(context.projectPath)) {
    throw httpError(403, "地图项目会话不再属于当前账号");
  }
  return context;
}

function normalizeMapProjectRelativePath(value, { extension = null, label = "地图项目资源" } = {}) {
  if (
    typeof value !== "string"
    || !value
    || value.includes("\0")
    || value.includes("\\")
    || path.posix.isAbsolute(value)
    || /^[a-z][a-z0-9+.-]*:/iu.test(value)
  ) throw httpError(400, `${label}必须使用工程相对路径`);
  const segments = value.split("/");
  if (segments.some((segment) => !segment || segment === "." || segment === ".." || segment.startsWith("."))) {
    throw httpError(400, `${label}路径无效`);
  }
  const relativePath = segments.join("/");
  if (extension && path.posix.extname(relativePath).toLowerCase() !== extension) {
    throw httpError(400, `${label}必须使用 ${extension} 扩展名`);
  }
  return relativePath;
}

function normalizeMapAiThreadId(value) {
  const threadId = normalizeCodexLifecycleThreadId(value, "地图 AI 对话 ID");
  if (isImportedThreadId(threadId)) {
    throw httpError(409, "迁移快照不能授权地图 AI，请先继续或分支为原生对话");
  }
  return threadId;
}

function normalizeMapAiEditorStateId(value) {
  const stateId = value === undefined || value === null || value === "" ? 0 : Number(value);
  if (!Number.isSafeInteger(stateId) || stateId < 0) {
    throw httpError(400, "地图编辑状态标识无效");
  }
  return stateId;
}

function publicMapAiLease(lease) {
  return {
    // The bearer is returned only at the explicit grant boundary so the map
    // editor can keep it in sessionStorage. It is never placed in a URL,
    // proposal body, tool argument, or conversation transcript.
    leaseId: String(lease?.leaseId || ""),
    threadId: String(lease?.threadId || ""),
    mapSessionId: String(lease?.mapSessionId || ""),
    mapVersion: String(lease?.mapVersion || ""),
    editorInstanceId: String(lease?.editorInstanceId || ""),
    editorStateId: normalizeMapAiEditorStateId(lease?.editorStateId),
    allowedOps: Array.isArray(lease?.allowedOps) ? [...lease.allowedOps] : [],
    grantedAt: Number(lease?.grantedAt) || null,
    expiresAt: Number(lease?.expiresAt) || null,
  };
}

function assertMapAiLeaseIdentity(leaseContext, {
  identity,
  mapSessionId,
  context,
  editorInstanceId,
  editorStateId,
} = {}) {
  const matches = leaseContext?.userId === identity?.userId
    && leaseContext?.browserSessionId === identity?.browserSessionId
    && leaseContext?.mapSessionId === String(mapSessionId || "")
    && path.resolve(String(leaseContext?.projectPath || ".")) === path.resolve(String(context?.projectPath || "."))
    && leaseContext?.mapVersion === context?.version
    && leaseContext?.editorInstanceId === editorInstanceId
    && leaseContext?.editorStateId === editorStateId;
  if (!matches) {
    const error = httpError(409, "地图 AI 临时授权不属于当前对话、地图或编辑器窗口");
    error.code = "MAP_AI_LEASE_CONTEXT_MISMATCH";
    throw error;
  }
}

async function assertMapAiThreadProject(runtime, threadId, projectPath, { signal = null } = {}) {
  throwIfMapAiOperationAborted(signal);
  if (!runtime?.bridge?.ready) throw httpError(503, "Codex 服务尚未就绪，暂时无法绑定地图 AI 对话");
  const imported = runtime.threadImportStore?.get(threadId);
  if (imported) throw httpError(409, "迁移快照不能授权地图 AI，请先继续或分支为原生对话");
  const nativeThreadId = runtime.nativeThreadIdForPublic(threadId);
  const read = await runtime.bridge.request(
    "thread/read",
    { threadId: nativeThreadId, includeTurns: false },
    { timeoutMs: 15_000 },
  );
  throwIfMapAiOperationAborted(signal);
  const returnedId = read?.thread?.id;
  const threadCwd = typeof read?.thread?.cwd === "string" ? path.resolve(read.thread.cwd) : null;
  if (returnedId !== nativeThreadId || !threadCwd || threadCwd !== path.resolve(projectPath)) {
    throw httpError(409, "地图 AI 对话不属于当前工程，或对话已经不存在");
  }
  await assertSafeProjectDirectory(path.resolve(projectPath), runtime);
  throwIfMapAiOperationAborted(signal);
  return { threadId, nativeThreadId };
}

async function mapAiLeaseRequestContext(request, {
  runtime = null,
  operation,
  requireWritable = false,
} = {}) {
  if (!mapAiAccess || !mapFileSessions) throw httpError(404, "地图 AI 工具在救援窗口中不可用");
  const activeRuntime = runtime || await runtimeForRequest(request);
  const editorInstanceId = normalizeMapEditorInstanceId(
    request.get("x-codex-desktop-editor-instance"),
  );
  const identity = mapSessionIdentity(request, editorInstanceId);
  const mapSessionId = request.params.sessionId;
  const context = mapFileSessions.context({ sessionId: mapSessionId, identity });
  const resolved = await resolveResourceTarget(context.projectPath, context.targetPath, activeRuntime);
  if (
    path.resolve(resolved.projectPath) !== path.resolve(context.projectPath)
    || path.resolve(resolved.targetPath) !== path.resolve(context.targetPath)
  ) throw httpError(403, "地图 AI 上下文不再属于当前工程");
  if (requireWritable) await assertWritableMapContext(context, activeRuntime);
  const inspected = await inspectMapFile(context.targetPath, { maxBytes: MAP_SAVE_MAX_BYTES });
  if (inspected.version !== context.version) {
    const error = httpError(409, "地图文件已经变化，请重新打开编辑器");
    error.code = "MAP_AI_MAP_VERSION_CONFLICT";
    throw error;
  }
  const leaseId = request.get("x-codex-desktop-map-ai-lease");
  const leaseContext = mapAiAccess.contextForLease({ leaseId });
  const editorStateHeader = request.get("x-codex-desktop-editor-state");
  const editorStateId = editorStateHeader === undefined || editorStateHeader === ""
    ? leaseContext.editorStateId
    : normalizeMapAiEditorStateId(editorStateHeader);
  assertMapAiLeaseIdentity(leaseContext, {
    identity,
    mapSessionId,
    context,
    editorInstanceId,
    editorStateId,
  });
  await assertMapAiThreadProject(activeRuntime, leaseContext.threadId, context.projectPath);
  const lease = mapAiAccess.requireLease({
    leaseId,
    operation,
    userId: identity.userId,
    browserSessionId: identity.browserSessionId,
    threadId: leaseContext.threadId,
    projectPath: context.projectPath,
    mapSessionId,
    mapVersion: context.version,
    editorInstanceId,
    editorStateId,
  });
  const collaborationPolicy = mapCollaborationPolicies?.contract({
    userId: identity.userId,
    projectPath: context.projectPath,
    mapPath: context.relativePath,
  }) || null;
  const proposalContext = {
    userId: identity.userId,
    browserSessionId: identity.browserSessionId,
    threadId: leaseContext.threadId,
    projectPath: context.projectPath,
    mapSessionId,
    mapVersion: context.version,
    editorInstanceId,
    mapPath: context.relativePath,
    editorStateId,
    collaborationPolicyRevision: Number(collaborationPolicy?.revision || 0),
  };
  return {
    runtime: activeRuntime,
    identity,
    context,
    editorInstanceId,
    editorStateId,
    leaseId,
    lease,
    leaseContext,
    collaborationPolicy,
    proposalContext,
  };
}

function publicMapAiContext(context, lease) {
  return {
    mapSessionId: String(lease?.mapSessionId || ""),
    mapPath: String(context?.relativePath || ""),
    mapVersion: String(context?.version || ""),
    writable: context?.writable === true,
    editorInstanceId: String(lease?.editorInstanceId || ""),
    editorStateId: normalizeMapAiEditorStateId(lease?.editorStateId),
    leaseExpiresAt: Number(lease?.expiresAt) || null,
  };
}

/**
 * Execute the headless managed-map tool contract. This path never trusts a
 * project path supplied by MCP: the opaque authorization resolves the exact
 * project/map scope, then the live file hash and Tiled document are checked
 * before any result or task is returned.
 */
async function executeManagedMapAiOperation(runtime, input, { signal = null } = {}) {
  if (RESCUE_MODE || !mapAiManagedAuthorizations) {
    throw httpError(404, "地图 AI 托管在救援窗口中不可用");
  }
  const operation = String(input?.action || "");
  const contract = mapAiManagedAuthorizations.toolContract({
    authorizationId: input?.authorizationId,
    userId: runtime?.user?.id || input?.userId,
  });
  if (!contract.allowedOps.includes(operation)) {
    const error = httpError(403, "当前托管授权不允许此地图 AI 操作");
    error.code = "MAP_AI_MANAGED_OPERATION_NOT_ALLOWED";
    throw error;
  }
  if (contract.scope.projectWide === true) {
    return executeManagedProjectWideOperation(runtime, input, contract, { signal });
  }
  const mapPath = normalizeMapProjectRelativePath(input?.mapPath, { extension: ".tmj", label: "托管地图" });
  const scopeMapPath = contract.scope.mapPaths.length === 1 ? contract.scope.mapPaths[0] : null;
  if ((scopeMapPath ? scopeMapPath !== mapPath : !contract.scope.mapPaths.includes(mapPath)) || input?.threadId !== contract.scope.threadId) {
    const error = httpError(403, "托管工具范围与授权不一致");
    error.code = "MAP_AI_MANAGED_SCOPE_MISMATCH";
    throw error;
  }
  const projectFingerprint = crypto.createHash("sha256").update(contract.scope.projectPath).digest("hex");
  if (String(input?.projectFingerprint || "").toLowerCase() !== projectFingerprint) {
    const error = httpError(403, "工程指纹与托管授权不一致");
    error.code = "MAP_AI_MANAGED_SCOPE_MISMATCH";
    throw error;
  }
  const expectedVersion = String(input?.mapVersion || "").toLowerCase();
  if (expectedVersion !== contract.scope.mapVersions[mapPath]) {
    const error = httpError(409, "地图版本与托管授权不一致，请重新读取并授权");
    error.code = "MAP_AI_MANAGED_VERSION_CONFLICT";
    throw error;
  }
  const targetPath = path.join(contract.scope.projectPath, ...mapPath.split("/"));
  const resolved = await resolveResourceTarget(contract.scope.projectPath, targetPath, runtime);
  if (path.resolve(resolved.projectPath) !== path.resolve(contract.scope.projectPath)
    || path.resolve(resolved.targetPath) !== path.resolve(targetPath)) {
    const error = httpError(403, "托管地图不再属于授权工程");
    error.code = "MAP_AI_MANAGED_SCOPE_MISMATCH";
    throw error;
  }
  const inspected = await inspectMapFile(targetPath, { maxBytes: MAP_SAVE_MAX_BYTES, signal });
  if (inspected.version !== expectedVersion) {
    const error = httpError(409, "地图文件已经变化，请重新读取并授权");
    error.code = "MAP_AI_MANAGED_VERSION_CONFLICT";
    throw error;
  }
  if (["propose_tiled_patch", "apply_tiled_patch", "restore_map_revision"].includes(operation)) {
    await assertManagedCollaborationPolicyCurrent({
      contract,
      projectPath: contract.scope.projectPath,
      mapPath,
      requireWrite: !["propose_tiled_patch", "propose_tiled_resource_patch"].includes(operation),
    });
  }
  if (["propose_tiled_resource_patch", "apply_tiled_resource_patch"].includes(operation)) {
    await assertManagedCollaborationPolicyCurrent({
      contract,
      projectPath: contract.scope.projectPath,
      mapPath,
      requireWrite: operation === "apply_tiled_resource_patch",
    });
    if (!contract.allowedOps.includes(operation)) throw httpError(403, "当前托管授权不允许资源补丁操作");
    const resourcePatch = normalizeManagedResourcePatch(input.patch);
    const targetFiles = new Set(contract.scope.targetFiles || contract.scope.mapPaths);
    for (const file of resourcePatch.files) {
      if (!targetFiles.has(file.path)) throw httpError(403, `资源 ${file.path} 不在托管授权范围`);
      const expected = contract.scope.targetFileVersions?.[file.path];
      if (expected !== file.baseVersion) throw httpError(409, `资源 ${file.path} 基础版本与授权不一致，请重新读取`);
      // The map hash checked above is not sufficient for a multi-resource
      // transaction.  Re-check every target at the tool boundary so a direct
      // MCP apply cannot queue a task against a resource that was created,
      // replaced, or deleted after authorization.  Parent directories are
      // checked separately because a null base version is an intentional new
      // file, not permission to follow a symlink.
      await assertManagedResourceParent(contract.scope.projectPath, file.path);
      const currentResource = await inspectManagedResourceVersion(path.join(contract.scope.projectPath, ...file.path.split("/")));
      if ((currentResource?.version || null) !== file.baseVersion) {
        const error = httpError(409, `资源 ${file.path} 版本已变化，请重新读取并授权`);
        error.code = "MAP_AI_MANAGED_VERSION_CONFLICT";
        throw error;
      }
    }
    // A proposal is still a server-owned candidate contract.  Resolve every
    // opaque candidate now so a missing, expired, scope-mismatched, or
    // tampered candidate cannot be represented as an apparently valid preview
    // and only fail much later when an apply task is already queued.
    if (!mapAiResourceCandidates) throw httpError(503, "地图资源候选服务当前不可用");
    const candidateLeases = [];
    try {
      for (const file of resourcePatch.files) {
        const resolvedCandidate = await mapAiResourceCandidates.resolve({
          candidateId: file.candidateId,
          userId: runtime.user.id,
          projectPath: contract.scope.projectPath,
          threadId: contract.scope.threadId,
          relativePath: file.path,
          baseVersion: file.baseVersion,
        });
        if (file.size !== undefined && file.size !== resolvedCandidate.metadata.size) {
          throw httpError(409, `资源 ${file.path} 候选大小与声明不一致`);
        }
        if (file.sha256 !== undefined && file.sha256 !== resolvedCandidate.metadata.sha256) {
          throw httpError(409, `资源 ${file.path} 候选哈希与声明不一致`);
        }
        candidateLeases.push(resolvedCandidate);
      }
    } finally {
      await Promise.all(candidateLeases.map((lease) => lease.release?.().catch(() => {})));
    }
    if (operation === "propose_tiled_resource_patch") {
      return { operation, mapPath, mapVersion: inspected.version, summary: resourcePatch.summary, preview: { kind: "resource-transaction", fileCount: resourcePatch.files.length, files: resourcePatch.files.map(({ path: relativePath, baseVersion, candidateId }) => ({ path: relativePath, baseVersion, candidateId: String(candidateId).slice(0, 8) + "…" })) }, risk: { ruleVersion: "map-risk-v1", riskLevel: "high", reasonCodes: ["multiple_files", "resource_dependency_transaction"], hardBlocks: [] }, requiresTask: true };
    }
    if (!mapAiManagedTasks) throw httpError(503, "地图 AI 托管任务当前不可用");
    const identity = { userId: runtime.user.id, browserSessionId: contract.identity.browserSessionId };
    const result = await mapAiManagedTasks.create({
      identity,
      authority: {
        authorityMode: "managed", managedAuthorizationId: contract.id, threadId: contract.scope.threadId,
        projectPath: contract.scope.projectPath, mapSessionId: null, mapPath,
        baseVersion: contract.scope.mapVersions[mapPath], mapPaths: contract.scope.mapPaths, mapVersions: contract.scope.mapVersions,
        targetFiles: contract.scope.targetFiles, targetFileVersions: contract.scope.targetFileVersions,
        allowedOps: contract.allowedOps, protectedTargets: contract.protectedTargets, collaborationPolicy: contract.collaborationPolicy, expiresAt: contract.expiresAt,
      },
      approvalSnapshot: contract.approvalSnapshot, settingsSnapshot: {}, clientOperationId: input.clientOperationId,
      request: resourcePatch, planSummary: { operationCount: resourcePatch.files.length, tileCellCount: 0, ordinaryObjectCount: 0 },
    });
    if (result.created && mapAiManagedTaskExecutor) scheduleMapAiManagedTaskExecution({ taskId: result.task.id, identity });
    return { operation, task: result.task, created: result.created };
  }
  // Runtime compatibility is a separate contract from Tiled syntax. Keep it
  // in every managed response so AI cannot infer game support from the
  // browser preview alone.
  const runtimeCapabilities = await inspectMapRuntimeCapabilities({
    projectPath: contract.scope.projectPath,
    mapPath,
  });
  if (operation === "inspect_project") {
    const parsed = await readManagedTiledDocument(targetPath, mapPath, signal);
    const references = publicManagedReferences(parsed.document, mapPath);
    return {
      operation,
      projectFingerprint,
      mapPath,
      mapVersion: inspected.version,
      resources: [{ path: mapPath, kind: "map" }, ...references.map((entry) => ({ path: entry.path, kind: entry.kind }))],
      resourceCount: references.length + 1,
      runtimeCapabilities,
    };
  }
  if (operation === "get_map_context") {
    const parsed = await readManagedTiledDocument(targetPath, mapPath, signal);
    return { ...managedMapContext(parsed.document, mapPath, inspected.version), runtimeCapabilities };
  }
  if (operation === "read_map_region") {
    const parsed = await readManagedTiledDocument(targetPath, mapPath, signal);
    return managedMapRegion(parsed.document, input.region, input.layerIds);
  }
  if (operation === "validate_map") {
    try {
      const parsed = await readManagedTiledDocument(targetPath, mapPath, signal);
      return {
        operation,
        valid: true,
        mapPath,
        mapVersion: inspected.version,
        diagnostics: boundedManagedDiagnostics(parsed.diagnostics),
        references: publicManagedReferences(parsed.document, mapPath),
        runtimeCapabilities,
      };
    } catch (error) {
      return {
        operation,
        valid: false,
        mapPath,
        mapVersion: inspected.version,
        diagnostics: boundedManagedDiagnostics(error?.diagnostics || [{ severity: "error", code: error?.code || "invalid-map", message: error?.message || "Tiled 地图校验失败" }]),
        runtimeCapabilities,
      };
    }
  }
  if (operation === "request_map_preview") {
    if (!mapRenderJobs) throw httpError(503, "地图 Render Worker 当前不可用");
    const identity = {
      userId: runtime.user.id,
      browserSessionId: `managed:${contract.id}`,
      editorInstanceId: `managed:${contract.id}`,
    };
    const result = await mapRenderJobs.begin({
      identity,
      mapContext: {
        mapSessionId: `managed-preview:${contract.id}`,
        projectPath: contract.scope.projectPath,
        targetPath,
        relativePath: mapPath,
        version: inspected.version,
        writable: true,
      },
      request: {
        kind: "map-screenshot",
        outputRoot: "map-previews",
        clientOperationId: `managed-preview-${contract.id}-${inspected.version}`,
        spec: {},
      },
    });
    return { operation, job: result.job, created: result.created };
  }
  if (operation === "list_map_revisions") {
    if (!mapRevisions) throw httpError(503, "地图修订历史当前不可用");
    return { operation, mapPath, mapVersion: inspected.version, revisions: mapRevisions.list({ projectPath: contract.scope.projectPath, relativePath: mapPath, limit: input.limit }) };
  }
  if (operation === "restore_map_revision") {
    if (!mapRevisions || !mapAiManagedTasks) throw httpError(503, "地图修订恢复当前不可用");
    const expectedCurrentVersion = String(input.expectedCurrentVersion || "").toLowerCase();
    if (expectedCurrentVersion !== inspected.version) {
      const error = httpError(409, "恢复前地图版本已变化，请重新读取");
      error.code = "MAP_AI_MANAGED_VERSION_CONFLICT";
      throw error;
    }
    const revision = mapRevisions.get({ revisionId: input.revisionId, projectPath: contract.scope.projectPath, relativePath: mapPath });
    if (revision.version === expectedCurrentVersion) throw httpError(409, "目标修订已经是当前地图版本");
    if (!contract.allowedOps.includes("apply_tiled_patch") && !contract.allowedOps.includes("restore_map_revision")) throw httpError(403, "当前托管授权不允许恢复地图修订");
    const identity = { userId: runtime.user.id, browserSessionId: contract.identity.browserSessionId };
    const result = await mapAiManagedTasks.create({
      identity,
      authority: { authorityMode: "managed", managedAuthorizationId: contract.id, threadId: contract.scope.threadId, projectPath: contract.scope.projectPath, mapSessionId: null, mapPath, baseVersion: inspected.version, mapPaths: [mapPath], mapVersions: { [mapPath]: inspected.version }, targetFiles: [mapPath], targetFileVersions: { [mapPath]: inspected.version }, allowedOps: contract.allowedOps, protectedTargets: contract.protectedTargets, collaborationPolicy: contract.collaborationPolicy, expiresAt: contract.expiresAt },
      approvalSnapshot: contract.approvalSnapshot,
      settingsSnapshot: { restoreRevisionId: revision.id, restoreRevisionVersion: revision.version },
      clientOperationId: input.clientOperationId || `restore-${revision.id}-${expectedCurrentVersion}`,
      request: { format: "wfl-map-revision-restore", version: 1, revisionId: revision.id, expectedCurrentVersion, targetVersion: revision.version },
      planSummary: { operationCount: 1, tileCellCount: 0, ordinaryObjectCount: 0 },
    });
    if (result.created && mapAiManagedTaskExecutor) scheduleMapAiManagedTaskExecution({ taskId: result.task.id, identity });
    return { operation, task: result.task, created: result.created, revision };
  }
  if (operation === "propose_tiled_patch") {
    if (isManagedMultiMapPatch(input.patch)) {
      return await previewManagedMultiMapPatch({ runtime, contract, input, signal });
    }
    const parsed = await readManagedTiledDocument(targetPath, mapPath, signal);
    const patch = normalizeManagedPatch(input.patch, mapPath, inspected.version);
    assertMapPatchRuntimeCompatible(parsed.document, patch, runtimeCapabilities);
    if (contract.collaborationPolicy) {
      const violations = findCollaborationOperationViolations(parsed.document, patch, contract.collaborationPolicy, mapPath);
      if (violations.length) {
        const error = httpError(403, violations[0].message);
        error.code = violations[0].code || "MAP_COLLABORATION_HUMAN_OWNED";
        throw error;
      }
    }
    const preview = {
      ...previewTiledAiPatch(parsed.document, patch),
      ordinaryObjectCount: patch.operations.filter((entry) => ["add-object", "update-object", "remove-object"].includes(entry.op)).length,
    };
    const risk = assessMapAiTask({
      approvalPolicy: contract.approvalSnapshot.policy,
      operations: patch.operations,
      targetMapPaths: [mapPath],
      targetFiles: [mapPath],
      tileCellCount: preview.tileCellCount,
      ordinaryObjectCount: preview.ordinaryObjectCount,
      mapCount: 1,
      previewOnly: true,
    });
    return { operation, mapPath, mapVersion: inspected.version, summary: patch.summary, preview: boundedManagedPreview(preview), risk: managedRiskReceipt(risk), requiresTask: true };
  }
  if (operation === "apply_tiled_patch") {
    if (!mapAiManagedTasks) throw httpError(503, "地图 AI 托管任务当前不可用");
    if (isManagedMultiMapPatch(input.patch)) {
      return await createManagedMultiMapTask({ runtime, contract, input, signal });
    }
    const patch = normalizeManagedPatch(input.patch, mapPath, inspected.version);
    const parsed = await readManagedTiledDocument(targetPath, mapPath, signal);
    assertMapPatchRuntimeCompatible(parsed.document, patch, runtimeCapabilities);
    if (contract.collaborationPolicy) {
      const violations = findCollaborationOperationViolations(parsed.document, patch, contract.collaborationPolicy, mapPath);
      if (violations.length) {
        const error = httpError(403, violations[0].message);
        error.code = violations[0].code || "MAP_COLLABORATION_HUMAN_OWNED";
        throw error;
      }
    }
    const preview = {
      ...previewTiledAiPatch(parsed.document, patch),
      ordinaryObjectCount: patch.operations.filter((entry) => ["add-object", "update-object", "remove-object"].includes(entry.op)).length,
    };
    const identity = { userId: runtime.user.id, browserSessionId: contract.identity.browserSessionId };
    const result = await mapAiManagedTasks.create({
      identity,
      authority: {
        authorityMode: "managed",
        managedAuthorizationId: contract.id,
        threadId: contract.scope.threadId,
        projectPath: contract.scope.projectPath,
        mapSessionId: null,
        mapPath,
        baseVersion: inspected.version,
        mapPaths: [mapPath],
        mapVersions: { [mapPath]: inspected.version },
        targetFiles: [mapPath],
        targetFileVersions: { [mapPath]: inspected.version },
        allowedOps: contract.allowedOps,
        protectedTargets: contract.protectedTargets,
        collaborationPolicy: contract.collaborationPolicy,
        expiresAt: contract.expiresAt,
      },
      approvalSnapshot: contract.approvalSnapshot,
      settingsSnapshot: {},
      clientOperationId: input.clientOperationId,
      request: patch,
      planSummary: {
        operationCount: preview.operationCount,
        tileCellCount: preview.tileCellCount,
        ordinaryObjectCount: preview.ordinaryObjectCount,
      },
    });
    if (result.created && mapAiManagedTaskExecutor) scheduleMapAiManagedTaskExecution({ taskId: result.task.id, identity });
    return { operation, task: result.task, created: result.created };
  }
  throw httpError(400, "托管地图 AI 操作无效");
}

async function executeManagedProjectWideOperation(runtime, input, contract, { signal = null } = {}) {
  throwIfMapAiOperationAborted(signal);
  const projectPath = contract.scope.projectPath;
  await assertSafeProjectDirectory(projectPath, runtime);
  const projectFingerprint = crypto.createHash("sha256").update(projectPath).digest("hex");
  if (input?.projectFingerprint !== undefined
    && String(input.projectFingerprint || "").toLowerCase() !== projectFingerprint) {
    const error = httpError(403, "工程指纹与托管授权不一致");
    error.code = "MAP_AI_MANAGED_SCOPE_MISMATCH";
    throw error;
  }
  // Keep the public MCP receipt below the adapter's bounded array limit while
  // retaining a slightly larger internal catalog for a transaction. A target
  // near the scan boundary must still be writable even when it is omitted
  // from the human-readable project summary.
  const catalog = await listMapAiProjectResources({ projectPath, limit: 4_096 });
  const resources = catalog.resources.map((entry) => ({ ...entry }));
  const publicResources = resources.slice(0, 3_500);
  const publicTruncated = catalog.truncated || publicResources.length < resources.length;
  if (input?.action === "inspect_project") {
    return {
      operation: "inspect_project",
      scope: "project",
      projectFingerprint,
      resources: publicResources,
      resourceCount: resources.length,
      truncated: publicTruncated,
    };
  }
  if (input?.action === "get_project_context") {
    const byKind = Object.fromEntries([...new Set(publicResources.map((entry) => entry.kind))].sort().map((kind) => [
      kind,
      publicResources.filter((entry) => entry.kind === kind).map((entry) => entry.path),
    ]));
    return {
      operation: "get_project_context",
      scope: "project",
      projectFingerprint,
      resources: publicResources,
      resourceCount: resources.length,
      byKind,
      truncated: publicTruncated,
    };
  }
  if (input?.action === "get_map_context" && !input?.mapPath) {
    return {
      operation: "get_map_context",
      scope: "project",
      projectFingerprint,
      resources: publicResources,
      resourceCount: resources.length,
      truncated: publicTruncated,
    };
  }
  if (input?.action === "read_project_resource") {
    const resourcePath = normalizeMapProjectRelativePath(input?.resourcePath, { label: "托管工程资源" });
    if (!resources.some((entry) => entry.path === resourcePath)) throw httpError(404, "托管工程资源不存在或不在工程清单内");
    const requestedMaxBytes = input?.maxBytes === undefined ? 512 * 1024 : Number(input.maxBytes);
    if (!Number.isSafeInteger(requestedMaxBytes) || requestedMaxBytes < 1 || requestedMaxBytes > 512 * 1024) {
      throw httpError(400, "托管工程资源读取上限无效");
    }
    const resource = await readMapAiProjectResource({ projectPath, relativePath: resourcePath, maxBytes: requestedMaxBytes });
    return {
      operation: "read_project_resource",
      scope: "project",
      projectFingerprint,
      resource: {
        path: resource.path,
        name: resource.name,
        kind: resource.kind,
        size: resource.size,
        modifiedAt: resource.modifiedAt,
        version: resource.version,
      },
      content: resource.content,
    };
  }
  if (["propose_project_patch", "apply_project_patch", "propose_tiled_resource_patch", "apply_tiled_resource_patch"].includes(input?.action)) {
    return executeManagedProjectResourceOperation(runtime, input, contract, resources, { signal });
  }

  const mapPath = normalizeMapProjectRelativePath(
    input?.mapPath || resources.find((entry) => entry.kind === "map")?.path,
    { extension: ".tmj", label: "托管地图" },
  );
  const targetPath = path.join(projectPath, ...mapPath.split("/"));
  const resolved = await resolveResourceTarget(projectPath, targetPath, runtime);
  if (path.resolve(resolved.projectPath) !== path.resolve(projectPath)
    || path.resolve(resolved.targetPath) !== path.resolve(targetPath)) {
    throw httpError(403, "托管地图不再属于授权工程");
  }
  const inspected = await inspectMapFile(targetPath, { maxBytes: MAP_SAVE_MAX_BYTES, signal });
  if (input?.mapVersion !== undefined && String(input.mapVersion).toLowerCase() !== inspected.version) {
    const error = httpError(409, "地图版本已变化，请重新读取工程资源");
    error.code = "MAP_AI_MANAGED_VERSION_CONFLICT";
    throw error;
  }
  const runtimeCapabilities = await inspectMapRuntimeCapabilities({ projectPath, mapPath });
  if (input?.action === "get_map_context") {
    const parsed = await readManagedTiledDocument(targetPath, mapPath, signal);
    return { ...managedMapContext(parsed.document, mapPath, inspected.version), scope: "project", projectFingerprint, runtimeCapabilities };
  }
  if (input?.action === "read_map_region") {
    const parsed = await readManagedTiledDocument(targetPath, mapPath, signal);
    return managedMapRegion(parsed.document, input.region, input.layerIds);
  }
  if (input?.action === "validate_map") {
    try {
      const parsed = await readManagedTiledDocument(targetPath, mapPath, signal);
      return {
        operation: "validate_map", scope: "project", valid: true, mapPath, mapVersion: inspected.version,
        diagnostics: boundedManagedDiagnostics(parsed.diagnostics), references: publicManagedReferences(parsed.document, mapPath),
        runtimeCapabilities,
      };
    } catch (error) {
      return {
        operation: "validate_map", scope: "project", valid: false, mapPath, mapVersion: inspected.version,
        diagnostics: boundedManagedDiagnostics(error?.diagnostics || [{ severity: "error", code: error?.code || "invalid-map", message: error?.message || "Tiled 地图校验失败" }]),
        runtimeCapabilities,
      };
    }
  }
  if (input?.action === "request_map_preview") {
    if (!mapRenderJobs) throw httpError(503, "地图 Render Worker 当前不可用");
    const identity = { userId: runtime.user.id, browserSessionId: `managed:${runtime.user.id}`, editorInstanceId: `managed:${contract.id}` };
    const result = await mapRenderJobs.begin({
      identity,
      mapContext: { mapSessionId: `managed-preview:${contract.id}`, projectPath, targetPath, relativePath: mapPath, version: inspected.version, writable: true },
      request: { kind: "map-screenshot", outputRoot: "map-previews", clientOperationId: `managed-preview-${contract.id}-${inspected.version}`, spec: {} },
    });
    return { operation: "request_map_preview", scope: "project", job: result.job, created: result.created };
  }
  if (input?.action === "list_map_revisions") {
    if (!mapRevisions) throw httpError(503, "地图修订历史当前不可用");
    return { operation: "list_map_revisions", scope: "project", mapPath, mapVersion: inspected.version, revisions: mapRevisions.list({ projectPath, relativePath: mapPath, limit: input.limit }) };
  }
  if (input?.action === "propose_tiled_patch" || input?.action === "apply_tiled_patch") {
    if (isManagedMultiMapPatch(input.patch)) {
      return input.action === "propose_tiled_patch"
        ? previewManagedMultiMapPatch({ contract, input, runtime, signal })
        : createManagedMultiMapTask({ contract, input, runtime, signal });
    }
    const parsed = await readManagedTiledDocument(targetPath, mapPath, signal);
    const patch = normalizeManagedPatch(input.patch, mapPath, inspected.version);
    assertMapPatchRuntimeCompatible(parsed.document, patch, runtimeCapabilities);
    const preview = {
      ...previewTiledAiPatch(parsed.document, patch),
      ordinaryObjectCount: patch.operations.filter((entry) => ["add-object", "update-object", "remove-object"].includes(entry.op)).length,
    };
    const risk = assessMapAiTask({
      approvalPolicy: contract.approvalSnapshot.policy,
      operations: patch.operations,
      targetMapPaths: [mapPath], targetFiles: [mapPath], tileCellCount: preview.tileCellCount,
      ordinaryObjectCount: preview.ordinaryObjectCount, mapCount: 1, previewOnly: input.action === "propose_tiled_patch",
    });
    if (input.action === "propose_tiled_patch") {
      return { operation: "propose_tiled_patch", scope: "project", mapPath, mapVersion: inspected.version, summary: patch.summary, preview: boundedManagedPreview(preview), risk: managedRiskReceipt(risk), requiresTask: true };
    }
    if (!mapAiManagedTasks) throw httpError(503, "地图 AI 托管任务当前不可用");
    const result = await mapAiManagedTasks.create({
      identity: { userId: runtime.user.id, browserSessionId: contract.identity.browserSessionId },
      authority: managedProjectTaskAuthority(contract, { mapPath, mapVersion: inspected.version, mapPaths: [mapPath], mapVersions: { [mapPath]: inspected.version }, targetFiles: [mapPath], targetFileVersions: { [mapPath]: inspected.version } }),
      approvalSnapshot: contract.approvalSnapshot, settingsSnapshot: {}, clientOperationId: input.clientOperationId,
      request: patch, planSummary: { operationCount: preview.operationCount, tileCellCount: preview.tileCellCount, ordinaryObjectCount: preview.ordinaryObjectCount },
    });
    if (result.created && mapAiManagedTaskExecutor) scheduleMapAiManagedTaskExecution({ taskId: result.task.id, identity: { userId: runtime.user.id, browserSessionId: contract.identity.browserSessionId } });
    return { operation: "apply_tiled_patch", scope: "project", task: result.task, created: result.created };
  }
  throw httpError(400, "托管工程 AI 操作无效");
}

async function executeManagedProjectResourceOperation(runtime, input, contract, resources, { signal = null } = {}) {
  const resourcePatch = normalizeManagedResourcePatch(input.patch);
  const currentVersions = {};
  const candidates = [];
  try {
    for (const file of resourcePatch.files) {
      throwIfMapAiOperationAborted(signal);
      await assertManagedResourceParent(contract.scope.projectPath, file.path);
      const target = path.join(contract.scope.projectPath, ...file.path.split("/"));
      const current = await inspectManagedResourceVersion(target);
      if ((current?.version || null) !== file.baseVersion) throw httpError(409, `资源 ${file.path} 版本已变化，请重新读取工程资源`);
      currentVersions[file.path] = current?.version || null;
      if (!mapAiResourceCandidates) throw httpError(503, "地图资源候选服务当前不可用");
      const candidate = await mapAiResourceCandidates.resolve({
        candidateId: file.candidateId, userId: runtime.user.id, projectPath: contract.scope.projectPath,
        threadId: null, projectWide: true, relativePath: file.path, baseVersion: file.baseVersion,
      });
      if (file.size !== undefined && file.size !== candidate.metadata.size) throw httpError(409, `资源 ${file.path} 候选大小与声明不一致`);
      if (file.sha256 !== undefined && file.sha256 !== candidate.metadata.sha256) throw httpError(409, `资源 ${file.path} 候选哈希与声明不一致`);
      candidates.push(candidate);
    }
    if (["propose_project_patch", "propose_tiled_resource_patch"].includes(input.action)) {
      return { operation: input.action, scope: "project", summary: resourcePatch.summary, preview: { kind: "project-resource-transaction", fileCount: resourcePatch.files.length, files: resourcePatch.files.map(({ path: resourcePath, baseVersion }) => ({ path: resourcePath, baseVersion })) }, risk: { ruleVersion: "map-risk-v1", riskLevel: "high", reasonCodes: ["multiple_files", "project_scope"], hardBlocks: [] }, requiresTask: true };
    }
    if (!mapAiManagedTasks) throw httpError(503, "地图 AI 托管任务当前不可用");
    // The task store still requires one hash-shaped anchor for checkpoint
    // receipts. Prefer a live map when the project has one; when an AI task
    // only edits a role/image/template (or the project has no map yet), use
    // the exact target's current version or the opaque candidate hash. This
    // keeps resource-only work independent from a "primary map" assumption.
    const primary = resources.find((entry) => entry.kind === "map")
      || resources.find((entry) => entry.path === resourcePatch.files[0].path)
      || resourcePatch.files[0];
    const primaryCandidate = candidates.find((entry) => entry.metadata.path === primary.path) || candidates[0];
    const primaryVersion = currentVersions[primary.path]
      || primary.version
      || primaryCandidate?.metadata.sha256
      || resourcePatch.files[0].baseVersion;
    if (!/^[a-f0-9]{64}$/iu.test(String(primaryVersion || ""))) throw httpError(409, "资源事务缺少有效版本锚点");
    const mapResources = resources.filter((entry) => entry.kind === "map");
    const mapVersions = Object.fromEntries(mapResources
      .map((entry) => [entry.path, currentVersions[entry.path] || entry.version || null])
      .filter(([, version]) => /^[a-f0-9]{64}$/iu.test(String(version))));
    const mapPaths = Object.keys(mapVersions).length ? Object.keys(mapVersions) : [primary.path];
    if (!mapVersions[primary.path]) mapVersions[primary.path] = primaryVersion;
    const targetFiles = [...new Set([primary.path, ...resourcePatch.files.map((file) => file.path)])];
    const targetFileVersions = { ...currentVersions, [primary.path]: primaryVersion };
    const taskIdentity = { userId: runtime.user.id, browserSessionId: contract.identity.browserSessionId };
    const result = await mapAiManagedTasks.create({
      identity: taskIdentity,
      authority: managedProjectTaskAuthority(contract, { mapPath: primary.path, mapVersion: primaryVersion, mapPaths, mapVersions, targetFiles, targetFileVersions }),
      approvalSnapshot: contract.approvalSnapshot, settingsSnapshot: {}, clientOperationId: input.clientOperationId,
      request: resourcePatch, planSummary: { operationCount: resourcePatch.files.length, tileCellCount: 0, ordinaryObjectCount: 0 },
    });
    if (result.created && mapAiManagedTaskExecutor) scheduleMapAiManagedTaskExecution({ taskId: result.task.id, identity: taskIdentity });
    return { operation: input.action, scope: "project", task: result.task, created: result.created };
  } finally {
    await Promise.all(candidates.map((candidate) => candidate.release?.().catch(() => {})));
  }
}

function managedProjectTaskAuthority(contract, { mapPath, mapVersion, mapPaths, mapVersions, targetFiles, targetFileVersions }) {
  return {
    authorityMode: "managed", scopeKind: "project", projectWide: true, managedAuthorizationId: contract.id,
    threadId: null, projectPath: contract.scope.projectPath, mapSessionId: null, mapPath, baseVersion: mapVersion,
    mapPaths, mapVersions, targetFiles, targetFileVersions, allowedOps: contract.allowedOps,
    protectedTargets: contract.protectedTargets, collaborationPolicy: contract.collaborationPolicy, expiresAt: contract.expiresAt,
  };
}

async function assertManagedCollaborationPolicyCurrent({ contract, projectPath, mapPath, requireWrite = false } = {}) {
  if (!contract?.collaborationPolicy || !mapCollaborationPolicies) return true;
  const current = mapCollaborationPolicies.contract({
    userId: contract.identity?.userId,
    projectPath,
    mapPath,
  });
  if (current.projectFingerprint !== contract.collaborationPolicy.projectFingerprint
    || current.mapPath !== contract.collaborationPolicy.mapPath
    || Number(current.revision || 0) !== Number(contract.collaborationPolicy.revision || 0)) {
    const error = httpError(409, "协同策略已经变化，请重新读取策略并创建新的托管授权");
    error.code = "MAP_COLLABORATION_POLICY_CONFLICT";
    throw error;
  }
  if (requireWrite) await assertWritableProjectDirectory(path.resolve(projectPath), await runtimeForUser(contract.identity.userId));
  return true;
}

async function readManagedTiledDocument(targetPath, mapPath, signal = null) {
  if (signal?.aborted) throw signal.reason instanceof Error ? signal.reason : httpError(504, "地图 AI 工具调用超时");
  const stat = await fs.stat(targetPath);
  if (!stat.isFile() || stat.size > MAP_AI_MANAGED_CONTEXT_MAX_BYTES) {
    const error = httpError(413, "地图上下文超过托管读取预算，请改用小范围读取或提交托管任务");
    error.code = "MAP_AI_MANAGED_CONTEXT_TOO_LARGE";
    throw error;
  }
  const source = await fs.readFile(targetPath, "utf8");
  if (Buffer.byteLength(source, "utf8") > MAP_AI_MANAGED_CONTEXT_MAX_BYTES) throw httpError(413, "地图上下文超过托管读取预算");
  return parseTiledDocument(source, { expectedKind: "map", sourcePath: mapPath });
}

function normalizeManagedPatch(value, mapPath, mapVersion) {
  const patch = value && typeof value === "object" && !Array.isArray(value) ? structuredClone(value) : null;
  if (!patch) throw httpError(400, "托管补丁必须是结构化对象");
  const base = { ...(patch.base || {}), mapPath, mapVersion, editorStateId: Number(patch.base?.editorStateId || 0) };
  try {
    return parseTiledAiPatch(JSON.stringify({ ...patch, base }), { mapPath, mapVersion, editorStateId: base.editorStateId });
  } catch (error) {
    const failure = httpError(422, error?.message || "托管 Tiled 补丁校验失败");
    failure.code = error?.code || "MAP_AI_MANAGED_PATCH_INVALID";
    throw failure;
  }
}

function normalizeManagedResourcePatch(value) {
  const patch = value && typeof value === "object" && !Array.isArray(value) ? structuredClone(value) : null;
  if (!patch || patch.format !== "wfl-tiled-resource-patch" || patch.version !== 1 || !Array.isArray(patch.files) || patch.files.length < 1 || patch.files.length > 256) throw httpError(422, "托管资源补丁结构无效");
  const patchKeys = new Set(["format", "version", "summary", "files"]);
  if (Object.keys(patch).some((key) => !patchKeys.has(key))) throw httpError(400, "托管资源补丁包含未知字段");
  const seen = new Set();
  const files = patch.files.map((entry) => {
    if (!entry || typeof entry !== "object" || Array.isArray(entry)) throw httpError(422, "托管资源补丁文件条目无效");
    const fileKeys = new Set(["path", "baseVersion", "candidateId", "size", "sha256"]);
    if (Object.keys(entry).some((key) => !fileKeys.has(key))) throw httpError(400, "托管资源补丁文件条目包含未知字段");
    const relativePath = normalizeMapProjectRelativePath(entry?.path || entry?.relativePath, { label: "托管资源" });
    if (!/(?:\.(?:tmj|tsj|tx|world|png|jpe?g|webp)|\.character\.json)$/iu.test(relativePath) || seen.has(relativePath)) throw httpError(422, `托管资源路径无效或重复: ${relativePath}`);
    seen.add(relativePath);
    const baseVersion = entry.baseVersion === null ? null : String(entry.baseVersion || "").toLowerCase();
    if (baseVersion !== null && !/^[a-f0-9]{64}$/u.test(baseVersion)) throw httpError(422, `托管资源 ${relativePath} 基础版本无效`);
    if (typeof entry.candidateId !== "string" || !entry.candidateId.trim() || Object.hasOwn(entry, "candidatePath") || Object.hasOwn(entry, "content") || Object.hasOwn(entry, "bytes")) throw httpError(400, "资源补丁只能使用服务端候选 ID");
    if (entry.size !== undefined && (!Number.isSafeInteger(Number(entry.size)) || Number(entry.size) <= 0)) throw httpError(422, `托管资源 ${relativePath} 候选大小无效`);
    const sha256 = entry.sha256 === undefined ? null : String(entry.sha256).toLowerCase();
    if (sha256 !== null && !/^[a-f0-9]{64}$/u.test(sha256)) throw httpError(422, `托管资源 ${relativePath} 候选哈希无效`);
    return { path: relativePath, baseVersion, candidateId: entry.candidateId.trim(), ...(entry.size === undefined ? {} : { size: Number(entry.size) }), ...(sha256 === null ? {} : { sha256 }) };
  });
  return { format: "wfl-tiled-resource-patch", version: 1, summary: String(patch.summary || "地图资源托管修改").slice(0, 2_000), files };
}

function isManagedMultiMapPatch(value) {
  return Boolean(value && typeof value === "object" && value.format === "wfl-multi-map-patch" && value.version === 1 && Array.isArray(value.maps));
}

async function inspectManagedMultiMapPatch({ contract, patch, runtime, signal = null } = {}) {
  if (!isManagedMultiMapPatch(patch) || patch.maps.length < 2 || patch.maps.length > 128) {
    throw httpError(422, "多地图托管补丁必须包含 2 到 128 张地图");
  }
  const projectResources = contract.scope.projectWide
    ? (await listMapAiProjectResources({ projectPath: contract.scope.projectPath, limit: 4_096 })).resources
    : [];
  const allowed = new Set(contract.scope.projectWide
    ? projectResources.filter((entry) => entry.kind === "map").map((entry) => entry.path)
    : contract.scope.mapPaths);
  const seen = new Set();
  const maps = [];
  for (const entry of patch.maps) {
    const mapPath = normalizeMapProjectRelativePath(entry?.mapPath || entry?.base?.mapPath, { extension: ".tmj", label: "托管地图" });
    if (!allowed.has(mapPath) || seen.has(mapPath)) throw httpError(403, `地图 ${mapPath} 不在托管授权范围`);
    seen.add(mapPath);
    const targetPath = path.join(contract.scope.projectPath, ...mapPath.split("/"));
    const resolved = await resolveResourceTarget(contract.scope.projectPath, targetPath, runtime);
    if (path.resolve(resolved.targetPath) !== path.resolve(targetPath)) throw httpError(403, `托管地图 ${mapPath} 路径无效`);
    const inspected = await inspectMapFile(targetPath, { maxBytes: MAP_SAVE_MAX_BYTES, signal });
    const expected = contract.scope.projectWide ? inspected.version : contract.scope.mapVersions[mapPath];
    if (inspected.version !== expected) throw httpError(409, `地图 ${mapPath} 版本已变化，请重新授权`);
    const nested = entry?.patch && typeof entry.patch === "object" ? entry.patch : entry;
    const normalized = normalizeManagedPatch({ ...nested, base: { ...nested?.base, mapPath, mapVersion: inspected.version } }, mapPath, inspected.version);
    const parsed = await readManagedTiledDocument(targetPath, mapPath, signal);
    const runtimeCapabilities = await inspectMapRuntimeCapabilities({ projectPath: contract.scope.projectPath, mapPath });
    assertMapPatchRuntimeCompatible(parsed.document, normalized, runtimeCapabilities);
    if (contract.collaborationPolicy) {
      const violations = findCollaborationOperationViolations(parsed.document, normalized, contract.collaborationPolicy, mapPath);
      if (violations.length) { const error = httpError(403, violations[0].message); error.code = violations[0].code || "MAP_COLLABORATION_HUMAN_OWNED"; throw error; }
    }
    const preview = { ...previewTiledAiPatch(parsed.document, normalized), ordinaryObjectCount: normalized.operations.filter((entry) => ["add-object", "update-object", "remove-object"].includes(entry.op)).length };
    maps.push({ mapPath, patch: normalized, preview, version: inspected.version });
  }
  if (!contract.scope.projectWide && (seen.size !== allowed.size || contract.scope.mapPaths.some((mapPath) => !seen.has(mapPath)))) {
    throw httpError(403, "多地图补丁必须覆盖全部托管地图");
  }
  return { format: "wfl-multi-map-patch", version: 1, summary: String(patch.summary || "多地图托管修改").slice(0, 2_000), maps };
}

async function previewManagedMultiMapPatch({ contract, input, runtime, signal } = {}) {
  const plan = await inspectManagedMultiMapPatch({ contract, patch: input.patch, runtime, signal });
  const operationCount = plan.maps.reduce((sum, entry) => sum + entry.preview.operationCount, 0);
  const tileCellCount = plan.maps.reduce((sum, entry) => sum + entry.preview.tileCellCount, 0);
  const ordinaryObjectCount = plan.maps.reduce((sum, entry) => sum + entry.preview.ordinaryObjectCount, 0);
  const risk = assessMapAiTask({ approvalPolicy: contract.approvalSnapshot.policy, operations: plan.maps.flatMap((entry) => entry.patch.operations), targetMapPaths: plan.maps.map((entry) => entry.mapPath), targetFiles: plan.maps.map((entry) => entry.mapPath), tileCellCount, ordinaryObjectCount, mapCount: plan.maps.length, previewOnly: true });
  return { operation: "propose_tiled_patch", mapPaths: plan.maps.map((entry) => entry.mapPath), summary: plan.summary, preview: boundedManagedPreview({ summary: plan.summary, operationCount, tileCellCount, ordinaryObjectCount, entries: plan.maps.flatMap((entry) => entry.preview.entries).slice(0, 512) }), risk: managedRiskReceipt(risk), requiresTask: true };
}

async function createManagedMultiMapTask({ contract, input, runtime, signal } = {}) {
  if (!mapAiManagedTasks) throw httpError(503, "地图 AI 托管任务当前不可用");
  const plan = await inspectManagedMultiMapPatch({ contract, patch: input.patch, runtime, signal });
  const operationCount = plan.maps.reduce((sum, entry) => sum + entry.preview.operationCount, 0);
  const tileCellCount = plan.maps.reduce((sum, entry) => sum + entry.preview.tileCellCount, 0);
  const ordinaryObjectCount = plan.maps.reduce((sum, entry) => sum + entry.preview.ordinaryObjectCount, 0);
  const identity = { userId: runtime.user.id, browserSessionId: contract.identity.browserSessionId };
  const mapPaths = plan.maps.map((entry) => entry.mapPath);
  const mapVersions = Object.fromEntries(plan.maps.map((entry) => [entry.mapPath, entry.version]));
  const result = await mapAiManagedTasks.create({
    identity,
    authority: {
      authorityMode: "managed", scopeKind: contract.scope.scopeKind, projectWide: contract.scope.projectWide === true,
      managedAuthorizationId: contract.id, threadId: contract.scope.threadId, projectPath: contract.scope.projectPath,
      mapSessionId: null, mapPath: mapPaths[0], baseVersion: mapVersions[mapPaths[0]], mapPaths, mapVersions,
      targetFiles: mapPaths, targetFileVersions: mapVersions, allowedOps: contract.allowedOps, protectedTargets: contract.protectedTargets,
      collaborationPolicy: contract.collaborationPolicy, expiresAt: contract.expiresAt,
    },
    approvalSnapshot: contract.approvalSnapshot,
    settingsSnapshot: {},
    clientOperationId: input.clientOperationId,
    request: plan,
    planSummary: { operationCount, tileCellCount, ordinaryObjectCount },
  });
  if (result.created && mapAiManagedTaskExecutor) scheduleMapAiManagedTaskExecution({ taskId: result.task.id, identity });
  return { operation: "apply_tiled_patch", task: result.task, created: result.created, mapPaths: plan.maps.map((entry) => entry.mapPath) };
}

function managedMapContext(document, mapPath, mapVersion) {
  const layers = [...tiledLayerEntries(document)].slice(0, 2_000).map(({ layer, parentId }) => ({
    id: layer.id, parentId, name: String(layer.name || "").slice(0, 200), type: layer.type,
    visible: layer.visible !== false, locked: layer.locked === true,
    ...(layer.type === "tilelayer" ? { width: layer.width || 0, height: layer.height || 0, infinite: Array.isArray(layer.chunks) } : {}),
    ...(layer.type === "objectgroup" ? { objectCount: Array.isArray(layer.objects) ? layer.objects.length : 0 } : {}),
  }));
  return { operation: "get_map_context", mapPath, mapVersion, map: { type: document.type, orientation: document.orientation, infinite: document.infinite === true, width: document.width, height: document.height, tilewidth: document.tilewidth, tileheight: document.tileheight }, layers, layerCount: layers.length, references: publicManagedReferences(document, mapPath) };
}

function managedMapRegion(document, region, layerIds = null) {
  const x = Number(region?.x); const y = Number(region?.y); const width = Number(region?.width); const height = Number(region?.height);
  if (![x, y, width, height].every(Number.isSafeInteger) || width < 1 || height < 1 || width > 512 || height > 512) throw httpError(400, "托管地图区域无效");
  const selected = Array.isArray(layerIds) && layerIds.length ? new Set(layerIds) : null;
  const layers = [];
  for (const { layer } of tiledLayerEntries(document)) {
    if (layer.type !== "tilelayer" || (selected && !selected.has(layer.id))) continue;
    const cells = [...tileLayerCellsInRange(layer, { startColumn: x, endColumn: x + width - 1, startRow: y, endRow: y + height - 1 })]
      .slice(0, width * height).map((cell) => ({ x: cell.column, y: cell.row, gid: cell.encodedGid }));
    layers.push({ layerId: layer.id, name: String(layer.name || "").slice(0, 200), cells });
  }
  return { operation: "read_map_region", region: { x, y, width, height }, layers };
}

function publicManagedReferences(document, mapPath) {
  return collectTiledReferences(document, { sourcePath: mapPath })
    .filter((reference) => typeof reference?.resolvedPath === "string" && reference.resolvedPath.length > 0)
    .slice(0, 1_000)
    .map((reference) => ({ kind: reference.kind, path: reference.resolvedPath }));
}
function boundedManagedDiagnostics(value) { return (Array.isArray(value) ? value : []).slice(0, 256).map((entry) => ({ severity: entry?.severity === "warning" ? "warning" : "error", code: String(entry?.code || "map-invalid").slice(0, 100), path: String(entry?.path || "$").slice(0, 512), message: String(entry?.message || "地图校验失败").slice(0, 1_000) })); }
function boundedManagedPreview(value) { return { summary: String(value?.summary || "").slice(0, 2_000), operationCount: value?.operationCount || 0, tileCellCount: value?.tileCellCount || 0, ordinaryObjectCount: value?.ordinaryObjectCount || 0, entries: (value?.entries || []).slice(0, 512) }; }
function managedRiskReceipt(value) { return { ruleVersion: value.ruleVersion, riskLevel: value.riskLevel, reasonCodes: [...value.reasonCodes].slice(0, 32), hardBlocks: [...value.hardBlocks].slice(0, 32), decision: value.decision }; }

function mapAiToolContextError(statusCode, code, message) {
  const error = httpError(statusCode, message);
  error.code = code;
  return error;
}

function throwIfMapAiOperationAborted(signal) {
  if (!signal?.aborted) return;
  if (signal.reason instanceof Error) throw signal.reason;
  throw mapAiToolContextError(504, "MAP_AI_TOOL_TIMEOUT", "地图 AI 工具调用超时");
}

function resolveMapAiToolContextForRuntime(runtime, input, operation, { signal = null } = {}) {
  throwIfMapAiOperationAborted(signal);
  if (RESCUE_MODE || !mapAiAccess || !mapFileSessions || !mapAiProposals) {
    throw mapAiToolContextError(409, "MAP_AI_DISABLED", "地图 AI 工具当前未启用");
  }
  // Deliberately ignore input.userId. A legacy runtime's owner id can change
  // when multi-user mode is enabled, and the construction-time socket value
  // must never become an authorization identity.
  return mapAiAccess.resolveToolContext({
    userId: runtime?.user?.id,
    threadId: input?.threadId,
    mapSessionId: input?.mapSessionId,
    editorInstanceId: input?.editorInstanceId,
    editorStateId: input?.editorStateId,
    operation,
  });
}

async function validateMapAiToolLiveContext(runtime, leaseContext, input, operation, {
  requireWritable = false,
  signal = null,
} = {}) {
  throwIfMapAiOperationAborted(signal);
  const editorInstanceId = normalizeMapEditorInstanceId(input?.editorInstanceId);
  const editorStateId = normalizeMapAiEditorStateId(input?.editorStateId);
  const mapSessionId = String(input?.mapSessionId || "");
  const identity = {
    userId: String(runtime?.user?.id || ""),
    browserSessionId: String(leaseContext?.browserSessionId || ""),
    editorInstanceId,
  };
  const context = mapFileSessions.context({ sessionId: mapSessionId, identity });
  assertMapAiLeaseIdentity(leaseContext, {
    identity,
    mapSessionId,
    context,
    editorInstanceId,
    editorStateId,
  });
  if (leaseContext.threadId !== input?.threadId) {
    throw mapAiToolContextError(409, "MAP_AI_LEASE_CONTEXT_MISMATCH", "地图 AI 临时授权不属于当前对话");
  }
  const resolved = await resolveResourceTarget(context.projectPath, context.targetPath, runtime);
  if (
    path.resolve(resolved.projectPath) !== path.resolve(context.projectPath)
    || path.resolve(resolved.targetPath) !== path.resolve(context.targetPath)
  ) {
    throw mapAiToolContextError(403, "MAP_AI_PROJECT_CONTEXT_INVALID", "地图 AI 上下文不再属于当前工程");
  }
  if (requireWritable) {
    if (context.writable !== true) {
      throw mapAiToolContextError(403, "MAP_AI_MAP_READ_ONLY", "只读地图会话不能接收 AI 补丁提案");
    }
    await assertWritableMapContext(context, runtime);
  }
  const inspected = await inspectMapFile(context.targetPath, {
    maxBytes: MAP_SAVE_MAX_BYTES,
    signal,
  });
  if (inspected.version !== context.version) {
    throw mapAiToolContextError(409, "MAP_AI_MAP_VERSION_CONFLICT", "地图文件已经变化，请重新打开编辑器并授权");
  }
  await assertMapAiThreadProject(runtime, leaseContext.threadId, context.projectPath, { signal });
  throwIfMapAiOperationAborted(signal);
  // Re-resolve immediately before returning so revoke, expiry, user opt-out,
  // duplicate grants or editor-state changes observed during validation fail
  // closed instead of allowing a late proposal write.
  const currentLease = resolveMapAiToolContextForRuntime(runtime, input, operation, { signal });
  assertMapAiLeaseIdentity(currentLease, {
    identity,
    mapSessionId,
    context,
    editorInstanceId,
    editorStateId,
  });
  const collaborationPolicy = mapCollaborationPolicies?.contract({
    userId: identity.userId,
    projectPath: context.projectPath,
    mapPath: context.relativePath,
  }) || null;
  return {
    identity,
    context,
    leaseContext: currentLease,
    collaborationPolicy,
    proposalContext: {
      userId: identity.userId,
      browserSessionId: identity.browserSessionId,
      threadId: currentLease.threadId,
      projectPath: context.projectPath,
      mapSessionId,
      mapVersion: context.version,
      editorInstanceId,
      mapPath: context.relativePath,
      editorStateId,
      collaborationPolicyRevision: Number(collaborationPolicy?.revision || 0),
    },
  };
}

async function getMapAiToolContextForRuntime(runtime, leaseContext, input, { signal = null } = {}) {
  const live = await validateMapAiToolLiveContext(
    runtime,
    leaseContext,
    input,
    "get_map_context",
    { requireWritable: false, signal },
  );
  return publicMapAiContext(live.context, live.leaseContext);
}

async function proposeMapAiPatchForRuntime(runtime, leaseContext, input, { signal = null } = {}) {
  const live = await validateMapAiToolLiveContext(
    runtime,
    leaseContext,
    input,
    "propose_tiled_patch",
    { requireWritable: true, signal },
  );
  throwIfMapAiOperationAborted(signal);
  // MCP and HTTP proposal entry points share the same server-side ownership
  // gate.  Do not rely on the browser inbox to enforce human/locked regions:
  // a model can call this private adapter directly while the editor is open.
  if (live.collaborationPolicy?.targets?.length) {
    const patch = parseTiledAiPatch(
      JSON.stringify(input?.patch),
      {
        mapPath: live.proposalContext.mapPath,
        mapVersion: live.proposalContext.mapVersion,
        editorStateId: live.proposalContext.editorStateId,
      },
    );
    const parsed = await readManagedTiledDocument(
      live.context.targetPath,
      live.context.relativePath,
      signal,
    );
    const violations = findCollaborationOperationViolations(
      parsed.document,
      patch,
      live.collaborationPolicy,
      live.proposalContext.mapPath,
    );
    if (violations.length) {
      const error = httpError(403, violations[0].message);
      error.code = violations[0].code || "MAP_COLLABORATION_HUMAN_OWNED";
      throw error;
    }
  }
  const currentPolicy = mapCollaborationPolicies?.contract({
    userId: live.proposalContext.userId,
    projectPath: live.proposalContext.projectPath,
    mapPath: live.proposalContext.mapPath,
  }) || null;
  if (Number(currentPolicy?.revision || 0) !== Number(live.proposalContext.collaborationPolicyRevision || 0)) {
    throw httpError(409, "协同策略已经变化，请重新读取后提交地图 AI 提案");
  }
  const proposal = await mapAiProposals.create({
    ...live.proposalContext,
    patch: input?.patch,
    collaborationPolicyRevision: Number(currentPolicy?.revision || 0),
  });
  throwIfMapAiOperationAborted(signal);
  // Keep the full patch only in the editor inbox. Returning it through MCP
  // would duplicate it into both text and structured conversation content.
  return {
    id: proposal.id,
    status: proposal.status,
    summary: String(proposal.patch?.summary || ""),
    patchBytes: proposal.patchBytes,
    mapPath: proposal.mapPath,
    mapVersion: proposal.mapVersion,
    editorStateId: proposal.editorStateId,
    // Return only the bounded, deterministic review receipt. The patch body
    // remains in the editor inbox and is never duplicated into MCP/chat.
    risk: proposal.risk ? {
      ruleVersion: proposal.risk.ruleVersion,
      riskLevel: proposal.risk.riskLevel,
      reasonCodes: Array.isArray(proposal.risk.reasonCodes) ? proposal.risk.reasonCodes.slice(0, 32) : [],
      hardBlocks: Array.isArray(proposal.risk.hardBlocks) ? proposal.risk.hardBlocks.slice(0, 32) : [],
      tileCellCount: proposal.risk.tileCellCount,
      ordinaryObjectCount: proposal.risk.ordinaryObjectCount,
      operationCount: proposal.risk.operationCount,
    } : null,
    createdAt: proposal.createdAt,
    expiresAt: proposal.expiresAt,
  };
}

function mapImageJobLimits() {
  const worker = imageExecutionSettings?.snapshot()?.config?.worker;
  const activeLimit = worker
    ? Math.min(100_000, worker.queueLimit + worker.concurrency)
    : 1;
  return { maxJobs: activeLimit, concurrency: activeLimit };
}

function normalizeMapImageEditorStateId(value) {
  const number = Number(value);
  if (!Number.isSafeInteger(number) || number < 0) {
    throw imageExecutionError(400, "MAP_IMAGE_EDITOR_STATE_INVALID", "地图编辑状态标识无效");
  }
  return number;
}

function authorizeMapImageSources({ identity, mapContext, sourcePaths = [], maskPath = null }) {
  if (!mapFileSessions) {
    throw imageExecutionError(503, "MAP_IMAGE_SESSION_UNAVAILABLE", "地图会话当前不可用");
  }
  const authorize = (resourcePath) => mapFileSessions.authorizeResource({
    sessionId: mapContext.mapSessionId,
    identity,
    resourcePath,
  });
  return {
    sources: sourcePaths.map(authorize),
    mask: maskPath ? authorize(maskPath) : null,
  };
}

/**
 * Re-authorize a browser-captured map image input against the live map
 * session. The input store calls this callback at creation/finalization and
 * again when a queued job claims/stages an input; it is intentionally the only
 * place where the store learns project/session authority.
 */
async function authorizeMapImageInput({
  purpose = "input-read",
  identity,
  mapContext,
  mapVersion,
} = {}) {
  if (!mapFileSessions) {
    throw imageExecutionError(503, "MAP_IMAGE_SESSION_UNAVAILABLE", "地图会话当前不可用");
  }
  const normalizedIdentity = {
    userId: String(identity?.userId || ""),
    browserSessionId: String(identity?.browserSessionId || ""),
    editorInstanceId: String(identity?.editorInstanceId || ""),
  };
  const current = mapFileSessions.context({
    sessionId: mapContext?.mapSessionId,
    identity: normalizedIdentity,
  });
  if (
    String(mapVersion || "") !== current.version
    || String(mapContext?.version || "") !== current.version
    || path.resolve(String(mapContext?.projectPath || ".")) !== path.resolve(current.projectPath)
    || path.resolve(String(mapContext?.targetPath || ".")) !== path.resolve(current.targetPath)
  ) {
    throw imageExecutionError(409, "MAP_IMAGE_INPUT_CONTEXT_CONFLICT", "地图图片输入所属地图版本或工程位置已经变化");
  }
  const runtime = await runtimeForUser(normalizedIdentity.userId);
  const resolved = await resolveResourceTarget(current.projectPath, current.targetPath, runtime);
  if (
    path.resolve(resolved.projectPath) !== path.resolve(current.projectPath)
    || path.resolve(resolved.targetPath) !== path.resolve(current.targetPath)
  ) throw imageExecutionError(403, "MAP_IMAGE_INPUT_CONTEXT_CONFLICT", "地图图片输入不再属于当前工程");
  if (["input-create", "input-finalize", "input-retain", "input-claim", "input-stage", "input-delete"].includes(String(purpose))) {
    await assertWritableMapContext(current, runtime);
  }
  // A candidate input must never survive a changed map file. The bounded
  // fingerprint pass is cheap compared with an image Worker invocation and
  // keeps queued jobs deterministic without parsing a potentially huge TMJ in
  // the main process.
  if (["input-finalize", "input-retain", "input-claim", "input-stage"].includes(String(purpose))) {
    const inspected = await inspectMapFile(current.targetPath, { maxBytes: MAP_SAVE_MAX_BYTES });
    if (inspected.version !== current.version) {
      throw imageExecutionError(409, "MAP_IMAGE_INPUT_CONTEXT_CONFLICT", "地图文件已变化，请重新截取图片");
    }
  }
  return { uid: null, gid: null };
}

async function authorizeMapAiResourceUpload({
  purpose = "resource-upload-create",
  identity,
  mapContext,
  editorStateId,
  relativePath,
  baseVersion,
  threadId,
} = {}) {
  if (!mapFileSessions) throw httpError(503, "地图编辑器当前不可用");
  const normalizedIdentity = {
    userId: String(identity?.userId || ""),
    browserSessionId: String(identity?.browserSessionId || ""),
    editorInstanceId: String(identity?.editorInstanceId || ""),
  };
  const current = mapFileSessions.context({ sessionId: mapContext?.mapSessionId, identity: normalizedIdentity });
  if (current.version !== String(mapContext?.version || "")
    || path.resolve(current.projectPath) !== path.resolve(String(mapContext?.projectPath || ""))
    || (mapContext?.targetPath && path.resolve(current.targetPath) !== path.resolve(String(mapContext.targetPath)))) {
    throw httpError(409, "资源候选上传所属地图版本或工程位置已经变化");
  }
  const runtime = await runtimeForUser(normalizedIdentity.userId);
  await assertWritableMapContext(current, runtime);
  await assertMapAiThreadProject(runtime, normalizeMapAiThreadId(threadId), current.projectPath);
  const inspected = await inspectMapFile(current.targetPath, { maxBytes: MAP_SAVE_MAX_BYTES });
  if (inspected.version !== current.version) throw httpError(409, "地图文件已变化，请重新上传资源候选");
  if (baseVersion !== null && baseVersion !== undefined) {
    const target = path.join(current.projectPath, ...String(relativePath || "").split("/"));
    const targetVersion = await inspectManagedResourceVersion(target);
    if (targetVersion?.version !== String(baseVersion).toLowerCase()) throw httpError(409, `资源 ${relativePath} 基础版本已变化，请重新读取`);
  } else if (["resource-upload-create", "resource-upload-finalize", "resource-upload-source"].includes(String(purpose))) {
    const target = path.join(current.projectPath, ...String(relativePath || "").split("/"));
    const existing = await fs.lstat(target).then(() => true, (error) => error?.code === "ENOENT" ? false : Promise.reject(error));
    if (existing) throw httpError(409, `资源 ${relativePath} 已存在，请重新声明基础版本`);
  }
  return { uid: null, gid: null };
}

function normalizeMapImageInputSelection(value) {
  if (value == null) return null;
  if (!isRecord(value)) {
    throw imageExecutionError(400, "INVALID_MAP_IMAGE_INPUTS", "地图图片临时输入清单无效");
  }
  const allowedKeys = new Set(["sourceInputIds", "sourceInputId", "maskInputId"]);
  if (Object.keys(value).some((key) => !allowedKeys.has(key))) {
    throw imageExecutionError(400, "INVALID_MAP_IMAGE_INPUTS", "地图图片临时输入清单包含未知字段");
  }
  const rawSources = value.sourceInputIds ?? (value.sourceInputId == null ? [] : [value.sourceInputId]);
  if (!Array.isArray(rawSources) || rawSources.length < 1 || rawSources.length > 16) {
    throw imageExecutionError(400, "INVALID_MAP_IMAGE_INPUTS", "地图图片临时源清单无效");
  }
  const normalizeId = (entry, label) => {
    const id = String(entry || "");
    if (!/^[A-Za-z0-9_-]{16,128}$/u.test(id)) {
      throw imageExecutionError(400, "INVALID_MAP_IMAGE_INPUTS", `${label}标识无效`);
    }
    return id;
  };
  const sourceInputIds = rawSources.map((entry) => normalizeId(entry, "源图片"));
  const maskInputId = value.maskInputId == null || value.maskInputId === ""
    ? null
    : normalizeId(value.maskInputId, "蒙版");
  const all = [...sourceInputIds, ...(maskInputId ? [maskInputId] : [])];
  if (new Set(all).size !== all.length) {
    throw imageExecutionError(400, "INVALID_MAP_IMAGE_INPUTS", "源图片和蒙版不能重复引用同一个临时输入");
  }
  return Object.freeze({
    sourceInputIds: Object.freeze([...new Set(sourceInputIds)]),
    maskInputId,
  });
}

async function retainMapImageInputs({ identity, mapContext, editorStateId, selection, imageApi, localOnly = false }) {
  if (!mapImageInputs) {
    throw imageExecutionError(503, "MAP_IMAGE_INPUT_UNAVAILABLE", "地图图片临时输入服务当前不可用");
  }
  const maximumImages = localOnly ? 1 : Number(imageApi?.limits?.maxInputImages || 0);
  if (!Number.isSafeInteger(maximumImages) || maximumImages < 1 || selection.sourceInputIds.length > maximumImages) {
    throw imageExecutionError(400, "IMAGE_INPUT_COUNT_UNSUPPORTED", "当前图片预设不能接收这么多源图片");
  }
  const leases = [];
  try {
    const retain = async (inputId, expectedKind) => {
      const lease = await mapImageInputs.retain({
        inputId,
        identity,
        mapSessionId: mapContext.mapSessionId,
        mapVersion: mapContext.version,
        editorStateId,
        purpose: "input-retain",
      });
      if (lease.metadata?.kind !== expectedKind) {
        await lease.release().catch(() => {});
        throw imageExecutionError(400, "INVALID_MAP_IMAGE_INPUTS", expectedKind === "mask" ? "蒙版输入类型不正确" : "源图片输入类型不正确");
      }
      return lease;
    };
    for (const inputId of selection.sourceInputIds) leases.push(await retain(inputId, "source"));
    if (selection.maskInputId) leases.push(await retain(selection.maskInputId, "mask"));
    const totalBytes = leases.reduce((sum, lease) => sum + Number(lease.metadata?.totalBytes || 0), 0);
    const maxPerImage = localOnly
      ? MAP_IMAGE_INPUT_MAX_BYTES
      : Number(imageApi?.limits?.maxInputBytesPerImage || 0);
    const maxTotal = localOnly
      ? MAP_IMAGE_INPUT_MAX_BYTES
      : Number(imageApi?.limits?.maxInputBytesTotal || 0);
    if (leases.some((lease) => Number(lease.metadata?.totalBytes || 0) > maxPerImage)) {
      throw imageExecutionError(413, "IMAGE_SOURCE_TOO_LARGE", "输入图片超过管理员设置的单图大小限制");
    }
    if (totalBytes > maxTotal) {
      throw imageExecutionError(413, "IMAGE_INPUTS_TOO_LARGE", "输入图片总大小超过管理员设置的限制");
    }
    const toRef = (lease, kind) => {
      const metadata = lease.metadata;
      const mediaType = String(metadata.mediaType || "");
      const format = mediaType === "image/jpeg" ? "jpeg" : mediaType === "image/webp" ? "webp" : "png";
      return {
        id: metadata.id,
        kind,
        size: metadata.totalBytes,
        sha256: metadata.sha256,
        format,
        mediaType,
        width: metadata.width ?? null,
        height: metadata.height ?? null,
      };
    };
    return {
      refs: {
        source: leases.slice(0, selection.sourceInputIds.length).map((lease) => toRef(lease, "source")),
        mask: selection.maskInputId ? toRef(leases.at(-1), "mask") : null,
      },
      leases,
    };
  } catch (error) {
    await Promise.allSettled(leases.map((lease) => lease.release()));
    throw error;
  }
}

function validateMapImageSelectionEnvelope({ target, request, operation, expectedVersion, editorStateId, imageApi }) {
  try {
    assertSafeMapSelectionImageClientPayload(target, { label: "地图选区目标" });
    assertSafeMapSelectionImageClientPayload(request, { label: "地图生图请求" });
  } catch (error) {
    throw imageExecutionError(400, error.code || "MAP_IMAGE_SELECTION_PAYLOAD_INVALID", error.message, {}, error);
  }
  if (!isRecord(target) || target.schema !== "wfl.map-selection-image-target.v1") {
    throw imageExecutionError(400, "MAP_IMAGE_SELECTION_SCHEMA_INVALID", "地图选区目标版本不受支持");
  }
  if (String(target.map?.version || "") !== expectedVersion) {
    throw imageExecutionError(409, "MAP_IMAGE_SELECTION_VERSION_CONFLICT", "地图版本已变化，请重新选择区域");
  }
  if (Number(target.map?.editorStateId) !== editorStateId) {
    throw imageExecutionError(409, "MAP_IMAGE_SELECTION_VERSION_CONFLICT", "地图编辑状态已变化，请重新选择区域");
  }
  if (!isRecord(target.logicalCanvas)
    || !Number.isSafeInteger(target.logicalCanvas.width)
    || !Number.isSafeInteger(target.logicalCanvas.height)
    || target.logicalCanvas.width < 1
    || target.logicalCanvas.height < 1) {
    throw imageExecutionError(400, "MAP_IMAGE_SELECTION_CANVAS_INVALID", "地图选区逻辑画布无效");
  }
  const maxCanvas = Number(imageApi?.limits?.size?.maxWidth || 16_384);
  const maxCanvasHeight = Number(imageApi?.limits?.size?.maxHeight || 16_384);
  if (target.logicalCanvas.width > maxCanvas || target.logicalCanvas.height > maxCanvasHeight) {
    throw imageExecutionError(413, "MAP_IMAGE_SELECTION_CANVAS_LIMIT", "地图选区逻辑画布超过图片预设限制");
  }
  const sides = target.expansion?.world;
  if (!isRecord(sides) || ["top", "right", "bottom", "left"].some((key) => !Number.isSafeInteger(sides[key]) || sides[key] < 0)) {
    throw imageExecutionError(400, "MAP_IMAGE_SELECTION_EXPANSION_INVALID", "地图选区扩展边界无效");
  }
  const totalExpansion = Object.values(sides).reduce((sum, value) => sum + value, 0);
  if ((operation === "outpaint") !== (totalExpansion > 0)) {
    throw imageExecutionError(400, "MAP_IMAGE_SELECTION_OPERATION_TARGET_INVALID", "地图选区操作与扩展边界不匹配");
  }
  if (String(request?.operation || "generate") !== operation) {
    throw imageExecutionError(400, "MAP_IMAGE_SELECTION_OPERATION_TARGET_INVALID", "地图选区操作与图片请求不一致");
  }
  const policies = target.policies || {};
  if (operation === "edit" && String(request?.maskMode || "") !== String(policies.maskMode || "")) {
    throw imageExecutionError(400, "MAP_IMAGE_SELECTION_POLICY_MISMATCH", "请求中的蒙版模式与选区目标不一致");
  }
  if (operation === "outpaint") {
    const requestExpansion = request?.outpaint ?? request?.expand;
    if (!sameJsonValue(requestExpansion, sides)) {
      throw imageExecutionError(400, "MAP_IMAGE_SELECTION_EXPANSION_MISMATCH", "请求中的扩图边界与选区目标不一致");
    }
    for (const key of ["preserveSource", "alignmentPolicy"]) {
      if (String(request?.[key] || "") !== String(policies[key] || "")) {
        throw imageExecutionError(400, "MAP_IMAGE_SELECTION_POLICY_MISMATCH", `请求中的 ${key} 与选区目标不一致`);
      }
    }
    if (policies.preserveSource === "seamless" && Number(request?.blendMargin) !== Number(policies.blendMargin)) {
      throw imageExecutionError(400, "MAP_IMAGE_SELECTION_POLICY_MISMATCH", "请求中的 blendMargin 与选区目标不一致");
    }
  }
}

async function validateMapImageSelectionContract(input) {
  validateMapImageSelectionEnvelope(input);
  const targetPath = String(input.mapContext?.targetPath || "");
  if (!path.isAbsolute(targetPath) || targetPath === path.parse(targetPath).root) {
    throw imageExecutionError(400, "MAP_IMAGE_SELECTION_MAP_INVALID", "地图选区缺少有效的地图文件上下文");
  }
  try {
    const contract = await validateMapSelectionImageTaskInChild({
      targetPath,
      serializedTarget: input.target,
      currentMapVersion: input.expectedVersion,
      currentEditorStateId: input.editorStateId,
      operation: input.operation,
      request: input.request,
      expectedLogicalCanvas: input.target.logicalCanvas,
      limits: mapImageSelectionLimits(input.imageApi, input.operation),
      maxMapBytes: mapReadSessionConfig().maxBytes,
    }, {
      memoryMb: MAP_SAVE_VALIDATION_MEMORY_MB,
      timeoutMs: MAP_SAVE_VALIDATION_TIMEOUT_MS,
      maxOutputBytes: 512 * 1024,
    });
    if (!isRecord(contract) || contract.operation !== input.operation) throw new Error("invalid contract");
    return contract;
  } catch (error) {
    if (error?.code === "MAP_IMAGE_SELECTION_VALIDATION_RESPONSE") {
      throw imageExecutionError(500, error.code, error.message, {}, error);
    }
    throw imageExecutionError(
      Number.isInteger(error?.statusCode) ? error.statusCode : 422,
      error?.code || "MAP_IMAGE_SELECTION_INVALID",
      error?.message || "地图选区校验失败",
      {},
      error,
    );
  }
}

function authoritativeMapImageSelectionTarget(contract) {
  if (!isRecord(contract?.target)) return null;
  const target = structuredClone(contract.target);
  const policies = isRecord(contract.policies) ? contract.policies : {};
  target.policies = {
    ...(isRecord(target.policies) ? target.policies : {}),
    ...Object.fromEntries(Object.entries(policies).filter(([, value]) => value != null)),
  };
  return target;
}

function assertMapImageSelectionInputDimensions(inputRefs, contract, operation) {
  const target = contract?.target;
  const sourceWorld = target?.selection?.world;
  if (!isRecord(sourceWorld)
    || !Number.isSafeInteger(sourceWorld.width)
    || !Number.isSafeInteger(sourceWorld.height)
    || sourceWorld.width < 1
    || sourceWorld.height < 1) {
    throw imageExecutionError(400, "MAP_IMAGE_SELECTION_SOURCE_CANVAS_INVALID", "地图选区源画布尺寸无效");
  }
  const sources = Array.isArray(inputRefs?.source) ? inputRefs.source : [];
  if (!sources.length || (operation === "outpaint" && sources.length !== 1)) {
    throw imageExecutionError(400, "MAP_IMAGE_SELECTION_INPUT_REQUIRED", "地图选区任务的源图片数量无效");
  }
  for (const source of sources) {
    if (source.width !== sourceWorld.width || source.height !== sourceWorld.height) {
      throw imageExecutionError(
        409,
        "MAP_IMAGE_SELECTION_SOURCE_CANVAS_MISMATCH",
        "截取的源图片尺寸与地图选区不一致，请重新截取",
        { expected: { width: sourceWorld.width, height: sourceWorld.height }, actual: { width: source.width, height: source.height } },
      );
    }
  }
  if (inputRefs.mask && (inputRefs.mask.width !== sourceWorld.width || inputRefs.mask.height !== sourceWorld.height)) {
    throw imageExecutionError(409, "MAP_IMAGE_SELECTION_MASK_CANVAS_MISMATCH", "编辑蒙版尺寸必须与地图选区一致");
  }
}

function mapImageSelectionLimits(imageApi, operation) {
  const configured = imageApi?.limits?.size;
  const fixed = imageApi?.operationCapabilities?.[operation]?.sizes;
  const dimensions = Array.isArray(fixed)
    ? fixed.flatMap((value) => {
      const match = /^(\d+)x(\d+)$/u.exec(String(value || ""));
      return match ? [{ width: Number(match[1]), height: Number(match[2]) }] : [];
    })
    : [];
  const maxWorldWidth = Number(configured?.maxWidth)
    || Math.max(0, ...dimensions.map((entry) => entry.width))
    || 16_384;
  const maxWorldHeight = Number(configured?.maxHeight)
    || Math.max(0, ...dimensions.map((entry) => entry.height))
    || 16_384;
  const maxWorldPixels = Number(configured?.maxPixels)
    || Math.max(0, ...dimensions.map((entry) => entry.width * entry.height))
    || 64 * 1024 * 1024;
  return { maxWorldWidth, maxWorldHeight, maxWorldPixels };
}

function sameJsonValue(left, right) {
  if (Object.is(left, right)) return true;
  if (Array.isArray(left) || Array.isArray(right)) {
    return Array.isArray(left) && Array.isArray(right)
      && left.length === right.length
      && left.every((entry, index) => sameJsonValue(entry, right[index]));
  }
  if (!left || !right || typeof left !== "object" || typeof right !== "object") return false;
  const leftKeys = Object.keys(left).sort();
  const rightKeys = Object.keys(right).sort();
  return leftKeys.length === rightKeys.length
    && leftKeys.every((key, index) => key === rightKeys[index] && sameJsonValue(left[key], right[key]));
}

function isRecord(value) {
  return Boolean(value) && typeof value === "object" && !Array.isArray(value);
}

function normalizeInternalMapImageInputRefs(value) {
  if (value == null) return null;
  if (!isRecord(value) || !Array.isArray(value.source) || value.source.length < 1 || value.source.length > 16) {
    throw imageExecutionError(400, "INVALID_MAP_IMAGE_INPUTS", "地图图片临时源清单无效");
  }
  const normalize = (entry, kind) => {
    if (!isRecord(entry)) throw imageExecutionError(400, "INVALID_MAP_IMAGE_INPUTS", "地图图片临时输入记录无效");
    const id = String(entry.id || entry.inputId || "");
    if (!/^[A-Za-z0-9_-]{16,128}$/u.test(id)) {
      throw imageExecutionError(400, "INVALID_MAP_IMAGE_INPUTS", "地图图片临时输入标识无效");
    }
    const size = Number(entry.size ?? entry.totalBytes);
    if (!Number.isSafeInteger(size) || size < 1) {
      throw imageExecutionError(400, "INVALID_MAP_IMAGE_INPUTS", "地图图片临时输入大小无效");
    }
    const sha256 = String(entry.sha256 || entry.totalHash || "").toLowerCase();
    if (!/^[a-f0-9]{64}$/u.test(sha256)) {
      throw imageExecutionError(400, "INVALID_MAP_IMAGE_INPUTS", "地图图片临时输入哈希无效");
    }
    const format = String(entry.format || (entry.mediaType === "image/jpeg" ? "jpeg" : entry.mediaType === "image/webp" ? "webp" : "png"));
    if (!new Set(["png", "jpeg", "webp"]).has(format)) {
      throw imageExecutionError(400, "INVALID_MAP_IMAGE_INPUTS", "地图图片临时输入格式无效");
    }
    return {
      id,
      kind,
      size,
      sha256,
      format,
      mediaType: String(entry.mediaType || `image/${format === "jpeg" ? "jpeg" : format}`),
      width: Number.isSafeInteger(entry.width) ? entry.width : null,
      height: Number.isSafeInteger(entry.height) ? entry.height : null,
    };
  };
  const source = value.source.map((entry) => normalize(entry, "source"));
  const mask = value.mask == null ? null : normalize(value.mask, "mask");
  if (mask && mask.format !== "png") throw imageExecutionError(400, "INVALID_MAP_IMAGE_INPUTS", "地图蒙版临时输入必须是 PNG");
  return Object.freeze({ source: Object.freeze(source), mask });
}

async function authorizeMapImageInputRefs({
  identity,
  mapContext,
  editorStateId,
  inputRefs,
  imageApi,
  localOnly = false,
}) {
  if (!mapImageInputs) throw imageExecutionError(503, "MAP_IMAGE_INPUT_UNAVAILABLE", "地图图片临时输入服务当前不可用");
  const refs = normalizeInternalMapImageInputRefs(inputRefs);
  const maximumImages = localOnly ? 1 : Number(imageApi?.limits?.maxInputImages || 0);
  if (refs.source.length > maximumImages) {
    throw imageExecutionError(400, "IMAGE_INPUT_COUNT_UNSUPPORTED", "当前图片预设不能接收这么多源图片");
  }
  const totalBytes = refs.source.reduce((sum, entry) => sum + entry.size, 0) + (refs.mask?.size || 0);
  const maxTotalBytes = localOnly
    ? MAP_IMAGE_INPUT_MAX_BYTES
    : Number(imageApi?.limits?.maxInputBytesTotal || 0);
  if (totalBytes > maxTotalBytes) {
    throw imageExecutionError(413, "IMAGE_INPUTS_TOO_LARGE", "输入图片总大小超过管理员设置的限制");
  }
  const context = {
    identity,
    mapSessionId: mapContext.mapSessionId,
    mapVersion: mapContext.version,
    editorStateId: normalizeMapImageEditorStateId(editorStateId),
  };
  const descriptors = [];
  try {
    for (const ref of [...refs.source, ...(refs.mask ? [refs.mask] : [])]) {
      const descriptor = await mapImageInputs.authorize({
        ...context,
        inputId: ref.id,
        purpose: "input-claim-check",
      });
      descriptors.push(descriptor);
      const actual = descriptor.metadata;
      if (
        actual.sha256 !== ref.sha256
        || actual.totalBytes !== ref.size
        || actual.mediaType !== ref.mediaType
        || actual.kind !== ref.kind
      ) throw imageExecutionError(409, "MAP_IMAGE_INPUT_CHANGED", "地图图片临时输入元数据已经变化");
    }
  } finally {
    await Promise.all(descriptors.map((descriptor) => descriptor.release().catch(() => {})));
  }
  return refs;
}

async function authorizeMapImageJob({
  purpose = "execute",
  jobId = null,
  identity,
  mapContext,
  mapVersion,
  candidateBytes = 0,
} = {}) {
  if (!mapFileSessions) {
    throw imageExecutionError(503, "MAP_IMAGE_SESSION_UNAVAILABLE", "地图会话当前不可用");
  }
  const current = mapFileSessions.context({
    sessionId: mapContext?.mapSessionId,
    identity,
  });
  if (
    current.version !== String(mapVersion || "")
    || current.version !== mapContext?.version
    || path.resolve(current.projectPath) !== path.resolve(String(mapContext?.projectPath || "."))
    || path.resolve(current.targetPath) !== path.resolve(String(mapContext?.targetPath || "."))
  ) {
    throw imageExecutionError(409, "MAP_IMAGE_VERSION_CONFLICT", "地图版本或工程位置已经变化");
  }
  const runtime = await runtimeForUser(identity.userId);
  await assertWritableMapContext(current, runtime);
  if (["execute", "publish"].includes(purpose)) {
    const inspected = await inspectMapFile(current.targetPath, { maxBytes: MAP_SAVE_MAX_BYTES });
    if (inspected.version !== current.version) {
      throw imageExecutionError(409, "MAP_IMAGE_VERSION_CONFLICT", "地图已被其他窗口或任务修改");
    }
  }
  if (purpose !== "publish") return { uid: null, gid: null };
  if (!Number.isSafeInteger(candidateBytes) || candidateBytes < 1) {
    throw imageExecutionError(400, "MAP_IMAGE_CANDIDATE_INVALID", "地图候选图大小无效");
  }
  const authorized = await assertWritableImageProjectDirectory(current.projectPath, runtime);
  const fileOwner = authorized.share
    ? multiUserStore.getUser(authorized.share.sourceUserId)
    : runtime.user;
  if (!fileOwner || (!fileOwner.legacy && fileOwner.status !== "active")) {
    throw imageExecutionError(403, "IMAGE_PROJECT_OWNER_UNAVAILABLE", "地图工程所有者账号不可用");
  }
  const quotaRuntime = authorized.share
    ? await runtimeForUser(authorized.share.sourceUserId)
    : runtime;
  const quotaReservation = await reserveImageQuota(quotaRuntime, {
    jobId: `map-publish-${String(jobId || "invalid")}`,
    bytes: candidateBytes,
  });
  return {
    uid: !fileOwner.legacy && Number.isInteger(fileOwner.uid) ? fileOwner.uid : null,
    gid: !fileOwner.legacy && Number.isInteger(fileOwner.gid) ? fileOwner.gid : null,
    release: quotaReservation
      ? () => imageQuotaReservations?.release(quotaReservation)
      : null,
  };
}

async function authorizeQueuedMapImageContext(context, queueIdentity, imageApi = null, request = null) {
  const identity = {
    userId: String(context?.userId || ""),
    browserSessionId: String(context?.browserSessionId || ""),
    editorInstanceId: String(context?.editorInstanceId || ""),
  };
  if (
    identity.userId !== queueIdentity?.userId
    || identity.browserSessionId !== queueIdentity?.browserSessionId
  ) {
    throw imageExecutionError(400, "INVALID_MAP_IMAGE_TASK_CONTEXT", "地图生图队列身份无效");
  }
  await authorizeMapImageJob({
    purpose: "execute",
    identity,
    mapContext: context?.mapContext,
    mapVersion: context?.mapContext?.version,
  });
  if (context.inputRefs) {
    await authorizeMapImageInputRefs({
      identity,
      mapContext: context.mapContext,
      editorStateId: context.editorStateId,
      inputRefs: context.inputRefs,
      imageApi: imageApi || { limits: { maxInputImages: 16, maxInputBytesTotal: Number.MAX_SAFE_INTEGER } },
    });
  } else {
    const authorized = authorizeMapImageSources({
      identity,
      mapContext: context.mapContext,
      sourcePaths: context.sourcePaths,
      maskPath: context.maskPath,
    });
    if (
      JSON.stringify(authorized.sources) !== JSON.stringify(context.sourcePaths)
      || authorized.mask !== context.maskPath
    ) {
      throw imageExecutionError(409, "MAP_IMAGE_SOURCE_CHANGED", "地图生图源素材授权已经变化");
    }
  }
  if (context.selectionTarget) {
    const selectionRequest = context.selectionRequest || context.request || request;
    const selectionContract = await validateMapImageSelectionContract({
      target: context.selectionTarget,
      request: selectionRequest,
      operation: selectionRequest?.operation,
      expectedVersion: context.mapContext?.version,
      editorStateId: context.editorStateId,
      imageApi: imageApi || {},
      mapContext: context.mapContext,
    });
    if (context.inputRefs) {
      assertMapImageSelectionInputDimensions(
        context.inputRefs,
        selectionContract,
        selectionRequest?.operation,
      );
    }
  }
}

async function mapImageRequestContext(request, runtime) {
  if (!mapFileSessions) throw httpError(404, "地图编辑器在救援窗口中不可用");
  const editorInstanceId = normalizeMapEditorInstanceId(
    request.get("x-codex-desktop-editor-instance"),
  );
  const identity = mapSessionIdentity(request, editorInstanceId);
  const context = mapFileSessions.context({
    sessionId: request.params.sessionId,
    identity,
  });
  // Resolve the session target against the current runtime before exposing
  // queue state. This preserves user/project isolation even while the worker
  // adapter is disabled.
  const resolved = await resolveResourceTarget(context.projectPath, context.targetPath, runtime);
  if (
    path.resolve(resolved.projectPath) !== path.resolve(context.projectPath)
    || path.resolve(resolved.targetPath) !== path.resolve(context.targetPath)
  ) throw httpError(403, "地图生图上下文不再属于当前工程");
  return { identity, context };
}

function mapReadSessionConfig() {
  const mapIo = mapRenderSettings?.snapshot().config.mapIo;
  return {
    chunkBytes: mapIo?.readChunkBytes || MAP_FILE_CHUNK_BYTES,
    maxBytes: mapIo?.maxMapBytes || MAP_SAVE_MAX_BYTES,
    autoSaveIntervalMs: mapIo?.autoSaveIntervalMs ?? 120_000,
  };
}

function mapSaveSessionConfig() {
  const mapIo = mapRenderSettings?.snapshot().config.mapIo;
  return {
    chunkBytes: mapIo?.saveChunkBytes || MAP_SAVE_CHUNK_BYTES,
    maxBytes: mapIo?.maxMapBytes || MAP_SAVE_MAX_BYTES,
    commitConcurrency: mapIo?.saveCommitConcurrency || MAP_SAVE_COMMIT_CONCURRENCY,
    validationMemoryMb: MAP_SAVE_VALIDATION_MEMORY_MB,
    validationTimeoutMs: MAP_SAVE_VALIDATION_TIMEOUT_MS,
  };
}

async function authorizeMapRenderJob(job) {
  const userId = String(job?.identity?.userId || "");
  const user = multiUserStore.getUser(userId) || (userId === legacyUser.id ? legacyUser : null);
  if (!user || user.status !== "active") throw httpError(403, "地图渲染任务所属账号不可用");
  const runtime = await runtimeForUser(userId);
  await assertWritableMapContext(job.mapContext, runtime);
  return runtime;
}

async function checkMapRenderQuota({ userId, projectPath, bytes }) {
  const runtime = await runtimeForUser(userId);
  const share = projectShareForExactPath(runtime, projectPath);
  const quotaRuntime = share ? await runtimeForUser(share.sourceUserId) : runtime;
  await assertQuotaAvailable(quotaRuntime, bytes);
}

async function mapRenderOpsSnapshot() {
  const settings = mapRenderSettings.snapshot();
  const queue = mapRenderJobs.status();
  return {
    settings,
    queue,
    realtime: {
      cpuPercent: readCpuPercent(),
      availableMemoryBytes: os.freemem(),
      mainSiteLatencyMs: await measureMainSiteLatency(),
      workerCount: queue.workerCount,
      queueLength: queue.queueLength,
      preset: settings.preset,
    },
  };
}

async function closeMapRenderSystem() {
  await mapRenderJobs?.close();
  await mapRenderWorkerRunner?.close?.();
  await mapAiPatchWorkerRunner?.close?.();
  await mapAiResourceCandidates?.close?.();
  await mapAiResourceUploads?.close?.();
}

function requireImageExecutionOps() {
  if (!imageExecutionSettings || !imageExecutionQueue) {
    throw httpError(404, "救援窗口不提供图片 Worker 管理");
  }
}

async function imageExecutionOpsSnapshot() {
  const settings = imageExecutionSettings.snapshot();
  const queue = imageExecutionQueue.status();
  return {
    settings,
    queue,
    realtime: {
      cpuPercent: readCpuPercent(),
      availableMemoryBytes: os.freemem(),
      mainSiteLatencyMs: await measureMainSiteLatency(),
      workerCount: queue.workerCount,
      queueLength: queue.queueLength,
      preset: settings.preset,
    },
  };
}

async function closeImageExecutionSystem() {
  if (imagePartialPreviewPruneTimer) clearInterval(imagePartialPreviewPruneTimer);
  // Stop admission and let map-job finalizers release temporary source/mask
  // pins before removing the input store. Otherwise a running Worker could
  // observe MAP_IMAGE_INPUT_CHANGED while shutdown is still draining.
  await mapImageJobs?.close?.();
  await imageExecutionQueue?.close();
  await mapImageInputs?.close?.();
  imageQuotaReservations?.close();
  await imageWorkerRunner?.close?.();
  await imagePartialPreviewStore?.close();
}

async function measureMainSiteLatency() {
  const gateway = await opsGatewaySnapshot();
  if (Number.isFinite(gateway.latencyMs)) return gateway.latencyMs;
  const startedAt = performance.now();
  try {
    const response = await fetch(`http://127.0.0.1:${PORT}/internal/ready`, {
      headers: { Host: `127.0.0.1:${PORT}` },
      cache: "no-store",
      signal: AbortSignal.timeout(1_000),
    });
    if (!response.ok) return null;
    await response.arrayBuffer();
    return Math.max(0, Math.round((performance.now() - startedAt) * 10) / 10);
  } catch {
    return null;
  }
}

function windowsLeaseInput(request, value, { includeEpoch = false } = {}) {
  const input = {
    userId: request.user.id,
    deviceId: String(value?.deviceId || ""),
    pluginId: String(value?.pluginId || ""),
    threadId: String(value?.threadId || ""),
    browserSessionId: browserSessionIdentity(request),
    windowId: String(value?.windowId || ""),
  };
  if (includeEpoch) input.leaseEpoch = Number(value?.leaseEpoch);
  return input;
}

function creatorJobCompletion(result) {
  const status = ["succeeded", "failed", "canceled"].includes(result?.status)
    ? result.status
    : "succeeded";
  const summary = typeof result?.summary === "string" && result.summary.trim()
    ? result.summary.trim()
    : status === "succeeded"
      ? "创作任务已完成"
      : "创作任务未完成";
  return {
    status,
    summary,
    outputPath: typeof result?.outputPath === "string" ? result.outputPath : null,
  };
}

function requireOwner(request) {
  if (!request.user || request.user.role !== "owner") {
    throw httpError(403, "只有所有者可以执行此操作");
  }
}

function verifyCurrentAdminPassword(user, password) {
  if (multiUserStore.getUser(user.id)) return multiUserStore.verifyPassword(user.id, String(password || ""));
  return Boolean(AUTH && verifyAuthCredentials(user.username, String(password || ""), AUTH));
}

function rescueOwnerCanAuthenticate() {
  if (!RESCUE_MODE) return true;
  if (!multiUserStore.modeSnapshot().configured) return Boolean(AUTH);
  const owner = multiUserStore.getOwner();
  return Boolean(
    owner
    && owner.role === "owner"
    && owner.status === "active"
    && AUTH
    && owner.username === AUTH.username,
  );
}

async function reconciledDeploymentStatuses() {
  if (deploymentReconciliation) return deploymentReconciliation;
  deploymentReconciliation = (async () => {
    const statuses = Object.fromEntries(await Promise.all([
      ["release", releaseStatusStore.read()],
      ["appUpdate", appUpdateStatusStore.read()],
      ["codexUpdate", codexUpdateStatusStore.read()],
      ["rollback", rollbackStatusStore.read()],
      ["restore", readBackupRestoreStatus()],
    ].map(async ([key, pending]) => [key, await pending])));
    const definitions = [
      {
        key: "release", kind: "release", active: ACTIVE_RELEASE_PHASES, store: releaseStatusStore,
        lock: path.join(RELEASE_RUNTIME_DIR, "release.lock"), command: "scripts/release.mjs",
      },
      {
        key: "appUpdate", kind: "app-update", active: ACTIVE_APP_UPDATE_PHASES, store: appUpdateStatusStore,
        lock: path.join(RELEASE_RUNTIME_DIR, "app-update.lock"), command: "scripts/update-app.mjs",
      },
      {
        key: "codexUpdate", kind: "codex-update", active: ACTIVE_CODEX_UPDATE_PHASES, store: codexUpdateStatusStore,
        lock: path.join(RELEASE_RUNTIME_DIR, "codex-update.lock"), command: "scripts/update-codex.mjs",
      },
      {
        key: "rollback", kind: "rollback", active: ACTIVE_ROLLBACK_PHASES, store: rollbackStatusStore,
        lock: path.join(RELEASE_RUNTIME_DIR, "release.lock"), command: "scripts/rollback.mjs",
      },
    ];
    for (const definition of definitions) {
      const status = statuses[definition.key];
      if (!definition.active.has(status?.phase)) continue;
      const updateAgeMs = deploymentStatusUpdateAge(status);
      if (updateAgeMs < DEPLOYMENT_STATUS_STALE_GRACE_MS) continue;
      const liveness = await maintenanceOperationLiveness({
        kind: definition.kind,
        unit: status.unit,
        lockPath: definition.lock,
        expectedCommand: definition.command,
      });
      if (
        liveness === "active"
        || (
          liveness === "unknown"
          && deploymentStatusRuntimeAge(status) < DEPLOYMENT_LIVENESS_UNKNOWN_GRACE_MS
        )
      ) {
        continue;
      }
      const latest = await definition.store.read();
      if (!sameDeploymentObservation(status, latest) || !definition.active.has(latest?.phase)) {
        statuses[definition.key] = latest;
        continue;
      }
      statuses[definition.key] = {
        ...latest,
        status: "failed",
        phase: "failed",
        detail: "后台维护任务已失联，状态已自动解除",
        updatedAt: Date.now(),
        completedAt: Date.now(),
        error: "Maintenance worker is no longer active",
      };
    }
    const restore = statuses.restore;
    if (
      restore?.status === "running"
      && deploymentStatusUpdateAge(restore) >= DEPLOYMENT_STATUS_STALE_GRACE_MS
    ) {
      const liveness = await maintenanceOperationLiveness({
        kind: "data-restore",
        unit: restore.unit,
        lockPath: path.join(RELEASE_RUNTIME_DIR, "backup-restore.lock"),
        expectedCommand: "scripts/restore-data-backup.mjs",
      });
      if (
        liveness !== "active"
        && !(
          liveness === "unknown"
          && deploymentStatusRuntimeAge(restore) < DEPLOYMENT_LIVENESS_UNKNOWN_GRACE_MS
        )
      ) {
        const latest = await readBackupRestoreStatus();
        if (sameDeploymentObservation(restore, latest) && latest.status === "running") {
          statuses.restore = {
            ...latest,
            status: "failed",
            phase: "failed",
            detail: "数据恢复后台任务已失联，状态已自动解除",
            updatedAt: Date.now(),
            completedAt: Date.now(),
            error: "Data restore worker is no longer active",
          };
        } else {
          statuses.restore = latest;
        }
      }
    }
    return statuses;
  })();
  try {
    return await deploymentReconciliation;
  } finally {
    deploymentReconciliation = null;
  }
}

async function maintenanceOperationLiveness({ kind, unit, lockPath, expectedCommand }) {
  const trustedUnit = deploymentUnitIsTrusted(kind, unit) ? unit : null;
  const [unitState, lockState] = await Promise.all([
    systemdUnitState(trustedUnit),
    operationLockState(lockPath, expectedCommand, trustedUnit),
  ]);
  if (unitState === "active" || lockState === "active") return "active";
  if (lockState === "unknown") return "unknown";
  return "inactive";
}

function deploymentUnitIsTrusted(kind, unit) {
  const pattern = DEPLOYMENT_UNIT_PATTERNS.get(kind);
  return Boolean(pattern && typeof unit === "string" && pattern.test(unit));
}

async function operationLockState(lockPath, expectedCommand, operationId) {
  let raw;
  let stat;
  try {
    stat = await fs.lstat(lockPath);
    if (!stat.isFile() || stat.isSymbolicLink() || stat.size > 4_096) return "inactive";
    raw = (await fs.readFile(lockPath, "utf8")).trim();
  } catch (error) {
    return error.code === "ENOENT" ? "inactive" : "unknown";
  }
  let value = null;
  try {
    value = JSON.parse(raw);
  } catch {
    value = null;
  }
  const pid = Number(value?.pid ?? raw);
  if (!Number.isSafeInteger(pid) || pid <= 1) {
    const ageMs = validPastAge(stat.mtimeMs);
    return ageMs !== null && ageMs < INCOMPLETE_OPERATION_LOCK_GRACE_MS ? "unknown" : "inactive";
  }
  if (value?.operationId && operationId && value.operationId !== operationId) return "inactive";
  try {
    process.kill(pid, 0);
  } catch (error) {
    if (["ENOENT", "ESRCH"].includes(error.code)) return "inactive";
    if (error.code !== "EPERM") return "unknown";
  }
  if (value?.startTicks) {
    const startTicks = await processStartTicks(pid);
    if (startTicks === null) return "inactive";
    if (startTicks === undefined) return "unknown";
    if (String(value.startTicks) !== startTicks) return "inactive";
  }
  try {
    const commandLine = await fs.readFile(`/proc/${pid}/cmdline`, "utf8");
    return commandLine.includes(expectedCommand) && commandLine.includes("--worker") ? "active" : "inactive";
  } catch (error) {
    if (["ENOENT", "ESRCH"].includes(error.code)) return "inactive";
    return "unknown";
  }
}

async function processStartTicks(pid) {
  try {
    const stat = await fs.readFile(`/proc/${pid}/stat`, "utf8");
    const commandEnd = stat.lastIndexOf(")");
    if (commandEnd === -1) return undefined;
    const fields = stat.slice(commandEnd + 1).trim().split(/\s+/);
    return /^\d+$/.test(fields[19] || "") ? fields[19] : undefined;
  } catch (error) {
    if (["ENOENT", "ESRCH"].includes(error.code)) return null;
    return undefined;
  }
}

function systemdUnitState(unit) {
  if (!/^[A-Za-z0-9][A-Za-z0-9._@-]{0,199}$/.test(String(unit || ""))) return Promise.resolve("inactive");
  return new Promise((resolve) => {
    let settled = false;
    const child = spawn(SYSTEMCTL_COMMAND, ["is-active", "--quiet", unit], { stdio: "ignore" });
    const finish = (state) => {
      if (settled) return;
      settled = true;
      clearTimeout(timer);
      resolve(state);
    };
    const timer = setTimeout(() => {
      child.kill("SIGKILL");
      finish("unknown");
    }, 3_000);
    timer.unref?.();
    child.on("error", () => finish("unknown"));
    child.on("exit", (code) => finish(code === 0 ? "active" : [3, 4].includes(code) ? "inactive" : "unknown"));
  });
}

function sameDeploymentObservation(left, right) {
  return (left?.unit || left?.operationId || null) === (right?.unit || right?.operationId || null)
    && (left?.phase || null) === (right?.phase || null)
    && (left?.updatedAt || null) === (right?.updatedAt || null)
    && (left?.startedAt || null) === (right?.startedAt || null);
}

function deploymentStatusUpdateAge(status, now = Date.now()) {
  return validPastAge(status?.updatedAt, now) ?? validPastAge(status?.startedAt, now) ?? Number.POSITIVE_INFINITY;
}

function deploymentStatusRuntimeAge(status, now = Date.now()) {
  return validPastAge(status?.startedAt, now) ?? deploymentStatusUpdateAge(status, now);
}

function validPastAge(value, now = Date.now()) {
  if (!Number.isFinite(value) || value <= 0 || value > now + 5_000) return null;
  return Math.max(0, now - value);
}

async function assertNoConflictingDeployment() {
  const { release, appUpdate, codexUpdate, rollback, restore } = await reconciledDeploymentStatuses();
  if (androidApkBuilder?.isBusy()) throw httpError(409, "Android APK 构建正在执行");
  if (backupCreationTask || backupCenter.snapshot().busy) throw httpError(409, "数据备份正在执行");
  const workspaceMigration = workspaceMigrationCenter.snapshot();
  if (
    workspaceExportTask
    || workspaceImportTask
    || workspaceInspectionInProgress > 0
    || workspaceMigration.busy
    || workspaceMigration.activeUploadWrites > 0
  ) {
    throw httpError(409, "工作区迁移正在执行");
  }
  if (restore.status === "running") throw httpError(409, "数据恢复正在执行");
  if (ACTIVE_RELEASE_PHASES.has(release.phase)) throw httpError(409, "网页版本正在发布");
  if (ACTIVE_APP_UPDATE_PHASES.has(appUpdate.phase)) throw httpError(409, "远程同步正在执行");
  if (codexUpdateIsActive(codexUpdate)) throw httpError(409, "官方 Codex 正在升级");
  if (ACTIVE_ROLLBACK_PHASES.has(rollback.phase)) throw httpError(409, "手动回滚正在执行");
}

function launchRollbackWorker(targetVersion, { candidateId = null } = {}) {
  return launchDeploymentWorker("rollback.mjs", ["--version", targetVersion], {
    env: {
      ...process.env,
      CODEX_DESKTOP_STATE_DIR: STATE_DIR,
      CODEX_DESKTOP_RUNTIME_DIR: RELEASE_RUNTIME_DIR,
      ...(candidateId ? { CODEX_DESKTOP_RELEASE_CANDIDATE_ID: candidateId } : {}),
    },
    failureMessage: "无法启动手动回滚任务",
    invalidResultMessage: "手动回滚任务返回了无效结果",
    timeoutMessage: "手动回滚任务启动超时，启动锁已解除",
  });
}

async function candidateRollbackVersion(candidate) {
  let activePort;
  try {
    activePort = Number((await fs.readFile(path.join(RELEASE_RUNTIME_DIR, "active-port"), "utf8")).trim());
    if (!MAIN_BACKEND_PORTS.includes(activePort)) return null;
    const activeResponse = await fetch(`http://127.0.0.1:${activePort}/internal/ready`, {
      headers: { Host: `127.0.0.1:${activePort}` },
      cache: "no-store",
      signal: AbortSignal.timeout(3_000),
    });
    const activeReady = await activeResponse.json();
    if (activeReady?.ok !== true || !activeResponse.ok || activeReady.version !== candidate?.version) return null;
  } catch {
    return null;
  }
  if (
    candidate?.previousVersion
    && candidate.previousVersion !== candidate.version
    && /^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)$/.test(candidate.previousVersion)
  ) {
    return candidate.previousVersion;
  }
  try {
    if (MAIN_BACKEND_PORTS.length !== 2) return null;
    const targetPort = MAIN_BACKEND_PORTS.find((port) => port !== activePort);
    if (!targetPort) return null;
    const target = await fs.realpath(path.join(RELEASE_RUNTIME_DIR, "slots", String(targetPort)));
    const releasesRoot = await fs.realpath(path.join(RELEASE_RUNTIME_DIR, "releases"));
    const relative = path.relative(releasesRoot, target);
    if (!relative || relative.startsWith("..") || path.isAbsolute(relative)) return null;
    const packageJson = JSON.parse(await fs.readFile(path.join(target, "package.json"), "utf8"));
    if (
      packageJson.version === candidate?.version
      || !/^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)$/.test(packageJson.version || "")
      || relative !== `v${packageJson.version}`
    ) return null;
    return packageJson.version;
  } catch {
    return null;
  }
}

function parseConfiguredBackendPorts(value) {
  return [...new Set(String(value || "").split(",").map((entry) => Number(entry.trim())))]
    .filter((port) => Number.isInteger(port) && port > 0 && port < 65_536);
}

async function activeBackendSelectorExists() {
  try {
    await fs.access(path.join(RELEASE_RUNTIME_DIR, "active-port"));
    return true;
  } catch (error) {
    if (error.code === "ENOENT") return false;
    throw error;
  }
}

