function claudeHttpPermission(pathname) {
  const value = typeof pathname === "string" ? pathname : "/";
  if (/^\/official(?:\/|$)/.test(value)) return "claudeOfficialLogin";
  if (/^\/providers(?:\/|$)/.test(value)) return "claudeProviders";
  if (/^\/background-agents(?:\/|$)/.test(value)) return "claudeBackground";
  if (/^\/mcp(?:\/|$)/.test(value)) return "claudeMcp";
  if (/^\/hooks(?:\/|$)/.test(value)) return "claudeHooks";
  if (/^\/memory(?:\/|$)/.test(value)) return "claudeMemory";
  if (/^\/project(?:\/|$)/.test(value)) return "claudeProjectPurge";
  if (/^\/ultrareview(?:\/|$)/.test(value)) return "claudeUltraReview";
  if (/^\/(?:extensions|auto-mode|skills|agents|plugins|plugin-marketplaces)(?:\/|$)/.test(value)) {
    return "claudeExtensions";
  }
  return "claudeRuntime";
}

