function beginProviderModelQuery(userId) {
  if (providerModelQueriesInFlight.has(userId)) throw httpError(409, "当前账号正在查询供应商模型");
  const now = Date.now();
  const recent = (providerModelQueryWindows.get(userId) || [])
    .filter((timestamp) => timestamp >= now - PROVIDER_MODEL_QUERY_WINDOW_MS);
  if (recent.length >= PROVIDER_MODEL_QUERY_WINDOW_LIMIT) {
    throw httpError(429, "供应商模型查询过于频繁，请一分钟后重试");
  }
  recent.push(now);
  providerModelQueryWindows.set(userId, recent);
  providerModelQueriesInFlight.add(userId);
  return () => providerModelQueriesInFlight.delete(userId);
}

async function createCodexFeedbackPreview(runtime, input) {
  const draft = normalizeCodexFeedbackDraft(input);
  const taskCounts = {
    running: 0,
    waiting: 0,
    stopping: 0,
    completed: 0,
    failed: 0,
    interrupted: 0,
  };
  for (const task of runtime.taskStatus.list({ limit: 200 }).tasks) {
    if (Object.hasOwn(taskCounts, task.status)) taskCounts[task.status] += 1;
  }
  const codex = await codexUpdateSnapshot();
  return buildCodexFeedbackPreview({
    draft,
    appVersion: APP_VERSION,
    codexVersion: codex.installedVersion || null,
    protocolBaseline: CODEX_PROTOCOL_BASELINE,
    runtime: {
      codexReady: runtime.bridge.ready,
      connectedClients: runtime.clients.size,
      taskCounts,
      goalRecoveryWaiting: (runtime.goalRecoveryStore?.snapshot() || [])
        .filter((record) => record.resumeWhenAvailable === true)
        .length,
      multiUserEnabled: multiUserStore.modeSnapshot().enabled,
    },
  });
}

function pruneCodexFeedbackPreviews(now = Date.now()) {
  for (const [previewId, record] of codexFeedbackPreviews) {
    if (!record || record.expiresAt <= now) codexFeedbackPreviews.delete(previewId);
  }
}

function storeCodexFeedbackPreview(previewId, record) {
  const accountPreviews = [...codexFeedbackPreviews.entries()]
    .filter(([, candidate]) => candidate?.userId === record.userId)
    .sort((left, right) => left[1].createdAt - right[1].createdAt);
  while (accountPreviews.length >= 4) {
    const [oldestId] = accountPreviews.shift();
    codexFeedbackPreviews.delete(oldestId);
  }
  if (codexFeedbackPreviews.size >= 128) {
    throw httpError(429, "当前诊断预览较多，请稍后重试");
  }
  codexFeedbackPreviews.set(previewId, record);
}

function beginCodexFeedbackUpload(userId) {
  if (codexFeedbackUploadsInFlight.has(userId)) {
    throw httpError(409, "当前账号已有反馈正在上传");
  }
  const now = Date.now();
  const recent = (codexFeedbackUploadWindows.get(userId) || [])
    .filter((timestamp) => timestamp >= now - CODEX_FEEDBACK_UPLOAD_WINDOW_MS);
  if (recent.length >= CODEX_FEEDBACK_UPLOAD_WINDOW_LIMIT) {
    throw httpError(429, "反馈上传过于频繁，请一小时后再试");
  }
  recent.push(now);
  codexFeedbackUploadWindows.set(userId, recent);
  codexFeedbackUploadsInFlight.add(userId);
  return () => codexFeedbackUploadsInFlight.delete(userId);
}

async function writeCodexFeedbackAttachment(runtime, content) {
  if (
    typeof content !== "string"
    || Buffer.byteLength(content) < 1
    || Buffer.byteLength(content) > CODEX_FEEDBACK_ATTACHMENT_MAX_BYTES
  ) {
    throw httpError(413, "脱敏诊断摘要大小无效");
  }
  const directory = path.join(runtime.user.stateDirectory, "feedback-staging");
  await fs.mkdir(directory, { recursive: true, mode: 0o700 });
  const directoryStat = await fs.lstat(directory);
  if (!directoryStat.isDirectory() || directoryStat.isSymbolicLink()) {
    throw httpError(409, "反馈暂存目录不安全");
  }
  await fs.chmod(directory, 0o700);
  if (!runtime.legacy) await fs.chown(directory, runtime.user.uid, runtime.user.gid);
  const target = path.join(directory, `safe-diagnostics-${crypto.randomBytes(12).toString("hex")}.json`);
  let handle = null;
  try {
    handle = await fs.open(target, "wx", 0o600);
    await handle.writeFile(content, "utf8");
    await handle.chmod(0o600);
    if (!runtime.legacy) await handle.chown(runtime.user.uid, runtime.user.gid);
    await handle.close();
    handle = null;
    const stat = await fs.lstat(target);
    if (
      !stat.isFile()
      || stat.isSymbolicLink()
      || stat.size > CODEX_FEEDBACK_ATTACHMENT_MAX_BYTES
      || (stat.mode & 0o077) !== 0
      || (!runtime.legacy && (stat.uid !== runtime.user.uid || stat.gid !== runtime.user.gid))
    ) {
      throw httpError(409, "反馈诊断文件校验失败");
    }
    return target;
  } catch (error) {
    await handle?.close().catch(() => {});
    await fs.unlink(target).catch(() => {});
    throw error;
  }
}

