function codexFeedbackUploadError(error) {
  const status = Number(error?.statusCode || error?.status);
  if ([400, 403, 404, 409, 413, 429].includes(status)) return error;
  const safe = redactCodexFeedbackText(error?.message || "");
  if (/feedback.{0,30}(?:disabled|关闭|禁用)/i.test(safe)) {
    return httpError(409, "Codex 当前配置已关闭反馈上传");
  }
  return httpError(502, "Codex 未完成反馈上传；脱敏摘要仍可复制，请稍后重试");
}

